import { VERSION } from "./src/main.ts";
import { readFileSync, writeFileSync, rmSync, cpSync } from "node:fs";
import { join } from "node:path";

const outDir = "./npm";

// Forward parser specs from the dev package.json so the published CLI pins
// to the same versions devs install/test against.
const cliDeps: Record<string, string> =
  JSON.parse(readFileSync("./package.json", "utf-8")).dependencies ?? {};

// Parser packages: bundle externals + published dependencies. Derived from
// package.json (not hand-listed) — a parser missing from this set ships a CLI
// whose loadParser() silently falls back. package.json itself is kept in sync
// with loadParser() call sites by test/parser_packages_unit.test.ts.
const parserPackages = Object.keys(cliDeps).filter((p) =>
  p.startsWith("windmill-parser-wasm")
);
const parserExternals = parserPackages.flatMap(p => ["--external", p]);

// Clean output directory
rmSync(outDir, { recursive: true, force: true });

// Build with bun — bundle everything except esbuild (platform-specific binary),
// svelte (optional, only needed for `wmill app bundle/dev`), and parser packages
// (loaded at runtime via init() with readFileSync for the .wasm binary).
// esbuild-wasm is not a dependency at all: the host/binary-mismatch fallback in
// esbuild_loader.ts downloads and caches the whole esbuild-wasm package at
// runtime, so it stays out of the bundle and the published dependencies.
console.log("Bundling with bun build...");
const buildResult = Bun.spawnSync([
  "bun", "build", "src/main.ts",
  "--outdir", join(outDir, "esm"),
  "--target", "node",
  "--format", "esm",
  "--external", "esbuild",
  "--external", "svelte",
  "--external", "svelte/compiler",
  ...parserExternals,
], { cwd: import.meta.dir, stdout: "inherit", stderr: "inherit" });

if (buildResult.exitCode !== 0) {
  console.error("Build failed");
  process.exit(1);
}

// Add shebang to main.js
const mainJsPath = join(outDir, "esm", "main.js");
const mainJs = readFileSync(mainJsPath, "utf-8");
writeFileSync(mainJsPath, "#!/usr/bin/env node\n" + mainJs, "utf-8");

// Copy LICENSE and README
cpSync("../LICENSE", join(outDir, "LICENSE"));
cpSync("README.md", join(outDir, "README.md"));

// Generate package.json
const packageJson = {
  name: "windmill-cli",
  version: VERSION,
  description: "CLI for Windmill",
  license: "Apache 2.0",
  type: "module",
  main: "esm/main.js",
  bin: {
    wmill: "esm/main.js",
  },
  repository: {
    type: "git",
    url: "git+https://github.com/windmill-labs/windmill.git",
  },
  bugs: {
    url: "https://github.com/windmill-labs/windmill/issues",
  },
  dependencies: {
    esbuild: "0.28.0",
    ...Object.fromEntries(parserPackages.map(p => [p, cliDeps[p] ?? "*"])),
  },
  optionalDependencies: {
    svelte: "^5.0.0",
  },
};

writeFileSync(
  join(outDir, "package.json"),
  JSON.stringify(packageJson, null, 2) + "\n",
  "utf-8"
);

console.log(`Built npm package v${VERSION} to ${outDir}/`);

#!/usr/bin/env nu

let cli_cache = "/tmp/windmill/cache_nomount/bun/"
let bundle_cache = "/tmp/windmill/cache/bun/"

# Clean CLI package cache
def "main clean" [] {
    rm -rf ($cli_cache ++ "windmill-cli@*")
    rm -rf ($cli_cache ++ "windmill-cli/")
    print "Cleaned CLI cache"
}

# Clear bundle cache (forces hub scripts to re-bundle)
def "main clear-bundles" [] {
    rm -rf ($bundle_cache ++ "*")
    print "Cleared bundle cache"
}

# Patch CLI cache with local build
def "main patch" [] {
    print "Patching CLI cache..."

    let versions = (ls $cli_cache | where name =~ "windmill-cli@" | get name)

    if ($versions | is-empty) {
        print "No CLI versions found in cache"
        return
    }

    for path in $versions {
        rm -rf ($path ++ "/esm")
        ^cp -r npm/esm ($path ++ "/esm")
        ^cp npm/package.json ($path ++ "/package.json")
        print $"Patched ($path | path basename)"
    }

    print "Done!"
}

# Build CLI, patch cache, and clear bundles
def main [
    --patch(-p)  # Only patch existing cache (skip build)
    --clean(-c)  # Clean CLI cache first
] {
    if $clean {
        main clean
    }

    if $patch {
        main patch
    } else {
        print "Building CLI..."
        bun run build
        main patch
    }

    # Always clear bundle cache so hub scripts use patched CLI
    main clear-bundles
}

