/**
 * Bundles the frontend's raw-app policy derivation into a script the server's
 * bundle job carries, and writes it next to that job's source.
 *
 * The derivation is not re-implemented in Rust, and not shelled out to `wmill`
 * either. `triggerables_v2` is the allowlist every component run is matched
 * against, keyed by `<component>:rawscript/<sha256 of the inline code>` — a key
 * derived any other way leaves a deployed app's runnables "forbidden by policy",
 * which reads as a broken app rather than a failed deploy. So the app editor,
 * `wmill app push` and the server all have to agree, and the way to guarantee
 * that is one source.
 *
 * It rides in the job script rather than in the CLI the job already runs,
 * because the images install `windmill-cli` unpinned: an image can carry a CLI
 * older than its server, and falling back to `bun x windmill-cli@<release>`
 * needs npm reachable at deploy time, which is exactly what the bundler's
 * installed-CLI branch exists to avoid. The job script is `include_str!`d into
 * the server binary, so it always matches the server.
 *
 * Run `bun run gen:app-policy` after touching
 * frontend/src/lib/components/raw_apps/rawAppPolicy.ts or anything it imports;
 * test/app_policy_bundle_unit.test.ts fails when the committed bundle no longer
 * matches those sources.
 */
import * as esbuild from "esbuild";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const REPO_ROOT = join(import.meta.dir, "..");
const RAW_APPS_DIR = join(
  REPO_ROOT,
  "frontend",
  "src",
  "lib",
  "components",
  "raw_apps",
);
export const OUT_FILE = join(
  REPO_ROOT,
  "backend",
  "windmill-api",
  "src",
  "apps_raw_policy.gen.js",
);

const HEADER = `// Generated by cli/generate-app-policy.ts. Do not edit.
// Run \`bun run gen:app-policy\` from cli/ to rebuild it from
// frontend/src/lib/components/raw_apps/rawAppPolicy.ts.
//
// Prepended to the raw-app bundle job (see apps_raw_bundle.rs), which calls
// \`__wmillAppPolicy.updateRawAppPolicy\` from its own module scope.
`;

/** The bundled IIFE, header included. Exported so the staleness test can build
 * it and compare, rather than keep a hash in step by hand. */
export async function buildAppPolicyBundle(): Promise<string> {
  const result = await esbuild.build({
    stdin: {
      contents: `export { updateRawAppPolicy } from './rawAppPolicy'`,
      resolveDir: RAW_APPS_DIR,
      loader: "ts",
    },
    bundle: true,
    format: "iife",
    globalName: "__wmillAppPolicy",
    target: "es2022",
    // `hash()` falls back to this only when Web Crypto is missing, which it
    // never is on a worker's bun. Left unresolved so the bundle needs nothing
    // installed where it runs.
    external: ["@aws-crypto/sha256-js"],
    minify: true,
    write: false,
    legalComments: "none",
  });
  return HEADER + result.outputFiles[0].text;
}

if (import.meta.main) {
  const js = await buildAppPolicyBundle();
  const before = (() => {
    try {
      return readFileSync(OUT_FILE, "utf-8");
    } catch {
      return "";
    }
  })();
  writeFileSync(OUT_FILE, js, "utf-8");
  console.log(
    `${before === js ? "Unchanged" : "Wrote"} ${OUT_FILE} (${
      Math.round(js.length / 1024)
    } KB)`,
  );
}

/**
 * Bundles the frontend's raw-app session recorder into a browser script the dev
 * server can serve, and writes it as a string constant the CLI bundle carries.
 *
 * The recorder is not re-implemented here: `wmill app dev --recording` must
 * produce the exact recording format the players read, and the event
 * classification it encodes is the hard part. The one adaptation is the `$state`
 * rune: outside Svelte the store's fields are read through its getters, so the
 * rune is stripped and the values become plain `let`s.
 *
 * Run `bun run gen:dev-recorder` after touching anything under
 * frontend/src/lib/components/recording/; test/dev_recorder_bundle_unit.test.ts
 * fails when the committed bundle no longer matches those sources.
 */
import * as esbuild from "esbuild";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";

const REPO_ROOT = join(import.meta.dir, "..");
const RECORDING_DIR = join(
  REPO_ROOT,
  "frontend",
  "src",
  "lib",
  "components",
  "recording",
);
const ENTRY = "./rawAppRecording.svelte";
const OUT_FILE = join(
  import.meta.dir,
  "src",
  "commands",
  "app",
  "devRecorderBundle.gen.ts",
);

/** Hash of everything that went into the bundle. Over the modules esbuild
 * actually pulled in rather than a hand-kept list, so a module added to the
 * recorder's import graph can't slip past the staleness check. Line endings are
 * normalized: a CRLF checkout is the same source, and must not read as drift. */
export function hashRecorderSources(
  sources: string[],
  root: string = REPO_ROOT,
): string {
  const hash = createHash("sha256");
  for (const file of sources) {
    hash.update(file);
    hash.update(
      readFileSync(join(root, file), "utf-8").replace(/\r\n/g, "\n"),
    );
  }
  return hash.digest("hex");
}

/** Reactivity has no meaning in a plain browser script, and the store exposes
 * every rune-backed field through a getter, so `$state(x)` collapses to `x`.
 * Every other rune is compiled away by Svelte and would survive here as an
 * undefined identifier, so refuse rather than emit a bundle that throws. */
function stripRunes(source: string, file: string): string {
  const unsupported = [
    ...(source.match(/\$state[\w.]*\s*\(?/g) ?? []).filter(
      (r) => r.replace(/\s/g, "") !== "$state(",
    ),
    ...(source.match(
      /\$(derived|effect|props|bindable|inspect|host)[\w.]*/g,
    ) ?? []),
  ];
  if (unsupported.length > 0) {
    throw new Error(
      `${file} uses ${
        [...new Set(unsupported)].join(", ")
      }, which this generator cannot strip. ` +
        `Keep the recorder store free of runes beyond \`$state(...)\`.`,
    );
  }
  return source.replace(/\$state\s*\(/g, "(");
}

const runeStripper: esbuild.Plugin = {
  name: "strip-svelte-runes",
  setup(build) {
    build.onLoad({ filter: /\.svelte\.ts$/ }, (args) => ({
      contents: stripRunes(readFileSync(args.path, "utf-8"), args.path),
      loader: "ts",
    }));
  },
};

if (import.meta.main) {
  const result = await esbuild.build({
    stdin: {
      contents: `export { createRawAppRecording } from '${ENTRY}'`,
      resolveDir: RECORDING_DIR,
      loader: "ts",
    },
    plugins: [runeStripper],
    bundle: true,
    format: "iife",
    globalName: "__wmillRecorder",
    target: "es2020",
    minify: true,
    metafile: true,
    write: false,
    legalComments: "none",
  });

  const js = result.outputFiles[0].text;
  // Repo-relative and sorted, so the hash does not move with the checkout path
  // or with esbuild's traversal order. `<stdin>` is the entry above, not a file.
  const sources = Object.keys(result.metafile.inputs)
    .filter((f) => f !== "<stdin>")
    .map((f) => relative(REPO_ROOT, join(import.meta.dir, f)))
    .sort();
  writeFileSync(
    OUT_FILE,
    `// Generated by cli/generate-dev-recorder.ts. Do not edit.\n` +
      `// Run \`bun run gen:dev-recorder\` from cli/ to rebuild it from\n` +
      `// frontend/src/lib/components/recording/.\n\n` +
      `/** Repo-relative sources bundled below. */\n` +
      `export const DEV_RECORDER_SOURCES = ${
        JSON.stringify(sources, null, 2)
      };\n\n` +
      `/** SHA-256 of those sources, as of this build. */\n` +
      `export const DEV_RECORDER_SOURCE_HASH = ${
        JSON.stringify(hashRecorderSources(sources))
      };\n\n` +
      `/** IIFE exposing \`createRawAppRecording\` on \`window.__wmillRecorder\`. */\n` +
      `export const DEV_RECORDER_BUNDLE = ${JSON.stringify(js)};\n`,
    "utf-8",
  );
  console.log(
    `Wrote ${OUT_FILE} (${
      Math.round(js.length / 1024)
    } KB of bundled JS from ${sources.length} sources)`,
  );
}

#!/usr/bin/env npx tsx
/**
 * Regenerate cli/wmill.schema.json from CONFIG_REFERENCE.
 *
 * Run after adding or modifying config options in src/commands/init/template.ts:
 *   npx tsx generate-schema.ts
 */
import { writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { generateJsonSchema } from "./src/commands/init/template.ts";

const dir = dirname(fileURLToPath(import.meta.url));
const out = join(dir, "wmill.schema.json");
writeFileSync(out, JSON.stringify(generateJsonSchema(), null, 2) + "\n");
console.log(`Wrote ${out}`);

// `wmill lint` imports windmill-yaml-validator from source, and its schemas are generated
// from this checkout's OpenAPI specs. Regenerating them on every install is what keeps lint
// from validating against a schema older than the code being linted.

import { spawnSync } from "node:child_process";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import { readFileSync } from "node:fs";
import path from "node:path";

const validatorDir = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  "windmill-yaml-validator"
);

function npm(args) {
  const result = spawnSync("npm", args, {
    cwd: validatorDir,
    stdio: "inherit",
    shell: process.platform === "win32",
  });
  if (result.status !== 0) {
    process.exit(result.status ?? 1);
  }
}

// Read the names off the manifest: these resolve only from the validator's own
// node_modules, so a dependency added later must not be able to slip past this probe.
const manifestPath = path.join(validatorDir, "package.json");
const require = createRequire(manifestPath);
const deps = Object.keys(
  JSON.parse(readFileSync(manifestPath, "utf8")).dependencies ?? {}
);
const hasDeps = deps.every((pkg) => {
  try {
    require.resolve(pkg);
    return true;
  } catch {
    return false;
  }
});

// --omit=dev keeps the validator's test toolchain off the CLI's install path; skipping the
// install entirely when the deps already resolve keeps it from pruning a full install made
// by someone working on the validator itself.
if (!hasDeps) {
  npm(["install", "--omit=dev", "--no-audit", "--no-fund", "--loglevel=error"]);
}

npm(["run", "gen"]);

import { requireLogin } from "../../core/auth.ts";
import { resolveWorkspace, validatePath } from "../../core/context.ts";
import { Command } from "@cliffy/command";
import { Table } from "@cliffy/table";
import { colors } from "@cliffy/ansi/colors";
import * as log from "../../core/log.ts";
import { sep as SEP, isAbsolute, resolve as pathResolve, relative as pathRelative, basename } from "node:path";
