// Postgres wire-protocol helpers used by `wmill datatable serve`.
//
// pg-gateway handles the startup/auth handshake for us, but it leaves
// query-response framing (RowDescription / DataRow / CommandComplete /
// ReadyForQuery) to the caller. The functions below build those four
// messages from a `RawOutputEnvelope` returned by the backend.
//
// References:
//   https://www.postgresql.org/docs/current/protocol-message-formats.html

const TEXT_OID = 25;

export interface RawOutputColumn {
  name: string;
  oid: number;
  type_name: string;
}

export interface RawOutputEnvelope {
  columns: RawOutputColumn[];
  rows: (string | null)[][];
}

export interface ExecuteResponse {
  message: Uint8Array;
  nextRowOffset: number;
  suspended: boolean;
}

const encoder = new TextEncoder();

/**
 * Build a single backend message: one type byte, a 4-byte length (covering
 * the length field itself but not the type byte), then the payload.
 */
function buildMessage(type: number, payload: Uint8Array): Uint8Array {
  const out = new Uint8Array(1 + 4 + payload.byteLength);
  out[0] = type;
  const len = 4 + payload.byteLength;
  out[1] = (len >>> 24) & 0xff;
  out[2] = (len >>> 16) & 0xff;
  out[3] = (len >>> 8) & 0xff;
  out[4] = len & 0xff;
  out.set(payload, 5);
  return out;
}

function writeInt16(buf: Uint8Array, offset: number, v: number): void {
  buf[offset] = (v >>> 8) & 0xff;
  buf[offset + 1] = v & 0xff;
}

function writeInt32(buf: Uint8Array, offset: number, v: number): void {
  buf[offset] = (v >>> 24) & 0xff;
  buf[offset + 1] = (v >>> 16) & 0xff;
  buf[offset + 2] = (v >>> 8) & 0xff;
  buf[offset + 3] = v & 0xff;
}

/**
 * RowDescription ('T'): for each column, emit
 *   name CSTRING, tableOid INT32, attnum INT16,
 *   typeOid INT32, typeSize INT16, typeMod INT32, formatCode INT16
 *
 * We don't know the underlying table/attnum (the value travels through JSON,
 * not directly from the prepared statement), so we send 0 — psql is fine with
 * that. Format code 0 means "text" — we'll send DataRow values as UTF-8 bytes.
 */
export function buildRowDescription(columns: RawOutputColumn[]): Uint8Array {
  const fields = columns.map((col) => {
    const nameBytes = encoder.encode(col.name);
    const buf = new Uint8Array(nameBytes.byteLength + 1 + 4 + 2 + 4 + 2 + 4 + 2);
    let off = 0;
    buf.set(nameBytes, off);
    off += nameBytes.byteLength;
    buf[off++] = 0; // CSTRING terminator
    writeInt32(buf, off, 0); off += 4; // tableOid
    writeInt16(buf, off, 0); off += 2; // attnum
    writeInt32(buf, off, col.oid || TEXT_OID); off += 4; // typeOid (fall back to text)
    writeInt16(buf, off, -1); off += 2; // typeSize (-1 = variable)
    writeInt32(buf, off, -1); off += 4; // atttypmod
    writeInt16(buf, off, 0); off += 2; // format = text
    return buf;
  });
  const totalLen = 2 + fields.reduce((s, f) => s + f.byteLength, 0);
  const payload = new Uint8Array(totalLen);
  writeInt16(payload, 0, columns.length);
  let off = 2;
  for (const f of fields) {
    payload.set(f, off);
    off += f.byteLength;
  }
  return buildMessage(0x54 /* 'T' */, payload);
}

/**
 * DataRow ('D'): INT16 column count, then for each column either
 *   INT32 -1   (NULL)
 * or
 *   INT32 length + UTF-8 bytes
 */
export function buildDataRow(row: (string | null)[]): Uint8Array {
  const encoded = row.map((v) => (v === null ? null : encoder.encode(v)));
  const total =
    2 + encoded.reduce((s, e) => s + 4 + (e === null ? 0 : e.byteLength), 0);
  const payload = new Uint8Array(total);
  writeInt16(payload, 0, row.length);
  let off = 2;
  for (const e of encoded) {
    if (e === null) {
      writeInt32(payload, off, -1);
      off += 4;
    } else {
      writeInt32(payload, off, e.byteLength);
      off += 4;
      payload.set(e, off);
      off += e.byteLength;
    }
  }
  return buildMessage(0x44 /* 'D' */, payload);
}

/**
 * CommandComplete ('C'): null-terminated tag like "SELECT 12".
 * We always send SELECT-tagged completions — psql doesn't validate the tag
 * against the actual statement kind, so SET/CREATE/etc. just show as "SELECT 0".
 */
export function buildCommandComplete(tag: string): Uint8Array {
  const tagBytes = encoder.encode(tag);
  const payload = new Uint8Array(tagBytes.byteLength + 1);
  payload.set(tagBytes, 0);
  payload[tagBytes.byteLength] = 0;
  return buildMessage(0x43 /* 'C' */, payload);
}

/** ReadyForQuery ('Z') with the transaction-status indicator byte. */
export function buildReadyForQuery(status: "I" | "T" | "E" = "I"): Uint8Array {
  const payload = new Uint8Array(1);
  payload[0] = status.charCodeAt(0);
  return buildMessage(0x5a /* 'Z' */, payload);
}

/** EmptyQueryResponse ('I') with no payload. */
export function buildEmptyQueryResponse(): Uint8Array {
  return buildMessage(0x49 /* 'I' */, new Uint8Array(0));
}

/** ParseComplete ('1') with no payload. */
export function buildParseComplete(): Uint8Array {
  return buildMessage(0x31 /* '1' */, new Uint8Array(0));
}

/** BindComplete ('2') with no payload. */
export function buildBindComplete(): Uint8Array {
  return buildMessage(0x32 /* '2' */, new Uint8Array(0));
}

/** CloseComplete ('3') with no payload. */
export function buildCloseComplete(): Uint8Array {
  return buildMessage(0x33 /* '3' */, new Uint8Array(0));
}

/** NoData ('n') with no payload. */
export function buildNoData(): Uint8Array {
  return buildMessage(0x6e /* 'n' */, new Uint8Array(0));
}

/** PortalSuspended ('s') with no payload. */
export function buildPortalSuspended(): Uint8Array {
  return buildMessage(0x73 /* 's' */, new Uint8Array(0));
}

/** ParameterDescription ('t'): INT16 count + one INT32 OID per parameter. */
export function buildParameterDescription(typeOids: number[]): Uint8Array {
  const payload = new Uint8Array(2 + typeOids.length * 4);
  writeInt16(payload, 0, typeOids.length);
  let off = 2;
  for (const oid of typeOids) {
    writeInt32(payload, off, oid);
    off += 4;
  }
  return buildMessage(0x74 /* 't' */, payload);
}

/**
 * Translate a `RawOutputEnvelope` into the byte stream a Postgres client
 * expects in response to a Query message: RowDescription, one DataRow per
 * row, CommandComplete, ReadyForQuery.
 *
 * If there are no columns AND no rows, we treat the statement as a no-op
 * (e.g. `SET client_encoding`) and emit only CommandComplete + ReadyForQuery,
 * skipping RowDescription. psql is fine with either shape.
 */
export function buildQueryResponse(envelope: RawOutputEnvelope): Uint8Array {
  const parts: Uint8Array[] = [];
  if (envelope.columns.length > 0) {
    parts.push(buildRowDescription(envelope.columns));
    for (const row of envelope.rows) {
      parts.push(buildDataRow(row));
    }
  }
  parts.push(buildCommandComplete(`SELECT ${envelope.rows.length}`));
  parts.push(buildReadyForQuery("I"));
  return concat(parts);
}

export function buildExecuteResponse(
  envelope: RawOutputEnvelope,
  opts?: {
    includeRowDescription?: boolean;
    maxRows?: number;
    rowOffset?: number;
  },
): ExecuteResponse {
  const includeRowDescription = opts?.includeRowDescription ?? true;
  const maxRows = opts?.maxRows ?? 0;
  const rowOffset = opts?.rowOffset ?? 0;
  const remainingRows = envelope.rows.slice(rowOffset);
  const suspended = maxRows > 0 && remainingRows.length > maxRows;
  const rowsToSend = suspended ? remainingRows.slice(0, maxRows) : remainingRows;

  const parts: Uint8Array[] = [];
  if (includeRowDescription && envelope.columns.length > 0) {
    parts.push(buildRowDescription(envelope.columns));
  }
  for (const row of rowsToSend) {
    parts.push(buildDataRow(row));
  }
  if (suspended) {
    parts.push(buildPortalSuspended());
  } else {
    parts.push(buildCommandComplete(`SELECT ${envelope.rows.length}`));
  }

  return {
    message: concat(parts),
    nextRowOffset: rowOffset + rowsToSend.length,
    suspended,
  };
}

export function concat(parts: Uint8Array[]): Uint8Array {
  const total = parts.reduce((s, p) => s + p.byteLength, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.byteLength;
  }
  return out;
}

import { colors } from "@cliffy/ansi/colors";
import { spawn } from "node:child_process";

import * as log from "../../core/log.ts";
import { startServe, type ServeOpts } from "./serve.ts";

export interface PsqlOpts extends ServeOpts {
  name?: string;
}

const DEFAULT_DATATABLE_NAME = "main";

export async function psql(opts: PsqlOpts): Promise<void> {
  const datatableName = opts.name ?? DEFAULT_DATATABLE_NAME;
  const handle = await startServe(opts);
  const connectionString = handle.connectionString(datatableName);

  log.info(
    colors.gray(
      `Launching psql against datatable '${datatableName}' (proxy on ${handle.host}:${handle.port})`,
    ),
  );

  const child = spawn("psql", [connectionString], {
    stdio: "inherit",
  });

  // If psql isn't installed, surface that cleanly instead of a stack trace.
  child.on("error", (err) => {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOENT") {
      log.error(
        "psql not found in PATH. Install the postgresql client (e.g. `apt install postgresql-client`, `brew install libpq`) and try again.",
      );
    } else {
      log.error(`failed to launch psql: ${err.message}`);
    }
    handle.close().finally(() => process.exit(1));
  });

  const exitCode = await new Promise<number>((resolve) => {
    child.on("exit", (code, signal) => {
      // Mirror shell convention: signal N → 128 + N.
      if (signal && typeof signal === "string") {
        const num = signalToNumber(signal);
        resolve(num !== undefined ? 128 + num : 1);
      } else {
        resolve(code ?? 0);
      }
    });
  });

  await handle.close();
  process.exit(exitCode);
}

function signalToNumber(name: string): number | undefined {
  const table: Record<string, number> = {
    SIGINT: 2,
    SIGQUIT: 3,
    SIGTERM: 15,
    SIGHUP: 1,
    SIGKILL: 9,
  };
  return table[name];
}

import { colors } from "@cliffy/ansi/colors";
import { createServer, type Socket } from "node:net";
import { randomBytes } from "node:crypto";
import * as getPort from "get-port";
import { BackendError, createPreHashedPassword } from "pg-gateway";
import { fromNodeSocket } from "pg-gateway/node";

import * as wmill from "../../../gen/services.gen.ts";
import { requireLogin } from "../../core/auth.ts";
import { resolveWorkspace } from "../../core/context.ts";
import * as log from "../../core/log.ts";
import { GlobalOptions } from "../../types.ts";
import { pollJobWithQueueLogging } from "../../utils/job_polling.ts";
import {
  buildBindComplete,
  buildCloseComplete,
  buildEmptyQueryResponse,
  buildExecuteResponse,
  buildNoData,
  buildParameterDescription,
  buildParseComplete,
  buildQueryResponse,
  buildReadyForQuery,
  buildRowDescription,
  concat,
  type RawOutputEnvelope,
} from "./pg_wire.ts";
import {
  queryTouchesVirtualDatabaseCatalog,
  virtualizeDatabaseCatalogQuery,
} from "./virtual_catalog.ts";

const DEFAULT_USER = "wmill";
const DEFAULT_PORT_RANGE_START = 5433;
const DEFAULT_PORT_RANGE_END = 5500;

export interface ServeOpts extends GlobalOptions {
  port?: number;
  host?: string;
  password?: string;
}

export interface ServeHandle {
  host: string;
  port: number;
  user: string;
  password: string;
  /** Build a `postgresql://…/<dbName>` URL for a given datatable name. */
  connectionString: (datatableName: string) => string;
  close: () => Promise<void>;
}

interface PreparedStatementState {
  query: string;
  parameterTypeOids: number[];
}

interface PortalState {
  query: string;
  resultFormatCodes: number[];
  parameterTypeOids: number[];
  parameterSqlExpressions: string[];
  envelope?: RawOutputEnvelope;
  rowOffset: number;
  sentRowDescription: boolean;
}

/**
 * Bind the Postgres-wire proxy and return once it's accepting connections.
 * Each client connection picks its target datatable via the standard
 * Postgres `database` startup parameter (the `…/dbname` segment of the URL),
 * so the same listener can multiplex any number of datatables — and clients
 * like pgAdmin list them as separate databases instead of one shared "main".
 *
 * Caller owns `handle.close()`. Used by both `serve` (block on signal) and
 * `psql` (block on child process exit).
 */
export async function startServe(opts: ServeOpts): Promise<ServeHandle> {
  const host = opts.host ?? "127.0.0.1";

  const workspace = await resolveWorkspace(opts);
  await requireLogin(opts);

  const port =
    opts.port ??
    (await (getPort as any).default({
      port: (getPort as any).portNumbers(
        DEFAULT_PORT_RANGE_START,
        DEFAULT_PORT_RANGE_END,
      ),
    }));

  const password = opts.password ?? randomBytes(12).toString("hex");
  const preHashedPassword = await createPreHashedPassword(
    DEFAULT_USER,
    password,
  );

  const server = createServer((socket) => {
    handleConnection(socket, workspace.workspaceId, preHashedPassword)
      .catch((err) => {
        log.warn(
          colors.yellow(
            `connection error: ${err instanceof Error ? err.message : err}`,
          ),
        );
        try {
          socket.destroy();
        } catch {
          // ignore
        }
      });
  });

  server.on("error", (err) => {
    log.error(`server error: ${err.message}`);
    process.exitCode = 1;
  });

  await new Promise<void>((resolve) => server.listen(port, host, () => resolve()));

  return {
    host,
    port,
    user: DEFAULT_USER,
    password,
    connectionString: (datatableName: string) =>
      `postgresql://${DEFAULT_USER}:${encodeURIComponent(password)}@${host}:${port}/${encodeURIComponent(datatableName)}`,
    close: () =>
      new Promise<void>((resolve) => {
        server.close(() => resolve());
        // Force-resolve if open client connections keep the server from closing.
        setTimeout(resolve, 1000).unref();
      }),
  };
}

export async function serve(opts: ServeOpts): Promise<void> {
  const handle = await startServe(opts);

  // List available datatables so the user sees what they can `\c` into.
  const workspace = await resolveWorkspace(opts);
  let datatableNames: string[] = [];
  try {
    const items = await wmill.listDataTables({
      workspace: workspace.workspaceId,
    });
    datatableNames = items.map((x) => x.name);
  } catch {
    // Listing is best-effort — the proxy still serves whatever the client asks for.
  }

  log.info(colors.gray(`Serving datatables on ${handle.host}:${handle.port} via Postgres wire protocol`));
  log.info("");
  if (datatableNames.length > 0) {
    log.info(colors.gray("Available datatables:"));
    for (const name of datatableNames) {
      log.info(`  ${colors.bold("psql")} '${handle.connectionString(name)}'`);
    }
  } else {
    log.info(
      `  ${colors.bold("psql")} '${handle.connectionString("<datatable_name>")}'`,
    );
  }
  log.info("");
  log.info(colors.gray("Press Ctrl+C to stop."));

  const shutdown = () => {
    log.info(colors.gray("\nShutting down..."));
    handle.close().finally(() => process.exit(0));
    // Force-exit if connections linger.
    setTimeout(() => process.exit(0), 1000).unref();
  };
  process.once("SIGINT", shutdown);
  process.once("SIGTERM", shutdown);

  await new Promise<void>(() => {});
}

async function handleConnection(
  socket: Socket,
  workspaceId: string,
  preHashedPassword: string,
): Promise<void> {
  const preparedStatements = new Map<string, PreparedStatementState>();
  const portals = new Map<string, PortalState>();
  let waitingForSyncAfterError = false;

  await fromNodeSocket(socket, {
    auth: {
      method: "md5",
      // Same pre-hashed value regardless of the username the client sends.
      // Postgres's md5 auth derives preHashedPassword from `password + username`,
      // so a client connecting as anything other than DEFAULT_USER will produce
      // a different client-side hash and fail validation — effectively locking
      // the listener to DEFAULT_USER.
      getPreHashedPassword: async () => preHashedPassword,
    },
    // pg-gateway 0.3.0-beta.4 declares `onQuery` in its TypeScript types but
    // never actually invokes it — every frontend message goes through
    // `onMessage`, and unhandled codes fall through to a default handler that
    // returns "Message code not yet implemented". We handle the Query ('Q')
    // message ourselves and only intercept post-auth messages so the library
    // still drives the startup/auth handshake.
    onMessage: async (data, state) => {
      if (state.step !== "ReadyForQuery") return undefined;
      const code = data[0];
      if (code === FE_TERMINATE) {
        return undefined; // let pg-gateway close the connection
      }
      // Standard Postgres startup includes a `database` parameter — that's the
      // path segment in the URL (`postgresql://…/<dbname>`). pg-gateway exposes
      // it under clientParams; we use it to route the query to the matching
      // datatable. Falling back to the user name matches libpq's own default.
      const datatableName =
        state.clientParams?.database ?? state.clientParams?.user ?? "main";
      if (waitingForSyncAfterError) {
        if (code === FE_SYNC) {
          waitingForSyncAfterError = false;
          return buildReadyForQuery("I");
        }
        return new Uint8Array(0);
      }

      try {
        switch (code) {
          case FE_QUERY:
            return await runQuery(workspaceId, datatableName, readSimpleQuery(data));
          case FE_PARSE:
            return handleParseMessage(data, preparedStatements, portals);
          case FE_BIND:
            return handleBindMessage(data, preparedStatements, portals);
          case FE_DESCRIBE:
            return await handleDescribeMessage(
              data,
              preparedStatements,
              portals,
              (query) => runQueryEnvelope(workspaceId, datatableName, query),
            );
          case FE_EXECUTE:
            return await handleExecuteMessage(
              data,
              portals,
              (query) => runQueryEnvelope(workspaceId, datatableName, query),
            );
          case FE_CLOSE:
            return handleCloseMessage(data, preparedStatements, portals);
          case FE_FLUSH:
            return new Uint8Array(0);
          case FE_SYNC:
            return buildReadyForQuery("I");
          default:
            throw createPgProtocolError(
              `Postgres message code 0x${code.toString(16).padStart(2, "0")} is not supported by 'wmill datatable serve'`,
              "0A000",
            );
        }
      } catch (err) {
        const includeReadyForQuery = code === FE_QUERY;
        waitingForSyncAfterError = !includeReadyForQuery;
        return buildPgErrorResponse(err, includeReadyForQuery);
      }
    },
  });
}

const FE_QUERY = 0x51; // 'Q'
const FE_PARSE = 0x50; // 'P'
const FE_BIND = 0x42; // 'B'
const FE_CLOSE = 0x43; // 'C'
const FE_DESCRIBE = 0x44; // 'D'
const FE_EXECUTE = 0x45; // 'E'
const FE_FLUSH = 0x48; // 'H'
const FE_SYNC = 0x53; // 'S'
const FE_TERMINATE = 0x58; // 'X'

type PgProtocolError = Error & { pgCode?: string };

const textDecoder = new TextDecoder();

class FrontendMessageReader {
  constructor(
    private readonly data: Uint8Array,
    private offset = 5,
  ) {}

  byte(): number {
    return this.data[this.offset++] ?? 0;
  }

  int16(): number {
    const view = new DataView(
      this.data.buffer,
      this.data.byteOffset,
      this.data.byteLength,
    );
    const value = view.getInt16(this.offset);
    this.offset += 2;
    return value;
  }

  int32(): number {
    const view = new DataView(
      this.data.buffer,
      this.data.byteOffset,
      this.data.byteLength,
    );
    const value = view.getInt32(this.offset);
    this.offset += 4;
    return value;
  }

  cstring(): string {
    const start = this.offset;
    while (this.offset < this.data.length && this.data[this.offset] !== 0) {
      this.offset += 1;
    }
    const value = textDecoder.decode(this.data.subarray(start, this.offset));
    this.offset += 1;
    return value;
  }

  bytes(length: number): Uint8Array {
    const value = this.data.subarray(this.offset, this.offset + length);
    this.offset += length;
    return value;
  }
}

/**
 * Decode a simple-query message: 'Q', INT32 length (incl. itself), then a
 * null-terminated UTF-8 string.
 */
function readSimpleQuery(data: Uint8Array): string {
  const length =
    (data[1] << 24) | (data[2] << 16) | (data[3] << 8) | data[4];
  // Strip the trailing null byte.
  const queryBytes = data.subarray(5, 1 + length - 1);
  return textDecoder.decode(queryBytes);
}

function readParseMessage(data: Uint8Array): {
  statementName: string;
  query: string;
  parameterTypeOids: number[];
} {
  const reader = new FrontendMessageReader(data);
  const statementName = reader.cstring();
  const query = reader.cstring();
  const parameterCount = reader.int16();
  const parameterTypeOids = Array.from({ length: parameterCount }, () =>
    reader.int32(),
  );
  return { statementName, query, parameterTypeOids };
}

function readBindMessage(data: Uint8Array): {
  portalName: string;
  statementName: string;
  parameterFormatCodes: number[];
  parameters: (Uint8Array | null)[];
  resultFormatCodes: number[];
} {
  const reader = new FrontendMessageReader(data);
  const portalName = reader.cstring();
  const statementName = reader.cstring();
  const parameterFormatCodeCount = reader.int16();
  const parameterFormatCodes = Array.from(
    { length: parameterFormatCodeCount },
    () => reader.int16(),
  );
  const parameterCount = reader.int16();
  const parameters = Array.from({ length: parameterCount }, () => {
    const length = reader.int32();
    return length === -1 ? null : reader.bytes(length);
  });
  const resultFormatCodeCount = reader.int16();
  const resultFormatCodes = Array.from(
    { length: resultFormatCodeCount },
    () => reader.int16(),
  );
  return {
    portalName,
    statementName,
    parameterFormatCodes,
    parameters,
    resultFormatCodes,
  };
}

function readDescribeMessage(data: Uint8Array): {
  targetType: "P" | "S";
  name: string;
} {
  const reader = new FrontendMessageReader(data);
  const targetType = String.fromCharCode(reader.byte()) as "P" | "S";
  return { targetType, name: reader.cstring() };
}

function readExecuteMessage(data: Uint8Array): {
  portalName: string;
  maxRows: number;
} {
  const reader = new FrontendMessageReader(data);
  return { portalName: reader.cstring(), maxRows: reader.int32() };
}

function readCloseMessage(data: Uint8Array): {
  targetType: "P" | "S";
  name: string;
} {
  const reader = new FrontendMessageReader(data);
  const targetType = String.fromCharCode(reader.byte()) as "P" | "S";
  return { targetType, name: reader.cstring() };
}

function handleParseMessage(
  data: Uint8Array,
  preparedStatements: Map<string, PreparedStatementState>,
  portals: Map<string, PortalState>,
): Uint8Array {
  const parse = readParseMessage(data);
  preparedStatements.set(parse.statementName, {
    query: parse.query,
    parameterTypeOids: parse.parameterTypeOids,
  });
  if (parse.statementName === "") {
    portals.delete("");
  }
  return buildParseComplete();
}

function handleBindMessage(
  data: Uint8Array,
  preparedStatements: Map<string, PreparedStatementState>,
  portals: Map<string, PortalState>,
): Uint8Array {
  const bind = readBindMessage(data);
  const statement = preparedStatements.get(bind.statementName);
  if (!statement) {
    throw createPgProtocolError(
      `prepared statement ${formatProtocolName(bind.statementName, "statement")} does not exist`,
      "26000",
    );
  }
  for (let i = 0; i < bind.parameters.length; i += 1) {
    if (bind.parameters[i] !== null && resolveParameterFormatCode(bind.parameterFormatCodes, i) !== 0) {
      throw createPgProtocolError(
        "binary parameter formats are not supported by 'wmill datatable serve'",
        "0A000",
      );
    }
  }
  if (bind.resultFormatCodes.some((code) => code !== 0)) {
    throw createPgProtocolError(
      "binary result formats are not supported by 'wmill datatable serve'",
      "0A000",
    );
  }
  portals.set(bind.portalName, {
    query: statement.query,
    resultFormatCodes: bind.resultFormatCodes,
    parameterTypeOids: statement.parameterTypeOids,
    parameterSqlExpressions: bind.parameters.map(sqlExpressionForBoundParameter),
    rowOffset: 0,
    sentRowDescription: false,
  });
  return buildBindComplete();
}

async function handleDescribeMessage(
  data: Uint8Array,
  preparedStatements: Map<string, PreparedStatementState>,
  portals: Map<string, PortalState>,
  executeQuery: (query: string) => Promise<RawOutputEnvelope>,
): Promise<Uint8Array> {
  const describe = readDescribeMessage(data);
  if (describe.targetType === "S") {
    const statement = preparedStatements.get(describe.name);
    if (!statement) {
      throw createPgProtocolError(
        `prepared statement ${formatProtocolName(describe.name, "statement")} does not exist`,
        "26000",
      );
    }
    if (
      statement.parameterTypeOids.length === 0 &&
      isQueryLikelySafeToDescribe(statement.query)
    ) {
      const envelope = await executeQuery(statement.query);
      return concat([
        buildParameterDescription(statement.parameterTypeOids),
        envelope.columns.length > 0
          ? buildRowDescription(envelope.columns)
          : buildNoData(),
      ]);
    }
    return concat([
      buildParameterDescription(statement.parameterTypeOids),
      buildNoData(),
    ]);
  }

  const portal = portals.get(describe.name);
  if (!portal) {
    throw createPgProtocolError(
      `portal ${formatProtocolName(describe.name, "portal")} does not exist`,
      "34000",
    );
  }

  if (!portal.envelope && isQueryLikelySafeToDescribe(portal.query)) {
    portal.envelope = await executeQuery(buildPortalQuery(portal));
  }
  if (portal.envelope?.columns.length) {
    portal.sentRowDescription = true;
    return buildRowDescription(portal.envelope.columns);
  }
  return buildNoData();
}

async function handleExecuteMessage(
  data: Uint8Array,
  portals: Map<string, PortalState>,
  executeQuery: (query: string) => Promise<RawOutputEnvelope>,
): Promise<Uint8Array> {
  const execute = readExecuteMessage(data);
  const portal = portals.get(execute.portalName);
  if (!portal) {
    throw createPgProtocolError(
      `portal ${formatProtocolName(execute.portalName, "portal")} does not exist`,
      "34000",
    );
  }
  if (portal.resultFormatCodes.some((code) => code !== 0)) {
    throw createPgProtocolError(
      "binary result formats are not supported by 'wmill datatable serve'",
      "0A000",
    );
  }
  if (portal.query.trim().length === 0) {
    return buildEmptyQueryResponse();
  }
  if (!portal.envelope) {
    portal.envelope = await executeQuery(buildPortalQuery(portal));
  }

  const response = buildExecuteResponse(portal.envelope, {
    includeRowDescription: !portal.sentRowDescription,
    maxRows: execute.maxRows,
    rowOffset: portal.rowOffset,
  });

  portal.sentRowDescription = true;
  if (response.suspended) {
    portal.rowOffset = response.nextRowOffset;
  } else {
    portal.envelope = undefined;
    portal.rowOffset = 0;
    portal.sentRowDescription = false;
  }

  return response.message;
}

function handleCloseMessage(
  data: Uint8Array,
  preparedStatements: Map<string, PreparedStatementState>,
  portals: Map<string, PortalState>,
): Uint8Array {
  const close = readCloseMessage(data);
  if (close.targetType === "S") {
    preparedStatements.delete(close.name);
  } else {
    portals.delete(close.name);
  }
  return buildCloseComplete();
}

function createPgProtocolError(message: string, pgCode = "XX000"): PgProtocolError {
  const err = new Error(message) as PgProtocolError;
  err.pgCode = pgCode;
  return err;
}

function resolveParameterFormatCode(formatCodes: number[], index: number): number {
  if (formatCodes.length === 0) return 0;
  if (formatCodes.length === 1) return formatCodes[0] ?? 0;
  return formatCodes[index] ?? 0;
}

function sqlExpressionForBoundParameter(value: Uint8Array | null): string {
  if (value === null) {
    return "NULL";
  }
  return sqlStringLiteral(textDecoder.decode(value));
}

function sqlStringLiteral(value: string): string {
  return `'${value.replaceAll("'", "''")}'`;
}

function buildPortalQuery(portal: PortalState): string {
  if (portal.parameterSqlExpressions.length === 0) {
    return portal.query;
  }

  const trimmedQuery = portal.query.replace(/;+\s*$/, "");
  const typeList = buildPreparedStatementTypeList(portal.parameterTypeOids);
  return [
    `PREPARE "__wmill_proxy_stmt"${typeList} AS ${trimmedQuery};`,
    `EXECUTE "__wmill_proxy_stmt"(${portal.parameterSqlExpressions.join(", ")});`,
  ].join("\n");
}

function buildPreparedStatementTypeList(parameterTypeOids: number[]): string {
  if (parameterTypeOids.length === 0) {
    return "";
  }

  const typeNames = parameterTypeOids.map(postgresTypeNameFromOid);
  if (typeNames.some((name) => name === undefined)) {
    return "";
  }

  return `(${typeNames.join(", ")})`;
}

function postgresTypeNameFromOid(oid: number): string | undefined {
  switch (oid) {
    case 16:
      return "pg_catalog.bool";
    case 17:
      return "pg_catalog.bytea";
    case 19:
      return "pg_catalog.name";
    case 20:
      return "pg_catalog.int8";
    case 21:
      return "pg_catalog.int2";
    case 23:
      return "pg_catalog.int4";
    case 25:
      return "pg_catalog.text";
    case 26:
      return "pg_catalog.oid";
    case 700:
      return "pg_catalog.float4";
    case 701:
      return "pg_catalog.float8";
    case 1042:
      return "pg_catalog.bpchar";
    case 1043:
      return "pg_catalog.varchar";
    case 1082:
      return "pg_catalog.date";
    case 1083:
      return "pg_catalog.time";
    case 1114:
      return "pg_catalog.timestamp";
    case 1184:
      return "pg_catalog.timestamptz";
    case 1266:
      return "pg_catalog.timetz";
    case 1700:
      return "pg_catalog.numeric";
    case 2950:
      return "pg_catalog.uuid";
    case 114:
      return "pg_catalog.json";
    case 3802:
      return "pg_catalog.jsonb";
    default:
      return undefined;
  }
}

function isQueryLikelySafeToDescribe(query: string): boolean {
  let normalized = query.trimStart();
  while (true) {
    if (normalized.startsWith("--")) {
      const newlineIndex = normalized.indexOf("\n");
      normalized =
        newlineIndex === -1
          ? ""
          : normalized.slice(newlineIndex + 1).trimStart();
      continue;
    }
    if (normalized.startsWith("/*")) {
      const commentEnd = normalized.indexOf("*/");
      normalized =
        commentEnd === -1
          ? ""
          : normalized.slice(commentEnd + 2).trimStart();
      continue;
    }
    break;
  }
  normalized = normalized.toLowerCase();

  return (
    normalized.startsWith("select") ||
    normalized.startsWith("with") ||
    normalized.startsWith("show") ||
    normalized.startsWith("values") ||
    normalized.startsWith("table")
  );
}

function buildPgErrorResponse(
  err: unknown,
  includeReadyForQuery: boolean,
): Uint8Array {
  const error = err instanceof Error ? err : new Error(String(err ?? "unknown error"));
  const parts = [
    BackendError.create({
      severity: "ERROR",
      code: (error as PgProtocolError).pgCode ?? "XX000",
      message: error.message,
    }).flush(),
  ];
  if (includeReadyForQuery) {
    parts.push(buildReadyForQuery("I"));
  }
  return concat(parts);
}

function formatProtocolName(name: string, kind: "portal" | "statement"): string {
  if (name.length === 0) {
    return kind === "portal" ? "<unnamed portal>" : "<unnamed statement>";
  }
  return `"${name}"`;
}

async function runQuery(
  workspaceId: string,
  datatableName: string,
  query: string,
): Promise<Uint8Array> {
  const trimmed = query.trim();
  if (trimmed.length === 0) {
    return concat([buildEmptyQueryResponse(), buildReadyForQuery("I")]);
  }

  const envelope = await runQueryEnvelope(workspaceId, datatableName, query);
  return buildQueryResponse(envelope);
}

async function runQueryEnvelope(
  workspaceId: string,
  datatableName: string,
  query: string,
): Promise<RawOutputEnvelope> {
  const trimmed = query.trim();
  if (trimmed.length === 0) {
    return { columns: [], rows: [] };
  }

  // The annotation parser stops at the first non-blank line that isn't a
  // `--` comment, so prepending guarantees it's honored even if the client
  // sent leading comments of its own.
  const content = `-- raw_output\n${await prepareQueryForDatatableProxy(
    workspaceId,
    datatableName,
    query,
  )}`;

  const jobId = await wmill.runScriptPreview({
    workspace: workspaceId,
    requestBody: {
      content,
      language: "postgresql",
      args: { database: `datatable://${datatableName}` },
    },
  });

  const { result, success } = await pollJobWithQueueLogging(workspaceId, jobId);

  if (!success) {
    throw createPgProtocolError(extractErrorMessage(result));
  }

  return coerceEnvelope(result);
}

async function prepareQueryForDatatableProxy(
  workspaceId: string,
  datatableName: string,
  query: string,
): Promise<string> {
  if (!queryTouchesVirtualDatabaseCatalog(query)) {
    return query;
  }

  let databaseNames = [datatableName];
  if (query.toLowerCase().includes("pg_database")) {
    try {
      const items = await wmill.listDataTables({
        workspace: workspaceId,
      });
      databaseNames = Array.from(
        new Set([datatableName, ...items.map((item) => item.name)]),
      ).sort();
    } catch {
      // Fall back to the current datatable so catalog queries still stay virtual.
    }
  }

  return virtualizeDatabaseCatalogQuery(query, datatableName, databaseNames);
}

function extractErrorMessage(result: unknown): string {
  if (typeof result === "string") return result;
  if (result && typeof result === "object") {
    const obj = result as Record<string, unknown>;
    const err = obj.error;
    if (err && typeof err === "object") {
      const errObj = err as Record<string, unknown>;
      if (typeof errObj.message === "string") return errObj.message;
      if (typeof errObj.name === "string") return errObj.name;
    }
    if (typeof obj.message === "string") return obj.message;
  }
  return JSON.stringify(result);
}

/**
 * Validate that the worker returned the {columns, rows} envelope we asked for.
 * If the shape doesn't match (older backend, unexpected error shape), fall back
 * to an empty result — better than throwing inside the wire-protocol layer.
 */
function coerceEnvelope(result: unknown): RawOutputEnvelope {
  if (
    result &&
    typeof result === "object" &&
    "columns" in result &&
    "rows" in result &&
    Array.isArray((result as any).columns) &&
    Array.isArray((result as any).rows)
  ) {
    return result as RawOutputEnvelope;
  }
  return { columns: [], rows: [] };
}

const CURRENT_DATABASE_QUERY_RE = /\b(?:pg_catalog\.)?current_database\s*\(\s*\)/i;
const CURRENT_DATABASE_RE = /\b(?:pg_catalog\.)?current_database\s*\(\s*\)/gi;
const PG_DATABASE_RE = /\b(?:pg_catalog\.)?pg_database\b/i;
const PG_DATABASE_FROM_OR_JOIN_RE =
  /(\b(?:from|join)\s+(?:only\s+)?)(?:pg_catalog\.)?pg_database\b/gi;
const PG_DATABASE_COMMA_JOIN_RE = /(,\s*)(?:pg_catalog\.)?pg_database\b/gi;
const PG_SIZE_PRETTY_DATABASE_SIZE_RE =
  /\b(?:pg_catalog\.)?pg_size_pretty\s*\(\s*(?:pg_catalog\.)?pg_database_size\s*\((?:[^()]|\([^()]*\))*\)\s*\)/gi;
const PG_DATABASE_SIZE_RE =
  /\b(?:pg_catalog\.)?pg_database_size\s*\((?:[^()]|\([^()]*\))*\)/gi;
const HAS_DATABASE_PRIVILEGE_RE =
  /\b(?:pg_catalog\.)?has_database_privilege\s*\((?:[^()]|\([^()]*\))*\)/gi;
const PG_DATABASE_COLLATION_VERSION_RE =
  /\b(?:pg_catalog\.)?pg_database_collation_actual_version\s*\((?:[^()]|\([^()]*\))*\)/gi;

export function queryTouchesVirtualDatabaseCatalog(query: string): boolean {
  return CURRENT_DATABASE_QUERY_RE.test(query) || PG_DATABASE_RE.test(query);
}

export function virtualizeDatabaseCatalogQuery(
  query: string,
  currentDatabaseName: string,
  databaseNames: string[],
): string {
  let rewritten = query.replace(
    CURRENT_DATABASE_RE,
    sqlStringLiteral(currentDatabaseName),
  );

  if (!PG_DATABASE_RE.test(query)) {
    return rewritten;
  }

  const relation = buildVirtualPgDatabaseRelation(databaseNames);
  rewritten = rewritten
    .replace(PG_SIZE_PRETTY_DATABASE_SIZE_RE, "NULL::text")
    .replace(PG_DATABASE_SIZE_RE, "NULL::bigint")
    .replace(HAS_DATABASE_PRIVILEGE_RE, "true")
    .replace(PG_DATABASE_COLLATION_VERSION_RE, "NULL::text")
    .replace(PG_DATABASE_FROM_OR_JOIN_RE, `$1${relation}`)
    .replace(PG_DATABASE_COMMA_JOIN_RE, `$1${relation}`);

  return rewritten;
}

function buildVirtualPgDatabaseRelation(databaseNames: string[]): string {
  const names = Array.from(new Set(databaseNames));
  const arrayLiteral = names.map(sqlStringLiteral).join(", ");

  return `(
  SELECT
    (20000 + src.ordinality)::oid AS oid,
    src.datname,
    COALESCE((SELECT oid FROM pg_catalog.pg_roles WHERE rolname = CURRENT_USER LIMIT 1), 10::oid) AS datdba,
    pg_char_to_encoding(current_setting('server_encoding')) AS encoding,
    'c'::"char" AS datlocprovider,
    false AS datistemplate,
    true AS datallowconn,
    -1 AS datconnlimit,
    '0'::xid AS datfrozenxid,
    '1'::xid AS datminmxid,
    COALESCE((SELECT oid FROM pg_catalog.pg_tablespace WHERE spcname = 'pg_default' LIMIT 1), 1663::oid) AS dattablespace,
    current_setting('lc_collate') AS datcollate,
    current_setting('lc_ctype') AS datctype,
    NULL::text AS daticulocale,
    NULL::text AS daticurules,
    NULL::text AS datcollversion,
    NULL::aclitem[] AS datacl
  FROM unnest(ARRAY[${arrayLiteral}]::text[]) WITH ORDINALITY AS src(datname, ordinality)
)`;
}

function sqlStringLiteral(value: string): string {
  return `'${value.replaceAll("'", "''")}'`;
}

import * as fs from "node:fs";
import * as path from "node:path";
import * as log from "../core/log.ts";
import { colors } from "@cliffy/ansi/colors";
import * as wmill from "../../gen/services.gen.ts";
import { readTextFile } from "../utils/utils.ts";
import { Confirm } from "@cliffy/prompt/confirm";

// Migrations live under <cwd>/migrations/datatable/<datatable>/, one folder per
// target data table, as `<timestamp>_<name>.up.sql` (and optional `.down.sql`).
// They are synced as ordinary workspace files (see the workspace tarball export
// and the `datatable_migration` handling in sync.ts); this module only holds the
// `wmill datatable migrate` command helpers and the per-file push primitive.
const MIGRATIONS_DIR = path.join("migrations", "datatable");

// Migration names map directly onto file names and the DB `name` column.
const MIGRATION_NAME_RE = /^[a-zA-Z0-9_-]+$/;

/** Current UTC time as a YYYYMMDDHHMMSS migration version. */
function migrationTimestamp(): string {
  const d = new Date();
  const p = (n: number) => String(n).padStart(2, "0");
  return (
    `${d.getUTCFullYear()}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}` +
    `${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())}`
  );
}

/**
 * A migration version unique within a data table folder: the current UTC
 * timestamp bumped past any existing version, so two migrations scaffolded in
 * the same second don't collide on the `(datatable, timestamp)` identity used to
 * upsert them.
 */
function nextMigrationTimestamp(dir: string): string {
  const now = Number(migrationTimestamp());
  let max = 0;
  if (fs.existsSync(dir)) {
    for (const file of fs.readdirSync(dir)) {
      const m = file.match(/^(\d+)_.*\.(up|down)\.sql$/);
      if (m) max = Math.max(max, Number(m[1]));
    }
  }
  return String(max >= now ? max + 1 : now);
}

/**
 * Scaffold a new migration under migrations/datatable/<datatable>/ as empty
 * `<timestamp>_<name>.up.sql` and `.down.sql` files. Purely local — no network.
 */
export function createMigration(datatable: string, name: string): void {
  if (!MIGRATION_NAME_RE.test(name)) {
    throw new Error(
      `Invalid migration name '${name}': use only letters, digits, '_' and '-'`,
    );
  }
  const dir = path.join(process.cwd(), MIGRATIONS_DIR, datatable);
  fs.mkdirSync(dir, { recursive: true });

  const timestamp = nextMigrationTimestamp(dir);
  const base = `${timestamp}_${name}`;
  const up = path.join(dir, `${base}.up.sql`);
  const down = path.join(dir, `${base}.down.sql`);
  // Frame the body in an explicit transaction so it applies atomically, matching
  // the template the UI's "New migration" modal seeds.
  const template = (direction: string) =>
    `-- ${direction} migration: ${name}\nBEGIN;\n\n-- Add your migration here\n\nEND;\n`;
  fs.writeFileSync(up, template("up"), "utf-8");
  fs.writeFileSync(down, template("down"), "utf-8");

  log.info(
    colors.green(`Created migration ${base} in ${MIGRATIONS_DIR}/${datatable}/`),
  );
  for (const f of [up, down]) {
    log.info(colors.gray(`  ${path.relative(process.cwd(), f)}`));
  }
}

/**
 * Apply the workspace's pending migrations to a data table (forwards migrations
 * recorded in `_wm_migrations`). Mirrors `wmill datatable migrate up`.
 */
export async function runMigrations(
  workspace: string,
  datatableName: string,
): Promise<void> {
  const result = await wmill.runDatatableMigrations({
    workspace,
    datatableName,
  });
  const applied = result.applied ?? [];
  if (applied.length === 0) {
    log.info(colors.gray(`No pending migrations to run on '${datatableName}'`));
    return;
  }
  log.info(
    colors.green(`Applied ${applied.length} migration(s) to '${datatableName}':`),
  );
  for (const m of applied) {
    log.info(colors.gray(`  ${m.version} ${m.name}`));
  }
}

/**
 * Roll back the most recently applied migration on a data table (one step).
 * Mirrors `wmill datatable migrate down`.
 */
export async function rollbackMigrations(
  workspace: string,
  datatableName: string,
): Promise<void> {
  const result = await wmill.rollbackDatatableMigrations({
    workspace,
    datatableName,
  });
  const rolledBack = result.rolled_back ?? [];
  if (rolledBack.length === 0) {
    log.info(
      colors.gray(`No applied migrations to roll back on '${datatableName}'`),
    );
    return;
  }
  for (const m of rolledBack) {
    log.info(
      colors.green(`Rolled back migration ${m.version} ${m.name} on '${datatableName}'`),
    );
  }
}

/**
 * Validate the on-disk migration files for the given data tables (or all of
 * them when `datatables` is omitted). Returns a list of human-readable problems;
 * an empty list means the migrations are well-formed. Two states are invalid:
 *  - two up (or two down) files sharing the same timestamp, which collide on the
 *    `(datatable, timestamp)` identity used to upsert; and
 *  - a `.down.sql` with no matching `.up.sql` (an up file is mandatory).
 */
export function validateLocalMigrations(datatables?: Set<string>): string[] {
  const errors: string[] = [];
  const root = path.join(process.cwd(), MIGRATIONS_DIR);
  if (!fs.existsSync(root)) return errors;

  for (const datatable of fs.readdirSync(root)) {
    if (datatables && !datatables.has(datatable)) continue;
    const dtDir = path.join(root, datatable);
    if (!fs.statSync(dtDir).isDirectory()) continue;

    const upNamesByTs = new Map<number, string[]>();
    const downNamesByTs = new Map<number, string[]>();
    const upBases = new Set<string>();
    const downBases: { ts: number; name: string }[] = [];

    for (const file of fs.readdirSync(dtDir)) {
      const m = file.match(/^(\d+)_(.*)\.(up|down)\.sql$/);
      if (!m) continue;
      const ts = Number(m[1]);
      const name = m[2];
      if (m[3] === "up") {
        (upNamesByTs.get(ts) ?? upNamesByTs.set(ts, []).get(ts)!).push(name);
        upBases.add(`${ts}_${name}`);
      } else {
        (downNamesByTs.get(ts) ?? downNamesByTs.set(ts, []).get(ts)!).push(name);
        downBases.push({ ts, name });
      }
    }

    for (const [ts, names] of upNamesByTs) {
      if (names.length > 1) {
        errors.push(
          `${datatable}: ${names.length} up migrations share timestamp ${ts} (${names.join(", ")})`,
        );
      }
    }
    for (const [ts, names] of downNamesByTs) {
      if (names.length > 1) {
        errors.push(
          `${datatable}: ${names.length} down migrations share timestamp ${ts} (${names.join(", ")})`,
        );
      }
    }
    for (const d of downBases) {
      if (!upBases.has(`${d.ts}_${d.name}`)) {
        errors.push(
          `${datatable}: ${d.ts}_${d.name}.down.sql has no matching ${d.ts}_${d.name}.up.sql`,
        );
      }
    }
  }

  return errors;
}

/**
 * Sync a single migration to the workspace based on the current on-disk state of
 * its `<datatable>/<timestamp>_<name>.up.sql` file: upsert it when the up file
 * exists, otherwise delete it. Called by `wmill sync push` for each changed
 * `datatable_migration` file.
 */
export async function pushMigrationFromDisk(
  workspace: string,
  m: { datatable: string; timestamp: number },
): Promise<void> {
  const dir = path.join(process.cwd(), MIGRATIONS_DIR, m.datatable);
  // Find the up file for this timestamp regardless of its name segment. A rename
  // (`123_old.up.sql` -> `123_new.up.sql`) keeps the (datatable, timestamp)
  // identity but changes the name; the diff sorter may process the deleted old
  // path before the added new one, so keying off the passed name would delete
  // the record. Scanning by timestamp upserts the surviving file instead.
  const upFile = fs.existsSync(dir)
    ? fs.readdirSync(dir).find((f) => {
        const parsed = f.match(/^(\d+)_(.*)\.up\.sql$/);
        return parsed !== null && Number(parsed[1]) === m.timestamp;
      })
    : undefined;

  if (upFile === undefined) {
    log.info(colors.red(`Deleting datatable_migration ${m.datatable}/${m.timestamp}`));
    await wmill.deleteDatatableMigration({
      workspace,
      datatableName: m.datatable,
      timestamp: m.timestamp,
    });
    return;
  }

  const name = upFile.match(/^(\d+)_(.*)\.up\.sql$/)![2];
  const base = `${m.timestamp}_${name}`;
  const code_up = await readTextFile(path.join(dir, upFile));
  const downPath = path.join(dir, `${base}.down.sql`);
  const code_down = fs.existsSync(downPath) ? await readTextFile(downPath) : undefined;

  log.info(colors.green(`Pushing datatable_migration ${m.datatable}/${base}`));
  await wmill.upsertDatatableMigration({
    workspace,
    datatableName: m.datatable,
    requestBody: {
      timestamp: m.timestamp,
      name,
      code_up,
      ...(code_down !== undefined ? { code_down } : {}),
    },
  });
}

/**
 * Upsert the on-disk migrations of a data table to the workspace, so a freshly
 * created migration file works with `wmill datatable migrate up` even without a
 * prior `wmill sync push`. Pushes only migrations that are new or edited
 * (compared against the workspace's current definitions); it never deletes
 * remote migrations absent on disk and never touches other item kinds.
 */
export async function pushLocalMigrations(
  workspace: string,
  datatableName: string,
): Promise<void> {
  const dir = path.join(process.cwd(), MIGRATIONS_DIR, datatableName);
  if (!fs.existsSync(dir)) return;

  // Local migrations are identified by their `.up.sql` file (the up file is
  // mandatory); this deliberately ignores files that were only deleted locally.
  const local: { timestamp: number; name: string }[] = [];
  for (const file of fs.readdirSync(dir)) {
    const m = file.match(/^(\d+)_(.*)\.up\.sql$/);
    if (m) local.push({ timestamp: Number(m[1]), name: m[2] });
  }
  if (local.length === 0) return;

  const remote = await wmill.listDatatableMigrations({ workspace });
  const remoteByTs = new Map(
    remote
      .filter((r) => r.datatable === datatableName)
      .map((r) => [r.timestamp, r] as const),
  );

  for (const { timestamp, name } of local) {
    const base = `${timestamp}_${name}`;
    const code_up = await readTextFile(path.join(dir, `${base}.up.sql`));
    const downPath = path.join(dir, `${base}.down.sql`);
    const code_down = fs.existsSync(downPath)
      ? await readTextFile(downPath)
      : undefined;

    const r = remoteByTs.get(timestamp);
    const unchanged =
      r !== undefined &&
      r.name === name &&
      r.code_up === code_up &&
      (r.code_down ?? undefined) === code_down;
    if (unchanged) continue;

    log.info(colors.green(`Pushing datatable_migration ${datatableName}/${base}`));
    await wmill.upsertDatatableMigration({
      workspace,
      datatableName,
      requestBody: {
        timestamp,
        name,
        code_up,
        ...(code_down !== undefined ? { code_down } : {}),
      },
    });
  }
}

/**
 * After a push that introduced new migrations, list them and (interactively)
 * offer to run them, equivalent to `wmill datatable migrate up` on each affected
 * data table.
 */
export async function offerToRunNewMigrations(
  workspace: string,
  newMigrations: { datatable: string; timestamp: number; name: string }[],
  opts?: { yes?: boolean; jsonOutput?: boolean },
): Promise<void> {
  if (newMigrations.length === 0) return;

  log.info(colors.green("New migrations were pushed:"));
  for (const m of newMigrations) {
    log.info(colors.gray(`  ${m.datatable}: ${m.timestamp} ${m.name}`));
  }

  // Running migrations mutates the data tables, so skip the prompt in
  // non-interactive contexts (--yes, --json, no TTY).
  const interactive = !opts?.jsonOutput && !opts?.yes && !!process.stdin.isTTY;
  if (!interactive) {
    return;
  }

  const shouldRun = await Confirm.prompt({
    message: "New migrations were pushed, run them?",
    default: false,
  });
  if (!shouldRun) {
    return;
  }

  for (const datatable of new Set(newMigrations.map((m) => m.datatable))) {
    await runMigrations(workspace, datatable);
  }
}

