interface FileIssue {
  path: string;
  target: string;
  errors: string[];
}

interface LintWarning {
  path: string;
  message: string;
}

export interface LintReport {
  scannedFiles: number;
  validatedFiles: number;
  validFiles: number;
  invalidFiles: number;
  skippedUnsupportedFiles: number;
