// Bounded-cascade graph engine for `wmill pipeline run --to`.
//
// MIRROR of frontend/src/lib/components/assets/AssetGraph/boundedCascade.ts —
// the two have no shared import path (frontend is a separate package), so keep
// them in sync. The grammar is intentionally tiny: there is no dbt-style
// `--select` string. The user names a start (a schedule / manual root) and one
// or more end nodes; the run is the "path between" them:
//
//     descendants(start) ∩ (ancestors(ends) ∪ ends) ∪ {start}
//
// Node ids: assets `${kind}:${path}` (e.g. `datatable:main/raw`); runnables
// `script:${path}`. Operates on the asset-graph payload shape used by
// pipeline.ts.

export type BCGraph = {
  runnables: {
    path: string;
    usage_kind: "script" | "flow" | "job";
    // `// partitioned <kind>` on the script (daily/hourly/weekly/monthly/dynamic).
    // Emitted by both the deployed graph endpoint and the local builder.
    partition_kind?: string;
    // `// macros` library: non-empty on a workspace macro library (deployed
    // graph only). Definition-only — never a runnable cascade step.
    macros?: { name: string }[];
  }[];
  assets: { kind: string; path: string }[];
  edges: {
    runnable_kind: string;
    runnable_path: string;
    asset_kind: string;
    asset_path: string;
    access_type?: "r" | "w" | "rw";
  }[];
  triggers: (
    | {
        trigger_kind: "asset";
        asset_kind: string;
        asset_path: string;
        runnable_kind: string;
        runnable_path: string;
      }
    | { trigger_kind: string; runnable_kind: string; runnable_path: string }
  )[];
  // `// data_test` ordering edges (HD-1): the referenced asset's producer must
  // materialize before the tested script runs. Fed into the lineage DAG so a
  // bounded/cold cascade orders the referenced dimension first. Optional — the
  // deployed graph omits it when empty, and older local graphs never emit it.
  test_edges?: {
    producer_kind: string;
    producer_path: string;
    runnable_kind: string;
    runnable_path: string;
    asset_kind: string;
    asset_path: string;
  }[];
};

export const SCRIPT_PREFIX = "script:";
export const scriptNodeId = (path: string): string => `${SCRIPT_PREFIX}${path}`;
export const isScriptNode = (id: string): boolean => id.startsWith(SCRIPT_PREFIX);
export const scriptPathOf = (id: string): string => id.slice(SCRIPT_PREFIX.length);
const assetNodeId = (kind: string, path: string): string => `${kind}:${path}`;

// Native trigger kinds whose scripts must NOT be auto-run by the CLI cascade:
// event triggers fan out per external event, and `webhook`/`data_upload` are UI
// entrypoints that need caller-supplied input (a request body / an uploaded
// S3Object) — previewing any of them with empty args runs the wrong thing.
// The deployed graph omits `webhook`/`data_upload` rows, but the local graph
// emits them, so a `// on data_upload` script would otherwise read as a manual
// root and get auto-run without its upload argument.
const NON_AUTORUN_TRIGGER_KINDS = new Set([
  "kafka",
  "mqtt",
  "amqp",
  "nats",
  "postgres",
  "sqs",
  "gcp",
  "email",
  "webhook",
  "data_upload",
]);

/** Resolve an asset URI (`datatable://x`, `s3://b/k`, …) to its node id. */
export function assetUriToNodeId(uri: string): string | undefined {
  const m = uri.match(/^([a-z0-9_]+):\/\/(.+)$/i);
  if (!m) return undefined;
  const prefix = m[1].toLowerCase();
  const kind = prefix === "s3" ? "s3object" : prefix;
  // The suffix is kept verbatim (mirrors Rust `parse_asset_syntax`): an S3
  // path encodes the storage, with a leading `/` for the workspace default
  // (`s3:///key` → `/key`) vs `s3://secondary/key` → `secondary/key`.
  return `${kind}:${m[2]}`;
}

export type LineageDag = {
  down: Map<string, Set<string>>;
  up: Map<string, Set<string>>;
  nodes: Set<string>;
};

function addEdge(dag: LineageDag, a: string, b: string) {
  if (a === b) return;
  dag.nodes.add(a);
  dag.nodes.add(b);
  (dag.down.get(a) ?? dag.down.set(a, new Set()).get(a)!).add(b);
  (dag.up.get(b) ?? dag.up.set(b, new Set()).get(b)!).add(a);
}

/** Unified upstream→downstream lineage DAG over scripts ∪ assets. */
export function buildLineageDag(g: BCGraph): LineageDag {
  const dag: LineageDag = { down: new Map(), up: new Map(), nodes: new Set() };
  for (const r of g.runnables ?? []) {
    if (r.usage_kind === "script") dag.nodes.add(scriptNodeId(r.path));
  }
  for (const a of g.assets ?? []) dag.nodes.add(assetNodeId(a.kind, a.path));
  for (const e of g.edges ?? []) {
    if (e.runnable_kind !== "script") continue;
    const aid = assetNodeId(e.asset_kind, e.asset_path);
    const access = e.access_type ?? "r";
    if (access === "w" || access === "rw") {
      addEdge(dag, scriptNodeId(e.runnable_path), aid); // producer
    } else if (access === "r") {
      addEdge(dag, aid, scriptNodeId(e.runnable_path)); // pure reader
    }
  }
  for (const t of g.triggers ?? []) {
    if (t.trigger_kind !== "asset" || t.runnable_kind !== "script") continue;
    const at = t as Extract<BCGraph["triggers"][number], { trigger_kind: "asset" }>;
    addEdge(dag, assetNodeId(at.asset_kind, at.asset_path), scriptNodeId(at.runnable_path));
  }
  // Data-test ordering edges: route through the referenced asset node so the
  // existing producer → asset write edge extends into producer → asset → testing
  // script (mirrors frontend boundedCascade.ts) — the tested script runs after
  // the referenced dimension materializes.
  for (const t of g.test_edges ?? []) {
    if (t.runnable_kind !== "script") continue;
    addEdge(dag, assetNodeId(t.asset_kind, t.asset_path), scriptNodeId(t.runnable_path));
  }
  return dag;
}

function closure(adj: Map<string, Set<string>>, start: string): Set<string> {
  const seen = new Set<string>();
  const queue = [start];
  while (queue.length > 0) {
    const cur = queue.shift()!;
    for (const n of adj.get(cur) ?? []) {
      if (seen.has(n)) continue;
      seen.add(n);
      queue.push(n);
    }
  }
  // A cycle back to `start` would have re-added it; the contract excludes
  // the node itself.
  seen.delete(start);
  return seen;
}

export const descendants = (dag: LineageDag, n: string): Set<string> => closure(dag.down, n);
export const ancestors = (dag: LineageDag, n: string): Set<string> => closure(dag.up, n);

/**
 * Nodes reachable from `starts` over the lineage DAG, treating `barriers` as cut
 * points: a barrier node is neither included NOR traversed through. So a node
 * reachable ONLY via a barrier is excluded, while one also reachable via another
 * path stays. Used for whole-pipeline runs to keep event handlers AND their
 * event-only downstream closure out (subtracting only the handler would leave a
 * consumer whose producer was skipped, which topoOrder would then run with
 * missing/stale inputs).
 */
export function reachableCutting(
  dag: LineageDag,
  starts: Iterable<string>,
  barriers: Set<string>,
): Set<string> {
  const seen = new Set<string>();
  const queue: string[] = [];
  for (const s of starts) {
    if (barriers.has(s) || seen.has(s)) continue;
    seen.add(s);
    queue.push(s);
  }
  while (queue.length > 0) {
    const n = queue.shift()!;
    for (const next of dag.down.get(n) ?? []) {
      if (barriers.has(next) || seen.has(next)) continue;
      seen.add(next);
      queue.push(next);
    }
  }
  return seen;
}

export type BoundedResult = {
  nodes: Set<string>;
  reachableEnds: string[];
  droppedEnds: string[];
};

/** Path-between node set for `start` and `ends` (inclusive). */
export function boundedSet(dag: LineageDag, start: string, ends: string[]): BoundedResult {
  const downSet = new Set(descendants(dag, start));
  downSet.add(start);
  const reachableEnds = ends.filter((e) => downSet.has(e));
  const droppedEnds = ends.filter((e) => !downSet.has(e));
  if (reachableEnds.length === 0) {
    return { nodes: new Set([start]), reachableEnds, droppedEnds };
  }
  const upClosure = new Set<string>();
  for (const e of reachableEnds) {
    upClosure.add(e);
    for (const a of ancestors(dag, e)) upClosure.add(a);
  }
  const nodes = new Set<string>();
  for (const n of downSet) if (upClosure.has(n)) nodes.add(n);
  nodes.add(start);
  return { nodes, reachableEnds, droppedEnds };
}

/** Script node ids eligible to start a bounded run. */
export function validStarts(g: BCGraph): Set<string> {
  const subscribers = new Set<string>();
  const scheduleScripts = new Set<string>();
  const nonAutorunScripts = new Set<string>();
  for (const t of g.triggers ?? []) {
    if (t.runnable_kind !== "script") continue;
    if (t.trigger_kind === "asset") subscribers.add(t.runnable_path);
    else if (t.trigger_kind === "schedule") scheduleScripts.add(t.runnable_path);
    else if (NON_AUTORUN_TRIGGER_KINDS.has(t.trigger_kind)) nonAutorunScripts.add(t.runnable_path);
  }
  const out = new Set<string>();
  for (const r of g.runnables ?? []) {
    if (r.usage_kind !== "script") continue;
    const p = r.path;
    if (scheduleScripts.has(p)) out.add(scriptNodeId(p));
    else if (!subscribers.has(p) && !nonAutorunScripts.has(p)) out.add(scriptNodeId(p));
  }
  return out;
}

/**
 * Script node ids eligible as an EXPLICIT bounded-run start from *anywhere* in
 * the DAG (dbt's `--select model+`): every script that can run with empty args —
 * i.e. all scripts except non-autorun-trigger ones (kafka/mqtt/…/webhook/
 * data_upload, which fan out per event or need caller-supplied input). Unlike
 * `validStarts` (schedule/manual roots only), this INCLUDES mid-DAG asset
 * subscribers and pure readers, so `--from <mid-model>` runs that node plus its
 * transitive downstream WITHOUT re-running upstream. Roots stay a subset of this
 * set. A non-autorun handler still qualifies once it's `--upload`-bound (handled
 * by the caller, which unions in the bound node ids).
 */
export function validFromStarts(g: BCGraph): Set<string> {
  const nonAutorun = nonAutorunTriggerScripts(g);
  // Seed with the schedule/manual roots: `validStarts` lets a schedule identity
  // win over a secondary non-autorun trigger (a `// on schedule` + `// on
  // data_upload` script IS a scheduled root), so a root must stay `--from`-
  // eligible even though it's also in `nonAutorunTriggerScripts`.
  const out = new Set<string>(validStarts(g));
  for (const r of g.runnables ?? []) {
    if (r.usage_kind !== "script") continue;
    const id = scriptNodeId(r.path);
    if (!nonAutorun.has(id)) out.add(id);
  }
  return out;
}

/**
 * Script node ids that carry a trigger requiring caller-supplied input or
 * per-event fanout (kafka/mqtt/nats/postgres/sqs/gcp/email/webhook/data_upload).
 * These can't be run with empty args, so a whole-pipeline run must exclude them
 * even when they're a lineage descendant of a valid start (not just a root).
 */
export function nonAutorunTriggerScripts(g: BCGraph): Set<string> {
  const out = new Set<string>();
  for (const t of g.triggers ?? []) {
    if (t.runnable_kind === "script" && NON_AUTORUN_TRIGGER_KINDS.has(t.trigger_kind)) {
      out.add(scriptNodeId(t.runnable_path));
    }
  }
  return out;
}

/** Project a node-id set to the script paths it contains. */
export function scriptsOf(nodes: Iterable<string>): string[] {
  const out: string[] = [];
  for (const id of nodes) if (isScriptNode(id)) out.push(scriptPathOf(id));
  return out;
}

/**
 * Resolve a CLI `--to` / `--from` token to a node id, or undefined if it
 * matches nothing. Asset URIs (`kind://path`) resolve to the asset node; a bare
 * token matches a runnable by exact path or by short (last-segment) name.
 */
export function resolveToken(g: BCGraph, token: string): string | undefined {
  if (token.includes("://")) {
    const id = assetUriToNodeId(token);
    return id && g.assets.some((a) => `${a.kind}:${a.path}` === id) ? id : undefined;
  }
  const scripts = (g.runnables ?? []).filter((r) => r.usage_kind === "script");
  const exact = scripts.find((r) => r.path === token);
  if (exact) return scriptNodeId(exact.path);
  const byShort = scripts.filter((r) => (r.path.split("/").pop() ?? r.path) === token);
  return byShort.length === 1 ? scriptNodeId(byShort[0].path) : undefined;
}

/**
 * Topological order of `scripts` over the in-set producer→subscriber edges
 * (assets collapsed). Scripts on a cycle are returned in `cyclic` and excluded
 * from `order`. Serial-run friendly: every script comes after its in-set
 * upstreams.
 */
export function topoOrder(
  g: BCGraph,
  scripts: Set<string>,
): { order: string[]; cyclic: string[] } {
  const dag = buildLineageDag(g);
  const down = new Map<string, Set<string>>();
  const indegree = new Map<string, number>();
  for (const s of scripts) indegree.set(s, 0);
  // One-hop (through a single asset) script→script edges, restricted to the set.
  for (const s of scripts) {
    const sid = scriptNodeId(s);
    const oneHop = new Set<string>();
    for (const asset of dag.down.get(sid) ?? []) {
      for (const sub of dag.down.get(asset) ?? []) {
        if (isScriptNode(sub)) {
          const p = scriptPathOf(sub);
          if (p !== s && scripts.has(p)) oneHop.add(p);
        }
      }
    }
    if (oneHop.size > 0) {
      down.set(s, oneHop);
      for (const p of oneHop) indegree.set(p, (indegree.get(p) ?? 0) + 1);
    }
  }
  const ready = [...scripts].filter((s) => (indegree.get(s) ?? 0) === 0);
  const remaining = new Map(indegree);
  const order: string[] = [];
  while (ready.length > 0) {
    const n = ready.shift()!;
    order.push(n);
    for (const p of down.get(n) ?? []) {
      const d = (remaining.get(p) ?? 0) - 1;
      remaining.set(p, d);
      if (d === 0) ready.push(p);
    }
  }
  const orderedSet = new Set(order);
  const cyclic = [...scripts].filter((s) => !orderedSet.has(s));
  return { order, cyclic };
}

// `wmill pipeline dev [folder]` — live-preview a data pipeline from local files.
//
// The pipeline analog of `wmill dev` / `wmill app dev`: watch a folder of
// `// pipeline` scripts, rebuild the asset graph from the working tree on every
// save, and push it over a WebSocket to the `/pipeline_dev` page, which renders
// the same graph editor the UI uses and runs the cascade via preview (no deploy).
// Editing stays in the user's own editor; the page live-reloads.

import { Command } from "@cliffy/command";
import { colors } from "@cliffy/ansi/colors";
import * as http from "node:http";
import * as fs from "node:fs";
import * as path from "node:path";
import { createHash, randomBytes } from "node:crypto";
import process from "node:process";
import * as open from "open";
import { WebSocket, WebSocketServer } from "ws";
import * as log from "../../core/log.ts";
import { GlobalOptions } from "../../types.ts";
import { requireLogin } from "../../core/auth.ts";
import { resolveWorkspace } from "../../core/context.ts";
import {
  mergeConfigWithConfigFile,
  type SyncOptions,
} from "../../core/conf.ts";
import { listSyncCodebases } from "../../utils/codebase.ts";
import { resolveBindPort } from "../../utils/port-probe.ts";
import { getConfigDirPath } from "../../../windmill-utils-internal/src/config/config.ts";
import { buildLocalPipelineGraph, workspaceRoot } from "./localGraph.ts";

const PORT = 3201;
// Bind loopback only: each WS frame ships the folder's full script source
// (`scripts[].content` + `temp_script_refs`) with no auth, so it must not be
// reachable from the LAN. The webview connects via `ws://localhost`, and an SSH
// `-L` / devbox port-forward targets 127.0.0.1 on the host, so both still work.
const LISTEN_HOST = "127.0.0.1";

interface PipelineDevOpts extends GlobalOptions, SyncOptions {
  port?: number;
  open?: boolean;
  defaultTs?: "bun" | "deno";
  frontend?: string;
}

// The WS token gates access to local source. Persist it under the user-private
// config dir (0600) so a `pipeline dev` restart reuses it — an already-open
// `/pipeline_dev` page auto-reconnecting with the token from its URL then
// survives the restart, instead of every upgrade being rejected by
// `verifyClient` until the freshly printed URL is reopened. Scoped by
// remote+workspace+root+folder+port (NOT port alone): a same-session restart
// reconnects, but any *different* session — another folder, workspace, remote, or
// local checkout on the same port — gets a different token, so a stale tab can't
// reconnect and receive another session's source. Falls back to an ephemeral
// token if the config dir can't be read/written.
async function stableWsToken(
  remote: string,
  workspaceId: string,
  root: string,
  folder: string,
  port: number,
): Promise<string> {
  // Hash the tuple (NUL-delimited so no value can spoof the boundary) → a
  // collision-resistant, filesystem-safe key. A plain sanitized join would let
  // different values collide (`a/b` and `a_b` → same name), which would reuse a
  // token across sessions and reintroduce the cross-session leak.
  const key = createHash("sha256")
    .update(`${remote}\0${workspaceId}\0${root}\0${folder}\0${port}`)
    .digest("hex")
    .slice(0, 32);
  let tokenFile: string | undefined;
  try {
    tokenFile = path.join(await getConfigDirPath(), `pipeline-dev-${key}.token`);
    const existing = fs.readFileSync(tokenFile, "utf-8").trim();
    if (existing) return existing;
  } catch {
    // no reusable token file yet (or config dir unavailable) — mint a fresh one
  }
  const token = randomBytes(24).toString("base64url");
  if (tokenFile) {
    try {
      fs.writeFileSync(tokenFile, token, { mode: 0o600 });
    } catch {
      // best-effort persistence; fall back to the in-memory token
    }
  }
  return token;
}

// Resolve the target folder: explicit arg, else auto-detect when cwd sits inside
// `f/<folder>/…` (the supported `cd f/my_pipeline && wmill pipeline dev` form).
function resolveFolder(root: string, folderArg?: string): string | undefined {
  if (folderArg) return folderArg.replace(/^f\//, "").replace(/\/$/, "");
  const rel = path.relative(root, process.cwd()).replaceAll("\\", "/");
  if (rel === "" || rel.startsWith("..")) return undefined;
  const segs = rel.split("/");
  if (segs[0] === "f" && segs[1]) return segs[1];
  return undefined;
}

async function dev(opts: PipelineDevOpts, folderArg?: string) {
  const root = workspaceRoot();
  const folder = resolveFolder(root, folderArg);
  if (!folder) {
    log.error(
      colors.red(
        "Could not determine the pipeline folder. Pass it explicitly " +
          "(`wmill pipeline dev <folder>`) or run from inside an `f/<folder>` directory.",
      ),
    );
    process.exit(1);
  }
  const folderDir = path.join(root, "f", folder);
  if (!fs.existsSync(folderDir)) {
    log.error(colors.red(`Folder not found on disk: ${folderDir}`));
    process.exit(1);
  }

  const workspace = await resolveWorkspace(opts);
  await requireLogin(opts);
  const merged = await mergeConfigWithConfigFile(opts);
  const codebases = await listSyncCodebases(merged);

  // Resolve relative imports from local (not-yet-deployed) content for previews.
  // Snapshot at startup like `wmill dev`; restart to refresh. Degrades to
  // undefined on older backends.
  let tempScriptRefs: Record<string, string> | undefined;
  try {
    const { buildPreviewTempScriptRefs } = await import(
      "../generate-metadata/generate-metadata.ts"
    );
    tempScriptRefs = await buildPreviewTempScriptRefs(
      workspace,
      merged,
      codebases,
      { kind: "all" },
    );
  } catch {
    // best-effort
  }

  const EMPTY_GRAPH = { runnables: [], assets: [], edges: [], triggers: [] };
  async function buildBundle() {
    const { graph, scripts } = await buildLocalPipelineGraph({
      root,
      folder: folder!,
      defaultTs: merged.defaultTs,
    });
    return {
      type: "pipeline" as const,
      folder,
      graph,
      scripts,
      temp_script_refs: tempScriptRefs,
    };
  }

  // Don't let a transient build error (e.g. a half-written file) abort startup —
  // serve an empty graph and recover on the next save.
  let current: Awaited<ReturnType<typeof buildBundle>>;
  try {
    current = await buildBundle();
  } catch (e: any) {
    log.error(colors.red(`Initial graph build failed: ${e.message}`));
    current = { type: "pipeline", folder, graph: EMPTY_GRAPH, scripts: [], temp_script_refs: tempScriptRefs };
  }
  log.info(
    colors.blue(
      `Watching f/${folder} — ${current.scripts.length} pipeline script(s)`,
    ),
  );

  const clients = new Set<WebSocket>();
  function broadcast() {
    const msg = JSON.stringify(current);
    for (const ws of clients) {
      if (ws.readyState === WebSocket.OPEN) ws.send(msg);
    }
  }

  // Debounced rebuild on any change under the folder.
  let timer: ReturnType<typeof setTimeout> | undefined;
  const watcher = fs.watch(folderDir, { recursive: true });
  watcher.on("change", (_ev, filename) => {
    if (filename && filename.toString().endsWith(".lock")) return;
    if (timer) clearTimeout(timer);
    timer = setTimeout(async () => {
      timer = undefined;
      try {
        current = await buildBundle();
        log.info(colors.cyan(`↻ rebuilt graph (${current.scripts.length} scripts)`));
        broadcast();
      } catch (e: any) {
        log.error(colors.red(`Failed to rebuild pipeline graph: ${e.message}`));
      }
    }, 150);
  });
  watcher.on("error", (e) => log.error(colors.red(`Watcher error: ${e.message}`)));

  const port = await resolveBindPort(opts.port ?? PORT, "wmill pipeline dev", {
    info: (m) => log.info(m),
    warn: (m) => log.warn(m),
  });

  const server = http.createServer((_req, res) => {
    res.writeHead(200);
    res.end();
  });
  // Loopback bind keeps the LAN out, but any browser tab can still open a
  // `ws://localhost:<port>` connection — and each frame ships the folder's full
  // script source. Gate the upgrade on an unguessable per-session token (carried
  // in the dev-page URL) so a stray page on the predictable dev port can't
  // exfiltrate the source. base64url → safe as a query value.
  // Stable across restarts (scoped to remote+workspace+root+folder+port) so an
  // already-open page reconnects after a CLI restart (see stableWsToken), not
  // just after a transient WS drop.
  const wsToken = await stableWsToken(
    workspace.remote,
    workspace.workspaceId,
    root,
    folder,
    port,
  );
  const wss = new WebSocketServer({
    server,
    verifyClient: (info) => {
      try {
        const u = new URL(info.req.url ?? "", "http://localhost");
        return u.searchParams.get("token") === wsToken;
      } catch {
        return false;
      }
    },
  });
  wss.on("connection", (ws: WebSocket) => {
    clients.add(ws);
    // Push the current bundle immediately so the page renders without waiting
    // for the first file change.
    try {
      ws.send(JSON.stringify(current));
    } catch {
      // ignore
    }
    ws.on("close", () => clients.delete(ws));
    ws.on("error", () => clients.delete(ws));
  });

  // The `/pipeline_dev` page is served by the frontend, not the backend. By
  // default we open it on the workspace remote, but that 404s on a remote whose
  // deployed frontend predates this route — `--frontend` points the page at a
  // locally-run frontend (`REMOTE=<remote> npm run dev`) while the API/token
  // still target the remote. Normalize to a single trailing slash either way.
  const pageBase = (opts.frontend ?? workspace.remote).replace(/\/?$/, "/");
  const url =
    `${pageBase}pipeline_dev?workspace=${workspace.workspaceId}` +
    `&wm_token=${workspace.token}&folder=${encodeURIComponent(folder)}&port=${port}` +
    `&ws_token=${encodeURIComponent(wsToken)}`;

  server.listen(port, LISTEN_HOST, () => {
    log.info(colors.green.bold(`🚀 Pipeline dev server on ws://localhost:${port}/ws`));
    log.info(colors.gray(`Open: ${url}`));
    if (opts.open !== false) {
      open.default(url).catch((e: any) =>
        log.warn(colors.yellow(`Failed to open browser: ${e.message}`)),
      );
    }
  });

  process.on("SIGINT", () => {
    log.info(colors.yellow("\n🛑 Shutting down…"));
    watcher.close();
    for (const ws of clients) ws.close();
    server.close();
    process.exit(0);
  });
}

const command = new Command()
  .description(
    "Live-preview a data pipeline from local files: watch an `f/<folder>` of `// pipeline` scripts, push the working-tree graph to the dev page, and run the cascade via preview (no deploy).",
  )
  .arguments("[folder:string]")
  .option("--port <port:number>", "Port for the dev WebSocket server.")
  .option("--no-open", "Do not open the browser automatically.")
  .option(
    "--frontend <origin:string>",
    "Origin serving the /pipeline_dev page (e.g. http://localhost:3000 for a locally-run frontend). Defaults to the workspace remote; use it when the remote's deployed frontend predates the dev page.",
  )
  .action(dev as any);

export default command;

// `wmill pipeline docs <folder>` — generate a PIPELINE.md (+ AGENTS.md / CLAUDE.md
// pointer) describing a folder's pipeline so an editor or agentic loop has the
// same context the UI surfaces: the asset DAG, per-script triggers/IO, and the
// schemas of the datatables the pipeline touches. Mirrors the app docs pattern
// (`app/generate_agents.ts:regenerateAgentDocs`) but scoped to a pipeline folder.

import { writeFile } from "node:fs/promises";
import { existsSync, readFileSync } from "node:fs";
import * as path from "node:path";
import { OpenAPI } from "../../../gen/index.ts";
import * as wmill from "../../../gen/services.gen.ts";
import { requireLogin } from "../../core/auth.ts";
import { resolveWorkspace } from "../../core/context.ts";
import { mergeConfigWithConfigFile } from "../../core/conf.ts";
import * as log from "../../core/log.ts";
import { colors } from "@cliffy/ansi/colors";
import { GlobalOptions } from "../../types.ts";
import {
  type AssetGraph,
  hideDbtRunnables,
  buildLocalPipelineGraph,
  workspaceRoot,
} from "./localGraph.ts";

const ASSET_KINDS = "s3object,ducklake,datatable,volume,dbt";

function assetUri(kind: string, p: string): string {
  const prefix = kind === "s3object" ? "s3" : kind;
  return `${prefix}://${p}`;
}

async function fetchDeployedGraph(
  workspaceId: string,
  folder: string,
): Promise<AssetGraph> {
  const res = await fetch(
    `${OpenAPI.BASE}/w/${workspaceId}/assets/graph?folder=${encodeURIComponent(folder)}&asset_kinds=${ASSET_KINDS}`,
    { headers: { Authorization: `Bearer ${OpenAPI.TOKEN}` } },
  );
  if (!res.ok) {
    throw new Error(`GET assets/graph -> ${res.status}: ${await res.text()}`);
  }
  return hideDbtRunnables((await res.json()) as AssetGraph);
}

// Render the pipeline graph as a markdown document.
export function generatePipelineMarkdown(
  folder: string,
  graph: AssetGraph,
  datatableSchemas: any[],
  local: boolean,
): string {
  const writesByScript = new Map<string, string[]>();
  const readsByScript = new Map<string, string[]>();
  for (const e of graph.edges) {
    if (e.runnable_kind !== "script") continue;
    const uri = assetUri(e.asset_kind, e.asset_path);
    if (e.access_type === "w" || e.access_type === "rw") {
      (writesByScript.get(e.runnable_path) ?? writesByScript.set(e.runnable_path, []).get(e.runnable_path)!).push(uri);
    }
    if (e.access_type === "r" || e.access_type === "rw" || e.access_type === undefined) {
      (readsByScript.get(e.runnable_path) ?? readsByScript.set(e.runnable_path, []).get(e.runnable_path)!).push(uri);
    }
  }
  const onByScript = new Map<string, string[]>();
  const nativeByScript = new Map<string, string[]>();
  for (const t of graph.triggers) {
    if (t.runnable_kind !== "script") continue;
    if (t.trigger_kind === "asset") {
      const at = t as Extract<AssetGraph["triggers"][number], { trigger_kind: "asset" }>;
      (onByScript.get(at.runnable_path) ?? onByScript.set(at.runnable_path, []).get(at.runnable_path)!).push(assetUri(at.asset_kind, at.asset_path));
    } else {
      (nativeByScript.get(t.runnable_path) ?? nativeByScript.set(t.runnable_path, []).get(t.runnable_path)!).push(t.trigger_kind);
    }
  }

  // `// macros` libraries are definition-only nodes (not runnable pipeline
  // steps), so they get their own section below and are excluded from the
  // per-script listing + the script count.
  const macroLibs = graph.runnables
    .filter((r) => r.usage_kind === "script" && (r.macros?.length ?? 0) > 0)
    .sort((a, b) => a.path.localeCompare(b.path));
  const macroLibPaths = new Set(macroLibs.map((r) => r.path));
  const macroConsumersByLib = new Map<string, { consumer: string; names: string[]; viaUse?: boolean }[]>();
  for (const me of graph.macro_edges ?? []) {
    (macroConsumersByLib.get(me.lib_path) ?? macroConsumersByLib.set(me.lib_path, []).get(me.lib_path)!).push({
      consumer: me.consumer_path,
      names: me.macro_names,
      viaUse: me.via_use,
    });
  }

  const scripts = graph.runnables
    .filter((r) => r.usage_kind === "script" && !macroLibPaths.has(r.path))
    .map((r) => r.path)
    .sort();

  let md = `# Pipeline \`f/${folder}\`

${local ? "_Built from local working-tree files (`// pipeline` scripts)._" : "_Built from the deployed workspace asset graph._"}

A data pipeline is a folder of scripts marked \`// pipeline\` and wired by asset
annotations. A script subscribes to upstream data with \`// on <asset-uri>\` and
produces data by reading/writing assets in its body (\`datatable://\`,
\`ducklake://\`, \`s3://\`, \`volume://\`). The cascade runs a producer, then every
downstream subscriber, in topological order.

- **${scripts.length}** script${scripts.length === 1 ? "" : "s"} · **${graph.assets.length}** asset${graph.assets.length === 1 ? "" : "s"}${macroLibs.length > 0 ? ` · **${macroLibs.length}** macro librar${macroLibs.length === 1 ? "y" : "ies"}` : ""}

## Scripts

`;

  for (const s of scripts) {
    const on = onByScript.get(s) ?? [];
    const native = nativeByScript.get(s) ?? [];
    const writes = [...new Set(writesByScript.get(s) ?? [])].sort();
    const reads = [...new Set(readsByScript.get(s) ?? [])].sort();
    md += `### \`${s}\`\n\n`;
    if (native.length) md += `- **Triggers:** ${native.map((n) => `\`${n}\``).join(", ")}\n`;
    if (on.length) md += `- **On (subscribes to):** ${on.map((u) => `\`${u}\``).join(", ")}\n`;
    if (reads.length) md += `- **Reads:** ${reads.map((u) => `\`${u}\``).join(", ")}\n`;
    if (writes.length) md += `- **Writes:** ${writes.map((u) => `\`${u}\``).join(", ")}\n`;
    if (!native.length && !on.length && !reads.length && !writes.length) {
      md += `- _No declared triggers or asset IO._\n`;
    }
    md += `\n`;
  }

  // Macro libraries: `// macros` scripts whose macros are injected into consuming
  // DuckDB scripts at run time. List each library's signatures and its callers so
  // an agent discovers the reuse layer instead of re-inlining the logic.
  if (macroLibs.length > 0) {
    md += `## Macro libraries\n\n`;
    md += `\`// macros\` DuckDB libraries. Their \`CREATE MACRO\` definitions are injected as\nTEMP macros into consuming scripts at run time — call a macro by name, or force the\nwhole library in with \`// use <lib-path>\` (needed for macros only reached via dynamic SQL).\n\n`;
    for (const lib of macroLibs) {
      md += `### \`${lib.path}\`\n\n`;
      for (const m of lib.macros ?? []) {
        md += `- \`${m.name}(${m.params ?? ""})\`${m.is_table ? " → TABLE" : ""}\n`;
      }
      const consumers = [...(macroConsumersByLib.get(lib.path) ?? [])].sort((a, b) =>
        a.consumer.localeCompare(b.consumer),
      );
      if (consumers.length > 0) {
        md += `- **Used by:**\n`;
        for (const c of consumers) {
          md += `  - \`${c.consumer}\` (${c.viaUse ? "via \`// use\`" : `calls ${c.names.map((n) => `\`${n}\``).join(", ")}`})\n`;
        }
      }
      md += `\n`;
    }
  }

  // Datatable schemas, restricted to datatables this pipeline references.
  const referencedDatatables = new Set(
    graph.assets.filter((a) => a.kind === "datatable").map((a) => a.path.split("/")[0]),
  );
  const relevant = (datatableSchemas ?? []).filter((dt: any) => referencedDatatables.has(dt.datatable_name));
  if (relevant.length > 0) {
    md += `## Datatable schemas\n\n`;
    for (const dt of relevant) {
      md += `### Datatable \`${dt.datatable_name}\`\n\n`;
      if (dt.error) {
        md += `> ⚠️ ${dt.error}\n\n`;
        continue;
      }
      for (const [schemaName, tables] of Object.entries(dt.schemas ?? {})) {
        for (const [tableName, columns] of Object.entries(tables as Record<string, any>)) {
          const ref = schemaName === "public"
            ? `${dt.datatable_name}/${tableName}`
            : `${dt.datatable_name}/${schemaName}:${tableName}`;
          md += `- \`datatable://${ref}\`\n`;
          for (const [col, type] of Object.entries(columns as Record<string, any>)) {
            md += `  - \`${col}\`: ${type}\n`;
          }
        }
      }
      md += `\n`;
    }
  }

  md += `## Working with this pipeline

- **Inspect the graph:** \`wmill pipeline show ${folder} --local\`
- **Run the cascade locally (no deploy):** \`wmill pipeline run ${folder} --local\`
  (optionally \`--from <script> --to <script>\` to bound it, \`--dry-run\` to preview the plan)
- **Live visual preview while editing:** \`wmill pipeline dev ${folder}\`
- **Deploy:** \`wmill sync push\`

Mark a script as part of this pipeline with a bare \`// pipeline\` comment
(\`#\` for Python, \`--\` for SQL). Add \`// on <asset-uri>\` lines to subscribe it to
upstream assets.

---
*Generated by \`wmill pipeline docs\`.*
`;
  return md;
}

export async function generatePipelineDocs(
  opts: GlobalOptions & { local?: boolean; defaultTs?: "bun" | "deno" },
  folder: string,
) {
  const f = folder.replace(/^f\//, "").replace(/\/$/, "");
  // `docs` WRITES PIPELINE.md / AGENTS.md / CLAUDE.md under `f/<folder>`; a `..`
  // segment would escape the folder and clobber files elsewhere in the tree.
  if (f.split("/").includes("..")) {
    log.error(colors.red(`Invalid folder '${folder}': '..' path segments are not allowed.`));
    return;
  }
  const root = workspaceRoot();
  // defaultTs (from wmill.yaml) drives .ts → bun/deno inference for the local graph.
  const merged = await mergeConfigWithConfigFile(opts);

  const workspace = opts.local ? undefined : await resolveWorkspace(opts);
  if (!opts.local) await requireLogin(opts);

  const graph = opts.local
    ? (await buildLocalPipelineGraph({ root, folder: f, defaultTs: merged.defaultTs })).graph
    : await fetchDeployedGraph(workspace!.workspaceId, f);

  if (graph.runnables.length === 0) {
    // The deployed graph is empty — but a user/agent in a working tree may have
    // local `// pipeline` scripts not yet deployed. Point them at --local rather
    // than leaving them thinking the folder is empty.
    if (!opts.local) {
      try {
        const localCount =
          (await buildLocalPipelineGraph({ root, folder: f, defaultTs: merged.defaultTs })).graph
            .runnables.length;
        if (localCount > 0) {
          log.info(
            `No deployed pipeline scripts in f/${f}, but ${localCount} \`// pipeline\` script(s) exist in the local working tree — run \`wmill pipeline docs ${f} --local\` to document those.`,
          );
          return;
        }
      } catch {
        // best-effort hint; fall through to the generic message
      }
    }
    log.info(`No pipeline scripts in f/${f}.`);
    return;
  }

  let datatableSchemas: any[] = [];
  const hasExplicitWorkspace =
    !!opts.workspace ||
    (!!opts.baseUrl && !!opts.token) ||
    (!!process.env["WM_WORKSPACE"] &&
      !!process.env["WM_TOKEN"] &&
      !!(process.env["BASE_INTERNAL_URL"] ?? process.env["BASE_URL"]));
  if (!opts.local || hasExplicitWorkspace) {
    try {
      const schemaWorkspace = workspace ?? await resolveWorkspace(opts);
      if (opts.local) await requireLogin(opts);
      datatableSchemas = await wmill.listDataTableSchemas({ workspace: schemaWorkspace.workspaceId });
    } catch (err: any) {
      log.warn(colors.yellow(`Could not fetch datatable schemas: ${err.message}`));
    }
  }

  const md = generatePipelineMarkdown(f, graph, datatableSchemas, !!opts.local);
  const folderDir = path.join(root, "f", f);
  await writeFile(path.join(folderDir, "PIPELINE.md"), md, "utf-8");

  // PIPELINE.md is ours to own. AGENTS.md / CLAUDE.md are commonly user-authored,
  // so write the pointer only when the file is ABSENT or is byte-for-byte the
  // exact pointer we generate — never clobber hand-written instructions, even a
  // file that merely references `@PIPELINE.md` alongside its own content.
  const written = ["PIPELINE.md"];
  const pointers: Array<[string, string]> = [
    ["AGENTS.md", `See @PIPELINE.md for this pipeline's graph, assets, and how to run it.\n`],
    ["CLAUDE.md", `Instructions are in @PIPELINE.md\n`],
  ];
  for (const [name, content] of pointers) {
    const p = path.join(folderDir, name);
    if (existsSync(p)) {
      let existing: string;
      try {
        existing = readFileSync(p, "utf-8");
      } catch {
        continue;
      }
      // Anything other than our exact generated pointer is treated as
      // hand-written and preserved (writing when identical is a no-op anyway).
      if (existing.trim() !== content.trim()) {
        log.warn(
          colors.yellow(`Kept existing f/${f}/${name} (hand-written — not the generated pointer)`),
        );
        continue;
      }
    }
    await writeFile(p, content, "utf-8");
    written.push(name);
  }
  log.info(colors.green(`✓ Wrote ${written.join(", ")} to f/${f}`));
}

// Faithful TS port of the lexical rules in
// `backend/parsers/windmill-parser/src/duckdb_macros.rs` — keep the two in
// lockstep. Deliberately lexical, not an AST parse: over-matching a call only
// draws a spurious edge, never a wrong run. A macro reached only through dynamic
// SQL (`query('…')`) is invisible to call detection here as on the server —
// `// use <lib>` forces the whole-library edge instead.

export type ParsedMacro = {
  // Lowercased bare identifier (DuckDB identifiers are case-insensitive unquoted;
  // qualified / quoted names are rejected, matching the backend).
  name: string;
  // Verbatim text inside the parameter parens (may be empty).
  params: string;
  isTable: boolean;
};

// Case-insensitive whole-word prefix strip (whitespace-bounded). Returns the
// remainder with leading whitespace trimmed, or null when `s` does not start with
// `kw` as a whole word. `kw` must be lowercase. Mirrors `strip_kw`.
function stripKw(s: string, kw: string): string | null {
  if (s.length < kw.length) return null;
  if (s.slice(0, kw.length).toLowerCase() !== kw) return null;
  const after = s.slice(kw.length);
  if (after.length === 0 || /^\s/.test(after)) return after.replace(/^\s+/, "");
  return null;
}

function isIdent(s: string): boolean {
  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(s);
}

// Split a script body into `;`-terminated statements with line comments
// (`--`, `//`), block comments (`/* */`), and quoted spans stripped/preserved as
// in the SQL executor. Char-wise (not byte-wise) so multi-byte text survives.
// Mirrors `split_statements`.
export function splitStatements(sql: string): string[] {
  const out: string[] = [];
  let cur = "";
  const chars = [...sql];
  let i = 0;
  const n = chars.length;
  while (i < n) {
    const c = chars[i];
    // line comment: `--` (SQL) or `//` (Windmill annotation prefix)
    if (
      (c === "-" && i + 1 < n && chars[i + 1] === "-") ||
      (c === "/" && i + 1 < n && chars[i + 1] === "/")
    ) {
      while (i < n && chars[i] !== "\n") i += 1;
      continue;
    }
    // block comment
    if (c === "/" && i + 1 < n && chars[i + 1] === "*") {
      i += 2;
      while (i + 1 < n && !(chars[i] === "*" && chars[i + 1] === "/")) i += 1;
      i += 2;
      continue;
    }
    // single-quoted string ('' escapes an embedded quote)
    if (c === "'") {
      cur += c;
      i += 1;
      while (i < n) {
        cur += chars[i];
        if (chars[i] === "'") {
          if (i + 1 < n && chars[i + 1] === "'") {
            cur += "'";
            i += 2;
            continue;
          }
          i += 1;
          break;
        }
        i += 1;
      }
      continue;
    }
    // double-quoted identifier
    if (c === '"') {
      cur += c;
      i += 1;
      while (i < n) {
        cur += chars[i];
        if (chars[i] === '"') {
          i += 1;
          break;
        }
        i += 1;
      }
      continue;
    }
    if (c === ";") {
      const t = cur.trim();
      if (t !== "") out.push(t);
      cur = "";
      i += 1;
      continue;
    }
    cur += c;
    i += 1;
  }
  const t = cur.trim();
  if (t !== "") out.push(t);
  return out;
}

// Parse one comment-free, `;`-less statement as a CREATE MACRO. Returns null when
// the statement is not a well-formed macro definition (unlike the backend, which
// distinguishes "not macro-shaped" from "malformed" to surface deploy errors —
// the local graph is lenient and simply skips anything it can't read). Mirrors
// `parse_create_macro` for the shape it accepts.
export function parseCreateMacro(stmt: string): ParsedMacro | null {
  let rest = stripKw(stmt.trim(), "create");
  if (rest === null) return null;
  const afterOr = stripKw(rest, "or");
  if (afterOr !== null) {
    const afterReplace = stripKw(afterOr, "replace");
    if (afterReplace === null) return null; // CREATE OR <not replace>
    rest = afterReplace;
  }
  const afterTemp = stripKw(rest, "temp") ?? stripKw(rest, "temporary");
  if (afterTemp !== null) rest = afterTemp;
  // `FUNCTION` is DuckDB's alias for `MACRO`.
  const afterMacro = stripKw(rest, "macro") ?? stripKw(rest, "function");
  if (afterMacro === null) return null;
  rest = afterMacro;

  const nameEndMatch = rest.match(/[\s(]/);
  const nameEnd = nameEndMatch ? nameEndMatch.index! : rest.length;
  const rawName = rest.slice(0, nameEnd);
  if (rawName === "" || rawName.includes(".") || rawName.includes('"') || !isIdent(rawName)) {
    return null;
  }
  const name = rawName.toLowerCase();

  rest = rest.slice(nameEnd).replace(/^\s+/, "");
  if (!rest.startsWith("(")) return null;
  // Balanced-paren scan for the verbatim param list; skip quoted spans (a default
  // value may contain a paren).
  const pchars = [...rest];
  let depth = 0;
  let j = 0;
  let close = -1;
  while (j < pchars.length) {
    const ch = pchars[j];
    if (ch === "(") depth += 1;
    else if (ch === ")") {
      depth -= 1;
      if (depth === 0) {
        close = j;
        break;
      }
    } else if (ch === "'" || ch === '"') {
      const q = ch;
      j += 1;
      while (j < pchars.length && pchars[j] !== q) j += 1;
    }
    j += 1;
  }
  if (close === -1) return null; // unbalanced
  const params = pchars.slice(1, close).join("").trim();

  const afterParams = pchars.slice(close + 1).join("").replace(/^\s+/, "");
  let body = stripKw(afterParams, "as");
  if (body === null) return null;
  let isTable = false;
  const afterTable = stripKw(body, "table");
  if (afterTable !== null) {
    body = afterTable;
    isTable = true;
  }
  const trimmedBody = body.replace(/;+\s*$/, "").trim();
  if (trimmedBody === "") return null; // empty body
  return { name, params, isTable };
}

// All well-formed macro definitions in a `// macros` library body, in source
// order. Non-macro statements (setup: ATTACH/INSTALL/… ) are skipped.
export function parseMacroLibrary(sql: string): ParsedMacro[] {
  const out: ParsedMacro[] = [];
  for (const stmt of splitStatements(sql)) {
    const m = parseCreateMacro(stmt);
    if (m) out.push(m);
  }
  return out;
}

// Names from `names` that `sql` calls: an identifier token immediately followed
// by `(` (after optional whitespace), not `.`-qualified, outside strings and
// comments. Lexical (over-matching only adds an unused edge). Mirrors
// `detect_macro_calls`.
export function detectMacroCalls(sql: string, names: Set<string>): Set<string> {
  const found = new Set<string>();
  if (names.size === 0) return found;
  for (const stmt of splitStatements(sql)) {
    const chars = [...stmt];
    const n = chars.length;
    let i = 0;
    let prev: string | undefined = undefined;
    while (i < n) {
      const c = chars[i];
      if (c === "'" || c === '"') {
        const q = c;
        i += 1;
        while (i < n && chars[i] !== q) i += 1;
        i += 1;
        prev = q;
        continue;
      }
      const isIdentStart = /[A-Za-z_]/.test(c);
      const prevBlocks = prev !== undefined && /[.A-Za-z0-9_]/.test(prev);
      if (isIdentStart && !prevBlocks) {
        const start = i;
        while (i < n && /[A-Za-z0-9_]/.test(chars[i])) i += 1;
        const word = chars.slice(start, i).join("").toLowerCase();
        let k = i;
        while (k < n && /\s/.test(chars[k])) k += 1;
        if (k < n && chars[k] === "(" && names.has(word)) found.add(word);
        prev = chars[i - 1];
        continue;
      }
      prev = c;
      i += 1;
    }
  }
  return found;
}

// Scan the LEADING comment header for the `// macros` marker and `// use <lib>`
// annotations, independent of the wasm parser (which drops both). Faithful mirror
// of the canonical `parse_pipeline_annotations` (asset_parser.rs): each line's
// prefix is stripped as `//`, `--`, or `#` REGARDLESS of language (a DuckDB
// library may legitimately head its annotations with `// macros`), scanning stops
// at the first non-comment line, the marker must stand alone on its line, and a
// `// use` target is a single whitespace-free token containing `/`.
export function parseMacroAnnotations(
  content: string,
): { macros: boolean; useLibs: string[] } {
  let macros = false;
  const useLibs: string[] = [];
  for (const raw of content.split("\n")) {
    const line = raw.replace(/^\s+/, "");
    if (line === "") continue;
    let rest: string;
    if (line.startsWith("//") || line.startsWith("--")) rest = line.slice(2);
    else if (line.startsWith("#")) rest = line.slice(1);
    else break; // first line of actual code ends the annotation header
    rest = rest.replace(/^\s+/, "");
    // marker: `macros` as the only content on the line (rejects `macros_v2`,
    // `macros are below`)
    if (/^macros\s*$/.test(rest)) {
      macros = true;
      continue;
    }
    // `use <lib>`: a single whitespace-free path token (must contain `/`, so
    // prose like `use this to …` is dropped)
    const u = rest.match(/^use\s+(\S+)\s*$/);
    if (u && u[1].includes("/") && !useLibs.includes(u[1])) useLibs.push(u[1]);
  }
  return { macros, useLibs };
}

// Build a pipeline asset-graph from LOCAL, not-yet-deployed script files.
//
// The deployed asset-graph endpoint (`GET /assets/graph`) only reflects scripts
// already pushed to the workspace. To get the same graph from the working tree
// (so `pipeline show --local` / `pipeline run --local` / `pipeline dev` work
// before deploy), we infer each script's assets + pipeline annotations with the
// SAME wasm parser the frontend uses (`windmill-parser-wasm-asset`,
// `frontend/src/lib/infer.ts:inferAssets`). That wasm returns the full serialized
// Rust `ParseAssetsOutput`: body-inferred `assets` (with r/w/rw access) AND the
// parsed pipeline annotations (`in_pipeline`, `triggers`, …) in one call — so we
// reproduce the endpoint payload without a backend round-trip or a TS re-port of
// the annotation parser.

import * as fs from "node:fs";
import * as path from "node:path";
import process from "node:process";
import { loadParser } from "../../utils/metadata.ts";
import * as log from "../../core/log.ts";
import { exts, removeExtensionToPath } from "../script/script.ts";
import { inferContentTypeFromFilePath } from "../../utils/script_common.ts";
import { getWmillYamlPath } from "../../core/conf.ts";
import {
  detectMacroCalls,
  parseMacroAnnotations,
  parseMacroLibrary,
  type ParsedMacro,
} from "./duckdbMacros.ts";

// Resolve the workspace root (the directory containing wmill.yaml) for reading
// local files, falling back to the current directory.
export function workspaceRoot(): string {
  const yaml = getWmillYamlPath();
  return yaml ? path.dirname(yaml) : process.cwd();
}

// Graph payload shape — structurally identical to the backend `/assets/graph`
// response and a superset of `boundedCascade.ts`'s `BCGraph`. Defined here (the
// graph module) and re-imported by pipeline.ts so there is one canonical type.
export type GraphRunnable = {
  path: string;
  usage_kind: "script" | "flow" | "job";
  in_pipeline?: boolean;
  // Annotation metadata the shared canvas renders as badges / lineage. Mirrors
  // the deployed graph's runnable node (frontend `AssetGraphRunnableNode`) so the
  // local-dev graph is the same surface as the deployed one for annotated scripts.
  partition_kind?: string;
  freshness?: string;
  tag?: string;
  retry?: { count: number; delay?: string };
  data_tests?: unknown[];
  column_lineage?: unknown[];
  // `// materialize <asset>` target + strategy — the script's declared output,
  // so the UI anchors column lineage / the materialize badge to it (the producer
  // write-edge is emitted separately). `scd2` also identifies the producer of a
  // `<dim>_current` view for the editor's schema-contract fallback.
  materialize_target?: { kind: string; path: string };
  materialize_strategy?: "replace" | "append" | "merge" | "scd2";
  // `on_schema_change=ignore` — producer's opt-out from downstream
  // schema-contract warnings; only present when set (default `warn` is absent),
  // mirroring the deployed graph node.
  materialize_on_schema_change?: string;
  // `// macros` library: the macros it defines. Derived locally by
  // `buildMacroEdges` (the wasm asset parser emits neither the marker nor the
  // registry). Non-empty ⇒ definition-only node.
  macros?: { name: string; params?: string; is_table?: boolean }[];
  // Set by the deployed graph on a dbt script: it owns a whole project, so the
  // node counts models rather than reading as a single-output script. Never set
  // locally — a dbt descriptor has no asset parser here.
  dbt?: { model_count: number };
};
export type GraphEdge = {
  runnable_kind: string;
  runnable_path: string;
  asset_kind: string;
  asset_path: string;
  access_type?: "r" | "w" | "rw";
};
// Ordering-only "must-run-after" edge (HD-1): a `// data_test relationships`
// (or, best-effort, a custom `// data_test <script>` whose body reads an
// in-pipeline asset) needs the referenced asset's producer to materialize before
// the tested script runs — a dependency otherwise absent from the DAG, so a cold
// cascade could run the tested script first and hard-fail. Synthesized locally
// from the parsed `data_tests` + write edges; mirrors the deployed graph's
// `test_edges` (backend `asset_graph`) so `--local` orders a cold cascade the
// same way. Only emitted when the referenced asset has an in-pipeline producer;
// an external table (no producer) adds no edge. NOT a data-consumption edge.
export type GraphTestEdge = {
  producer_kind: string;
  producer_path: string;
  runnable_kind: string;
  runnable_path: string;
  asset_kind: string;
  asset_path: string;
};
export type GraphTrigger =
  | {
      trigger_kind: "asset";
      asset_kind: string;
      asset_path: string;
      runnable_kind: string;
      runnable_path: string;
    }
  | {
      trigger_kind: string;
      path?: string;
      runnable_kind: string;
      runnable_path: string;
      missing?: boolean;
    };
export type AssetGraph = {
  runnables: GraphRunnable[];
  // `derived_from` is the base `<dim>` path when this node is the SCD2
  // `<dim>_current` companion view of a managed `// materialize … history`
  // producer — lets the canvas mark it as a derived "current view". Absent
  // otherwise. Lockstep with backend `GraphAssetNode`.
  assets: { kind: string; path: string; derived_from?: string }[];
  edges: GraphEdge[];
  triggers: GraphTrigger[];
  // ƒ edges from a `// macros` library to the scripts calling its macros
  // (present on both the deployed graph and the locally-derived one).
  macro_edges?: {
    lib_path: string;
    consumer_path: string;
    macro_names: string[];
    via_use?: boolean;
  }[];
  // `// data_test` ordering edges (HD-1); present on both the deployed graph and
  // this local one. Absent when empty (matches the deployed graph's
  // `skip_serializing_if = Vec::is_empty`).
  test_edges?: GraphTestEdge[];
};

export type LocalScript = {
  path: string;
  content: string;
  language: string;
  // `// tag <worker-tag>` — routes the preview to that worker tag, matching the
  // deployed pipeline. Undefined → default worker.
  tag?: string;
};

// Raw shape of the wasm `parse_assets_<lang>` JSON output (a serialized Rust
// `ParseAssetsOutput`). `triggers` is internally tagged on `kind`
// (`#[serde(tag = "kind", rename_all = "lowercase")]`): asset triggers carry
// `asset_kind` + `path`; native triggers are bare `{ kind }`.
// One parsed `// data_test` entry (serialized Rust `DataTest`, tagged on `type`).
// A proper discriminated union over the five built-ins so a `dt.type` switch
// narrows; only `relationships` / `custom` carry a cross-asset ref that the
// local test-edge synthesis reads. Kept structurally identical to the wasm
// output and the deployed graph's `data_tests`.
export type ParsedDataTest =
  | { type: "unique"; column: string }
  | { type: "not_null"; column: string }
  | { type: "accepted_values"; column: string; values: string[] }
  | {
      type: "relationships";
      column: string;
      to_kind: string;
      to_path: string;
      to_column: string;
    }
  | { type: "custom"; path: string };

export type ParseAssetsRaw = {
  assets?: {
    kind: string;
    path: string;
    access_type?: "r" | "w" | "rw";
  }[];
  in_pipeline?: boolean;
  triggers?: (
    | { kind: "asset"; asset_kind: string; path: string; debounce?: string }
    | { kind: string }
  )[];
  // `// materialize [manual] <asset> …` — managed-materialize target (emitted by
  // the wasm asset parser). The body (a bare trailing SELECT) writes nothing
  // inferable, so the producer's output edge comes from here, not from `assets`.
  materialize?: {
    target_kind: string;
    target_path: string;
    manual?: boolean;
    append?: boolean;
    unique_key?: string;
    scd2?: boolean;
    // "ignore" when set; the default `warn` is skipped in serialization.
    on_schema_change?: string;
  };
  // `// tag <worker-tag>` — the worker tag the deployed pipeline routes to.
  tag?: string;
  // Other annotation metadata the deployed graph carries onto its runnable nodes.
  partition?: { kind: string };
  freshness?: { duration: string };
  retry?: { count: number; delay?: string };
  data_tests?: ParsedDataTest[];
  column_lineage?: unknown[];
};

// Mirror `inferAssets` (frontend/src/lib/infer.ts): only ts / py / sql have a
// wasm asset parser. SQL dialects all route to `parse_assets_sql` — the comment-
// header annotation scan inside it is dialect-independent, so `in_pipeline` /
// `// on` come through even when body asset detection is duckdb-shaped. Languages
// with no entry (go, bash, …) fall back to a minimal annotation scan below.
function wasmFnForLanguage(language: string): "parse_assets_ts" | "parse_assets_py" | "parse_assets_sql" | undefined {
  switch (language) {
    case "bun":
    case "deno":
    case "nativets":
      return "parse_assets_ts";
    case "bunnative":
      return "parse_assets_ts";
    case "python3":
      return "parse_assets_py";
    case "duckdb":
    case "postgresql":
    case "mysql":
    case "bigquery":
    case "snowflake":
    case "mssql":
    case "oracledb":
      return "parse_assets_sql";
    default:
      return undefined;
  }
}

const ASSET_WASM_PKG = "windmill-parser-wasm-asset";

// Comment prefix per language, for the no-wasm annotation fallback.
function commentPrefix(language: string): string {
  if (
    language === "python3" ||
    language === "bash" ||
    language === "ansible" ||
    language === "ruby" ||
    language === "rlang" ||
    language === "dbt" ||
    language === "nu" ||
    language === "powershell"
  )
    return "#";
  if (
    language === "postgresql" ||
    language === "mysql" ||
    language === "bigquery" ||
    language === "snowflake" ||
    language === "mssql" ||
    language === "oracledb" ||
    language === "duckdb"
  )
    return "--";
  return "//";
}

// Minimal annotation scan for languages without a wasm asset parser (go, bash).
// Deliberately a SUBSET of the canonical parsers (backend
// `parse_pipeline_annotations`, frontend `parsePipelineAnnotations.ts`): it
// recovers `// pipeline` membership, `// on <asset-uri | native-kind>`, and
// `// tag <worker-tag>` (routing affects execution) so the node, its trigger
// edges, and its worker tag still appear. Body-inferred I/O for these languages
// is out of scope (see plan); annotate explicitly to get edges.
const NATIVE_KINDS = new Set([
  "schedule",
  "webhook",
  "email",
  "kafka",
  "mqtt",
  "amqp",
  "nats",
  "postgres",
  "sqs",
  "gcp",
  "data_upload",
]);
function fallbackParse(content: string, language: string): ParseAssetsRaw {
  const raw = commentPrefix(language);
  const p = raw.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const out: ParseAssetsRaw = { in_pipeline: false, triggers: [] };
  // Annotations live in the LEADING comment header (like the canonical parsers).
  // Stop at the first non-comment line so a body comment — e.g. `// on s3://…`
  // inside commented-out code or a heredoc — can't inject a phantom trigger.
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (trimmed === "") continue;
    if (!trimmed.startsWith(raw)) break;
    if (line.match(new RegExp(`^\\s*${p}\\s*pipeline\\s*$`))) {
      out.in_pipeline = true;
      continue;
    }
    // `// tag <worker-tag>` — routes the preview; cheap to scan and it affects
    // execution, so recover it here too (the wasm path already carries it). A
    // worker tag is a single token — match `\S+` (not `.+`) so trailing prose
    // (`// tag gpu for heavy jobs`) can't smuggle a bogus multi-word tag.
    const tag = line.match(new RegExp(`^\\s*${p}\\s*tag\\s+(\\S+)\\s*$`));
    if (tag) {
      out.tag = tag[1];
      continue;
    }
    const on = line.match(new RegExp(`^\\s*${p}\\s*on\\s+(.+?)\\s*$`));
    if (!on) continue;
    // The asset/native kind is the FIRST token; trailing `key=value` options
    // (e.g. `debounce=5s`) are not part of the path.
    const rest = on[1].trim();
    const firstTok = rest.split(/\s+/)[0];
    const uri = firstTok.match(/^([a-z0-9_]+):\/\/(.+)$/i);
    if (uri) {
      const prefix = uri[1].toLowerCase();
      const kind = prefix === "s3" ? "s3object" : prefix;
      // The suffix is kept verbatim (mirrors Rust `parse_asset_syntax`): an S3
      // path encodes the storage, with a leading `/` for the workspace default
      // (`s3:///key` → `/key`) vs `s3://secondary/key` → `secondary/key`.
      out.triggers!.push({ kind: "asset", asset_kind: kind, path: uri[2] });
    } else if (NATIVE_KINDS.has(firstTok) && rest === firstTok) {
      // A native marker (`// on data_upload`) must stand alone: the canonical
      // parser rejects a marker line with trailing content (`// on data_upload
      // f/foo`, `# on kafka topic`), so match that here to keep local/deployed
      // parity for the fallback surface.
      out.triggers!.push({ kind: firstTok });
    }
  }
  return out;
}

function recoverHeaderNativeTriggers(content: string, language: string): string[] {
  const raw = commentPrefix(language);
  const p = raw.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const out: string[] = [];
  const seen = new Set<string>();
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (trimmed === "") continue;
    if (!trimmed.startsWith(raw)) break;
    const marker = line.match(new RegExp(`^\\s*${p}\\s*on\\s+(\\S+)\\s*$`));
    if (!marker) continue;
    const kind = marker[1];
    if (!NATIVE_KINDS.has(kind) || seen.has(kind)) continue;
    seen.add(kind);
    out.push(kind);
  }
  return out;
}

function normalizeRetry(retry: ParseAssetsRaw["retry"]): ParseAssetsRaw["retry"] {
  if (!retry?.delay) return retry;
  return { ...retry, delay: retry.delay.replace(/^delay=/, "") };
}

// Read-asset kinds whose read auto-derives a cascade trigger edge inside a
// `// pipeline`. Mirror of backend `is_auto_trigger_kind` (windmill-common
// assets.rs) / frontend `AUTO_TRIGGER_KINDS` (resolveGraph.ts) — ducklake
// tables and s3 objects; resource/datatable/volume/table stay explicit-`// on`.
// A local graph out of step with that set shows an edge the deploy will not
// cascade along, and the generated pipeline docs then describe the wrong DAG.
// `table` is excluded everywhere: a dbt run does not dispatch, and nothing else
// writes a warehouse relation.
const AUTO_TRIGGER_KINDS = new Set(["ducklake", "s3object"]);

// Asset-URI prefixes accepted by `// mute <asset>`, in lockstep with the
// canonical `parse_asset_syntax` / frontend `ASSET_PREFIXES`. Non-derivable
// kinds are parsed too (their muted key simply never matches a derived edge),
// so a mute line is never REinterpreted differently from the deploy path.
const MUTE_ASSET_PREFIXES: [string, string][] = [
  ["s3://", "s3object"],
  ["res://", "resource"],
  ["$res:", "resource"],
  ["ducklake://", "ducklake"],
  ["datatable://", "datatable"],
  ["volume://", "volume"],
];

// `// mute <asset>` / `// mute all` from the LEADING comment header, as
// `<kind>:<path>` keys. Parsed locally because the pinned wasm asset parser
// predates the mute annotations; mirrors the canonical parsers (Rust
// `parse_pipeline_annotations`, frontend parsePipelineAnnotations.ts): any of
// the three comment prefixes is accepted regardless of language, blank lines
// are skipped, scanning stops at the first non-comment line, and `mute` must
// be a complete word (`// muted for now` never matches).
export function parseMuteAnnotations(content: string): {
  muteAll: boolean;
  muted: Set<string>;
} {
  const muted = new Set<string>();
  let muteAll = false;
  for (const rawLine of content.split("\n")) {
    const line = rawLine.trimStart();
    if (line === "") continue;
    let rest: string;
    if (line.startsWith("//")) rest = line.slice(2);
    else if (line.startsWith("--")) rest = line.slice(2);
    else if (line.startsWith("#")) rest = line.slice(1);
    else break;
    rest = rest.trimStart();
    if (!rest.startsWith("mute")) continue;
    const after = rest.slice("mute".length);
    if (after !== "" && !/^\s/.test(after)) continue;
    const arg = after.trim();
    if (arg === "all") {
      muteAll = true;
      continue;
    }
    for (const [prefix, kind] of MUTE_ASSET_PREFIXES) {
      if (arg.startsWith(prefix)) {
        // The suffix is kept verbatim, as in `parse_asset_syntax` — a muted
        // `s3:///key` (default storage, path `/key`) only matches an inferred
        // default-storage read of the same object.
        muted.add(`${kind}:${arg.slice(prefix.length)}`);
        break;
      }
    }
  }
  return { muteAll, muted };
}

// Comment prefix for `volume:` annotations. Deliberately NOT `commentPrefix`
// above (which returns `--` for SQL): volume annotations are only recognized for
// the languages the backend/frontend recognize them for — mirrors
// `asset_inference.rs:comment_prefix` and `infer.ts:getCommentPrefix` (SQL → none).
function volumeCommentPrefix(language: string): string | undefined {
  switch (language) {
    case "python3":
    case "bash":
    case "powershell":
    case "ansible":
    case "ruby":
    case "rlang":
      return "#";
    case "deno":
    case "bun":
    case "bunnative":
    case "nativets":
    case "go":
      return "//";
    default:
      return undefined;
  }
}

// `<prefix> volume: <path>` lines in the LEADING comment block, each an `rw`
// volume asset. Scanning stops at the first non-comment line (blank lines
// skipped). Exact mirror of frontend `parseVolumeAnnotations` (infer.ts) /
// backend `parse_volume_annotations` (asset_inference.rs) — the wasm body parser
// does NOT emit these, so the local graph must supplement them or a `volume:`
// producer shows disconnected from its `// on volume://…` consumers.
function parseVolumeAnnotations(
  content: string,
  prefix: string,
): { kind: string; path: string; access_type: "rw" }[] {
  const out: { kind: string; path: string; access_type: "rw" }[] = [];
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (trimmed === "") continue;
    if (!trimmed.startsWith(prefix)) break;
    const after = trimmed.slice(prefix.length).trim();
    const m = after.match(/^volume:\s*(\S+)/);
    if (m) out.push({ kind: "volume", path: m[1], access_type: "rw" });
  }
  return out;
}

// Infer a single script's assets + pipeline annotations. Returns the raw
// `ParseAssetsOutput` (incl. `materialize` with its `scd2` flag, which the wasm
// asset parser emits as of windmill-parser-wasm-asset 1.749.0 — kept in lockstep
// with the frontend's pin so the local graph mirrors the deployed one), plus
// `volume:` annotation assets the wasm doesn't surface (merged in below, like
// the frontend/backend).
// wasm parse errors degrade to the annotation fallback so a syntactically-broken
// script still shows as a pipeline node if it's annotated.
export async function inferScriptAssets(
  content: string,
  language: string,
): Promise<ParseAssetsRaw> {
  const out = await inferScriptAssetsBody(content, language);
  const vp = volumeCommentPrefix(language);
  if (vp) {
    const vols = parseVolumeAnnotations(content, vp);
    if (vols.length > 0) out.assets = [...(out.assets ?? []), ...vols];
  }
  return out;
}

// Warn once when the wasm asset parser can't load: the annotation-only
// fallback silently drops all inferred read/write edges, so a packaging or
// install problem would otherwise masquerade as a parsing limitation.
let warnedAssetParserUnavailable = false;

async function inferScriptAssetsBody(
  content: string,
  language: string,
): Promise<ParseAssetsRaw> {
  const fn = wasmFnForLanguage(language);
  if (!fn) return fallbackParse(content, language);
  let raw: string;
  try {
    const mod = await loadParser(ASSET_WASM_PKG);
    raw = mod[fn](content) as string;
  } catch (e) {
    if (!warnedAssetParserUnavailable) {
      warnedAssetParserUnavailable = true;
      log.warnStderr(
        `warning: ${ASSET_WASM_PKG} failed to load (${
          e instanceof Error ? e.message : e
        }) — falling back to annotation-only parsing; inferred read/write edges (materialize targets, COPY TO, writeS3File) will be missing from the local graph`,
      );
    }
    return fallbackParse(content, language);
  }
  if (raw.startsWith("err:")) return fallbackParse(content, language);
  try {
    return JSON.parse(raw) as ParseAssetsRaw;
  } catch {
    return fallbackParse(content, language);
  }
}

// Recursively collect every local script file under `folderDir`, returning each
// one's windmill path (relative to `root`, extension stripped), content, and
// language. Skips lock files and metadata YAMLs.
export async function collectScripts(
  folderDir: string,
  root: string,
  defaultTs: "bun" | "deno" | undefined,
): Promise<LocalScript[]> {
  const out: LocalScript[] = [];
  function walk(dir: string) {
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      if (e.name.startsWith(".") || e.name === "node_modules") continue;
      const abs = path.join(dir, e.name);
      if (e.isDirectory()) {
        walk(abs);
        continue;
      }
      if (!e.isFile()) continue;
      const ext = exts.find((x) => e.name.endsWith(x));
      if (!ext) continue;
      const relFromRoot = path.relative(root, abs).replaceAll("\\", "/");
      // A bare `.sql` (no dialect) makes inferContentTypeFromFilePath throw —
      // skip the file rather than letting one unclassifiable file abort the
      // whole graph build (which would also wedge `pipeline dev` at startup).
      let language: string;
      try {
        language = inferContentTypeFromFilePath(abs, defaultTs);
      } catch {
        continue;
      }
      out.push({
        path: removeExtensionToPath(relFromRoot),
        content: fs.readFileSync(abs, "utf-8"),
        language,
      });
    }
  }
  walk(folderDir);
  out.sort((a, b) => a.path.localeCompare(b.path));
  return out;
}

// The structural minimum the dbt filter needs. Declared instead of taking
// `AssetGraph` so the bounded-cascade view of the same payload (`BCGraph`, a
// narrower shape over identical JSON) passes through without a cast.
type DbtFilterableGraph = {
  runnables: { path: string; usage_kind: string; dbt?: unknown }[];
  edges: { runnable_kind: string; runnable_path: string }[];
  triggers: { runnable_kind: string; runnable_path: string }[];
  macro_edges?: { lib_path: string; consumer_path: string }[];
  test_edges?: {
    producer_kind: string;
    producer_path: string;
    runnable_kind: string;
    runnable_path: string;
  }[];
};

/**
 * The pipeline's view of a deployed graph whose folder also holds a dbt project.
 *
 * `/assets/graph` is asset-usage driven, not membership driven: it lists every
 * script that reads or writes a relation, so a dbt script appears there like any
 * producer. That is right for the endpoint — the node is what attributes a
 * relation to what builds it — but a dbt project is not a pipeline, so it must
 * not be rendered as one of its scripts. Mirrors the frontend's
 * `hideDbtRunnables`; the local builder drops these nodes at the source.
 *
 * Its relations stay: they are what a downstream pipeline script reads.
 */
export function hideDbtRunnables<G extends DbtFilterableGraph>(graph: G): G {
  // Keyed by `(usage_kind, path)`, the graph's identity for a runnable — a
  // script and a flow may share a path, and keying on path alone would take the
  // flow's node, edges and triggers down with the dbt script's.
  const key = (usage_kind: string, path: string) => `${usage_kind}:${path}`;
  const dbtKeys = new Set(
    (graph.runnables ?? [])
      .filter((r) => r.dbt)
      .map((r) => key(r.usage_kind, r.path)),
  );
  if (dbtKeys.size === 0) return graph;
  const kept = (usage_kind: string, path: string) =>
    !dbtKeys.has(key(usage_kind, path));
  return {
    ...graph,
    runnables: graph.runnables.filter((r) => kept(r.usage_kind, r.path)),
    edges: graph.edges.filter((e) => kept(e.runnable_kind, e.runnable_path)),
    triggers: graph.triggers.filter((t) =>
      kept(t.runnable_kind, t.runnable_path),
    ),
    // A macro library is a script; a dbt script defines no macros, so neither
    // end can be a flow.
    ...(graph.macro_edges
      ? {
          macro_edges: graph.macro_edges.filter(
            (m) => kept("script", m.lib_path) && kept("script", m.consumer_path),
          ),
        }
      : {}),
    ...(graph.test_edges
      ? {
          test_edges: graph.test_edges.filter(
            (t) =>
              kept(t.producer_kind, t.producer_path) &&
              kept(t.runnable_kind, t.runnable_path),
          ),
        }
      : {}),
  };
}

// Build the full pipeline asset-graph from local files in `f/<folder>/`.
// Only `// pipeline` scripts become graph nodes (pipeline membership), mirroring
// the deployed graph endpoint. Returns the graph plus the in-pipeline scripts'
// content (the dev watcher pushes the latter; the runner re-reads it for preview).
export async function buildLocalPipelineGraph(args: {
  root: string;
  folder: string;
  defaultTs?: "bun" | "deno";
}): Promise<{ graph: AssetGraph; scripts: LocalScript[] }> {
  const folderClean = args.folder.replace(/^f\//, "").replace(/\/$/, "");
  const folderDir = path.join(args.root, "f", folderClean);
  const all = await collectScripts(folderDir, args.root, args.defaultTs);

  // `// macros` DuckDB libraries across the whole workspace (a pipeline may use a
  // shared library outside its folder).
  const libMacros = collectMacroLibraries(args.root);

  const runnables: GraphRunnable[] = [];
  const edges: GraphEdge[] = [];
  const triggers: GraphTrigger[] = [];
  const assetSet = new Map<
    string,
    { kind: string; path: string; derived_from?: string }
  >();
  // `<kind>:<current-path>` → base `<dim>` path, for scd2 `_current` companion
  // views. Applied to the final asset nodes so a consumer's `// on …_current`
  // trigger (processed after the producer) can't clobber the derived marker.
  const derivedFromByKey = new Map<string, string>();
  const pipelineScripts: LocalScript[] = [];
  // For HD-1 test edges: a pipeline member's parsed `// data_test`s, and the
  // assets each script READS (any script, so a custom test resolves against a
  // non-member test script's reads — best-effort, mirroring the backend, which
  // resolves custom tests against every deployed runnable's asset usages).
  const dataTestsByPath = new Map<string, ParsedDataTest[]>();
  const readsByRunnable = new Map<string, { kind: string; path: string }[]>();

  for (const s of all) {
    const out = await inferScriptAssets(s.content, s.language);
    const reads = (out.assets ?? [])
      .filter(
        (a) =>
          a.access_type == null ||
          a.access_type === "r" ||
          a.access_type === "rw",
      )
      .map((a) => ({ kind: a.kind, path: a.path }));
    if (reads.length > 0) readsByRunnable.set(s.path, reads);
    // A `// macros` library is a pipeline-member node carrying its macro
    // signatures — whether or not any consumer uses it — matching the deployed
    // graph, which marks every macro library `auto_kind='pipeline'`. It is
    // definition-only (no assets/triggers, never run), so we add just the node;
    // it is NOT a previewable script (excluded from `pipelineScripts`).
    const macroLibDefs = libMacros.get(s.path);
    if (macroLibDefs) {
      runnables.push({
        path: s.path,
        usage_kind: "script",
        in_pipeline: true,
        ...(out.tag ? { tag: out.tag } : {}),
        macros: macroLibDefs.map((m) => ({
          name: m.name,
          params: m.params,
          is_table: m.isTable,
        })),
      });
      continue;
    }
    // A dbt project is not a data pipeline: the deploy never marks a dbt script
    // `auto_kind='pipeline'` and the pipeline canvas drops its node, so the
    // local graph must not invent one. Its models don't belong here either —
    // they come from the manifest the deploy derives, not from the descriptor.
    if (s.language === "dbt") continue;
    if (!out.in_pipeline) continue; // not a pipeline member
    if (out.data_tests && out.data_tests.length > 0) {
      dataTestsByPath.set(s.path, out.data_tests);
    }
    const retry = normalizeRetry(out.retry);
    const nativeTriggers = recoverHeaderNativeTriggers(s.content, s.language);
    // Carry the parsed `// tag` so previews route to the same worker the
    // deployed pipeline would (both `pipeline run --local` and `/pipeline_dev`).
    pipelineScripts.push(out.tag ? { ...s, tag: out.tag } : s);
    const mat = out.materialize;
    // Managed-materialize write strategy, derived like the deployed graph —
    // precedence mirrors the runtime: scd2 (`history`) > append > merge
    // (key=<col>) > replace. Manual mode has no managed strategy.
    const materialize_strategy =
      mat && !mat.manual
        ? mat.scd2
          ? "scd2"
          : mat.append
            ? "append"
            : mat.unique_key
              ? "merge"
              : "replace"
        : undefined;
    runnables.push({
      path: s.path,
      usage_kind: "script",
      in_pipeline: true,
      ...(out.partition ? { partition_kind: out.partition.kind } : {}),
      ...(out.freshness ? { freshness: out.freshness.duration } : {}),
      ...(out.tag ? { tag: out.tag } : {}),
      ...(retry ? { retry } : {}),
      ...(out.data_tests && out.data_tests.length > 0 ? { data_tests: out.data_tests } : {}),
      ...(out.column_lineage && out.column_lineage.length > 0
        ? { column_lineage: out.column_lineage }
        : {}),
      ...(mat ? { materialize_target: { kind: mat.target_kind, path: mat.target_path } } : {}),
      ...(materialize_strategy ? { materialize_strategy } : {}),
      ...(mat?.on_schema_change === "ignore"
        ? { materialize_on_schema_change: "ignore" }
        : {}),
    });

    for (const a of out.assets ?? []) {
      assetSet.set(`${a.kind}:${a.path}`, { kind: a.kind, path: a.path });
      edges.push({
        runnable_kind: "script",
        runnable_path: s.path,
        asset_kind: a.kind,
        asset_path: a.path,
        access_type: a.access_type,
      });
    }
    // `// materialize <asset>` declares a write output via annotation, not the
    // SQL body, so body-inference misses it. Translate the parsed materialize
    // target into the producer's write edge here (mirrors frontend
    // resolveGraph.ts) so the materialized asset connects to its `// on`
    // consumers; dedup against any body write. A managed scd2 materialize also
    // produces the `<dim>_current` companion view — register it as a second
    // write (mirrors the deploy path) so a consumer reading only the view links
    // back to this producer instead of orphaning.
    if (mat) {
      const matWrites: { path: string; derived_from?: string }[] = [
        { path: mat.target_path },
      ];
      if (mat.scd2 && !mat.manual) {
        const currentPath = `${mat.target_path}_current`;
        matWrites.push({ path: currentPath, derived_from: mat.target_path });
        derivedFromByKey.set(
          `${mat.target_kind}:${currentPath}`,
          mat.target_path,
        );
      }
      for (const w of matWrites) {
        assetSet.set(`${mat.target_kind}:${w.path}`, {
          kind: mat.target_kind,
          path: w.path,
          ...(w.derived_from ? { derived_from: w.derived_from } : {}),
        });
        const hasWrite = edges.some(
          (e) =>
            e.runnable_path === s.path &&
            e.asset_kind === mat.target_kind &&
            e.asset_path === w.path &&
            (e.access_type === "w" || e.access_type === "rw"),
        );
        if (!hasWrite) {
          edges.push({
            runnable_kind: "script",
            runnable_path: s.path,
            asset_kind: mat.target_kind,
            asset_path: w.path,
            access_type: "w",
          });
        }
      }
    }
    const existingNativeTriggers = new Set<string>();
    for (const t of out.triggers ?? []) {
      if (t.kind === "asset") {
        const at = t as { kind: "asset"; asset_kind: string; path: string };
        assetSet.set(`${at.asset_kind}:${at.path}`, {
          kind: at.asset_kind,
          path: at.path,
        });
        triggers.push({
          trigger_kind: "asset",
          asset_kind: at.asset_kind,
          asset_path: at.path,
          runnable_kind: "script",
          runnable_path: s.path,
        });
      } else {
        existingNativeTriggers.add(t.kind);
        triggers.push({
          trigger_kind: t.kind,
          runnable_kind: "script",
          runnable_path: s.path,
        });
      }
    }
    for (const kind of nativeTriggers) {
      if (existingNativeTriggers.has(kind)) continue;
      triggers.push({
        trigger_kind: kind,
        runnable_kind: "script",
        runnable_path: s.path,
      });
    }
    // Auto-derived cascade edges (backend `derive_pipeline_asset_trigger_refs`,
    // frontend `deriveAutoAssetTriggers`): a pipeline script's read-only
    // ducklake/s3 input wires its cascade trigger straight from the body read,
    // so `// on <asset>` is only needed for edges inference can't see. Skipped:
    // assets this script also writes — including the `// materialize` target and
    // its scd2 `_current` companion, whose writes the body SELECT doesn't
    // express — plus `// mute <asset>` opt-outs and explicit `// on` (which wins
    // the dedup); `// mute all` opts the script out of derivation entirely.
    // Ambiguous access (no `access_type`) fails safe and derives nothing.
    const mute = parseMuteAnnotations(s.content);
    if (!mute.muteAll) {
      const skip = new Set<string>(mute.muted);
      for (const a of out.assets ?? []) {
        if (a.access_type === "w" || a.access_type === "rw") {
          skip.add(`${a.kind}:${a.path}`);
        }
      }
      if (mat) {
        skip.add(`${mat.target_kind}:${mat.target_path}`);
        if (mat.scd2 && !mat.manual) {
          skip.add(`${mat.target_kind}:${mat.target_path}_current`);
        }
      }
      for (const t of out.triggers ?? []) {
        if (t.kind === "asset") {
          const at = t as { kind: "asset"; asset_kind: string; path: string };
          skip.add(`${at.asset_kind}:${at.path}`);
        }
      }
      for (const a of out.assets ?? []) {
        if (a.access_type !== "r" || !AUTO_TRIGGER_KINDS.has(a.kind)) continue;
        const key = `${a.kind}:${a.path}`;
        if (skip.has(key)) continue;
        skip.add(key);
        triggers.push({
          trigger_kind: "asset",
          asset_kind: a.kind,
          asset_path: a.path,
          runnable_kind: "script",
          runnable_path: s.path,
        });
      }
    }
  }

  const macroEdges = buildMacroEdges(all, libMacros, runnables);

  const testEdges = buildTestEdges(dataTestsByPath, readsByRunnable, edges);

  const assets = [...assetSet.entries()].map(([key, a]) => {
    const derived_from = a.derived_from ?? derivedFromByKey.get(key);
    return derived_from ? { ...a, derived_from } : a;
  });

  return {
    graph: {
      runnables,
      assets,
      edges,
      triggers,
      ...(macroEdges.length > 0 ? { macro_edges: macroEdges } : {}),
      ...(testEdges.length > 0 ? { test_edges: testEdges } : {}),
    },
    scripts: pipelineScripts,
  };
}

// Synthesize HD-1 ordering edges from parsed `// data_test`s. Ports backend
// `asset_graph` (windmill-api-assets): resolve each test's referenced asset(s)
// to their in-pipeline producer(s) via the write edges, and add an ordering-only
// producer → tested-script edge. A `relationships` test references its `to_path`
// asset directly; a `custom` test references the tested/other script's parsed
// reads (best-effort). Self-edges (a script testing its own output) and assets
// with no in-pipeline producer are dropped, exactly like the backend.
function buildTestEdges(
  dataTestsByPath: Map<string, ParsedDataTest[]>,
  readsByRunnable: Map<string, { kind: string; path: string }[]>,
  edges: GraphEdge[],
): GraphTestEdge[] {
  const producersByAsset = new Map<string, { kind: string; path: string }[]>();
  for (const e of edges) {
    if (e.access_type !== "w" && e.access_type !== "rw") continue;
    // `\u0000` as the (kind, path) separator: it can't occur in an asset path,
    // so no packed key can collide.
    const key = `${e.asset_kind}\u0000${e.asset_path}`;
    (producersByAsset.get(key) ?? producersByAsset.set(key, []).get(key)!).push({
      kind: e.runnable_kind,
      path: e.runnable_path,
    });
  }

  const out: GraphTestEdge[] = [];
  // Dedup on (producer, tested_script, asset) so repeated tests / producers
  // referencing the same asset yield one edge (mirrors the backend's set).
  const seen = new Set<string>();
  for (const [memberPath, dts] of dataTestsByPath) {
    for (const dt of dts) {
      let referenced: { kind: string; path: string }[] = [];
      if (dt.type === "relationships") {
        referenced = [{ kind: dt.to_kind, path: dt.to_path }];
      } else if (dt.type === "custom") {
        // The custom test script's own parsed reads. Reading the member's OWN
        // output resolves to the member as producer and is dropped below.
        referenced = readsByRunnable.get(dt.path) ?? [];
      }
      for (const ref of referenced) {
        const producers = producersByAsset.get(`${ref.kind}\u0000${ref.path}`);
        if (!producers) continue; // external table (no producer) ⇒ no edge
        for (const p of producers) {
          // Skip a self-edge: the tested script produces the asset it tests.
          if (p.kind === "script" && p.path === memberPath) continue;
          const key = [p.path, memberPath, ref.kind, ref.path].join("\u0000");
          if (seen.has(key)) continue;
          seen.add(key);
          out.push({
            producer_kind: p.kind,
            producer_path: p.path,
            runnable_kind: "script",
            runnable_path: memberPath,
            asset_kind: ref.kind,
            asset_path: ref.path,
          });
        }
      }
    }
  }
  // Deterministic order for stable `--json` output (the deployed graph iterates
  // an unordered map; the local one sorts so snapshots don't churn).
  out.sort(
    (a, b) =>
      a.producer_path.localeCompare(b.producer_path) ||
      a.runnable_path.localeCompare(b.runnable_path) ||
      a.asset_kind.localeCompare(b.asset_kind) ||
      a.asset_path.localeCompare(b.asset_path),
  );
  return out;
}

// Every `// macros` DuckDB library in the workspace, keyed by its windmill path,
// mapped to its parsed macro definitions. Walks the whole `f/` tree (not just the
// pipeline folder) because the deployed graph resolves consumers against the
// workspace-wide macro registry — a pipeline may `// use` / call a shared library
// living outside its own folder. Only `*.duckdb.sql` files are read (macros are
// DuckDB-only), so the extra walk stays cheap.
function collectMacroLibraries(root: string): Map<string, ParsedMacro[]> {
  const out = new Map<string, ParsedMacro[]>();
  const walk = (dir: string) => {
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      if (e.name.startsWith(".") || e.name === "node_modules") continue;
      const abs = path.join(dir, e.name);
      if (e.isDirectory()) {
        walk(abs);
        continue;
      }
      if (!e.isFile() || !e.name.endsWith(".duckdb.sql")) continue;
      let content: string;
      try {
        content = fs.readFileSync(abs, "utf-8");
      } catch {
        continue;
      }
      if (!parseMacroAnnotations(content).macros) continue;
      const relFromRoot = path.relative(root, abs).replaceAll("\\", "/");
      out.set(removeExtensionToPath(relFromRoot), parseMacroLibrary(content));
    }
  };
  walk(path.join(root, "f"));
  return out;
}

// Derive lib→consumer edges (lexical calls + `// use`). In-folder libraries are
// already member nodes; this adds any out-of-folder provider referenced by an
// in-folder consumer. Mirrors the deployed `asset_graph`: libraries resolve
// workspace-wide, consumers are folder-scoped.
function buildMacroEdges(
  all: LocalScript[],
  libMacros: Map<string, ParsedMacro[]>,
  runnables: GraphRunnable[],
): NonNullable<AssetGraph["macro_edges"]> {
  if (libMacros.size === 0) return [];
  const useLibsByScript = new Map<string, string[]>();
  for (const s of all) {
    if (s.language !== "duckdb") continue;
    const { useLibs } = parseMacroAnnotations(s.content);
    if (useLibs.length > 0) useLibsByScript.set(s.path, useLibs);
  }

  // Macro name → providing library. Names are workspace-unique (the deploy path
  // enforces this); on a local collision, last-writer-wins, harmlessly.
  const providerByName = new Map<string, string>();
  for (const [lib, macros] of libMacros) {
    for (const m of macros) providerByName.set(m.name, lib);
  }
  const allMacroNames = new Set(providerByName.keys());

  // Aggregate per (lib, consumer): the set of called macro names and whether the
  // edge came (also) from a whole-library `// use`. Consumers are folder-scoped
  // (`all` is this folder's scripts).
  const pipelinePaths = new Set(runnables.map((r) => r.path));
  type EdgeAgg = { names: Set<string>; viaUse: boolean };
  // lib_path → consumer_path → aggregate. Nested (not a packed single-string key)
  // so no separator can ever collide with a path.
  const edgeMap = new Map<string, Map<string, EdgeAgg>>();
  const aggFor = (lib: string, consumer: string): EdgeAgg => {
    let byConsumer = edgeMap.get(lib);
    if (!byConsumer) {
      byConsumer = new Map();
      edgeMap.set(lib, byConsumer);
    }
    let agg = byConsumer.get(consumer);
    if (!agg) {
      agg = { names: new Set(), viaUse: false };
      byConsumer.set(consumer, agg);
    }
    return agg;
  };
  for (const s of all) {
    if (s.language !== "duckdb") continue;
    // Lexical call edges: the deploy path records `macro_usage` for EVERY DuckDB
    // script in the folder (not only pipeline members) — including a macro
    // library that calls another library's macros — so a lib→lib edge and its
    // upstream provider node survive. Mirror that: any folder DuckDB script is a
    // candidate consumer here.
    for (const name of detectMacroCalls(s.content, allMacroNames)) {
      const lib = providerByName.get(name)!;
      if (lib === s.path) continue; // a library calling its own macro is not an edge
      aggFor(lib, s.path).names.add(name);
    }
    // `// use` whole-library edges: the deployed graph re-parses these only from
    // pipeline members (`annotations_by_path`), so scope them the same way.
    if (!pipelinePaths.has(s.path)) continue;
    for (const lib of useLibsByScript.get(s.path) ?? []) {
      const macros = libMacros.get(lib);
      // An out-of-tree / unknown `// use` target can't be resolved locally.
      if (!macros || lib === s.path) continue;
      const agg = aggFor(lib, s.path);
      agg.viaUse = true;
      for (const m of macros) agg.names.add(m.name);
    }
  }

  const edges = [...edgeMap.entries()]
    .flatMap(([lib_path, byConsumer]) =>
      [...byConsumer.entries()].map(([consumer_path, agg]) => ({
        lib_path,
        consumer_path,
        macro_names: [...agg.names].sort(),
        // `via_use` is always present (the deployed `MacroEdge` serializes it
        // unconditionally) so `--json` matches byte-for-byte.
        via_use: agg.viaUse,
      })),
    )
    .sort((a, b) =>
      a.lib_path.localeCompare(b.lib_path) ||
      a.consumer_path.localeCompare(b.consumer_path),
    );

  // In-folder libraries are already member nodes (added above with `in_pipeline`
  // + macros). An OUT-OF-folder library referenced by an in-folder consumer is
  // added here as a non-member provider node (no `in_pipeline`), matching the
  // deployed graph, which folder-scopes membership but pulls the out-of-folder
  // provider in as the edge's endpoint.
  const libPaths = new Set<string>(edges.map((e) => e.lib_path));
  for (const lib of libPaths) {
    if (runnables.some((r) => r.path === lib)) continue;
    const macros = (libMacros.get(lib) ?? []).map((m) => ({
      name: m.name,
      params: m.params,
      is_table: m.isTable,
    }));
    runnables.push({ path: lib, usage_kind: "script", macros });
  }
  // Force every edge's CONSUMER endpoint into the node set too, like the deployed
  // builder, so no edge dangles at a missing runnable. Members and libraries are
  // already nodes; only a non-member DuckDB helper (calls a macro but isn't
  // `// pipeline` and isn't itself a library) needs a bare node here.
  for (const consumer of new Set(edges.map((e) => e.consumer_path))) {
    if (!runnables.some((r) => r.path === consumer)) {
      runnables.push({ path: consumer, usage_kind: "script" });
    }
  }
  runnables.sort((a, b) => a.path.localeCompare(b.path));

  return edges;
}

