export async function pullProtectionRules(
  opts: PullOpts,
  workspaceArg?: string,
) {
  // In JSON mode stdout must be exactly one JSON payload. Silence human logs
  // (log.info/warn → stdout) here, before anything that logs (readConfigFile,
  // workspace resolution). log.error still goes to stderr.
  if (opts.jsonOutput) log.setSilent(true);

  const prPath = getProtectionRulesPath();
  if (!prPath) {
    fail(opts, {
      error:
        "No wmill.yaml found. Run 'wmill init' first — protection-rules.yaml lives next to it.",
    });
  }

  const config = await readConfigFile();
  const resolver = WorkspaceResolver.fromConfig(config);

  let targets: string[];
  if (opts.all) {
    targets = resolver.knownNames();
    if (targets.length === 0) {
      fail(opts, {
        error: "No workspaces defined in wmill.yaml 'workspaces' block.",
      });
    }
  } else if (workspaceArg) {
    targets = [workspaceArg];
  } else {
    fail(opts, { error: "Specify a workspace name or use --all." });
  }

  const file = await readProtectionRulesFile(prPath!);
  const perWs: Record<string, any> = {};
  let hadError = false;
  let anyChange = false;

  for (const ws of targets) {
    let wsId: string;
    try {
      wsId = await configureClientForWorkspace(opts, ws, resolver);
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      if (opts.all) {
        log.error(colors.red(msg));
        hadError = true;
        continue;
      }
      fail(opts, { error: msg });
    }

    let backend;
    try {
      backend = ProtectionRulesConverter.fromBackend(
        await wmill.listProtectionRules({ workspace: wsId }),
      );
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      if (opts.all) {
        log.error(colors.red(`[${ws}] failed to fetch: ${msg}`));
        hadError = true;
        continue;
      }
      fail(opts, { error: `Failed to fetch protection rules: ${msg}` });
    }

    const current = ProtectionRulesConverter.normalizeList(file[ws]);
    // plan describes how the local file would change to match the backend
    const plan = ProtectionRulesConverter.computePlan(backend, current);
    if (ProtectionRulesConverter.planHasChanges(plan)) anyChange = true;
    perWs[ws] = structuredPlan(plan);

    if (!opts.dryRun) {
      file[ws] = backend;
    } else if (!opts.jsonOutput) {
      displayPlan(ws, plan);
    }
  }

  if (opts.dryRun) {
    if (opts.jsonOutput) {
      console.log(
        JSON.stringify({
          success: !hadError,
          dryRun: true,
          partialFailure: hadError,
          hasChanges: anyChange,
          workspaces: perWs,
        }),
      );
    } else if (!hadError && !anyChange) {
      log.info(colors.green("All targeted workspaces are in sync"));
    }
    if (hadError) process.exit(1);
    return;
  }

  await writeProtectionRulesFile(prPath!, file as ProtectionRulesFile);
  const n = Object.keys(perWs).length;
  if (hadError) {
    // Some --all workspaces failed: status must not say success while we
    // exit non-zero.
    outputResult(opts, {
      success: false,
      error: `Pulled ${n} workspace(s) into ${PROTECTION_RULES_FILENAME}, but one or more workspaces failed (see errors above)`,
      partialFailure: true,
      workspaces: perWs,
    });
    process.exit(1);
  }
  outputResult(opts, {
    success: true,
    message: `Pulled protection rules for ${n} workspace(s) into ${PROTECTION_RULES_FILENAME}`,
    workspaces: perWs,
  });
}

import process from "node:process";
import { existsSync } from "node:fs";

import { colors } from "@cliffy/ansi/colors";
import { Confirm } from "@cliffy/prompt/confirm";

import * as log from "../../core/log.ts";
import { GlobalOptions } from "../../types.ts";
import * as wmill from "../../../gen/services.gen.ts";
import { readConfigFile } from "../../core/conf.ts";

import { ProtectionRulesConverter, ProtectionRulesPlan } from "./converter.ts";
import {
  getProtectionRulesPath,
  readProtectionRulesFile,
  WorkspaceResolver,
  configureClientForWorkspace,
} from "./file.ts";
import { outputResult, fail, displayPlan, structuredPlan } from "./utils.ts";

type PushOpts = GlobalOptions & {
  all?: boolean;
  dryRun?: boolean;
  jsonOutput?: boolean;
  yes?: boolean;
};

interface WsPlan {
  ws: string;
  wsId: string;
  plan: ProtectionRulesPlan;
  wipesAll: boolean;
}

export async function pushProtectionRules(
  opts: PushOpts,
  workspaceArg?: string,
) {
  // In JSON mode stdout must be exactly one JSON payload. Silence human logs
  // (log.info/warn → stdout, incl. workspace resolution + the empty-list
  // delete warning) before anything logs. log.error still goes to stderr.
  if (opts.jsonOutput) log.setSilent(true);

  const prPath = getProtectionRulesPath();
  if (!prPath) {
    fail(opts, {
      error:
        "No wmill.yaml found. Run 'wmill init' first — protection-rules.yaml lives next to it.",
    });
  }
  if (!existsSync(prPath!)) {
    fail(opts, {
      error:
        "No protection-rules.yaml found. Run 'wmill protection-rules pull' first.",
    });
  }

  const config = await readConfigFile();
  const resolver = WorkspaceResolver.fromConfig(config);
  const file = await readProtectionRulesFile(prPath!);

  let targets: string[];
  if (opts.all) {
    targets = Object.keys(file).sort();
    if (targets.length === 0) {
      fail(opts, { error: "protection-rules.yaml defines no workspaces." });
    }
  } else if (workspaceArg) {
    if (!(workspaceArg in file)) {
      fail(opts, {
        error: `Workspace '${workspaceArg}' is not defined in protection-rules.yaml.`,
      });
    }
    targets = [workspaceArg];
  } else {
    fail(opts, { error: "Specify a workspace name or use --all." });
  }

  // Phase 1: resolve + diff every target before mutating anything.
  const wsPlans: WsPlan[] = [];
  let hadError = false;
  for (const ws of targets) {
    let wsId: string;
    try {
      wsId = await configureClientForWorkspace(opts, ws, resolver);
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      if (opts.all) {
        log.error(colors.red(msg));
        hadError = true;
        continue;
      }
      fail(opts, { error: msg });
    }

    let backend;
    try {
      backend = ProtectionRulesConverter.fromBackend(
        await wmill.listProtectionRules({ workspace: wsId }),
      );
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      if (opts.all) {
        log.error(colors.red(`[${ws}] failed to fetch: ${msg}`));
        hadError = true;
        continue;
      }
      fail(opts, { error: `Failed to fetch protection rules: ${msg}` });
    }

    const local = ProtectionRulesConverter.normalizeList(file[ws]);
    const plan = ProtectionRulesConverter.computePlan(local, backend);
    wsPlans.push({
      ws,
      wsId,
      plan,
      wipesAll: local.length === 0 && plan.toDelete.length > 0,
    });
  }

  const changed = wsPlans.filter((w) =>
    ProtectionRulesConverter.planHasChanges(w.plan)
  );

  if (opts.jsonOutput && opts.dryRun) {
    console.log(
      JSON.stringify({
        success: !hadError,
        dryRun: true,
        partialFailure: hadError,
        hasChanges: changed.length > 0,
        workspaces: Object.fromEntries(
          wsPlans.map((w) => [w.ws, structuredPlan(w.plan)]),
        ),
      }),
    );
    if (hadError) process.exit(1);
    return;
  }

  if (!opts.jsonOutput) {
    for (const w of wsPlans) displayPlan(w.ws, w.plan);
  }

  if (changed.length === 0) {
    if (hadError) {
      // A workspace failed to resolve/fetch — don't claim success while
      // exiting non-zero.
      outputResult(opts, {
        success: false,
        error:
          "One or more workspaces failed (see errors above); the rest are in sync",
        partialFailure: true,
      });
      process.exit(1);
    }
    if (!opts.dryRun) {
      outputResult(opts, {
        success: true,
        message: "No changes to push - all targeted workspaces are in sync",
      });
    }
    return;
  }

  if (opts.dryRun) {
    if (hadError) process.exit(1);
    return;
  }

  // Pushing an empty list wipes a workspace's rules — be loud even with --yes.
  for (const w of wsPlans) {
    if (w.wipesAll) {
      log.warn(
        colors.red(
          `WARNING: '${w.ws}' has an empty rule list — this DELETES ALL ${w.plan.toDelete.length} backend rule(s) for that workspace.`,
        ),
      );
    }
  }

  const totalDeletes = changed.reduce((n, w) => n + w.plan.toDelete.length, 0);
  if (!opts.yes && !!process.stdin.isTTY) {
    const confirmed = await Confirm.prompt({
      message: totalDeletes > 0
        ? `Apply these changes? This DELETES ${totalDeletes} protection rule(s) across ${changed.length} workspace(s).`
        : `Apply these changes to ${changed.length} workspace(s)?`,
      default: totalDeletes === 0,
    });
    if (!confirmed) {
      log.info("Operation cancelled");
      return;
    }
  }

  // Phase 2: apply. Track progress so a mid-run failure reports how far it got.
  const applied = { created: 0, updated: 0, deleted: 0 };
  try {
    for (const w of changed) {
      // Re-point the client at this workspace (phase 1 left it on the last one).
      await configureClientForWorkspace(opts, w.ws, resolver);
      for (const entry of w.plan.toCreate) {
        const n = ProtectionRulesConverter.normalizeEntry(entry);
        await wmill.createProtectionRule({
          workspace: w.wsId,
          requestBody: {
            name: n.name,
            rules: n.rules,
            bypass_groups: n.bypass_groups,
            bypass_users: n.bypass_users,
          },
        });
        applied.created++;
      }
      for (const entry of w.plan.toUpdate) {
        const n = ProtectionRulesConverter.normalizeEntry(entry);
        await wmill.updateProtectionRule({
          workspace: w.wsId,
          ruleName: n.name,
          requestBody: {
            rules: n.rules,
            bypass_groups: n.bypass_groups,
            bypass_users: n.bypass_users,
          },
        });
        applied.updated++;
      }
      for (const name of w.plan.toDelete) {
        await wmill.deleteProtectionRule({
          workspace: w.wsId,
          ruleName: name,
        });
        applied.deleted++;
      }
    }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    fail(opts, {
      error:
        `Push partially failed after ${applied.created} create, ${applied.updated} update, ` +
        `${applied.deleted} delete: ${msg}. Backend is partially reconciled; re-run push to converge.`,
      applied,
    });
  }

  if (hadError) {
    // Reconcile of resolvable workspaces succeeded, but some --all targets
    // failed earlier. Status must reflect the non-zero exit.
    outputResult(opts, {
      success: false,
      error: `Pushed (created ${applied.created}, updated ${applied.updated}, deleted ${applied.deleted}) across ${changed.length} workspace(s), but one or more workspaces failed (see errors above)`,
      partialFailure: true,
      ...applied,
    });
    process.exit(1);
  }
  outputResult(opts, {
    success: true,
    message: `Pushed protection rules (created ${applied.created}, updated ${applied.updated}, deleted ${applied.deleted}) across ${changed.length} workspace(s)`,
    ...applied,
  });
}

import { ProtectionRuleKind } from "../../../gen/types.gen.ts";

export type { ProtectionRuleKind };

// A single workspace protection ruleset as stored in protection-rules.yaml.
// Mirrors the backend ProtectionRuleset shape minus workspace_id (the workspace
// is the map key).
export interface ProtectionRuleEntry {
  name: string;
  rules: ProtectionRuleKind[];
  bypass_groups: string[];
  bypass_users: string[];
}

// protection-rules.yaml is a flat map: workspace name -> its protection rules.
// Workspace names MUST match keys in wmill.yaml's `workspaces` block, which is
// where the backend workspaceId/remote is resolved from.
export type ProtectionRulesFile = Record<string, ProtectionRuleEntry[]>;

import process from "node:process";

import { colors } from "@cliffy/ansi/colors";
import * as log from "../../core/log.ts";
import { ProtectionRuleEntry } from "./types.ts";
import { ProtectionRulesConverter, ProtectionRulesPlan } from "./converter.ts";

export function outputResult(
  opts: { jsonOutput?: boolean },
  result: {
    success: boolean;
    message?: string;
    error?: string;
    [key: string]: any;
  },
): void {
  if (opts.jsonOutput) {
    console.log(JSON.stringify(result));
  } else if (result.success && result.message) {
    log.info(colors.green(result.message));
  } else if (!result.success && result.error) {
    log.error(colors.red(result.error));
  }
}

// Report a genuine failure and exit non-zero so CI / scripted callers detect
// it. outputResult alone only logs, which would let a failed (possibly
// partial) reconcile hide behind exit code 0.
export function fail(
  opts: { jsonOutput?: boolean },
  result: { error: string; [key: string]: any },
): never {
  outputResult(opts, { ...result, success: false });
  process.exit(1);
}

function describeEntry(entry: ProtectionRuleEntry): string {
  const n = ProtectionRulesConverter.normalizeEntry(entry);
  const parts = [`rules=[${n.rules.join(", ")}]`];
  if (n.bypass_groups.length > 0) {
    parts.push(`bypass_groups=[${n.bypass_groups.join(", ")}]`);
  }
  if (n.bypass_users.length > 0) {
    parts.push(`bypass_users=[${n.bypass_users.join(", ")}]`);
  }
  return parts.join(" ");
}

// Render a reconciliation plan with a per-workspace heading.
export function displayPlan(ws: string, plan: ProtectionRulesPlan): void {
  log.info(colors.bold(`workspace ${ws}:`));
  for (const e of plan.toCreate) {
    log.info(colors.green(`  + ${e.name}  (${describeEntry(e)})`));
  }
  for (const e of plan.toUpdate) {
    log.info(colors.yellow(`  ~ ${e.name}  (${describeEntry(e)})`));
  }
  for (const name of plan.toDelete) {
    log.info(colors.red(`  - ${name}`));
  }
  if (!ProtectionRulesConverter.planHasChanges(plan)) {
    log.info(colors.green("  in sync"));
  }
}

export function structuredPlan(plan: ProtectionRulesPlan) {
  return {
    create: plan.toCreate.map((e) => e.name),
    update: plan.toUpdate.map((e) => e.name),
    delete: plan.toDelete,
    unchanged: plan.unchanged,
  };
}

import { Command } from "@cliffy/command";
import { Table } from "@cliffy/table";
import * as log from "../../core/log.ts";
import * as wmill from "../../../gen/services.gen.ts";
import { pickInstance } from "../instance/instance.ts";

type Data = {
  count: number;
  later: number;
  suspended: number;
  waiting: number;
  running: number;
  rps30s: string;
  rps5min: string;
  rps30min: string;
  rps24h: string;
}

type GlobalOptions = {
  instance?: string;
  baseUrl?: string;
};


function createRow(tag: string, data: Record<string, Data>) {
  if (data[tag]) {
    return;
  } else {
    data[tag] = {
      count: 0,
      waiting: 0,
      later: 0,
      running: 0,
      suspended: 0,
      rps30s: "",
      rps5min: "",
      rps30min: "",
      rps24h: "",
    }
  }
}
async function displayQueues(opts: GlobalOptions, workspace?: string) {
  const activeInstance = await pickInstance(opts, true);
  if (activeInstance) {
    try {
      const queuedJobs = await wmill.listQueue({workspace: workspace ?? 'admins', allWorkspaces: workspace === undefined, perPage: 100000});
      const jobCounts30s = await wmill.countJobsByTag({
        horizonSecs: 30,
        workspaceId: workspace,
      });
      const nowFromDb = new Date(await wmill.getDbClock());
      const jobCounts5min = await wmill.countJobsByTag({
        horizonSecs: 300,
        workspaceId: workspace,

      });
      const jobCounts30min = await wmill.countJobsByTag({
        horizonSecs: 1800,
        workspaceId: workspace,

      });
      const jobCounts24h = await wmill.countJobsByTag({
        horizonSecs: 86400,
        workspaceId: workspace,

      });

      const data: Record<string, Data> = {}

      for (const job of queuedJobs) {
        createRow(job.tag, data);
        const scheduledFor = new Date(job.scheduled_for ?? "");
        if (job.running) {
          if (job.suspend) {
            data[job.tag].suspended += 1;
          } else {
            data[job.tag].running += 1;
          }
        } else if (scheduledFor <= nowFromDb) {
          data[job.tag].waiting += 1;
        } else {
          data[job.tag].later += 1;
        } 
      }

      for (const count of jobCounts30s) {
        const tag = count.tag;
        createRow(tag, data);
        data[tag].rps30s = (count.count / 30).toFixed(3);
      }
      for (const count of jobCounts5min) {
        const tag = count.tag;
        createRow(tag, data);
        data[tag].rps5min = (count.count / 300).toFixed(3);
      }
      for (const count of jobCounts30min) {
        const tag = count.tag;
        createRow(tag, data);
        data[tag].rps30min = (count.count / 1800).toFixed(3);
      }

      for (const count of jobCounts24h) {
        const tag = count.tag;
        createRow(tag, data);
        data[tag].rps24h = (count.count / 86400).toFixed(3);
      }

      const table = new Table();
      table.header([
        "",
        "Running",
        "Waiting",
        "Later",
        "Suspended",
        "RPS (30s)",
        "RPS (5min)",
        "RPS (30min)",
        "RPS (24h)",
      ]);
      let body = []
      for (const tag in data) {
        body.push([tag, data[tag].running, data[tag].waiting, data[tag].later, data[tag].suspended, data[tag].rps30s, data[tag].rps5min, data[tag].rps30min, data[tag].rps24h]);
      }
      table.body(body).render();

    } catch (error) {
      log.error(`Failed to fetch queue metrics: ${error}`);
    }
  } else {
    log.info("No active instance found");
    log.info("Use 'wmill instance add' to add a new instance");
  }
}

const command = new Command()
  .description("List all queues with their metrics")
  .arguments("[workspace:string] the optional workspace to filter by (default to all workspaces)")
  .option(
    "--instance [instance]",
    "Name of the instance to push to, override the active instance"
  )
  .option(
    "--base-url [baseUrl]",
    "If used with --token, will be used as the base url for the instance"
  )
  .action(displayQueues as any);

export default command;

import { colors } from "@cliffy/ansi/colors";
import { Command } from "@cliffy/command";
import { Select } from "@cliffy/prompt/select";
import * as log from "../../core/log.ts";
import {
  type AgentsMdMigration,
  type ReconcileOutcome,
  WMILL_INIT_AI_AGENTS_SOURCE_ENV,
  WMILL_INIT_AI_CLAUDE_SOURCE_ENV,
  WMILL_INIT_AI_SKILLS_SOURCE_ENV,
  writeAiGuidanceFiles,
} from "../../guidance/writer.ts";

/**
 * Programmatic entry point reused by `wmill init`. The init flow doesn't
 * register the cliffy command itself — it imports and calls this directly so
 * that prompt regeneration is part of every init.
 */
export async function refreshPrompts(opts: {
  yes?: boolean;
}): Promise<void> {
  // Match `core/conf.ts`'s missing-key default (`?? false`) so legacy
  // wmill.yaml files without the key don't drift from how sync renders
  // paths. New projects get `true` via the wmill.yaml template, not via
  // this fallback.
  let nonDottedPaths = false;
  try {
    const { readConfigFile } = await import("../../core/conf.ts");
    const config = await readConfigFile();
    nonDottedPaths = config.nonDottedPaths ?? false;
  } catch {
    // If config can't be read, use the conservative default above.
  }

  const assumeYes = opts.yes === true;
  const interactive = process.stdin.isTTY && !assumeYes;

  try {
    const result = await writeAiGuidanceFiles({
      targetDir: ".",
      nonDottedPaths,
      skillsSourcePath: process.env[WMILL_INIT_AI_SKILLS_SOURCE_ENV],
      agentsSourcePath: process.env[WMILL_INIT_AI_AGENTS_SOURCE_ENV],
      claudeSourcePath: process.env[WMILL_INIT_AI_CLAUDE_SOURCE_ENV],
      resolveAgentsMdMigration: async () => {
        // Consent model (matches `wmill refresh tsconfig`): we only touch an
        // existing user-owned file that we don't recognize when the user opts
        // in. `--yes` (and `wmill init --default`) appends without asking; an
        // interactive run prompts; a plain non-interactive run leaves it alone.
        if (assumeYes) return "append";
        if (interactive) return await promptMigration();
        return "skip";
      },
    });

    log.info(colors.green("Refreshed AGENTS.wmill.md"));

    if (result.legacyManagedRemoved) {
      log.info(
        colors.yellow(
          "Migrated legacy AGENTS.cli.md → AGENTS.wmill.md (removed the old file and rewrote any @AGENTS.cli.md include)."
        )
      );
    }

    reportReconciliation({
      file: "AGENTS.md",
      includeLine: "@AGENTS.wmill.md",
      created: result.agentsCreated,
      migration: result.agentsMigration,
    });

    reportReconciliation({
      file: "CLAUDE.md",
      includeLine: "@AGENTS.md",
      created: result.claudeCreated,
      migration: result.claudeMigration,
    });

    log.info(
      colors.green(
        `Refreshed .claude/skills/ and .agents/skills/ with ${result.skillCount} skills`
      )
    );
    log.info(
      colors.gray(
        "Project-specific instructions live in AGENTS.md (never overwritten unless you opt in)."
      )
    );
  } catch (error) {
    // Log first so the user sees what happened, then rethrow so `wmill
    // refresh prompts` (and `wmill init`, which delegates here) exits
    // non-zero. Silent swallowing would hide a broken refresh from CI.
    if (error instanceof Error) {
      log.error(`Could not refresh guidance files: ${error.message}`);
    } else {
      log.error(`Could not refresh guidance files: ${error}`);
    }
    throw error;
  }
}

function reportReconciliation(opts: {
  file: string;
  includeLine: string;
  created: boolean;
  migration: ReconcileOutcome;
}): void {
  if (opts.created) {
    log.info(colors.green(`Created ${opts.file} (user-owned)`));
    return;
  }
  switch (opts.migration) {
    case "already-linked":
      log.info(
        colors.gray(
          `${opts.file} already references ${opts.includeLine} — left as-is`
        )
      );
      break;
    case "append":
      log.info(
        colors.green(`Appended ${opts.includeLine} include to existing ${opts.file}`)
      );
      break;
    case "overwrite":
      log.info(colors.yellow(`Overwrote ${opts.file} with managed skeleton`));
      break;
    case "skip":
      log.info(
        colors.gray(
          `${opts.file} left unchanged — wire \`${opts.includeLine}\` in manually when ready`
        )
      );
      break;
    case "not-applicable":
      // unreachable when created is false, but keep exhaustive
      break;
  }
}

async function promptMigration(): Promise<AgentsMdMigration> {
  log.info("");
  log.info(
    colors.yellow(
      "An existing AGENTS.md or CLAUDE.md was found that does not reference Windmill's managed guidance."
    )
  );
  log.info(
    colors.gray(
      "Choose how to link the managed files in (we'll apply the same choice to AGENTS.md and CLAUDE.md):"
    )
  );

  const choice = await Select.prompt({
    message: "How should we handle the existing file(s)?",
    options: [
      {
        name:
          "Append the include line " +
          "(preserves your content — recommended if you have custom instructions)",
        value: "append",
      },
      {
        name:
          "Overwrite with the managed skeleton " +
          "(replaces your content — pick if the file only had the default template)",
        value: "overwrite",
      },
      {
        name: "Skip — leave the file alone; I'll wire it up manually",
        value: "skip",
      },
    ],
  });

  return choice as AgentsMdMigration;
}

interface CommandOptions {
  yes?: boolean;
}

async function promptsAction(opts: CommandOptions): Promise<void> {
  await refreshPrompts({ yes: opts.yes === true });
}

const command = new Command()
