export async function pushWorkspaceSettings(
  workspace: string,
  _path: string,
  settings: SimplifiedSettings | undefined,
  localSettings: SimplifiedSettings | any
) {
  // Migrate local settings from legacy format if needed
  localSettings = migrateToGroupedFormat(localSettings);

  try {
    const remoteSettings = await wmill.getSettings({
      workspace,
    });

    const workspaceName = await wmill.getWorkspaceName({
      workspace,
    });

    // Build settings from remote (now using grouped format)
    settings = {
      auto_invite: remoteSettings.auto_invite as AutoInviteConfig | undefined,
      error_handler: remoteSettings.error_handler as ErrorHandlerConfig | undefined,
      success_handler: remoteSettings.success_handler as SuccessHandlerConfig | undefined,
      webhook: remoteSettings.webhook,
      ai_config: remoteSettings.ai_config,
      large_file_storage: remoteSettings.large_file_storage,
      git_sync: remoteSettings.git_sync,
      default_app: remoteSettings.default_app,
      default_scripts: remoteSettings.default_scripts,
      name: workspaceName,
      mute_critical_alerts: remoteSettings.mute_critical_alerts,
      color: remoteSettings.color,
      operator_settings: remoteSettings.operator_settings,
      datatable: remoteSettings.datatable,
      slack_team_id: remoteSettings.slack_team_id,
      slack_name: remoteSettings.slack_name,
      slack_command_script: remoteSettings.slack_command_script,
      slack_oauth_client_id: remoteSettings.slack_oauth_client_id,
      slack_oauth_client_secret: remoteSettings.slack_oauth_client_secret,
    };
  } catch (err) {
    throw new Error(`Failed to get workspace settings: ${err}`);
  }

  // Exclude fields that are never applied here: slack_team_id/slack_name are OAuth-only,
  // and name is not applied on pull (see below), so a name-only diff stays a no-op.
  const { slack_team_id: _lst, slack_name: _lsn, name: _ln, ...comparableLocal } = localSettings;
  const { slack_team_id: _rst, slack_name: _rsn, name: _rn, ...comparableRemote } = settings;
  if (isSuperset(comparableLocal, comparableRemote)) {
    log.debug(`Workspace settings are up to date`);
    return;
  }
  log.debug(`Workspace settings are not up-to-date, updating...`);

  if (localSettings.webhook !== settings.webhook) {
    log.debug(`Updating webhook...`);
    await wmill.editWebhook({
      workspace,
      requestBody: {
        webhook: localSettings.webhook,
      },
    });
  }

  // Handle auto_invite using grouped format
  if (!deepEqual(localSettings.auto_invite, settings.auto_invite)) {
    log.debug(`Updating auto invite...`);

    const localAutoInvite = localSettings.auto_invite;
    if (localAutoInvite?.mode && !["add", "invite"].includes(localAutoInvite.mode)) {
      throw new Error(
        `Invalid value for auto_invite.mode. Valid values are "invite" and "add"`
      );
    }
    try {
      await wmill.editAutoInvite({
        workspace,
        requestBody: localAutoInvite?.enabled
          ? {
              operator: localAutoInvite.operator ?? false,
              invite_all: true,
              auto_add: localAutoInvite.mode === "add",
            }
          : {},
      });
    } catch (_) {
      // on cloud
      log.debug(
        `Auto invite is not possible on cloud, only auto-inviting same domain...`
      );
      await wmill.editAutoInvite({
        workspace,
        requestBody: localAutoInvite?.enabled
          ? {
              operator: localAutoInvite.operator ?? false,
              invite_all: false,
              auto_add: localAutoInvite.mode === "add",
            }
          : {},
      });
    }
  }

  if (!deepEqual(localSettings.ai_config, settings.ai_config)) {
    log.debug(`Updating copilot settings...`);
    await wmill.editCopilotConfig({
      workspace,
      requestBody: localSettings.ai_config ?? {},
    });
  }

  // Handle error_handler using grouped format. YAML is canonical:
  // absent / null → clear remote; present object → upsert.
  // (Same "omit = clear" rule as every other workspace setting. Pull always
  // emits the field as null when remote is NULL, so round-trip is bijective.)
  if (!deepEqual(localSettings.error_handler, settings.error_handler)) {
    log.debug(`Updating error handler...`);
    const localErrorHandler = localSettings.error_handler;
    await wmill.editErrorHandler({
      workspace,
      requestBody: {
        path: localErrorHandler?.path,
        extra_args: localErrorHandler?.extra_args,
        muted_on_cancel: localErrorHandler?.muted_on_cancel ?? false,
        muted_on_user_path: localErrorHandler?.muted_on_user_path ?? false,
      },
    });
  }

  // Handle success_handler using grouped format. Same semantics as error_handler.
  if (!deepEqual(localSettings.success_handler, settings.success_handler)) {
    log.debug(`Updating success handler...`);
    const localSuccessHandler = localSettings.success_handler;
    await wmill.editSuccessHandler({
      workspace,
      requestBody: {
        path: localSuccessHandler?.path,
        extra_args: localSuccessHandler?.extra_args,
      },
    });
  }

  if (
    !deepEqual(localSettings.large_file_storage, settings.large_file_storage)
  ) {
    log.debug(`Updating large file storage...`);
    await wmill.editLargeFileStorageConfig({
      workspace,
      requestBody: {
        large_file_storage: localSettings.large_file_storage,
      },
    });
  }

  if (!deepEqual(localSettings.git_sync, settings.git_sync)) {
    log.debug(`Updating git sync...`);
    await wmill.editWorkspaceGitSyncConfig({
      workspace,
      requestBody: {
        git_sync_settings: localSettings.git_sync,
      },
    });
  }

  if (!deepEqual(localSettings.default_scripts, settings.default_scripts)) {
    log.debug(`Updating default scripts...`);
    await wmill.editDefaultScripts({
      workspace,
      requestBody: localSettings.default_scripts,
    });
  }

  if (localSettings.default_app != settings.default_app) {
    log.debug(`Updating default app...`);
    await wmill.editWorkspaceDefaultApp({
      workspace,
      requestBody: {
        default_app_path: localSettings.default_app,
      },
    });
  }

  // Workspace display name is intentionally not applied on pull: settings.yaml is shared
  // across a repo's branches, so applying it would let one workspace's name overwrite
  // another's when both sync the same repo. It stays in the file (written on push), but a
  // live workspace is only renamed by its owner.

  if (localSettings.mute_critical_alerts != settings.mute_critical_alerts) {
    log.debug(`Updating mute critical alerts...`);
    await wmill.workspaceMuteCriticalAlertsUi({
      workspace,
      requestBody: {
        mute_critical_alerts: localSettings.mute_critical_alerts,
      },
    });
  }

  if (localSettings.color != settings.color) {
    log.debug(`Updating workspace color...`);
    await wmill.changeWorkspaceColor({
      workspace,
      requestBody: {
        color: localSettings.color,
      },
    });
  }

  if (!deepEqual(localSettings.operator_settings, settings.operator_settings)) {
    log.debug(`Updating operator settings...`);
    await wmill.updateOperatorSettings({
      workspace,
      requestBody: localSettings.operator_settings,
    });
  }

  if (!deepEqual(localSettings.datatable, settings.datatable)) {
    log.debug(`Updating datatable config...`);
    await wmill.editDataTableConfig({
      workspace,
      requestBody: { settings: localSettings.datatable ?? { datatables: {} } },
    });
  }

  if (localSettings.slack_command_script != settings.slack_command_script) {
    log.debug(`Updating slack command script...`);
    await wmill.editSlackCommand({
      workspace,
      requestBody: {
        slack_command_script: localSettings.slack_command_script,
      },
    });
  }

  // Workspace-level Slack OAuth override. YAML is canonical (same rule as
  // every other setting): both present → upsert; anything else → delete.
  // Pull always emits both fields as null when remote is NULL.
  if (
    localSettings.slack_oauth_client_id != settings.slack_oauth_client_id ||
    localSettings.slack_oauth_client_secret != settings.slack_oauth_client_secret
  ) {
    log.debug(`Updating slack oauth config...`);
    if (
      localSettings.slack_oauth_client_id &&
      localSettings.slack_oauth_client_secret
    ) {
      await wmill.setWorkspaceSlackOauthConfig({
        workspace,
        requestBody: {
          slack_oauth_client_id: localSettings.slack_oauth_client_id,
          slack_oauth_client_secret: localSettings.slack_oauth_client_secret,
        },
      });
    } else {
      await wmill.deleteWorkspaceSlackOauthConfig({ workspace });
    }
  }
}

export interface PushWorkspaceKeyOptions {
  // True when no prompt may be shown (e.g. `--yes` was passed or stdin is not a
  // TTY). In that case the re-encryption decision is taken from `skipReencrypt`
  // / the WMILL_NO_REENCRYPT_ON_KEY_CHANGE env var instead of an interactive
  // confirmation.
  noninteractive?: boolean;
  // Explicit re-encryption decision from `--skip-reencrypt-on-key-change`.
  // When set it takes precedence over the prompt and the env var.
  skipReencrypt?: boolean;
}

export async function pushWorkspaceKey(
  workspace: string,
  _path: string,
  key: string | undefined,
  localKey: string,
  opts?: PushWorkspaceKeyOptions
) {
  try {
    key = await wmill
      .getWorkspaceEncryptionKey({
        workspace,
      })
      .then((r) => r.key);
  } catch (err) {
    throw new Error(`Failed to get workspace encryption key: ${err}`);
  }
  if (localKey && key !== localKey) {
    // Changing the key on the remote means the existing ciphertexts (encrypted
    // with the old key) become unreadable unless they are re-encrypted. By
    // default we ask the backend to re-encrypt every secret variable with the
    // new key, which preserves their plaintext values. The only reason to skip
    // re-encryption is when the stored ciphertexts are *already* encrypted with
    // the new key (e.g. a workspace/instance migration).
    let reencrypt: boolean;
    // Explicit choice via `--skip-reencrypt-on-key-change` or the env var wins
    // over everything, regardless of interactivity.
    const explicitSkip =
      opts?.skipReencrypt ||
      (process.env.WMILL_NO_REENCRYPT_ON_KEY_CHANGE ?? "").toLowerCase() ===
        "true";
    if (explicitSkip) {
      reencrypt = false;
      log.info(
        "Workspace encryption key changed; leaving remote ciphertexts untouched (skip re-encryption requested)."
      );
    } else if (opts?.noninteractive) {
      // No TTY (or --yes) and no explicit skip: we can't prompt, so default to
      // re-encrypting (matches the interactive default) to preserve secret
      // values. Pass --skip-reencrypt-on-key-change (or set
      // WMILL_NO_REENCRYPT_ON_KEY_CHANGE=true) to opt out.
      reencrypt = true;
      log.info(
        "Workspace encryption key changed; re-encrypting all remote secrets with the new key (non-interactive)."
      );
    } else {
      reencrypt = await Confirm.prompt({
        message:
          "The local workspace encryption key does not match the remote. Do you want to reencrypt all your secrets on the remote with the new key?\nSay 'no' if your local secrets are already encrypted with the new key (e.g. workspace/instance migration)\nOtherwise, say 'yes' and pull the secrets after the reencryption.\n",
        default: true,
      });
    }
    log.debug(`Updating workspace encryption key...`);
    await wmill.setWorkspaceEncryptionKey({
      workspace,
      requestBody: {
        new_key: localKey,
        skip_reencrypt: !reencrypt,
      },
    });
  } else {
    log.debug(`Workspace encryption key is up to date`);
  }
}

export async function readInstanceSettings(opts: InstanceSyncOptions) {
  let localSettings: GlobalSetting[] = [];

  await checkInstanceSettingsPath(opts);

  try {
    localSettings = (await yamlParseFile(
      instanceSettingsPath
    )) as GlobalSetting[];
  } catch {
    log.warn(`No ${instanceSettingsPath} found`);
  }
  return localSettings;
}

const SENSITIVE_FIELD: string[] = ["license_key", "jwt_secret"];

async function processInstanceSettings(
  settings: GlobalSetting[],
  mode: "encode" | "decode"
): Promise<GlobalSetting[]> {
  const encKey = process.env.WMILL_INSTANCE_LOCAL_ENCRYPTION_KEY;
  if (encKey) {
    const res: GlobalSetting[] = [];

    for (const s of settings) {
      if (SENSITIVE_FIELD.includes(s.name) && typeof s.value === "string") {
        res.push(
          (await processField(s, "value", encKey, mode)) as GlobalSetting
        );
      } else if (s.name == "oauths") {
        if (typeof s.value === "object") {
          const oauths = s.value as { [key: string]: any };
          for (const [k, v] of Object.entries(oauths)) {
            oauths[k] = await processField(v, "secret", encKey, mode);
          }
          res.push(s);
        } else {
          log.warn(`Unexpected oauths value type: ${typeof s.value}`);
          res.push(s);
        }
      } else {
        res.push(s);
      }
    }
    return res;
  } else {
    log.warn(
      "No encryption key found, skipping encryption. Recommend setting WMILL_INSTANCE_LOCAL_ENCRYPTION_KEY"
    );
  }
  return settings;
}

async function processField(
  obj: { [key: string]: any },
  field: string,
  encKey: string,
  mode: "encode" | "decode"
): Promise<{ [key: string]: any }> {
  return {
    ...obj,
    [field]:
      mode === "encode"
        ? await encrypt(obj[field], encKey)
        : ((await decrypt(obj[field], encKey)) as any),
  };
}

export async function pullInstanceSettings(
  opts: InstanceSyncOptions,
  preview = false
) {
  const remoteSettings = await wmill.listGlobalSettings();

  await checkInstanceSettingsPath(opts);

  if (preview) {
    const localSettings: GlobalSetting[] = await readInstanceSettings(opts);
    const processedSettings = await processInstanceSettings(
      remoteSettings,
      "encode"
    );
    return compareInstanceObjects(
      processedSettings,
      localSettings,
      "name",
      "setting"
    );
  } else {
    log.info("Pulling settings from instance");

    const processedSettings = await processInstanceSettings(
      remoteSettings,
      "encode"
    );
    await writeFile(
      instanceSettingsPath,
      yamlStringify(processedSettings),
      "utf-8"
    );

    log.info(colors.green(`Settings written to ${instanceSettingsPath}`));
  }
}

export async function pushInstanceSettings(
  opts: InstanceSyncOptions,
  preview: boolean = false
) {
  const remoteSettings = await wmill.listGlobalSettings();
  let localSettings: GlobalSetting[] = await readInstanceSettings(opts);
  localSettings = await processInstanceSettings(localSettings, "decode");

  if (opts.baseUrl) {
    localSettings = localSettings.filter((s) => s.name !== "base_url");
    localSettings.push({
      name: "base_url",
      //@ts-ignore
      value: opts.baseUrl,
    });
  }

  if (preview) {
    return compareInstanceObjects(
      localSettings,
      remoteSettings,
      "name",
      "setting"
    );
  } else {
    for (const setting of localSettings) {
      const remoteMatch = remoteSettings.find((s) => s.name === setting.name);
      if (remoteMatch && deepEqual(remoteMatch, setting)) {
        continue;
      }
      try {
        await wmill.setGlobal({
          key: setting.name,
          requestBody: {
            value: setting.value,
          },
        });
      } catch (err) {
        log.error(`Failed to set setting ${setting.name}: ${err}`);
      }
    }

    for (const remoteSetting of remoteSettings) {
      const localMatch = localSettings.find(
        (s) => s.name === remoteSetting.name
      );
      if (!localMatch) {
        try {
          await wmill.setGlobal({
            key: remoteSetting.name,
            requestBody: {
              value: null,
            },
          });
        } catch (err) {
          log.error(`Failed to delete setting ${remoteSetting.name}: ${err}`);
        }
      }
    }

    log.info(colors.green("Settings pushed to instance"));
  }
}

export async function readLocalConfigs(opts: InstanceSyncOptions) {
  let localConfigs: Config[] = [];

  await checkInstanceConfigPath(opts);

  try {
    localConfigs = (await yamlParseFile(instanceConfigsPath)) as Config[];
  } catch {
    log.warn(`No ${instanceConfigsPath} found`);
  }
  return localConfigs;
}

export async function pullInstanceConfigs(
  opts: InstanceSyncOptions,
  preview = false
) {
  const remoteConfigs = await wmill.listWorkerGroups();

  if (preview) {
    const localConfigs: Config[] = await readLocalConfigs(opts);

    return compareInstanceObjects(
      remoteConfigs,
      localConfigs,
      "name",
      "config"
    );
  } else {
    log.info("Pulling configs from instance");

    await writeFile(
      instanceConfigsPath,
      yamlStringify(remoteConfigs as any),
      "utf-8"
    );

    log.info(colors.green(`Configs written to ${instanceConfigsPath}`));
  }
}

export async function pushInstanceConfigs(
  opts: InstanceSyncOptions,
  preview: boolean = false
) {
  const remoteConfigs = await wmill.listWorkerGroups();
  const localConfigs = await readLocalConfigs(opts);

  if (preview) {
    return compareInstanceObjects(
      localConfigs,
      remoteConfigs,
      "name",
      "config"
    );
  } else {
    log.info("Pushing configs to instance");
    for (const config of localConfigs) {
      const remoteMatch = remoteConfigs.find((c) => c.name === config.name);
      if (remoteMatch && deepEqual(remoteMatch, config)) {
        continue;
      }
      try {
        await wmill.updateConfig({
          name: `worker__${config.name}`,
          requestBody: config.config,
        });
      } catch (err) {
        log.error(`Failed to set config ${config.name}: ${err}`);
      }
    }

    for (const removeConfig of remoteConfigs) {
      const localMatch = localConfigs.find((c) => c.name === removeConfig.name);

      if (!localMatch) {
        try {
          await wmill.deleteConfig({
            name: `worker__${removeConfig.name}`,
          });
        } catch (err) {
          log.error(`Failed to delete config ${removeConfig.name}: ${err}`);
        }
      }
    }

    log.info(colors.green("Configs pushed to instance"));
  }
}

import { minimatch } from "minimatch";
import { getCurrentGitBranch, isGitRepository } from "../utils/git.ts";
import { isFileResource, isFilesetResource } from "../utils/utils.ts";
import {
  SyncOptions,
  findWorkspaceByGitBranch,
  readConfigFile,
  WorkspaceEntryConfig,
} from "./conf.ts";
import { TRIGGER_TYPES } from "../types.ts";

/**
 * Resolve the effective workspace name (wmill.yaml config key) for a given
 * git branch. Falls back to the branch name itself when no matching workspace
 * entry exists (legacy behavior).
 */
export async function resolveWsNameForGitBranch(branchName: string): Promise<string> {
  const config = await readConfigFile({ warnIfMissing: false });
  const match = findWorkspaceByGitBranch(config.workspaces, branchName);
  return match ? match[0] : branchName;
}

export interface SpecificItemsConfig {
  variables?: string[];
  resources?: string[];
  triggers?: string[];
  schedules?: string[];
  folders?: string[];
  settings?: boolean;
}

// Define all workspace-specific file type *kinds* (extension-less). The
// actual on-disk file is `<kind>.yaml` or `<kind>.json` depending on
// opts.json — every helper below treats both as equivalent.
function getWorkspaceSpecificTypeKinds(): string[] {
  return [
    'variable',
    'resource',
    'schedule',
    ...TRIGGER_TYPES.map(t => `${t}_trigger`),
  ];
}

/**
 * Check if a path ends with any trigger type
 */
function isTriggerFile(path: string): boolean {
  return TRIGGER_TYPES.some(type =>
    path.endsWith(`.${type}_trigger.yaml`) || path.endsWith(`.${type}_trigger.json`)
  );
}

/**
 * Check if a path is a schedule file
 */
function isScheduleFile(path: string): boolean {
  return path.endsWith('.schedule.yaml') || path.endsWith('.schedule.json');
}

/**
 * Extract the file type suffix from a path. Preserves the original `.yaml`
 * or `.json` extension so callers like toWorkspaceSpecificPath round-trip
 * correctly.
 */
function getFileTypeSuffix(path: string): string | null {
  for (const kind of getWorkspaceSpecificTypeKinds()) {
    if (path.endsWith(`.${kind}.yaml`)) return `.${kind}.yaml`;
    if (path.endsWith(`.${kind}.json`)) return `.${kind}.json`;
  }

  const resourceFileMatch = path.match(/(\.resource\.file\..+)$/);
  if (resourceFileMatch) {
    return resourceFileMatch[1];
  }

  return null;
}

/**
 * Build regex pattern for all supported item-kind file types
 */
function buildItemTypePattern(): string {
  const basicTypes = ['variable', 'resource', 'schedule'];
  const triggerTypes = TRIGGER_TYPES.map(t => `${t}_trigger`);
  return `((${basicTypes.join('|')})|(${triggerTypes.join('|')}))`;
}

/**
 * Get the specific items configuration for the current workspace.
 * workspaceNameOverride selects by workspace name (O(1)).
 * When not provided, auto-detects from the current git branch.
 * Merges commonSpecificItems with workspace-specific specificItems.
 */
export function getSpecificItemsForCurrentBranch(config: SyncOptions, workspaceNameOverride?: string): SpecificItemsConfig | undefined {
  if (!config.workspaces) {
    return undefined;
  }

  let wsEntry: WorkspaceEntryConfig | undefined;

  if (workspaceNameOverride) {
    wsEntry = config.workspaces[workspaceNameOverride] as WorkspaceEntryConfig | undefined;
  } else if (isGitRepository()) {
    const currentWorkspace = getCurrentGitBranch();
    if (currentWorkspace) {
      const match = findWorkspaceByGitBranch(config.workspaces, currentWorkspace);
      if (match) {
        wsEntry = match[1];
      }
    }
  }

  const commonItems = config.workspaces.commonSpecificItems;
  const wsItems = wsEntry?.specificItems;

  // If neither common nor workspace-specific items exist, return undefined
  if (!commonItems && !wsItems) {
    return undefined;
  }

  // Merge common and workspace-specific items
  const merged: SpecificItemsConfig = {};

  // Add common items
  if (commonItems?.variables) {
    merged.variables = [...commonItems.variables];
  }
  if (commonItems?.resources) {
    merged.resources = [...commonItems.resources];
  }
  if (commonItems?.triggers) {
    merged.triggers = [...commonItems.triggers];
  }
  if (commonItems?.schedules) {
    merged.schedules = [...commonItems.schedules];
  }
  if (commonItems?.folders) {
    merged.folders = [...commonItems.folders];
  }
  if (commonItems?.settings !== undefined) {
    merged.settings = commonItems.settings;
  }

  // Add workspace-specific items (extending common items)
  if (wsItems?.variables) {
    merged.variables = [...(merged.variables || []), ...wsItems.variables];
  }
  if (wsItems?.resources) {
    merged.resources = [...(merged.resources || []), ...wsItems.resources];
  }
  if (wsItems?.triggers) {
    merged.triggers = [...(merged.triggers || []), ...wsItems.triggers];
  }
  if (wsItems?.schedules) {
    merged.schedules = [...(merged.schedules || []), ...wsItems.schedules];
  }
  if (wsItems?.folders) {
    merged.folders = [...(merged.folders || []), ...wsItems.folders];
  }
  // For settings (boolean), workspace-specific overrides common
  if (wsItems?.settings !== undefined) {
    merged.settings = wsItems.settings;
  }

  return merged;
}

/**
 * Check if a path matches any of the patterns in the given list
 */
function matchesPatterns(path: string, patterns: string[]): boolean {
  return patterns.some(pattern => minimatch(path, pattern));
}

/**
 * Normalize a `.json` extension to `.yaml` for pattern matching. Patterns in
 * wmill.yaml (and those appended by mergeWsSpecificFromServer) are expressed
 * with `.yaml` regardless of opts.json, so a `.json` local file would never
 * match without this. The rest of `isSpecificItem`/`isItemTypeConfigured`
 * checks `endsWith('.X.yaml')`, so normalizing once at the entry point keeps
 * both the helpers and the patterns single-extension.
 */
function normalizeJsonToYaml(path: string): string {
  return path.endsWith('.json') ? path.slice(0, -'.json'.length) + '.yaml' : path;
}

/**
 * Check if the item type for a given path is configured in specificItems.
 * This checks if the TYPE is configured, not whether it matches the pattern.
 * Used to determine if workspace-specific files should be used for this type.
 */
export function isItemTypeConfigured(path: string, specificItems: SpecificItemsConfig | undefined): boolean {
  if (!specificItems) {
    return false;
  }

  path = normalizeJsonToYaml(path);

  if (path.endsWith('.variable.yaml')) {
    return specificItems.variables !== undefined;
  }

  if (path.endsWith('.resource.yaml')) {
    return specificItems.resources !== undefined;
  }

  if (isTriggerFile(path)) {
    return specificItems.triggers !== undefined;
  }

  if (isScheduleFile(path)) {
    return specificItems.schedules !== undefined;
  }

  if (path.endsWith('/folder.meta.yaml')) {
    return specificItems.folders !== undefined;
  }

  if (path === 'settings.yaml') {
    return specificItems.settings !== undefined;
  }

  if (isFileResource(path) || isFilesetResource(path)) {
    return specificItems.resources !== undefined;
  }

  return false;
}

/**
 * Check if a file path should be treated as workspace-specific
 */
export function isSpecificItem(path: string, specificItems: SpecificItemsConfig | undefined): boolean {
  if (!specificItems) {
    return false;
  }

  path = normalizeJsonToYaml(path);

  // Determine the item type from the file path
  if (path.endsWith('.variable.yaml')) {
    return specificItems.variables ? matchesPatterns(path, specificItems.variables) : false;
  }

  if (path.endsWith('.resource.yaml')) {
    return specificItems.resources ? matchesPatterns(path, specificItems.resources) : false;
  }

  // Check for any trigger type
  if (isTriggerFile(path)) {
    return specificItems.triggers ? matchesPatterns(path, specificItems.triggers) : false;
  }

  // Check for schedule files
  if (isScheduleFile(path)) {
    return specificItems.schedules ? matchesPatterns(path, specificItems.schedules) : false;
  }

  // Check for folder meta files
  if (path.endsWith('/folder.meta.yaml')) {
    if (specificItems.folders) {
      // Match against the folder path (without /folder.meta.yaml)
      const folderPath = path.slice(0, -'/folder.meta.yaml'.length);
      return matchesPatterns(folderPath, specificItems.folders);
    }
    return false;
  }

  // Check for settings.yaml (root-level file)
  if (path === 'settings.yaml') {
    return specificItems.settings === true;
  }

  // Check for resource files using the standard detection function
  if (isFileResource(path)) {
    // Extract the base path without the file extension to match against patterns
    const basePathMatch = path.match(/^(.+?)\.resource\.file\./);
    if (basePathMatch && specificItems.resources) {
      const basePath = basePathMatch[1] + '.resource.yaml';
      return matchesPatterns(basePath, specificItems.resources);
    }
  }

  if (isFilesetResource(path)) {
    const basePathMatch = path.match(/^(.+?)\.fileset[/\\]/);
    if (basePathMatch && specificItems.resources) {
      const basePath = basePathMatch[1] + '.resource.yaml';
      return matchesPatterns(basePath, specificItems.resources);
    }
  }

  return false;
}

/**
 * Convert a base path to a workspace-specific path
 */
export function toWorkspaceSpecificPath(basePath: string, workspaceName: string): string {
  // Sanitize branch name to be filesystem-safe
  const sanitizedName = workspaceName.replace(/[\/\\:*?"<>|.]/g, '_');

  // Warn about potential collisions if sanitization occurred
  if (sanitizedName !== workspaceName) {
    console.warn(`Warning: Workspace name "${workspaceName}" contains filesystem-unsafe characters (/ \\ : * ? " < > | .) and was sanitized to "${sanitizedName}". This may cause collisions with other similarly named branches.`);
  }

  // Check for folder meta file pattern: folder.meta.{yaml,json} -> folder.workspaceName.meta.{yaml,json}
  const folderMetaMatch = basePath.match(/^(.*)\/folder\.meta\.(yaml|json)$/);
  if (folderMetaMatch) {
    return `${folderMetaMatch[1]}/folder.${sanitizedName}.meta.${folderMetaMatch[2]}`;
  }

  // Check for settings.{yaml,json}: settings.{ext} -> settings.workspaceName.{ext}
  const settingsMatch = basePath.match(/^settings\.(yaml|json)$/);
  if (settingsMatch) {
    return `settings.${sanitizedName}.${settingsMatch[1]}`;
  }

  // Check for resource file pattern (e.g., .resource.file.ini)
  const resourceFileMatch = basePath.match(/^(.+?)(\.resource\.file\..+)$/);

  let extension: string;
  let pathWithoutExtension: string;

  if (resourceFileMatch) {
    // Handle resource files
    extension = resourceFileMatch[2];
    pathWithoutExtension = resourceFileMatch[1];
  } else {
    const suffix = getFileTypeSuffix(basePath);
    if (!suffix) {
      return basePath;
    }
    extension = suffix;
    pathWithoutExtension = basePath.substring(0, basePath.length - extension.length);
  }

  return `${pathWithoutExtension}.${sanitizedName}${extension}`;
}

/**
 * Convert a workspace-specific path back to a base path
 */
export function fromWorkspaceSpecificPath(workspaceSpecificPath: string, workspaceName: string): string {
  // Sanitize branch name the same way as in toWorkspaceSpecificPath
  const sanitizedName = workspaceName.replace(/[\/\\:*?"<>|.]/g, '_');
  const escapedName = sanitizedName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  // Check for folder meta file pattern: /folder.workspaceName.meta.{yaml,json} -> /folder.meta.{ext}
  const folderPattern = new RegExp(`/folder\\.${escapedName}\\.meta\\.(yaml|json)$`);
  const folderMatch = workspaceSpecificPath.match(folderPattern);
  if (folderMatch) {
    return workspaceSpecificPath.replace(folderPattern, `/folder.meta.${folderMatch[1]}`);
  }

  // Check for settings file pattern: settings.workspaceName.{yaml,json} -> settings.{ext}
  const settingsPattern = new RegExp(`^settings\\.${escapedName}\\.(yaml|json)$`);
  const settingsMatch = workspaceSpecificPath.match(settingsPattern);
  if (settingsMatch) {
    return `settings.${settingsMatch[1]}`;
  }

  // Check for resource file pattern
  const resourceFilePattern = new RegExp(`\\.${escapedName}(\\.resource\\.file\\..+)$`);
  const resourceFileMatch = workspaceSpecificPath.match(resourceFilePattern);

  if (resourceFileMatch) {
    const extension = resourceFileMatch[1];
    const pathWithoutBranchAndExtension = workspaceSpecificPath.substring(
      0,
      workspaceSpecificPath.length - `.${sanitizedName}${extension}`.length
    );
    return `${pathWithoutBranchAndExtension}${extension}`;
  }

  const typedPattern = new RegExp(`\\.${escapedName}(\\.${buildItemTypePattern()}\\.(yaml|json))$`);
  const typedMatch = workspaceSpecificPath.match(typedPattern);

  if (!typedMatch) {
    return workspaceSpecificPath; // Return unchanged if not a workspace-specific path
  }

  const extension = typedMatch[1];
  const pathWithoutBranchAndExtension = workspaceSpecificPath.substring(
    0,
    workspaceSpecificPath.length - `.${sanitizedName}${extension}`.length
  );

  return `${pathWithoutBranchAndExtension}${extension}`;
}

/**
 * Get the workspace-specific path if the item should be workspace-specific.
 * workspaceNameOverride is the workspace name used as file suffix.
 * Falls back to current git branch when no override (backward compat: old key = branch name).
 */
export function getWorkspaceSpecificPath(
  basePath: string,
  specificItems: SpecificItemsConfig | undefined,
  workspaceNameOverride?: string
): string | undefined {
  if (!specificItems) {
    return undefined;
  }

  let currentWorkspace: string | null = null;
  if (workspaceNameOverride) {
    currentWorkspace = workspaceNameOverride;
  } else if (isGitRepository()) {
    currentWorkspace = getCurrentGitBranch();
  }

  if (!currentWorkspace) {
    return undefined;
  }

  if (isSpecificItem(basePath, specificItems)) {
    return toWorkspaceSpecificPath(basePath, currentWorkspace);
  }

  return undefined;
}

// Cache for compiled regex patterns to avoid recompilation
const workspacePatternCache = new Map<string, RegExp>();

/**
 * Check if a path is a workspace-specific file for the current branch.
 * workspaceNameOverride is the effective git branch name (for file naming on disk).
 */
export function isCurrentWorkspaceFile(path: string, workspaceNameOverride?: string): boolean {
  // Fileset children are never workspace-specific: only the parent's metadata
  // file carries the suffix, children stay in the shared canonical directory.
  // Their names are arbitrary, so one can look like typed metadata — and since
  // the patterns match a workspace-name segment with `[^.]` (which spans `/`),
  // an unguarded child is dropped from the diff or, worse, remapped onto a
  // sibling's key and deployed over it.
  if (isFilesetResource(path)) {
    return false;
  }
  let currentWorkspace: string | null = null;
  if (workspaceNameOverride) {
    currentWorkspace = workspaceNameOverride;
  } else if (isGitRepository()) {
    currentWorkspace = getCurrentGitBranch();
  }

  if (!currentWorkspace) {
    return false;
  }

  // Sanitize branch name to match what would be used in file naming
  const sanitizedName = currentWorkspace.replace(/[\/\\:*?"<>|.]/g, '_');
  const escapedName = sanitizedName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  // Use cached pattern or create and cache new one
  let pattern = workspacePatternCache.get(currentWorkspace);
  if (!pattern) {
    pattern = new RegExp(
      `\\.${escapedName}\\.${buildItemTypePattern()}\\.(yaml|json)$|` +
      `\\.${escapedName}\\.resource\\.file\\..+$|` +
      `/folder\\.${escapedName}\\.meta\\.(yaml|json)$|` +
      `^settings\\.${escapedName}\\.(yaml|json)$`
    );
    workspacePatternCache.set(currentWorkspace, pattern);
  }

  return pattern.test(path);
}

/**
 * Check if a path is a workspace-specific file for ANY branch (not necessarily current)
 * Used to identify and skip files from other branches during sync operations
 */
export function isWorkspaceSpecificFile(path: string): boolean {
  // Same fileset exemption as isCurrentWorkspaceFile.
  if (isFilesetResource(path)) {
    return false;
  }
  const typePattern = buildItemTypePattern();
  return new RegExp(
    `\\.[^.]+\\.${typePattern}\\.(yaml|json)$|` +
    `\\.[^.]+\\.resource\\.file\\..+$|` +
    `/folder\\.[^.]+\\.meta\\.(yaml|json)$|` +
    `^settings\\.[^.]+\\.(yaml|json)$`
  ).test(path);
}

import { mkdir } from "node:fs/promises";
import { getConfigDirPath } from "../../windmill-utils-internal/src/config/config.ts";

function hash_string(str: string): number {
  let hash = 0,
    i,
    chr;
  if (str.length === 0) return hash;
  for (i = 0; i < str.length; i++) {
    chr = str.charCodeAt(i);
    hash = (hash << 5) - hash + chr;
    hash |= 0; // Convert to 32bit integer
  }
  return hash;
}

export async function getStore(baseUrl: string, configDirOverride?: string): Promise<string> {
  const baseHash = Math.abs(hash_string(baseUrl)).toString(16);
  const baseStore = (await getConfigDirPath(configDirOverride)) + baseHash + "/";
  await mkdir(baseStore, { recursive: true });
  return baseStore;
}

/**
 * Versioning + freshness check for the managed AGENTS.wmill.md bundle.
 *
 * We embed a short hash of "what this CLI would write" into AGENTS.wmill.md as
 * an HTML comment. On every `wmill` command (with a few exceptions), we read
 * the stored hash and compare against the current CLI's hash. Mismatch =>
 * one-line warning telling the user to `wmill refresh prompts`.
 *
 * The hash covers all inputs that affect the rendered bundle: the
 * AGENTS.wmill.md template, every skill body, schemas and schema mappings, and
 * the nonDottedPaths setting. It is *not* tied to the CLI's package version,
 * so non-prompt CLI releases don't produce false positives.
 */
import { createHash } from "node:crypto";
import { stat } from "node:fs/promises";
import { colors } from "@cliffy/ansi/colors";
import { readTextFile } from "../utils/utils.ts";
import {
  AGENTS_WMILL_FILENAME,
  LEGACY_AGENTS_CLI_FILENAME,
  generateAgentsCliMdContent,
} from "./core.ts";
import {
  SCHEMAS,
  SCHEMA_MAPPINGS,
  SKILLS,
  SKILL_CONTENT,
} from "./skills.gen.ts";

// Re-export from the gate module so existing callers (and tests) keep working.
// `shouldRunFreshnessCheck` lives there to avoid pulling skills.gen.ts (~360 KB)
// into main.ts's static import graph; main.ts now imports the gate directly
// and only `await import`s this file lazily.
import { shouldRunFreshnessCheck } from "./freshness_gate.ts";
export { shouldRunFreshnessCheck };

export const PROMPTS_HASH_MARKER_PREFIX = "<!-- wmill-prompts-hash: ";
const PROMPTS_HASH_REGEX = /<!-- wmill-prompts-hash: ([0-9a-f]{12}) -->/;

export function buildPromptsHashMarker(hash: string): string {
  return `${PROMPTS_HASH_MARKER_PREFIX}${hash} -->`;
}

export function extractPromptsHash(content: string): string | null {
  const match = content.match(PROMPTS_HASH_REGEX);
  return match ? match[1] : null;
}

/**
 * Insert the hash marker into rendered AGENTS.wmill.md content. The marker
 * goes on the line right after the title so it's easy to find and doesn't
 * break the rendered Markdown structure.
 */
export function injectPromptsHashMarker(
  content: string,
  hash: string
): string {
  const lines = content.split("\n");
  const marker = buildPromptsHashMarker(hash);
  // Insert right after the first line if it's an H1 title; otherwise
  // prepend so the marker is always near the top.
  const insertAt = lines[0].startsWith("# ") ? 1 : 0;
  lines.splice(insertAt, 0, marker);
  return lines.join("\n");
}

/**
 * Compute the hash for the rendered bundle. The hash is deterministic for a
 * given (CLI bundle, nonDottedPaths) pair.
 */
export function currentPromptsHash(nonDottedPaths: boolean): string {
  const hasher = createHash("sha256");

  // Template structure (without the skills reference — that's hashed
  // separately from the SKILLS metadata).
  hasher.update("template:");
  hasher.update(generateAgentsCliMdContent("__PLACEHOLDER__"));

  // Skill metadata (names + descriptions) — fed into the skills reference
  // line in AGENTS.wmill.md and the wrapper frontmatter.
  hasher.update("\nskills:");
  hasher.update(JSON.stringify(SKILLS));

  // Skill bodies — what actually lands in .agents/skills/<name>/SKILL.md.
  // Sort entries for stable ordering.
  hasher.update("\nbodies:");
  for (const [name, content] of Object.entries(SKILL_CONTENT).sort()) {
    hasher.update("\n");
    hasher.update(name);
    hasher.update("\n");
    hasher.update(content);
  }

  // Schemas + their mappings — embedded inside specific skills.
  hasher.update("\nschemas:");
  hasher.update(JSON.stringify(SCHEMAS));
  hasher.update("\nmappings:");
  hasher.update(JSON.stringify(SCHEMA_MAPPINGS));

  // Path-style setting — controls __flow vs .flow rendering in skill bodies.
  hasher.update("\nnonDotted:");
  hasher.update(String(nonDottedPaths));

  return hasher.digest("hex").slice(0, 12);
}

/**
 * Read the managed guidance file in the current working directory, compare its
 * embedded hash to the current CLI's hash, and print a one-line warning if they
 * differ. Silent on every other code path (no managed file, no marker,
 * matching hash, IO error, …) so it never gets in the user's way.
 *
 * Back-compat: prefers `AGENTS.wmill.md` but falls back to the legacy
 * `AGENTS.cli.md` and runs the exact same staleness check on it. We do NOT
 * warn merely because the old filename is in use — an up-to-date `AGENTS.cli.md`
 * stays quiet; only a stale hash (which `wmill refresh prompts` fixes, and
 * which also migrates the filename) trips the warning.
 */
export async function warnIfPromptsStale(opts?: {
  cwd?: string;
  nonDottedPaths?: boolean;
  argv?: readonly string[];
}): Promise<void> {
  if (opts?.argv && !shouldRunFreshnessCheck(opts.argv)) return;

  const cwd = opts?.cwd ?? process.cwd();

  // Prefer the current filename; fall back to the legacy one for back-compat.
  let fileName = AGENTS_WMILL_FILENAME;
  let path = `${cwd}/${fileName}`;
  if (!(await stat(path).catch(() => null))) {
    fileName = LEGACY_AGENTS_CLI_FILENAME;
    path = `${cwd}/${fileName}`;
    if (!(await stat(path).catch(() => null))) {
      // Neither file present — this project just isn't wmill-managed.
      return;
    }
  }

  let content: string;
  try {
    content = await readTextFile(path);
  } catch {
    return;
  }

  const stored = extractPromptsHash(content);
  if (!stored) {
    // Managed file without a marker. Warn so the user re-runs refresh and
    // picks up the new format (and the new filename).
    emitWarning(
      `Your ${fileName} predates prompt versioning. Run \`wmill refresh prompts\` to refresh and add a version marker.`
    );
    return;
  }

  let nonDottedPaths = opts?.nonDottedPaths;
  if (nonDottedPaths === undefined) {
    try {
      const { readConfigFile } = await import("../core/conf.ts");
      const config = await readConfigFile();
      // Match `core/conf.ts`'s missing-key default (`?? false`); otherwise
      // legacy wmill.yaml files without the key trip a permanent freshness
      // warning even though the prompts are objectively up to date.
      nonDottedPaths = config.nonDottedPaths ?? false;
    } catch {
      nonDottedPaths = false;
    }
  }

  const current = currentPromptsHash(nonDottedPaths);
  if (stored !== current) {
    emitWarning(
      `Your ${fileName} is out of date. Run \`wmill refresh prompts\` to refresh.`
    );
  }
}

/**
 * Send the freshness warning to **stderr** so it never contaminates a
 * downstream pipe (e.g. `wmill job result <id> | jq`). The rest of the CLI
 * uses `log.warn` which writes to stdout — that's wrong for an always-on
 * notification like this one, but we don't want to fix `log.warn` globally
 * in this PR.
 */
function emitWarning(message: string): void {
  process.stderr.write(`${colors.yellow(message)}\n`);
}

/**
 * Argv-only gate for the prompts freshness check. Kept in its own module so
 * `main.ts` can import it without pulling in the heavy `skills.gen.ts`
 * bundle (~360 KB) on every `wmill` invocation. The full check (which does
 * touch the bundle) lives in `./freshness.ts` and is loaded lazily after
 * this gate returns `true`.
 */

/**
 * Subcommands where a freshness warning is noise (the user is either fixing
 * it, asking for help, or doing something orthogonal).
 */
const SKIP_FRESHNESS_FOR_SUBCOMMANDS = new Set([
  "init",
  "refresh",
  "completions",
  "upgrade",
]);

/**
 * Cliffy global options that consume the *next* argv element as their value.
 * Must be kept in sync with the option declarations on the top-level
 * `command` in `cli/src/main.ts`.
 */
const VALUE_GLOBAL_OPTS = new Set([
  "--workspace",
  "--token",
  "--base-url",
  "--config-dir",
]);

/**
 * Returns `true` if the freshness check should run for this invocation.
 *
 * Bypasses:
 * - bare `wmill` (no subcommand → shows help)
 * - `--help`, `-h`, `--version`, `-V` anywhere in the args
 * - subcommands in {init, refresh, completions, upgrade}
 *
 * Handles cliffy global options that take a value (`--workspace foo`,
 * `--token tok`, `--base-url https://…`, `--config-dir /etc/wmill`) by
 * skipping their value when scanning for the first positional argument.
 * Without that, `wmill --workspace prod refresh prompts` would misread
 * `"prod"` as the subcommand and fire the warning during the very command
 * meant to fix it.
 */
export function shouldRunFreshnessCheck(argv: readonly string[]): boolean {
  const args = argv.slice(2); // strip node + script
  if (args.length === 0) return false;
  if (args.includes("--help") || args.includes("-h")) return false;
  if (args.includes("--version") || args.includes("-V")) return false;

  let i = 0;
  while (i < args.length) {
    const arg = args[i];
    if (VALUE_GLOBAL_OPTS.has(arg)) {
      i += 2; // skip flag + its value
      continue;
    }
    if (arg.startsWith("-")) {
      i += 1; // flag with no value
      continue;
    }
    return !SKIP_FRESHNESS_FOR_SUBCOMMANDS.has(arg);
  }
  return false;
}

import { cp, mkdir, readdir, rm, stat, writeFile } from "node:fs/promises";
import { readTextFile } from "../utils/utils.ts";
import { join } from "node:path";
import {
  AGENTS_WMILL_FILENAME,
  AGENTS_WMILL_INCLUDE_LINE,
  LEGACY_AGENTS_CLI_FILENAME,
  LEGACY_AGENTS_CLI_INCLUDE_LINE,
  generateAgentsCliMdContent,
  generateAgentsMdSkeleton,
} from "./core.ts";
import {
  currentPromptsHash,
  injectPromptsHashMarker,
} from "./freshness.ts";
import {
  SCHEMAS,
  SCHEMA_MAPPINGS,
  SKILLS,
  SKILL_CONTENT,
  type SkillMetadata,
} from "./skills.gen.ts";

type ResolvedSkillMetadata = SkillMetadata & {
  directoryName: string;
};

/**
 * How to reconcile an existing user-owned guidance file (AGENTS.md or
 * CLAUDE.md) that doesn't reference the managed file below it
 * (`@AGENTS.wmill.md` for AGENTS.md, `@AGENTS.md` for CLAUDE.md).
 *
 * - `append`: leave the file as-is and append the include line.
 * - `overwrite`: replace the file with the managed skeleton.
 * - `skip`: leave the file alone. The managed downstream file is still
 *   written/refreshed, but no link to it — the user is expected to wire it
 *   manually later.
 */
export type AgentsMdMigration = "append" | "overwrite" | "skip";

export type ReconcileOutcome =
  | AgentsMdMigration
  | "already-linked"
  | "not-applicable";

export interface WriteAiGuidanceOptions {
  targetDir: string;
  nonDottedPaths?: boolean;
  /** Skill source override (testing / source-of-truth bundling). */
  skillsSourcePath?: string;
  /** AGENTS.wmill.md source override (testing). */
  agentsSourcePath?: string;
  /** CLAUDE.md source override (testing). */
  claudeSourcePath?: string;
  /**
   * Optional resolver invoked when an existing AGENTS.md lacks an
   * `@AGENTS.wmill.md` reference. Callers are expected to prompt the user; if
   * omitted, the writer defaults to `append` (non-destructive).
   */
  resolveAgentsMdMigration?: () => Promise<AgentsMdMigration>;
}

export interface WriteAiGuidanceResult {
  agentsCliWritten: boolean;
  agentsCreated: boolean;
  agentsMigration: ReconcileOutcome;
  claudeCreated: boolean;
  claudeMigration: ReconcileOutcome;
  skillCount: number;
  /**
   * True when a legacy `AGENTS.cli.md` was found and removed (its content is
   * superseded by `AGENTS.wmill.md`, and any `@AGENTS.cli.md` includes were
   * rewritten to `@AGENTS.wmill.md`).
   */
  legacyManagedRemoved: boolean;
}

export const WMILL_INIT_AI_SKILLS_SOURCE_ENV = "WMILL_INIT_AI_SKILLS_SOURCE";
export const WMILL_INIT_AI_AGENTS_SOURCE_ENV = "WMILL_INIT_AI_AGENTS_SOURCE";
export const WMILL_INIT_AI_CLAUDE_SOURCE_ENV = "WMILL_INIT_AI_CLAUDE_SOURCE";

const CLAUDE_MD_DEFAULT = "Instructions are in @AGENTS.md\n";
const CLAUDE_MD_INCLUDE_LINE = "@AGENTS.md";

/**
 * Both `.agents/skills/` (read by Codex, Pi) and `.claude/skills/` (read by
 * Claude Code) receive the full skill content. We can't use `@<path>` to
 * deduplicate because Claude's skill loader reads SKILL.md as-is — it does
 * not expand `@` references inside skill bodies (those work only in
 * AGENTS.md / CLAUDE.md).
 */
const SKILL_TARGET_ROOTS = [".agents", ".claude"] as const;

export async function writeAiGuidanceFiles(
  options: WriteAiGuidanceOptions
): Promise<WriteAiGuidanceResult> {
  // Match `core/conf.ts`'s missing-key default — if a legacy wmill.yaml
  // omits `nonDottedPaths`, sync treats it as `false`, so we must too or
  // the freshness hash will be permanently out of sync with the rest of
  // the CLI's view of the project.
  const nonDottedPaths = options.nonDottedPaths ?? false;
  const skillMetadata = options.skillsSourcePath
    ? await readSkillMetadataFromDirectory(options.skillsSourcePath)
    : getGeneratedSkillMetadata();

  // AGENTS.wmill.md — always (re)written, this is the managed file.
  // We embed a content-hash marker so other `wmill` commands can detect a
  // stale bundle and prompt the user to `wmill refresh prompts`.
  const rawAgentsCliContent =
    options.agentsSourcePath != null
      ? await readTextFile(options.agentsSourcePath)
      : generateAgentsCliMdContent(buildSkillsReference(skillMetadata));
  const agentsCliContent = injectPromptsHashMarker(
    rawAgentsCliContent,
    currentPromptsHash(nonDottedPaths)
  );
  const agentsCliPath = join(options.targetDir, AGENTS_WMILL_FILENAME);
  await writeFile(agentsCliPath, agentsCliContent, "utf8");
  const agentsCliWritten = true;

  // Migrate the legacy `AGENTS.cli.md`: rewrite `@AGENTS.cli.md` includes in
  // user-owned files to `@AGENTS.wmill.md`, then remove the stale managed
  // file. Done before reconciliation so the rewritten include reads as
  // "already-linked" rather than triggering a duplicate append.
  const legacyManagedRemoved = await migrateLegacyManagedFile(options.targetDir);

  // Cache the user's first migration answer and reuse it for every file
  // that needs reconciling in this run — there's never a good reason to ask
  // the same question twice in a row.
  const resolveMigration = cacheOnce(options.resolveAgentsMdMigration);

  // AGENTS.md — user-owned. Three paths:
  //   1. doesn't exist → create skeleton (which already includes @AGENTS.wmill.md).
  //   2. exists and already references @AGENTS.wmill.md → leave alone.
  //   3. exists but doesn't reference @AGENTS.wmill.md → ask caller via
  //      resolveMigration (defaults to append).
  const agentsMdResult = await reconcileIncludingFile({
    path: join(options.targetDir, "AGENTS.md"),
    includeLine: AGENTS_WMILL_INCLUDE_LINE,
    skeleton: generateAgentsMdSkeleton(),
    resolveMigration,
  });

  // CLAUDE.md — user-owned wrapper that points at @AGENTS.md. Same three-way
  // reconciliation: create if missing, leave alone if it already references
  // AGENTS.md, otherwise ask via resolveMigration.
  const claudeSkeleton =
    options.claudeSourcePath != null
      ? await readTextFile(options.claudeSourcePath)
      : CLAUDE_MD_DEFAULT;
  const claudeMdResult = await reconcileIncludingFile({
    path: join(options.targetDir, "CLAUDE.md"),
    includeLine: CLAUDE_MD_INCLUDE_LINE,
    skeleton: claudeSkeleton,
    resolveMigration,
  });

  if (options.skillsSourcePath) {
    await copySkillsFromSource(options.targetDir, options.skillsSourcePath);
  } else {
    await writeGeneratedSkills(options.targetDir, nonDottedPaths);
  }

  return {
    agentsCliWritten,
    agentsCreated: agentsMdResult.created,
    agentsMigration: agentsMdResult.migration,
    claudeCreated: claudeMdResult.created,
    claudeMigration: claudeMdResult.migration,
    skillCount: skillMetadata.length,
    legacyManagedRemoved,
  };
}

/**
 * One-time migration from the old managed filename (`AGENTS.cli.md`) to
 * `AGENTS.wmill.md`:
 *
 *   1. Rewrite the `@AGENTS.cli.md` include token → `@AGENTS.wmill.md` in
 *      AGENTS.md and CLAUDE.md (only when it appears as a standalone
 *      whitespace-delimited token, so lookalikes like `@AGENTS.cli.md.backup`
 *      are left intact).
 *   2. Delete the stale `AGENTS.cli.md` — its content is fully superseded by
 *      the freshly written `AGENTS.wmill.md`.
 *
 * Returns true when a legacy `AGENTS.cli.md` was present and removed.
 */
async function migrateLegacyManagedFile(targetDir: string): Promise<boolean> {
  for (const fileName of ["AGENTS.md", "CLAUDE.md"]) {
    const filePath = join(targetDir, fileName);
    const existing = await readTextFile(filePath).catch(() => null);
    if (existing == null) continue;
    const rewritten = rewriteIncludeToken(
      existing,
      LEGACY_AGENTS_CLI_INCLUDE_LINE,
      AGENTS_WMILL_INCLUDE_LINE
    );
    if (rewritten !== existing) {
      await writeFile(filePath, rewritten, "utf8");
    }
  }

  const legacyPath = join(targetDir, LEGACY_AGENTS_CLI_FILENAME);
  const legacyExists = (await stat(legacyPath).catch(() => null)) != null;
  if (legacyExists) {
    await rm(legacyPath, { force: true });
  }
  return legacyExists;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Replace `from` with `to` only where `from` appears as a standalone
 * whitespace-delimited token. Line endings and surrounding content are
 * preserved (`\s` in the lookahead matches `\r`), so a CRLF file stays CRLF.
 */
function rewriteIncludeToken(content: string, from: string, to: string): string {
  const re = new RegExp(`(?<=^|\\s)${escapeRegExp(from)}(?=\\s|$)`, "gm");
  return content.replace(re, to);
}

function cacheOnce(
  resolver: (() => Promise<AgentsMdMigration>) | undefined
): (() => Promise<AgentsMdMigration>) | undefined {
  if (!resolver) return undefined;
  let cached: AgentsMdMigration | null = null;
  return async () => {
    if (cached !== null) return cached;
    cached = await resolver();
    return cached;
  };
}

async function reconcileIncludingFile(options: {
  path: string;
  includeLine: string;
  skeleton: string;
  resolveMigration?: () => Promise<AgentsMdMigration>;
}): Promise<{ created: boolean; migration: ReconcileOutcome }> {
  const exists = (await stat(options.path).catch(() => null)) != null;
  if (!exists) {
    await writeFile(options.path, options.skeleton, "utf8");
    return { created: true, migration: "not-applicable" };
  }

  const existing = await readTextFile(options.path);
  if (referencesIncludeLine(existing, options.includeLine)) {
    return { created: false, migration: "already-linked" };
  }

  const choice = options.resolveMigration
    ? await options.resolveMigration()
    : "append";

  if (choice === "skip") {
    return { created: false, migration: "skip" };
  }

  if (choice === "overwrite") {
    await writeFile(options.path, options.skeleton, "utf8");
    return { created: false, migration: "overwrite" };
  }

  // append — add the include at the end, leaving existing content untouched.
  const appended = existing.endsWith("\n")
    ? `${existing}\n${options.includeLine}\n`
    : `${existing}\n\n${options.includeLine}\n`;
  await writeFile(options.path, appended, "utf8");
  return { created: false, migration: "append" };
}

function referencesIncludeLine(content: string, includeLine: string): boolean {
  // Match when the include appears as a whitespace-separated token on any
  // line that isn't an HTML comment. We can't require the include to be on a
  // line by itself: our own CLAUDE.md default is `Instructions are in
  // @AGENTS.md` (one sentence), and a strict equality check made `wmill
  // refresh prompts` re-prompt every run on files wmill itself wrote.
  // Skipping comment-bearing lines keeps `<!-- @AGENTS.wmill.md -->` from
  // false-positiving.
  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (trimmed.startsWith("<!--") || trimmed.endsWith("-->")) {
      continue;
    }
    if (trimmed.split(/\s+/).includes(includeLine)) {
      return true;
    }
  }
  return false;
}

function buildSkillsReference(
  skills: Pick<ResolvedSkillMetadata, "directoryName" | "description">[]
): string {
  return skills
    .map(
      (skill) =>
        `- \`.agents/skills/${skill.directoryName}/SKILL.md\` - ${skill.description}`
    )
    .join("\n");
}

async function copySkillsFromSource(
  targetDir: string,
  skillsSourcePath: string
): Promise<ResolvedSkillMetadata[]> {
  const skillsDirs = await ensureSkillsDirectories(targetDir);
  await Promise.all(
    skillsDirs.map((skillsDir) =>
      copyDirectoryContents(skillsSourcePath, skillsDir)
    )
  );
  return await readSkillMetadataFromDirectory(skillsDirs[0]);
}

async function writeGeneratedSkills(
  targetDir: string,
  nonDottedPaths: boolean
): Promise<ResolvedSkillMetadata[]> {
  const skillsDirs = await ensureSkillsDirectories(targetDir);

  await Promise.all(
    skillsDirs.flatMap((skillsDir) =>
      SKILLS.map(async (skill) => {
        const skillDir = join(skillsDir, skill.name);
        await mkdir(skillDir, { recursive: true });
        await writeFile(
          join(skillDir, "SKILL.md"),
          renderGeneratedSkillContent(skill.name, nonDottedPaths),
          "utf8"
        );
      })
    )
  );

  return SKILLS.map((skill) => ({
    ...skill,
    directoryName: skill.name,
  }));
}

function getGeneratedSkillMetadata(): ResolvedSkillMetadata[] {
  return SKILLS.map((skill) => ({
    ...skill,
    directoryName: skill.name,
  }));
}

async function ensureSkillsDirectories(targetDir: string): Promise<string[]> {
  const skillsDirs = SKILL_TARGET_ROOTS.map((root) =>
    join(targetDir, root, "skills")
  );
  await Promise.all(
    skillsDirs.map((skillsDir) => mkdir(skillsDir, { recursive: true }))
  );
  return skillsDirs;
}

async function copyDirectoryContents(
  sourceDir: string,
  targetDir: string
): Promise<void> {
  const entries = await readdir(sourceDir, { withFileTypes: true });

  await Promise.all(
    entries.map(async (entry) => {
      await cp(join(sourceDir, entry.name), join(targetDir, entry.name), {
        recursive: true,
        force: true,
      });
    })
  );
}

function renderGeneratedSkillContent(
  skillName: string,
  nonDottedPaths: boolean
): string {
  let skillContent = SKILL_CONTENT[skillName];
  if (!skillContent) {
    throw new Error(`Missing generated skill content for ${skillName}`);
  }

  if (nonDottedPaths) {
    skillContent = skillContent
      .replaceAll("{{FLOW_SUFFIX}}", "__flow")
      .replaceAll("{{APP_SUFFIX}}", "__app")
      .replaceAll("{{RAW_APP_SUFFIX}}", "__raw_app")
      .replaceAll(
        "{{INLINE_SCRIPT_NAMING}}",
        "Inline script files should NOT include `.inline_script.` in their names (e.g. use `a.ts`, not `a.inline_script.ts`)."
      );
  } else {
    skillContent = skillContent
      .replaceAll("{{FLOW_SUFFIX}}", ".flow")
      .replaceAll("{{APP_SUFFIX}}", ".app")
      .replaceAll("{{RAW_APP_SUFFIX}}", ".raw_app")
      .replaceAll(
        "{{INLINE_SCRIPT_NAMING}}",
        "Inline script files use the `.inline_script.` naming convention (e.g. `a.inline_script.ts`)."
      );
  }

  const schemaMappings = SCHEMA_MAPPINGS[skillName];
  if (!schemaMappings || schemaMappings.length === 0) {
    return skillContent;
  }

  const schemaDocs = schemaMappings
    .map((mapping) => {
      const schemaYaml = SCHEMAS[mapping.schemaKey];
      if (!schemaYaml) {
        return null;
      }
      return formatSchemaForMarkdown(
        schemaYaml,
        mapping.name,
        mapping.filePattern
      );
    })
    .filter((entry): entry is string => entry !== null);

  if (schemaDocs.length === 0) {
    return skillContent;
  }

  return `${skillContent}\n\n${schemaDocs.join("\n\n")}`;
}

async function readSkillMetadataFromDirectory(
  skillsDir: string
): Promise<ResolvedSkillMetadata[]> {
  const entries = await readdir(skillsDir, { withFileTypes: true });
  const skills: ResolvedSkillMetadata[] = [];

  for (const entry of entries.sort((left, right) =>
    left.name.localeCompare(right.name)
  )) {
    if (!entry.isDirectory()) {
      continue;
    }

    const skillPath = join(skillsDir, entry.name, "SKILL.md");
    if (!(await stat(skillPath).catch(() => null))) {
      continue;
    }

    const content = await readTextFile(skillPath);
    skills.push(parseSkillMetadata(content, entry.name));
  }

  return skills;
}

function parseSkillMetadata(
  content: string,
  fallbackName: string
): ResolvedSkillMetadata {
  const frontMatterMatch = content.match(/^---\s*\n([\s\S]*?)\n---/);
  if (!frontMatterMatch) {
    return {
      name: fallbackName,
      description: `Skill loaded from ${fallbackName}`,
      directoryName: fallbackName,
    };
  }

  let name = fallbackName;
  let description = `Skill loaded from ${fallbackName}`;

  for (const line of frontMatterMatch[1].split("\n")) {
    const separatorIndex = line.indexOf(":");
    if (separatorIndex === -1) {
      continue;
    }

    const key = line.slice(0, separatorIndex).trim();
    const value = line.slice(separatorIndex + 1).trim();

    if (key === "name" && value) {
      name = value;
    } else if (key === "description" && value) {
      description = value;
    }
  }

  return { name, description, directoryName: fallbackName };
}

function formatSchemaForMarkdown(
  schemaYaml: string,
  schemaName: string,
  filePattern: string
): string {
  return `## ${schemaName} (\`${filePattern}\`)

Must be a YAML file that adheres to the following schema:

\`\`\`yaml
${schemaYaml.trim()}
\`\`\``;
}

