export function isSuperset(
  subset: Record<string, any>,
  superset: Record<string, any>
): boolean {
  return Object.keys(subset).every((key) => {
    const eq = deepEqual(subset[key], superset[key]);
    if (!eq && showDiffs) {
      const sub = subset[key];
      const supers = superset[key];
      if (!supers) {
        log.info(`Key ${key} not found in remote`);
      } else {
        log.info(`Found diff for ${key}:`);
        showDiff(
          yamlStringify(sub, yamlOptions),
          yamlStringify(supers, yamlOptions)
        );
      }
    }
    return eq;
  });
}

export function showDiff(local: string, remote: string) {
  let finalString = "";
  if (local?.length > 20000 || remote?.length > 20000) {
    log.info("Diff too large to display");
    return;
  }

  for (const part of Diff.diffLines(local ?? "", remote ?? "")) {
    if (part.removed) {
      // print red if removed without newline
      finalString += `\x1b[31m${part.value}\x1b[0m`;
    } else if (part.added) {
      // print green if added
      finalString += `\x1b[32m${part.value}\x1b[0m`;
    } else {
      let lines = part.value.split("\n");

      if (lines.length > 4) {
        lines = lines.slice(0, 2);
        lines.push("...");
        lines = lines.concat(part.value.split("\n").slice(-2));
      }
      // print white if unchanged
      finalString += `\x1b[37m${lines.join("\n")}\x1b[0m`;
    }
  }
  log.info(finalString);
}

export function showConflict(path: string, local: string, remote: string) {
  log.info(colors.yellow(`- ${path}`));
  let isEncryptionKey = false;
  try {
    isEncryptionKey = getTypeStrFromPath(path) === "encryption_key";
  } catch {
    // ignore
  }
  if (isEncryptionKey) {
    showDiff(redactEncryptionKey(local), redactEncryptionKey(remote));
  } else {
    showDiff(local, remote);
  }
  log.info("\x1b[31mlocal\x1b[31m - \x1b[32mremote\x1b[32m");
  log.info("\n");
}

// Reveal only the first 5 chars of the key so a rotation is still visible in
// the diff (different prefixes), without leaking the whole secret to stdout.
// The remaining chars are replaced with `*`, preserving length so the diff
// keeps showing whether the key length changed.
export function redactEncryptionKey(content: string): string {
  if (!content) return content;
  // The encryption_key payload is JSON-encoded (a quoted string). Parse it so
  // we redact the key value itself, then re-serialize to JSON to preserve the
  // file's shape; fall back to raw redaction if parsing fails.
  try {
    const parsed = JSON.parse(content);
    if (typeof parsed === "string") {
      return JSON.stringify(redactString(parsed));
    }
  } catch {
    // not JSON — treat content as the raw key
  }
  return redactString(content);
}

function redactString(s: string): string {
  if (s.length <= 5) return s;
  return s.slice(0, 5) + "*".repeat(s.length - 5);
}

export interface PushObjOptions {
  /** Optional commit/update message */
  message?: string;
  /** The original local file path (used for branch-specific resource file resolution) */
  originalLocalPath?: string;
  /** Identity to attribute the push to, for the types that carry one */
  permissionedAsContext?: PermissionedAsContext;
  /** Whether the item is workspace-specific */
  wsSpecific?: boolean;
  /** encryption_key push: non-interactive flag and explicit re-encryption choice */
  keyPushOpts?: PushWorkspaceKeyOptions;
  /** TypeScript runtime a bare `.ts` denotes, for raw-app runnables */
  defaultTs?: "bun" | "deno";
}

/**
 * Pushes an object to the workspace server based on its type
 * @param workspace - The workspace ID to push to
 * @param p - The server path (base path for branch-specific items)
 * @param befObj - The previous object state (for updates)
 * @param newObj - The new object state to push
 * @param plainSecrets - Whether to store secrets in plain text
 * @param alreadySynced - Array to track already synced items
 * @param opts - Per-type extras; see PushObjOptions
 */
export async function pushObj(
  workspace: string,
  p: string,
  befObj: any,
  newObj: any,
  plainSecrets: boolean,
  alreadySynced: string[],
  opts: PushObjOptions = {},
) {
  const {
    message,
    originalLocalPath,
    permissionedAsContext,
    wsSpecific,
    keyPushOpts,
    defaultTs,
  } = opts;
  const typeEnding = getTypeStrFromPath(p);

  if (typeEnding === "app") {
    const appName = extractResourceName(p, "app");
    if (!appName) {
      throw new Error(`Could not extract app name from path: ${p}`);
    }
    await pushApp(workspace, appName, buildFolderPath(appName, "app"), message, permissionedAsContext);
  } else if (typeEnding === "raw_app") {
    const rawAppName = extractResourceName(p, "raw_app");
    if (!rawAppName) {
      throw new Error(`Could not extract raw app name from path: ${p}`);
    }
    await pushRawApp(workspace, rawAppName, buildFolderPath(rawAppName, "raw_app"), message, defaultTs);
  } else if (typeEnding === "folder") {
    await pushFolder(workspace, p, befObj, newObj);
  } else if (typeEnding === "variable") {
    await pushVariable(workspace, p, befObj, newObj, plainSecrets, wsSpecific);
  } else if (typeEnding === "flow") {
    const flowName = extractResourceName(p, "flow");
    if (!flowName) {
      throw new Error(`Could not extract flow name from path: ${p}`);
    }
    await pushFlow(workspace, flowName, buildFolderPath(flowName, "flow"), message, permissionedAsContext);
  } else if (typeEnding === "resource") {
    if (!alreadySynced.includes(p)) {
      alreadySynced.push(p);
      await pushResource(workspace, p, befObj, newObj, originalLocalPath || p, wsSpecific, true);
    }
  } else if (typeEnding === "resource-type") {
    await pushResourceType(workspace, p, befObj, newObj);
  } else if (typeEnding === "schedule") {
    await pushSchedule(workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "http_trigger") {
    await pushTrigger("http", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "websocket_trigger") {
    await pushTrigger("websocket", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "kafka_trigger") {
    await pushTrigger("kafka", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "nats_trigger") {
    await pushTrigger("nats", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "postgres_trigger") {
    await pushTrigger("postgres", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "mqtt_trigger") {
    await pushTrigger("mqtt", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "amqp_trigger") {
    await pushTrigger("amqp", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "sqs_trigger") {
    await pushTrigger("sqs", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "gcp_trigger") {
    await pushTrigger("gcp", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "azure_trigger") {
    await pushTrigger("azure", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "email_trigger") {
    await pushTrigger("email", workspace, p, befObj, newObj, permissionedAsContext);
  } else if (typeEnding === "native_trigger") {
    await pushNativeTrigger(workspace, p, befObj, newObj);
  } else if (typeEnding === "user") {
    await pushWorkspaceUser(workspace, p, befObj, newObj);
  } else if (typeEnding === "group") {
    await pushGroup(workspace, p, befObj, newObj);
  } else if (typeEnding === "workspace_dependencies") {
    await pushWorkspaceDependencies(workspace, p, befObj, newObj);
  } else if (typeEnding === "settings") {
    await pushWorkspaceSettings(workspace, p, befObj, newObj);
  } else if (typeEnding === "encryption_key") {
    await pushWorkspaceKey(workspace, p, befObj, newObj, keyPushOpts);
  } else {
    throw new Error(
      `The item ${p} has an unrecognized type ending ${typeEnding}`
    );
  }
}

export function parseFromPath(p: string, content: string): any {
  return isWorkspaceDependencies(p)
    ? content
    : p.endsWith(".yaml")
      ? yamlParseContent(p, content)
      : p.endsWith(".json")
        ? JSON.parse(content)
        : content;
}
export function parseFromFile(p: string): any {
  if (p.endsWith(".json")) {
    return JSON.parse(readTextFileSync(p));
  } else if (p.endsWith(".yaml") || p.endsWith(".yml")) {
    return yamlParseContent(p, readTextFileSync(p));
  } else {
    throw new Error("Could not read file " + p);
  }
}
/**
 * Parse a `migrations/datatable/<datatable>/<timestamp>_<name>.(up|down).sql`
 * path into its parts. Returns undefined for any other path.
 */
export function parseDatatableMigrationPath(p: string):
  | { datatable: string; timestamp: number; name: string; kind: "up" | "down" }
  | undefined {
  const parts = p.split("/");
  if (
    parts[0] !== "migrations" ||
    parts[1] !== "datatable" ||
    parts.length !== 4
  )
    return undefined;
  const m = parts[3].match(/^(\d+)_(.*)\.(up|down)\.sql$/);
  if (!m) return undefined;
  return {
    datatable: parts[2],
    timestamp: Number(m[1]),
    name: m[2],
    kind: m[3] as "up" | "down",
  };
}

export function isDatatableMigrationPath(p: string): boolean {
  return parseDatatableMigrationPath(p) !== undefined;
}

export function getTypeStrFromPath(
  p: string
):
  | "datatable_migration"
  | "script"
  | "variable"
  | "flow"
  | "resource"
  | "resource-type"
  | "folder"
  | "app"
  | "raw_app"
  | "schedule"
  | "http_trigger"
  | "websocket_trigger"
  | "kafka_trigger"
  | "nats_trigger"
  | "postgres_trigger"
  | "mqtt_trigger"
  | "amqp_trigger"
  | "sqs_trigger"
  | "gcp_trigger"
  | "azure_trigger"
  | "email_trigger"
  | "native_trigger"
  | "user"
  | "group"
  | "settings"
  | "encryption_key"
  | "shared_lock"
  | "workspace_dependencies" {
  if (isDatatableMigrationPath(p)) {
    return "datatable_migration";
  }
  if (isScriptModulePath(p)) {
    return "script";
  }
  if (isFlowPath(p)) {
    return "flow";
  }
  if (isAppPath(p)) {
    return "app";
  }
  if (isRawAppPath(p)) {
    return "raw_app";
  }
  // A repo-side artifact of `dedupeLockfiles`: it has no object on the server.
  if (isSharedLockPath(p)) {
    return "shared_lock";
  }
  if (p.startsWith("dependencies" + SEP)) {
    return "workspace_dependencies";
  }
  if (isFileResource(p) || isFilesetResource(p)) {
    return "resource";
  }
  const parsed = path.parse(p);
  if (
    parsed.ext == ".go" ||
    parsed.ext == ".ts" ||
    parsed.ext == ".sh" ||
    parsed.ext == ".py" ||
    parsed.ext == ".sql" ||
    parsed.ext == ".gql" ||
    parsed.ext == ".ps1" ||
    parsed.ext == ".js" ||
    parsed.ext == ".php" ||
    parsed.ext == ".rs" ||
    parsed.ext == ".cs" ||
    parsed.ext == ".nu" ||
    parsed.ext == ".java" ||
    parsed.ext == ".rb" ||
    parsed.ext == ".r" ||
    // for related places search: ADD_NEW_LANG
    (parsed.ext == ".yml" && parsed.name.split(".").pop() == "playbook") ||
    // A dbt descriptor is `<project>__dbt/wm_dbt.yaml`. Without this it reads
    // as one of the CLI's own `.yaml` metadata files and a pull writes the
    // script's metadata and lock but never its content.
    isDbtDescriptorPath(p)
  ) {
    return "script";
  }
  // Match folder.meta (base) or folder.<branch>.meta (branch-specific)
  if (parsed.name === "folder.meta" || /^folder\.[^.]+\.meta$/.test(parsed.name)) {
    return "folder";
  }
  // Match settings (base) or settings.<branch> (branch-specific)
  if (parsed.name === "settings" || /^settings\.[^.]+$/.test(parsed.name)) {
    return "settings";
  }
  // Match encryption_key (base) or encryption_key.<branch> (branch-specific)
  if (parsed.name === "encryption_key" || /^encryption_key\.[^.]+$/.test(parsed.name)) {
    return "encryption_key";
  }

  const typeEnding = parsed.name.split(".").at(-1);
  // Check for native trigger: {service}_native_trigger pattern
  if (typeEnding?.endsWith("_native_trigger")) {
    return "native_trigger";
  }
  if (
    typeEnding === "script" ||
    typeEnding === "variable" ||
    typeEnding === "resource" ||
    typeEnding === "resource-type" ||
    typeEnding === "app" ||
    typeEnding === "schedule" ||
    typeEnding === "http_trigger" ||
    typeEnding === "websocket_trigger" ||
    typeEnding === "kafka_trigger" ||
    typeEnding === "nats_trigger" ||
    typeEnding === "postgres_trigger" ||
    typeEnding === "mqtt_trigger" ||
    typeEnding === "amqp_trigger" ||
    typeEnding === "sqs_trigger" ||
    typeEnding === "gcp_trigger" ||
    typeEnding === "azure_trigger" ||
    typeEnding === "email_trigger" ||
    typeEnding === "user" ||
    typeEnding === "group" ||
    typeEnding === "settings" ||
    typeEnding === "encryption_key"
  ) {
    return typeEnding;
  } else {
    throw new Error("Could not infer type of path " + JSON.stringify(parsed));
  }
}

export function removeType(str: string, type: string) {
  // Normalize path for cross-platform compatibility and convert to forward slashes for API consistency
  const normalizedStr = path.normalize(str).replaceAll(SEP, "/");

  if (
    normalizedStr.endsWith("." + type + ".yaml") ||
    normalizedStr.endsWith("." + type + ".json")
  ) {
    return normalizedStr.slice(0, normalizedStr.length - type.length - 6);
  }
  // Accept clean paths without the type suffix (e.g. "f/folder/name" instead of "f/folder/name.schedule.yaml")
  if (normalizedStr.includes("." + type)) {
    log.debug(`Path '${str}' contains '.${type}' but doesn't end with '.${type}.(yaml|json)' — treating as clean path`);
  }
  return normalizedStr;
}

/**
 * Extracts native trigger info from a path like:
 * u/admin/script.flow.12345.nextcloud_native_trigger.json
 * Returns { scriptPath: "u/admin/script", isFlow: true, externalId: "12345", serviceName: "nextcloud" }
 */
export function extractNativeTriggerInfo(p: string): {
  scriptPath: string;
  isFlow: boolean;
  externalId: string;
  serviceName: string;
} | null {
  // Remove extension (.json or .yaml)
  const normalizedPath = path.normalize(p).replaceAll(SEP, "/");
  const withoutExt = normalizedPath.replace(/\.(json|yaml)$/, "");

  // Match pattern: {script_path}.{flow|script}.{external_id}.{service}_native_trigger
  const match = withoutExt.match(/^(.+)\.(flow|script)\.([^.]+)\.(\w+)_native_trigger$/);
  if (!match) {
    return null;
  }

  return {
    scriptPath: match[1],
    isFlow: match[2] === "flow",
    externalId: match[3],
    serviceName: match[4],
  };
}

export function removePathPrefix(str: string, prefix: string) {
  // Normalize paths for cross-platform compatibility and convert to forward slashes for API consistency
  const normalizedStr = path.normalize(str).replaceAll(SEP, "/");
  const normalizedPrefix = path.normalize(prefix).replaceAll(SEP, "/");

  // Handle exact match case
  if (normalizedStr === normalizedPrefix) {
    return "";
  }

  if (!normalizedStr.startsWith(normalizedPrefix + "/")) {
    throw new Error(str + " does not start with " + prefix);
  }
  return normalizedStr.slice(normalizedPrefix.length + 1);
}

import { colors } from "@cliffy/ansi/colors";
import { Table } from "@cliffy/table";

import * as wmill from "../../gen/services.gen.ts";
import { Preview } from "../../gen/types.gen.ts";
import { requireLogin } from "../core/auth.ts";
import { resolveWorkspace } from "../core/context.ts";
import * as log from "../core/log.ts";
import { GlobalOptions } from "../types.ts";
import { pollJobWithQueueLogging } from "./job_polling.ts";

// Shared building blocks for SQL catalogs (`wmill datatable` and
// `wmill ducklake`). Both expose a SQL surface backed by Windmill script
// previews, but the language and arg shape differ — `buildCatalogQueryPlan`
// centralizes that difference so subcommands stay thin.

export type CatalogKind = "datatable" | "ducklake";

interface CatalogQueryPlan {
  language: NonNullable<Preview["language"]>;
  content: string;
  args: Record<string, unknown>;
}

function buildCatalogQueryPlan(
  kind: CatalogKind,
  name: string,
  sql: string,
): CatalogQueryPlan {
  switch (kind) {
    case "datatable":
      return {
        language: "postgresql",
        content: sql,
        args: { database: `datatable://${name}` },
      };
    case "ducklake": {
      const attach = `ATTACH 'ducklake://${name}' AS dl;\nUSE dl;\n`;
      return {
        language: "duckdb",
        content: attach + sql,
        args: {},
      };
    }
  }
}

export async function runCatalogQuery(
  opts: GlobalOptions & { silent?: boolean },
  kind: CatalogKind,
  name: string,
  sql: string,
): Promise<void> {
  if (opts.silent) {
    log.setSilent(true);
  }
  const workspace = await resolveWorkspace(opts);
  await requireLogin(opts);

  const plan = buildCatalogQueryPlan(kind, name, sql);

  log.info(colors.gray(`Running query on ${kind}://${name}`));

  const jobId = await wmill.runScriptPreview({
    workspace: workspace.workspaceId,
    requestBody: {
      content: plan.content,
      language: plan.language,
      args: plan.args,
    },
  });

  const { result, success } = await pollJobWithQueueLogging(
    workspace.workspaceId,
    jobId,
  );

  if (!success) {
    process.exitCode = 1;
    if (opts.silent) {
      console.log(JSON.stringify(result));
    } else {
      log.info(colors.red.bold("Query failed"));
      log.info(JSON.stringify(result, null, 2));
    }
    return;
  }

  if (opts.silent) {
    console.log(JSON.stringify(result));
  } else {
    renderQueryResult(result);
  }
}

/**
 * Render a SQL query result. Postgres script previews return rows as an array
 * of `{column: value}` objects — display those as a table. Anything else
 * (DDL output, empty results, scalar payloads) falls back to pretty JSON.
 */
function renderQueryResult(result: unknown): void {
  if (Array.isArray(result) && result.length > 0 && result.every(isRecord)) {
    const rows = result as Record<string, unknown>[];
    const columns = collectColumns(rows);
    new Table()
      .header(columns)
      .padding(2)
      .border(true)
      .body(rows.map((row) => columns.map((c) => formatCell(row[c]))))
      .render();
    return;
  }
  log.info(JSON.stringify(result, null, 2));
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

function collectColumns(rows: Record<string, unknown>[]): string[] {
  const seen = new Set<string>();
  const columns: string[] = [];
  for (const row of rows) {
    for (const key of Object.keys(row)) {
      if (!seen.has(key)) {
        seen.add(key);
        columns.push(key);
      }
    }
  }
  return columns;
}

function formatCell(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }
  return JSON.stringify(value);
}

import { Codebase, SyncOptions } from "../core/conf.ts";
import * as log from "../core/log.ts";
import { digestDir } from "./utils.ts";

export type SyncCodebase = Codebase & {
  getDigest: (forceTar?: boolean) => Promise<string>;
};
export function listSyncCodebases(options: SyncOptions): SyncCodebase[] {
  const res: SyncCodebase[] = [];
  const nb_codebase = options?.codebases?.length ?? 0;
  if (nb_codebase > 0) {
    log.info(
      `Found ${nb_codebase} codebases: ${options?.codebases
        ?.map((c) => c.relative_path)
        .join(", ")}`
    );
  }
  for (const codebase of options?.codebases ?? []) {
    let _digest: string | undefined = undefined;
    let alreadyPrinted = false;
    let hasAssets = false;
    const getDigest: (forceTar?: boolean) => Promise<string> = async (
      forceTar?: boolean
    ) => {
      if (_digest == undefined) {
        _digest = await digestDir(
          codebase.relative_path,
          JSON.stringify(codebase)
        );
        if (codebase.format == "esm") {
          _digest += ".esm";
        }
        if (!alreadyPrinted) {
          alreadyPrinted = true;
          log.info(`Codebase ${codebase.relative_path}, digest: ${_digest}`);
        }
        hasAssets =
          Array.isArray(codebase.assets) && codebase.assets.length > 0;
      }
      if (forceTar || hasAssets) {
        return _digest + ".tar";
      } else {
        return _digest;
      }
    };
    res.push({ ...codebase, getDigest });
  }

  return res;
}

/**
 * Double-linked dependency tree for tracking script imports and propagating staleness.
 */

import { Workspace } from "../commands/workspace/workspace.ts";
import * as wmill from "../../gen/services.gen.ts";
import type { ScriptLang } from "../../gen/types.gen.ts";
import { ScriptLanguage } from "./script_common.ts";
import {
  filterWorkspaceDependencies,
  generateScriptHash,
  checkifMetadataUptodate,
  workspaceDependenciesPathToLanguageAndFilename,
  updateMetadataGlobalLock,
} from "./metadata.ts";
import { generateHash } from "./utils.ts";

/**
 * Diff local scripts against deployed versions, upload only those that differ.
 * Only uploaded (mismatched) scripts get contentHash set, so flatten() returns
 * temp_script_refs only for scripts the backend can't resolve from deployed versions.
 */
export async function uploadScripts(
  tree: DoubleLinkedDependencyTree,
  workspace: Workspace
): Promise<void> {
  // Split into scripts vs workspace deps and compute SHA256(content) for each
  const scriptHashes: Record<string, string> = {};
  const workspaceDeps: { path: string; language: ScriptLang; name?: string; hash: string }[] = [];

  for (const path of tree.allPaths()) {
    const content = tree.getContent(path);
    const itemType = tree.getItemType(path);

    if (itemType === "dependencies") {
      // Empty string is valid for workspace deps (means "no deps") — only skip undefined
      if (content === undefined) continue;
      const info = workspaceDependenciesPathToLanguageAndFilename(path);
      if (info) {
        const hash = await generateHash(content);
        workspaceDeps.push({ path, language: info.language as ScriptLang, name: info.name, hash });
      }
    } else if (itemType === "script") {
      if (!content) continue;
      const hash = await generateHash(content);
      scriptHashes[path] = hash;
    }
    // Skip inline_script, flow, app — they don't need temp storage uploads
  }

  if (Object.keys(scriptHashes).length === 0 && workspaceDeps.length === 0) return;

  // Single batch query: find which scripts/deps differ from deployed versions
  const mismatched = await wmill.diffRawScriptsWithDeployed({
    workspace: workspace.workspaceId,
    requestBody: {
      scripts: scriptHashes,
      workspace_deps: workspaceDeps,
    },
  });

  // Upload only mismatched scripts to temp storage
  for (const path of mismatched) {
    const content = tree.getContent(path);
    const itemType = tree.getItemType(path);

    if (itemType === "dependencies") {
      // Workspace deps don't need temp storage — just mark as mismatched.
      // Empty string is valid (means the dep file was emptied locally).
      if (content !== undefined) {
        tree.setContentHash(path, "mismatched");
      }
    } else if (content) {
      const hash = await wmill.storeRawScriptTemp({
        workspace: workspace.workspaceId,
        requestBody: content,
      });
      tree.setContentHash(path, hash);
    }
  }
}

export type ItemType = "script" | "inline_script" | "flow" | "app" | "dependencies";

interface DependencyNode {
  content: string;
  stalenessHash: string;  // Hash for staleness detection (includes deps, content, metadata)
  contentHash?: string;   // Hash for temp storage lookup (content only)
  language: ScriptLanguage;
  metadata: string;
  imports: Set<string>;
  importedBy: Set<string>;
  staleReason?: string;
  // Item metadata for generate-metadata command
  itemType: ItemType;
  folder: string;        // Folder path (for flows/apps) or remote path (for scripts)
  originalPath: string;  // Original path passed to handler (with extension for scripts)
  isRawApp?: boolean;    // Only set for apps
  isDirectlyStale: boolean;  // True if this item's content changed (vs transitively stale)
}

export class DoubleLinkedDependencyTree {
  private nodes: Map<string, DependencyNode> = new Map();
  private workspaceDeps: Record<string, string> = {};

  setWorkspaceDeps(deps: Record<string, string>): void {
    this.workspaceDeps = deps;
  }

  async addNode(
    path: string,
    content: string,
    language: ScriptLanguage,
    metadata: string,
    imports: string[],
    itemType: ItemType,
    folder: string,
    originalPath: string,
    isDirectlyStale: boolean,
    isRawApp?: boolean
  ): Promise<void> {
    const hasWorkspaceDeps = itemType === "script" || itemType === "inline_script";
    const filteredDeps = hasWorkspaceDeps
      ? filterWorkspaceDependencies(this.workspaceDeps, content, language)
      : {};
    const stalenessHash = await generateScriptHash({}, content, metadata);

    if (!this.nodes.has(path)) {
      this.nodes.set(path, {
        content: "", stalenessHash: "", language: "deno", metadata: "",
        imports: new Set(), importedBy: new Set(),
        itemType: "script", folder: "", originalPath: "", isDirectlyStale: false,
      });
    }
    const node = this.nodes.get(path)!;
    node.content = content;
    node.stalenessHash = stalenessHash;
    node.language = language;
    node.metadata = metadata;
    node.itemType = itemType;
    node.folder = folder;
    node.originalPath = originalPath;
    node.isDirectlyStale = isDirectlyStale;
    node.isRawApp = isRawApp;

    // Create nodes for referenced workspace deps with content and language.
    const filteredDepsPaths = Object.keys(filteredDeps);
    for (const depsPath of filteredDepsPaths) {
      if (!this.nodes.has(depsPath)) {
        const depsInfo = workspaceDependenciesPathToLanguageAndFilename(depsPath);
        const contentHash = await generateHash(filteredDeps[depsPath] + depsPath);
        const isUpToDate = await checkifMetadataUptodate(depsPath, contentHash, undefined);
        this.nodes.set(depsPath, {
          content: filteredDeps[depsPath],
          stalenessHash: "", language: depsInfo?.language ?? "deno", metadata: "",
          imports: new Set(), importedBy: new Set(),
          itemType: "dependencies", folder: "", originalPath: depsPath,
          isDirectlyStale: !isUpToDate,
        });
      }
    }

    const allImports = [...imports, ...filteredDepsPaths];
    for (const importPath of allImports) {
      node.imports.add(importPath);

      if (!this.nodes.has(importPath)) {
        this.nodes.set(importPath, {
          content: "", stalenessHash: "", language: "deno", metadata: "",
          imports: new Set(), importedBy: new Set(),
          itemType: "script", folder: "", originalPath: "", isDirectlyStale: false,
        });
      }
      this.nodes.get(importPath)!.importedBy.add(path);
    }
  }

  getContent(path: string): string | undefined {
    return this.nodes.get(path)?.content;
  }

  getStalenessHash(path: string): string | undefined {
    return this.nodes.get(path)?.stalenessHash;
  }

  getContentHash(path: string): string | undefined {
    return this.nodes.get(path)?.contentHash;
  }

  setContentHash(path: string, hash: string): void {
    const node = this.nodes.get(path);
    if (node) {
      node.contentHash = hash;
    }
  }

  getLanguage(path: string): ScriptLanguage | undefined {
    return this.nodes.get(path)?.language;
  }

  getMetadata(path: string): string | undefined {
    return this.nodes.get(path)?.metadata;
  }

  getStaleReason(path: string): string | undefined {
    return this.nodes.get(path)?.staleReason;
  }

  getItemType(path: string): ItemType | undefined {
    return this.nodes.get(path)?.itemType;
  }

  getFolder(path: string): string | undefined {
    return this.nodes.get(path)?.folder;
  }

  getIsRawApp(path: string): boolean | undefined {
    return this.nodes.get(path)?.isRawApp;
  }

  getIsDirectlyStale(path: string): boolean {
    return this.nodes.get(path)?.isDirectlyStale ?? false;
  }

  getOriginalPath(path: string): string | undefined {
    return this.nodes.get(path)?.originalPath;
  }

  getImports(path: string): Set<string> | undefined {
    return this.nodes.get(path)?.imports;
  }

  /**
   * Returns true if this node has been marked stale (directly or transitively).
   */
  isStale(path: string): boolean {
    return this.nodes.get(path)?.staleReason !== undefined;
  }

  /**
   * Mutates the tree by removing all nodes that are not stale.
   * Uses BFS on reverse graph (importedBy) to find all stale scripts.
   * Starts from nodes with isDirectlyStale=true.
   */
  propagateStaleness(): void {
    // Collect directly stale nodes
    const directlyStale = new Set<string>();
    for (const [path, node] of this.nodes.entries()) {
      if (node.isDirectlyStale) {
        directlyStale.add(path);
        node.staleReason = "content changed";
      }
    }

    const allStale = new Set(directlyStale);
    const queue = [...directlyStale];
    const visited = new Set<string>();

    while (queue.length > 0) {
      const scriptPath = queue.shift()!;
      if (visited.has(scriptPath)) continue;
      visited.add(scriptPath);

      const node = this.nodes.get(scriptPath);
      if (!node) continue;

      for (const importer of node.importedBy) {
        if (!allStale.has(importer)) {
          allStale.add(importer);
          queue.push(importer);
          // Set reason for transitively stale scripts
          const importerNode = this.nodes.get(importer);
          if (importerNode) importerNode.staleReason = `depends on ${scriptPath}`;
        }
      }
    }

  }

  /**
   * Walks all transitive imports for a node, calling the callback for each.
   * Callback may return true to stop traversing that branch.
   */
  traverseTransitive(scriptPath: string, callback: (importPath: string, node: DependencyNode) => boolean | void): void {
    const queue = [scriptPath];
    const visited = new Set<string>();

    while (queue.length > 0) {
      const current = queue.shift()!;
      if (visited.has(current)) continue;
      visited.add(current);

      const node = this.nodes.get(current);
      if (!node) continue;

      for (const importPath of node.imports) {
        const importNode = this.nodes.get(importPath);
        if (importNode) {
          const stop = callback(importPath, importNode);
          if (!stop) {
            queue.push(importPath);
          }
        }
      }
    }
  }

  allPaths(): IterableIterator<string> {
    return this.nodes.keys();
  }

  /**
   * Returns paths of all stale nodes (those with a staleReason).
   */
  *stalePaths(): IterableIterator<string> {
    for (const [path, node] of this.nodes.entries()) {
      if (node.staleReason) {
        yield path;
      }
    }
  }

  has(path: string): boolean {
    return this.nodes.has(path);
  }

  /**
   * Returns workspace deps that were uploaded as mismatched with remote.
   * These need to be passed as raw_workspace_dependencies in job args
   * so the backend uses local content instead of deployed.
   */
  getMismatchedWorkspaceDeps(): Record<string, string> {
    const result: Record<string, string> = {};
    for (const [path, node] of this.nodes.entries()) {
      if (node.itemType === "dependencies" && node.contentHash && node.content !== undefined) {
        result[path] = node.content;
      }
    }
    return result;
  }

  /**
   * Returns path → contentHash for all transitive imports that have been uploaded.
   * Must be called after uploadScripts() has populated contentHash values.
   */
  getTempScriptRefs(scriptPath: string): Record<string, string> {
    const result: Record<string, string> = {};
    this.traverseTransitive(scriptPath, (_path, node) => {
      if (node.contentHash) {
        result[_path] = node.contentHash;
      }
    });
    return result;
  }

  /**
   * Returns path → contentHash for ALL uploaded nodes, regardless of which
   * script imports them. Superset of getTempScriptRefs(path) for every path —
   * used by `wmill dev`, where the previewed item changes at runtime so no
   * single anchor node exists. Must be called after uploadScripts().
   */
  getAllTempScriptRefs(): Record<string, string> {
    const result: Record<string, string> = {};
    for (const [path, node] of this.nodes.entries()) {
      if (node.contentHash) {
        result[path] = node.contentHash;
      }
    }
    return result;
  }

  /**
   * Persist workspace dep hashes to wmill-lock.yaml so getRawWorkspaceDependencies
   * considers them up-to-date on the next run.
   */
  async persistDepsHashes(depsPaths: string[]): Promise<void> {
    for (const path of depsPaths) {
      const node = this.nodes.get(path);
      if (node?.itemType === "dependencies" && node.content !== undefined) {
        const hash = await generateHash(node.content + path);
        await updateMetadataGlobalLock(path, hash);
      }
    }
  }

  get size(): number {
    return this.nodes.size;
  }
}

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import process from "node:process";
import { createGunzip } from "node:zlib";
import { Readable } from "node:stream";
import { pathToFileURL } from "node:url";
import * as tar from "tar-stream";
import * as log from "../core/log.ts";

// esbuild splits into a JS host package and a per-platform native binary
// (@esbuild/<platform>). They must be the same version. A broken or incremental
// install can leave the on-disk binary at a different version than the pinned
// host, which crashes service start with
//   Cannot start service: Host version "X" does not match binary version "Y"
// The running code can't fix what npm/bun put on disk, so when that happens we
// fall back to esbuild-wasm, whose binary is a single version-pinned .wasm. To
// keep that 14MB out of every CLI install, the esbuild-wasm package is not a
// dependency: it is downloaded once and cached on disk, on the fallback path
// only. We download the whole package (not just the .wasm) because esbuild-wasm
// reads the app's files from disk by spawning `node bin/esbuild`, which needs
// bin/esbuild + esbuild.wasm + wasm_exec*.js co-located on disk.

type Esbuild = typeof import("esbuild");

// Version to fall back to if the native host's version can't be read. Keep in
// sync with the "esbuild" pin in cli/package.json.
const FALLBACK_VERSION = "0.28.0";

let cached: Esbuild | undefined;
let inFlight: Promise<Esbuild> | undefined;
// Distinguishes concurrent extraction temp dirs within a process.
let extractCounter = 0;

/**
 * Returns a working esbuild module, preferring the native binary and falling
 * back to esbuild-wasm only when the native host/binary versions don't match.
 * Memoized for the process: concurrent first callers (e.g. a parallel
 * `wmill sync push`) share one probe/download instead of each running their own.
 */
export function getEsbuild(): Promise<Esbuild> {
  if (cached) return Promise.resolve(cached);
  if (inFlight) return inFlight;
  inFlight = acquireEsbuild()
    .then((esbuild) => {
      cached = esbuild;
      return esbuild;
    })
    .finally(() => {
      inFlight = undefined;
    });
  return inFlight;
}

async function acquireEsbuild(): Promise<Esbuild> {
  // Escape hatch: skip native entirely (e.g. a host known to have a broken
  // install, or to exercise the fallback path).
  if (process.env.WINDMILL_FORCE_ESBUILD_WASM) {
    return loadWasmEsbuild(await nativeHostVersion());
  }

  try {
    const esbuild = await import("esbuild");
    // The native service only starts on the first call; force it with the most
    // trivial op so any breakage (host/binary version mismatch, a dead service)
    // surfaces now rather than mid-build. The mismatch detail is printed to the
    // child's stderr while the thrown error is generic ("service was stopped"),
    // so we fall back on ANY smoke-test failure rather than matching a string.
    await esbuild.transform("");
    return esbuild;
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    log.warn(
      `native esbuild is not usable; falling back to esbuild-wasm (${msg.trim()})`
    );
  }

  return loadWasmEsbuild(await nativeHostVersion());
}

/**
 * Stops the esbuild service (native or wasm — both spawn a child process) so the
 * process can exit. Safe to call repeatedly; the service restarts lazily on the
 * next build.
 */
export async function stopEsbuild(): Promise<void> {
  await cached?.stop();
}

async function nativeHostVersion(): Promise<string> {
  try {
    return (await import("esbuild")).version ?? FALLBACK_VERSION;
  } catch {
    return FALLBACK_VERSION;
  }
}

async function loadWasmEsbuild(version: string): Promise<Esbuild> {
  const pkgDir = await ensureWasmPackage(version);
  const mainJs = path.join(pkgDir, "lib", "main.js");
  // The Node build (lib/main.js) reads app files from disk by spawning
  // `node bin/esbuild`, so it works with on-disk entry points and node_modules,
  // unlike the browser build.
  return (await import(pathToFileURL(mainJs).href)) as unknown as Esbuild;
}

/**
 * Returns a directory containing an extracted esbuild-wasm package (with
 * lib/main.js). Uses an explicit override, then an on-disk cache, then downloads
 * and extracts the npm tarball.
 */
async function ensureWasmPackage(version: string): Promise<string> {
  // Explicit local override wins (air-gapped / self-hosted workers): a path to
  // an already-extracted esbuild-wasm package directory.
  const override = process.env.WINDMILL_ESBUILD_WASM_PATH;
  if (override) return override;

  const destDir = path.join(cacheDir(), `esbuild-wasm-${version}`);
  if (fs.existsSync(path.join(destDir, "lib", "main.js"))) {
    return destDir;
  }

  const url = process.env.WINDMILL_ESBUILD_WASM_URL ??
    `https://registry.npmjs.org/esbuild-wasm/-/esbuild-wasm-${version}.tgz`;
  log.info(`Downloading esbuild-wasm@${version} from ${url} ...`);
  const res = await fetch(url);
  if (!res.ok || !res.body) {
    throw new Error(
      `Failed to download esbuild-wasm@${version} (${res.status} ${res.statusText}). ` +
        `Set WINDMILL_ESBUILD_WASM_PATH to an extracted esbuild-wasm package dir, ` +
        `point WINDMILL_ESBUILD_WASM_URL at a reachable tarball, or repair the native esbuild install.`
    );
  }

  // Extract to a unique temp dir and rename into place so a crash or a
  // concurrent writer can't leave a half-extracted package behind, and so two
  // extractions never share an in-progress directory.
  const tmpDir = `${destDir}.${process.pid}.${extractCounter++}.tmp`;
  fs.rmSync(tmpDir, { recursive: true, force: true });
  await extractTarball(res.body, tmpDir);
  if (!fs.existsSync(path.join(tmpDir, "lib", "main.js"))) {
    fs.rmSync(tmpDir, { recursive: true, force: true });
    throw new Error(`esbuild-wasm@${version} tarball did not contain lib/main.js`);
  }
  try {
    fs.renameSync(tmpDir, destDir);
  } catch {
    // Another process won the race, or rename across devices failed; clean up
    // and let the existsSync check below decide whether the cache is usable.
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }
  if (!fs.existsSync(path.join(destDir, "lib", "main.js"))) {
    throw new Error(`Failed to cache esbuild-wasm@${version} at ${destDir}`);
  }
  return destDir;
}

/**
 * Resolves a tar entry to an absolute path inside destDir, stripping the leading
 * "package/" component that npm tarballs use. Returns null if the entry would
 * escape destDir (tar-slip), since WINDMILL_ESBUILD_WASM_URL allows untrusted
 * tarball sources.
 */
export function resolveTarEntryPath(
  destDir: string,
  entryName: string
): string | null {
  const rel = entryName.replace(/^[^/]+\//, "");
  const root = path.resolve(destDir);
  const outPath = path.resolve(root, rel);
  if (outPath !== root && !outPath.startsWith(root + path.sep)) {
    return null;
  }
  return outPath;
}

// Extracts an npm tarball (gzipped tar) into destDir, stripping the leading
// "package/" path component that npm tarballs use.
async function extractTarball(
  body: ReadableStream<Uint8Array>,
  destDir: string
): Promise<void> {
  const extract = tar.extract();
  extract.on("entry", (header, stream, next) => {
    if (header.type !== "file") {
      stream.resume();
      stream.on("end", next);
      return;
    }
    const outPath = resolveTarEntryPath(destDir, header.name);
    if (!outPath) {
      // Reject tar-slip entries that would write outside the cache dir.
      stream.resume();
      stream.on("end", () =>
        next(new Error(`unsafe path in esbuild-wasm tarball: ${header.name}`))
      );
      return;
    }
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    const ws = fs.createWriteStream(outPath, { mode: header.mode ?? 0o644 });
    stream.pipe(ws);
    ws.on("finish", next);
    ws.on("error", next);
    stream.on("error", next);
  });

  await new Promise<void>((resolve, reject) => {
    extract.on("finish", resolve);
    extract.on("error", reject);
    Readable.fromWeb(body as unknown as Parameters<typeof Readable.fromWeb>[0])
      .pipe(createGunzip())
      .on("error", reject)
      .pipe(extract)
      .on("error", reject);
  });
}

function cacheDir(): string {
  const explicit = process.env.WINDMILL_CACHE_DIR;
  if (explicit) return explicit;
  const xdg = process.env.XDG_CACHE_HOME;
  if (xdg) return path.join(xdg, "windmill");
  try {
    return path.join(os.homedir(), ".cache", "windmill");
  } catch {
    return path.join(os.tmpdir(), "windmill");
  }
}

import * as log from "../core/log.ts";
import { execSync, spawnSync } from "node:child_process";
import { WM_FORK_PREFIX } from "../core/constants.ts";

// Fork *workspace id* prefix ("wm-fork-"). WM_FORK_PREFIX is the *branch*
// prefix ("wm-fork") used inside the wm-fork/<branch>/<id> branch name.
const FORK_WORKSPACE_PREFIX = `${WM_FORK_PREFIX}-`;

export function getCurrentGitBranch(): string | null {
  try {
    const result = execSync("git rev-parse --abbrev-ref HEAD", {
      encoding: "utf8",
      stdio: "pipe"
    });
    const branch = result.trim();
    return branch || null;
  } catch (error) {
    log.debug(`Failed to get Git branch: ${error}`);
    return null;
  }
}

/** Whether a local branch with this exact name exists. */
export function gitBranchExists(branchName: string): boolean {
  const r = spawnSync(
    "git",
    ["show-ref", "--verify", "--quiet", `refs/heads/${branchName}`],
    { stdio: "pipe" },
  );
  return r.status === 0;
}

/**
 * Rename the currently checked-out branch (`git branch -m <newName>`). Used by
 * `wmill workspace fork --from-branch` to turn an existing working branch into
 * the `wm-fork/<base>/<id>` fork branch in place, preserving its commits.
 */
export function renameCurrentGitBranch(newName: string): void {
  const r = spawnSync("git", ["branch", "-m", newName], {
    encoding: "utf8",
    stdio: "pipe",
  });
  if ((r.status ?? 1) !== 0) {
    throw new Error(
      `git branch -m ${newName} failed (exit ${r.status}): ${r.stderr ?? ""}`,
    );
  }
}

export function getOriginalBranchForWorkspaceForks(branchName: string | null): string | null {
  if (!branchName || !branchName.startsWith(WM_FORK_PREFIX)) {
    return null
  }

  const start = branchName.indexOf("/") + 1;
  const end = branchName.lastIndexOf("/");

  if (start < 0 || end < 0 || end - start <= 0) {
    return null
  }

  return branchName.slice(start, end)
}

export function getWorkspaceIdForWorkspaceForkFromBranchName(branchName: string): string | null {
  if (!branchName.startsWith(WM_FORK_PREFIX)) {
    return null
  }

  const start = branchName.lastIndexOf("/") + 1;

  if (start < 0) {
    return null
  }

  return `${WM_FORK_PREFIX}-${branchName.slice(start)}`
}
/**
 * Whether this checkout can vouch for what it once held under `migrations/datatable/**`.
 *
 * `known` lists every such path recorded on the current branch (paths stay listed after
 * the commit that removed them, so a real deletion is still recognisable). `unknown`
 * means a file's absence from the working tree proves nothing, either because the
 * history can't be read — no repository, a shallow clone's truncated history, an
 * unresolvable root, a failing git — or because the working tree deliberately doesn't
 * mirror it, as in a sparse checkout. Both shapes carry the same obligation on the
 * caller: trust nothing, rather than read absence as evidence.
 */
export type RecordedMigrationPaths =
  | { kind: "known"; paths: Set<string> }
  | { kind: "unknown"; reason: string; remedy: string };

/**
 * Resolve [`RecordedMigrationPaths`] for the checkout at the current directory.
 *
 * This is the durable answer to "did this checkout ever track that migration?", which
 * the working tree cannot give: an absent `migrations/datatable/` is equally a clone
 * that never pulled migrations and one where the last was deleted, and creating a
 * migration locally (`wmill datatable migrate new`) makes the directory appear without
 * anything having been tracked.
 *
 * Scoped to `HEAD`, not `--all`: a migration that only ever existed on some other
 * branch is not evidence that *this* branch ever tracked it, and using it as such would
 * authorize deleting it. Output paths are repo-root-relative, so the `--show-prefix` of
 * the working directory is stripped to match the cwd-relative paths a sync diff uses.
 */
export function gitRecordedDatatableMigrationPaths(): RecordedMigrationPaths {
  if (!isGitRepository()) {
    return {
      kind: "unknown",
      reason: "this directory is not a git repository",
      remedy: "Run the push from a git checkout of the synced repository",
    };
  }
  const shallow = spawnSync("git", ["rev-parse", "--is-shallow-repository"], {
    encoding: "utf8",
    stdio: "pipe",
  });
  if ((shallow.stdout ?? "").trim() === "true") {
    return {
      kind: "unknown",
      reason: "this is a shallow clone, so its history is truncated",
      remedy:
        "Fetch the full history (for actions/checkout, fetch-depth: 0)",
    };
  }
  // A sparse checkout can record migrations in history while never materialising
  // them in the working tree, so their absence there says nothing about whether the
  // user deleted them. Over-protective for a sparse cone that does include
  // migrations/, which the interactive prompt can still override.
  // `--type=bool` normalises git's booleans (1, yes, on, …) to true/false; a raw
  // `--get` would let `core.sparseCheckout = 1` walk straight past this.
  const sparse = spawnSync(
    "git",
    ["config", "--type=bool", "--get", "core.sparseCheckout"],
    { encoding: "utf8", stdio: "pipe" },
  );
  if ((sparse.stdout ?? "").trim() === "true") {
    return {
      kind: "unknown",
      reason:
        "this is a sparse checkout, so its working tree may not hold every tracked file",
      remedy: "Run the push from a full (non-sparse) checkout",
    };
  }
  const prefixOut = spawnSync("git", ["rev-parse", "--show-prefix"], {
    encoding: "utf8",
    stdio: "pipe",
  });
  if ((prefixOut.status ?? 1) !== 0) {
    return {
      kind: "unknown",
      reason: "the repository root could not be resolved",
      remedy: "Check that git runs correctly in this directory",
    };
  }
  const prefix = (prefixOut.stdout ?? "").trim();

  const r = spawnSync(
    "git",
    ["log", "HEAD", "--format=", "--name-only", "--", "migrations/datatable"],
    { encoding: "utf8", stdio: "pipe", maxBuffer: 64 * 1024 * 1024 },
  );
  if ((r.status ?? 1) !== 0) {
    log.debug(`Could not read git history for migrations: ${r.stderr ?? ""}`);
    return {
      kind: "unknown",
      reason: "its history could not be read",
      remedy: "Check that git runs correctly in this directory",
    };
  }
  const paths = new Set<string>();
  for (const line of (r.stdout ?? "").split("\n")) {
    const p = line.trim();
    if (p.length === 0) continue;
    if (prefix.length > 0) {
      if (!p.startsWith(prefix)) continue;
      paths.add(p.slice(prefix.length));
    } else {
      paths.add(p);
    }
  }
  return { kind: "known", paths };
}

export function isGitRepository(): boolean {
  try {
    execSync("git rev-parse --git-dir", {
      encoding: "utf8",
      stdio: "pipe"
    });
    return true;
  } catch (error) {
    log.debug(`Failed to check Git repository: ${error}`);
    return false;
  }
}

// ===========================================================================
// Git-sync deployment-callback branch/commit/push.
//
// The git-sync hub script ("sync-script-to-git-repo-windmill") historically
// owned this logic. When `use_individual_branch` is set, a deploy must land on
// a dedicated `wm_deploy/<workspace>/<...>` branch (or a `wm-fork/<branch>/<id>`
// branch for forks) instead of the repo's protected base branch — otherwise
// the push to a protected `main` is rejected (GH006). A hub-script rewrite once
// dropped this and every deploy pushed straight to `main`; keeping the logic
// here (in-repo, behind `wmill sync pull`) makes it deterministically testable.
// ===========================================================================

export interface GitSyncDeployItem {
  path_type: string;
  path?: string | null;
  parent_path?: string | null;
  commit_msg?: string;
}

// A throwaway fork syncs to its own wm-fork/<branch>/<id> branch. The hub script
// force-disables use_individual_branch / group_by_folder for these (that disabling
// also changes the include/promotion derivation — so callers must apply it BEFORE
// deriving includes, not just for branch naming). A dev workspace is the exception:
// with promotion on it keeps use_individual_branch / group_by_folder and gets
// per-item wm_deploy/** branches like a root workspace.
//
// Fork-ness is "has a parent workspace" OR the "wm-fork-" id prefix. Regular forks
// get an auto-generated `wm-fork-<slug>` id, but dev workspaces keep a custom id
// with no prefix — so the prefix alone misses them. Mirrors the backend's
// `parent.is_some() || starts_with(WM_FORK_PREFIX)` rule (the prefix also covers a
// fork whose parent was deleted, since parent_workspace_id is ON DELETE SET NULL).
export function isForkWorkspace(
  workspaceId: string,
  parentWorkspaceId?: string | null,
): boolean {
  return !!parentWorkspaceId || workspaceId.startsWith(FORK_WORKSPACE_PREFIX);
}

// Mirrors the hub script's get_fork_branch_name. A dev workspace syncs with its
// environment-label branch verbatim ("dev"/"staging" — a first-class top-level
// branch; the backend passes the label with the deploy). A `wm-fork-<slug>`
// throwaway fork id becomes "wm-fork/<originalBranch>/<slug>"; a prefix-less id
// without a label falls back to "wm-fork/<originalBranch>/<id>".
export function forkBranchName(
  workspaceId: string,
  originalBranch: string,
  devWorkspaceLabel?: string | null,
): string {
  if (devWorkspaceLabel) {
    return devWorkspaceLabel;
  }
  const branchPrefix = `${WM_FORK_PREFIX}/${originalBranch}/`;
  return workspaceId.startsWith(FORK_WORKSPACE_PREFIX)
    ? workspaceId.replace(FORK_WORKSPACE_PREFIX, branchPrefix)
    : `${branchPrefix}${workspaceId}`;
}

// Pure branch-name resolution mirroring the hub script's git_checkout_branch.
// Returns null when the deploy should stay on the cloned/base branch (i.e.
// workspace-wide mode, or user/group objects which never get their own branch).
export function computeGitSyncDeployBranch(params: {
  workspaceId: string;
  parentWorkspaceId?: string | null;
  devWorkspaceLabel?: string | null;
  items: GitSyncDeployItem[];
  useIndividualBranch: boolean;
  groupByFolder: boolean;
  clonedBranchName: string;
}): string | null {
  const {
    workspaceId,
    parentWorkspaceId,
    devWorkspaceLabel,
    items,
    useIndividualBranch,
    groupByFolder,
    clonedBranchName,
  } = params;

  // A dev workspace in promotion mode falls through to the wm_deploy/** formula
  // below (per-item/-folder PRs that promote into its parent). Throwaway forks,
  // and dev workspaces with promotion off, sync to their own wm-fork/<branch>/<id>
  // (or env-label) branch.
  const isDevWorkspace = !!devWorkspaceLabel;
  if (
    isForkWorkspace(workspaceId, parentWorkspaceId) &&
    !(isDevWorkspace && useIndividualBranch)
  ) {
    return forkBranchName(workspaceId, clonedBranchName, devWorkspaceLabel);
  }

  // A dev workspace's deploys must never fall through to the base branch — that
  // is its parent's tracked branch, so a null here would push dev content
  // straight to prod. Anything without its own wm_deploy/** branch (user/group
  // objects, an unresolvable ref) goes to the dev's env-label branch instead.
  // A root workspace has no such isolation, so its fallback stays null (base).
  const fallback = isDevWorkspace
    ? forkBranchName(workspaceId, clonedBranchName, devWorkspaceLabel)
    : null;

  if (items.length === 0) return fallback;
  const first = items[0];

  // `use_individual_branch` disables debouncing, so items is length 1 here.
  if (
    !useIndividualBranch ||
    first.path_type === "user" ||
    first.path_type === "group"
  ) {
    return fallback;
  }

  // `||` not `??`: the backend serializes a path that no longer matches the repo
  // filter (a rename out of the included set) as "" with the old path in
  // parent_path. That "" must fall back to parent_path — mirroring the backend's
  // `!item_path.is_empty()` derivation. `??` would keep "", return null, and skip
  // the branch checkout, letting the removal land on the tracked base branch.
  const ref = first.path || first.parent_path;
  if (!ref) return fallback;

  return groupByFolder
    ? `wm_deploy/${workspaceId}/${ref.split("/").slice(0, 2).join("__")}`
    : `wm_deploy/${workspaceId}/${first.path_type}/${ref.replaceAll("/", "__")}`;
}

// Mirrors the hub script's composeCommitHeader: summarise the deployed object
// types, e.g. "[WM]: Deployed 2 scripts, 1 flow and 3 other objects".
export function composeGitSyncCommitHeader(
  items: GitSyncDeployItem[],
): string {
  const typeCounts = new Map<string, number>();
  for (const item of items) {
    typeCounts.set(item.path_type, (typeCounts.get(item.path_type) ?? 0) + 1);
  }
  const sorted = Array.from(typeCounts.entries()).sort((a, b) => b[1] - a[1]);

  const parts: string[] = [];
  let othersCount = 0;
  for (let i = 0; i < sorted.length; i++) {
    const [pathType, count] = sorted[i];
    if (i < 3) {
      const label = count > 1 ? `${pathType}s` : pathType;
      if (i === 2 && sorted.length === 3) {
        parts.push(`and ${count} ${label}`);
      } else {
        parts.push(`${count} ${label}`);
      }
    } else {
      othersCount += count;
    }
  }

  let header = `[WM]: Deployed ${parts.join(", ")}`;
  if (othersCount > 0) {
    header += ` and ${othersCount} other object${othersCount > 1 ? "s" : ""}`;
  }
  return header;
}

// Mirrors the hub script's git_push commit-message construction EXACTLY,
// including its quirks: it pushes `commit_msg` once per item unconditionally
// (so the array length equals items.length even when some msgs are empty),
// uses the single message verbatim when there is exactly one item, otherwise
// the composed header + newline-joined descriptions, and falls back to
// "no commit msg" when the chosen header is empty/undefined. join() coerces
// undefined entries to "" just like the original.
export function gitSyncCommitMessage(items: GitSyncDeployItem[]): {
  header: string;
  description: string;
} {
  const descs = items.map((i) => i.commit_msg);
  const [h, d] =
    descs.length === 1
      ? [descs[0], ""]
      : [composeGitSyncCommitHeader(items), descs.join("\n")];
  return {
    header: h === undefined || h === "" ? "no commit msg" : h,
    description: d ?? "",
  };
}

// Mirrors the hub script's regexFromPath: the include glob(s) that select an
// object's files for `wmill sync pull --extra-includes`. Some types expand to
// two comma-separated patterns (dotted + double-underscore folder layouts).
export function gitSyncIncludePattern(
  pathType: string,
  path: string,
): string {
  switch (pathType) {
    case "flow":
      return `${path}.flow/*,${path}__flow/*`;
    case "app":
      return `${path}.app/*,${path}__app/*`;
    case "raw_app":
      return `${path}.raw_app/**,${path}__raw_app/**`;
    case "folder":
      return `${path}/folder.meta.*`;
    case "resourcetype":
      return `${path}.resource-type.*`;
    case "resource":
      return `${path}.resource.*`;
    case "variable":
      return `${path}.variable.*`;
    case "schedule":
      return `${path}.schedule.*`;
    case "user":
      return `${path}.user.*`;
    case "group":
      return `${path}.group.*`;
    case "httptrigger":
      return `${path}.http_trigger.*`;
    case "websockettrigger":
      return `${path}.websocket_trigger.*`;
    case "kafkatrigger":
      return `${path}.kafka_trigger.*`;
    case "natstrigger":
      return `${path}.nats_trigger.*`;
    case "postgrestrigger":
      return `${path}.postgres_trigger.*`;
    case "mqtttrigger":
      return `${path}.mqtt_trigger.*`;
    case "amqptrigger":
      return `${path}.amqp_trigger.*`;
    case "sqstrigger":
      return `${path}.sqs_trigger.*`;
    case "gcptrigger":
      return `${path}.gcp_trigger.*`;
    case "azuretrigger":
      return `${path}.azure_trigger.*`;
    case "emailtrigger":
      return `${path}.email_trigger.*`;
    case "datatable_migration":
      // One migration is two files under `migrations/datatable/<dt>/`; the
      // backend already sends the repo-relative base path.
      return `${path}.up.sql,${path}.down.sql`;
    default:
      // Scripts: `${path}.*` matches the dotted layout
      // (`${path}.script.yaml` etc.), `${path}__mod/**` matches the folder
      // layout used by scripts with companion modules
      // (`${path}__mod/script.ts`, `${path}__mod/helper.ts`, ...). Without the
      // second pattern the module files are filtered out of the pull and the
      // subsequent `git add '${path}**'` fails with "pathspec did not match".
      return `${path}.*,${path}__mod/**`;
  }
}

// `forcedIncludes` carries ONLY the include-* flags that must be force-set to
// true (overriding the repo's wmill.yaml). Kinds not present are intentionally
// omitted (never set to false) so the caller can spread this object and let
// the repo's effective config govern the rest — see deriveGitSyncDeployIncludes.
export type GitSyncForcedIncludes = Partial<{
  includeSchedules: boolean;
  includeGroups: boolean;
  includeUsers: boolean;
  includeTriggers: boolean;
  includeSettings: boolean;
  includeKey: boolean;
}>;

export interface GitSyncDeployIncludes {
  extraIncludes: string[];
  forcedIncludes: GitSyncForcedIncludes;
}

// Mirrors the hub script's wmill_sync_pull include-derivation: build the
// --extra-includes set from the deployed items, and decide which default-
// excluded object kinds (triggers, schedules, groups, users, settings, key)
// must be force-included in the pull. Replaces the script's regexFromPath +
// per-kind --include-* construction so the hub script can drop both.
//
// Branch-mode distinction (this is load-bearing — see the trigger-promotion
// bug it fixes):
//   - Workspace-wide mode: the repo is a full mirror of the workspace, so a
//     deployed object of a default-excluded kind MUST be re-included, even if
//     wmill.yaml would otherwise skip it. We force the flag on.
//   - Individual-branch (promotion) mode: the repo is a filtered prod surface
//     whose own wmill.yaml filters decide what gets promoted. We force NOTHING
//     here and the keys stay absent, so the caller's pull resolves them from
//     the target's effective config (a deployed trigger lands iff the target
//     includes triggers). Forcing `false` (the original behavior) did NOT
//     defer — it CLOBBERED the effective config via Object.assign in pull's
//     option merge, silently dropping kinds the target actually wanted (e.g. a
//     deployed trigger when the target has includeTriggers: true), and the
//     server then omitted the object from the tarball entirely.
export function deriveGitSyncDeployIncludes(
  items: GitSyncDeployItem[],
  useIndividualBranch: boolean,
): GitSyncDeployIncludes {
  const extraIncludes: string[] = [];
  for (const { path_type, path, parent_path } of items) {
    if (path) {
      extraIncludes.push(...gitSyncIncludePattern(path_type, path).split(","));
    }
    if (parent_path) {
      extraIncludes.push(
        ...gitSyncIncludePattern(path_type, parent_path).split(","),
      );
    }
  }

  const forcedIncludes: GitSyncForcedIncludes = {};
  if (!useIndividualBranch) {
    const has = (pred: (t: string) => boolean) =>
      items.some((i) => pred(i.path_type));
    if (has((t) => t === "schedule")) forcedIncludes.includeSchedules = true;
    if (has((t) => t === "group")) forcedIncludes.includeGroups = true;
    if (has((t) => t === "user")) forcedIncludes.includeUsers = true;
    if (has((t) => t.includes("trigger"))) forcedIncludes.includeTriggers = true;
    if (has((t) => t === "settings")) forcedIncludes.includeSettings = true;
    if (has((t) => t === "key")) forcedIncludes.includeKey = true;
  }

  return { extraIncludes, forcedIncludes };
}

function git(
  args: string[],
  opts?: { allowFail?: boolean },
): { status: number; stdout: string; stderr: string } {
  const r = spawnSync("git", args, { encoding: "utf8", stdio: "pipe" });
  const status = r.status ?? 1;
  if (r.error) {
    if (opts?.allowFail) return { status, stdout: "", stderr: String(r.error) };
    throw r.error;
  }
  if (status !== 0 && !opts?.allowFail) {
    throw new Error(
      `git ${args.join(" ")} failed (exit ${status}): ${r.stderr ?? ""}`,
    );
  }
  return { status, stdout: r.stdout ?? "", stderr: r.stderr ?? "" };
}

// Checkout (or create) the dedicated deploy branch, mirroring the hub script:
// try `git checkout <branch>`, on failure create it with -b and enable
// push.autoSetupRemote so the subsequent bare `git push` targets it.
export function checkoutGitSyncDeployBranch(branch: string): void {
  const existing = git(["checkout", branch], { allowFail: true });
  if (existing.status === 0) {
    log.info(`Switched to existing branch ${branch}`);
    return;
  }
  git(["checkout", "-b", branch]);
  git(["config", "--add", "--bool", "push.autoSetupRemote", "true"]);
  log.info(`Created and switched to branch ${branch}`);
}

// Stage, commit and push the deploy, mirroring the hub script's git_push:
// stage `wmill-lock.yaml` plus each item's path tree, no-op when nothing is
// staged, and push the *current* branch with a rebase-retry fallback.
export function gitSyncDeployPush(params: {
  items: GitSyncDeployItem[];
  authorName: string;
  authorEmail: string;
  // Committer identity (git config user.*). Defaults to the author identity,
  // matching the hub script's non-GPG branch. For GPG-signed repos the hub
  // sets the committer email to the GPG key's email — the caller passes that
  // through here so the committed identity stays 1:1.
  committerName?: string;
  committerEmail?: string;
  onlyCreateBranch?: boolean;
}): { pushed: boolean } {
  const { items, authorName, authorEmail, onlyCreateBranch } = params;
  const committerName = params.committerName ?? authorName;
  const committerEmail = params.committerEmail ?? authorEmail;

  git(["config", "user.email", committerEmail]);
  git(["config", "user.name", committerName]);

  // only_create_branch: publish the (possibly empty) branch ref and stop.
  // Mirrors the hub script's early `git push --porcelain` (NOT swallowed —
  // a failure here fails the job, exactly as in the hub).
  if (onlyCreateBranch) {
    git(["push", "--porcelain"]);
    return { pushed: true };
  }

  // 1:1 with the hub script: `git add wmill-lock.yaml <path>**` as a single
  // command per item, failure swallowed (its try/catch). `commit_msg` is
  // collected once per item unconditionally — see gitSyncCommitMessage.
  for (const { path, parent_path } of items) {
    if (path) {
      git(["add", "wmill-lock.yaml", `${path}**`], { allowFail: true });
    }
    if (parent_path) {
      git(["add", "wmill-lock.yaml", `${parent_path}**`], { allowFail: true });
    }
  }

  // `git diff --cached --quiet` exits 1 iff there is something staged.
  const staged = git(["diff", "--cached", "--quiet"], { allowFail: true });
  if (staged.status === 0) {
    log.info("No changes detected, nothing to commit.");
    return { pushed: false };
  }

  const { header, description } = gitSyncCommitMessage(items);

  git([
    "commit",
    "--author",
    `${authorName} <${authorEmail}>`,
    "-m",
    header,
    "-m",
    description,
  ]);

  const push = git(["push", "--porcelain"], { allowFail: true });
  if (push.status !== 0) {
    log.info(`Push failed, rebasing and retrying: ${push.stderr}`);
    git(["pull", "--rebase"]);
    git(["push", "--porcelain"]);
  }
  return { pushed: true };
}

// Detects responses that look like an upstream auth-gateway challenge
// (Cloudflare Access SSO page, Vercel auth wall, basic-auth form, etc.) and
// surfaces a clear error instead of letting the caller treat the HTML body as
// a typed Windmill response.

const ACCESS_TITLE = /<title>\s*Sign in[^<]*Cloudflare Access\s*<\/title>/i;
const HTML_DOCTYPE = /^\s*<(!doctype|html)/i;

export class AuthGatewayChallengeError extends Error {
  override name = "AuthGatewayChallengeError";
  constructor(
    public url: string,
    public cfRay: string | undefined,
    public cfMitigated: string | undefined,
    public status: number,
    public bodySnippet: string,
  ) {
    const cfPart = [
      cfRay ? `cf-ray=${cfRay}` : null,
      cfMitigated ? `cf-mitigated=${cfMitigated}` : null,
    ]
      .filter(Boolean)
      .join(", ");
    super(
      `Got an HTML response from ${url} (status ${status}${cfPart ? `, ${cfPart}` : ""}). ` +
        `The request was intercepted by an upstream auth gateway (likely Cloudflare Access) ` +
        `before reaching Windmill. Verify the runner is on the right network or pass service-token headers via the HEADERS env var ` +
        `(e.g. HEADERS="CF-Access-Client-Id: <id>, CF-Access-Client-Secret: <secret>"). ` +
        `Body starts with: ${JSON.stringify(bodySnippet.slice(0, 120))}`,
    );
  }
}

export async function detectAuthGatewayChallenge(
  response: Response,
  url?: string,
): Promise<void> {
  const contentType = (response.headers.get("content-type") ?? "").toLowerCase();
  const cfMitigated = response.headers.get("cf-mitigated") ?? undefined;
  const looksHtml = contentType.includes("text/html");

  // Cheap check first; only peek the body when something already smells off.
  if (!looksHtml && cfMitigated !== "challenge") return;

  let snippet = "";
  try {
    snippet = (await response.clone().text()).slice(0, 256);
  } catch {
    /* body unreadable — fall through */
  }

  const isChallenge =
    cfMitigated === "challenge" ||
    ACCESS_TITLE.test(snippet) ||
    (looksHtml && HTML_DOCTYPE.test(snippet));

  if (!isChallenge) return;

  throw new AuthGatewayChallengeError(
    url || response.url || "(unknown)",
    response.headers.get("cf-ray") ?? undefined,
    cfMitigated,
    response.status,
    snippet,
  );
}

import * as wmill from "../../gen/services.gen.ts";
import * as log from "../core/log.ts";
import { colors } from "@cliffy/ansi/colors";

const DEFAULT_FAST_POLL_INTERVAL_MS = 100;
const DEFAULT_FAST_POLL_DURATION_MS = 2000;
const DEFAULT_SLOW_POLL_INTERVAL_MS = 2000;
const QUEUE_LOG_INTERVAL_MS = 5000;
const HEARTBEAT_INTERVAL_MS = 60000;
const MAX_CONSECUTIVE_POLL_ERRORS = 10;

export type JobCompletion = { result: unknown; success: boolean };

export async function logQueueStatus(
  workspace: string,
  jobId: string,
  label: string = "Job ",
): Promise<boolean> {
  try {
    const job: any = await wmill.getJob({ workspace, id: jobId });
    if (!job) return false;

    if (job.running === true) {
      log.info(
        colors.gray(`${label}${jobId}: running, waiting for completion...`),
      );
      return true;
    }

    if (typeof job.running !== "boolean") {
      return false;
    }

    const scheduledFor = job.scheduled_for as string | undefined;
    if (!scheduledFor) {
      log.info(colors.gray(`${label}${jobId}: queued, waiting for executor...`));
      return true;
    }

    const scheduledForMs = new Date(scheduledFor).getTime();
    if (!Number.isFinite(scheduledForMs)) {
      log.info(colors.gray(`${label}${jobId}: queued, waiting for executor...`));
      return true;
    }

    try {
      const pos = await wmill.getQueuePosition({
        workspace,
        scheduledFor: scheduledForMs,
      });
      const position = (pos as any)?.position;
      if (position != null) {
        log.info(
          colors.gray(
            `${label}${jobId}: queued, waiting for executor (position ${position} in queue)`,
          ),
        );
      } else {
        log.info(
          colors.gray(`${label}${jobId}: queued, waiting for executor...`),
        );
      }
      return true;
    } catch {
      log.info(colors.gray(`${label}${jobId}: queued, waiting for executor...`));
      return true;
    }
  } catch {
    return false;
  }
}

export async function pollJobWithQueueLogging(
  workspace: string,
  jobId: string,
  options?: {
    fastPollIntervalMs?: number;
    fastPollDurationMs?: number;
    slowPollIntervalMs?: number;
    label?: string;
  },
): Promise<JobCompletion> {
  const fastPollIntervalMs =
    options?.fastPollIntervalMs ?? DEFAULT_FAST_POLL_INTERVAL_MS;
  const fastPollDurationMs =
    options?.fastPollDurationMs ?? DEFAULT_FAST_POLL_DURATION_MS;
  const slowPollIntervalMs =
    options?.slowPollIntervalMs ?? DEFAULT_SLOW_POLL_INTERVAL_MS;
  const label = options?.label ? `[${options.label}] ` : "Job ";
  const startedAt = Date.now();
  let lastQueueLogAt = Date.now();
  let lastHeartbeatAt = Date.now();
  let consecutiveErrors = 0;

  while (true) {
    try {
      const maybe = await wmill.getCompletedJobResultMaybe({
        workspace,
        id: jobId,
        getStarted: false,
      });

      consecutiveErrors = 0;

      if (maybe.completed) {
        return { result: maybe.result, success: maybe.success ?? false };
      }
    } catch (err: any) {
      consecutiveErrors++;
      log.warn(
        colors.yellow(
          `${label}${jobId}: error checking job status (${consecutiveErrors}/${MAX_CONSECUTIVE_POLL_ERRORS}): ${err?.message ?? err}`,
        ),
      );
      lastHeartbeatAt = Date.now();
      if (consecutiveErrors >= MAX_CONSECUTIVE_POLL_ERRORS) {
        throw new Error(
          `Giving up polling job ${jobId} after ${MAX_CONSECUTIVE_POLL_ERRORS} consecutive errors. Last error: ${err?.message ?? err}`,
        );
      }
    }

    if (Date.now() - lastQueueLogAt >= QUEUE_LOG_INTERVAL_MS) {
      lastQueueLogAt = Date.now();
      const logged = await logQueueStatus(workspace, jobId, label);
      if (logged) lastHeartbeatAt = Date.now();
    }

    if (Date.now() - lastHeartbeatAt >= HEARTBEAT_INTERVAL_MS) {
      lastHeartbeatAt = Date.now();
      log.info(
        colors.gray(
          `${label}${jobId}: still polling, queue status unavailable...`,
        ),
      );
    }

    const delayMs =
      Date.now() - startedAt < fastPollDurationMs
        ? fastPollIntervalMs
        : slowPollIntervalMs;
    await new Promise((resolve) => setTimeout(resolve, delayMs));
  }
}

import crypto from "node:crypto";

// Helper function to convert strings to Uint8Array (binary)
function encode(input: string): Uint8Array {
  return new TextEncoder().encode(input);
}

// Helper function to convert Uint8Array (binary) to base64
function toBase64(arr: Uint8Array): string {
  return btoa(String.fromCharCode(...arr));
}

// Helper function to convert base64 to Uint8Array (binary)
function fromBase64(base64: string): Uint8Array {
  return new Uint8Array(
    atob(base64)
      .split("")
      .map((char) => char.charCodeAt(0))
  );
}

// Function to derive a 256-bit key from any input string using SHA-256
async function deriveKey(
  keyString: string
): Promise<crypto.webcrypto.CryptoKey> {
  const keyMaterial = encode(keyString);
  const keyHash = await crypto.subtle.digest("SHA-256", keyMaterial); // Generate SHA-256 hash
  // Import the hash as a CryptoKey for AES-GCM
  return crypto.subtle.importKey("raw", keyHash, { name: "AES-GCM" }, false, [
    "encrypt",
    "decrypt",
  ]);
}

// Encrypt function
export async function encrypt(
  plaintext: string,
  keyString: string
): Promise<string> {
  const key = await deriveKey(keyString); // Derive a 256-bit AES key from any input string
  const iv = crypto.getRandomValues(new Uint8Array(12)); // AES-GCM needs a 12-byte IV
  const encrypted = await crypto.subtle.encrypt(
    {
      name: "AES-GCM",
      iv,
      tagLength: 128,
    },
    key,
    encode(plaintext) // convert plaintext to binary
  );

  // Concatenate IV and encrypted data
  const combined = new Uint8Array(iv.length + encrypted.byteLength);
  combined.set(iv, 0); // first part is the IV
  combined.set(new Uint8Array(encrypted), iv.length); // second part is the ciphertext

  // Convert to base64 for storage/transmission
  return toBase64(combined);
}

// Decrypt function
export async function decrypt(
  combinedCiphertext: string,
  keyString: string
): Promise<string> {
  const key = await deriveKey(keyString); // Derive the same 256-bit AES key from the input string
  const combined = fromBase64(combinedCiphertext); // decode base64 to binary

  // Split the IV and the ciphertext
  const iv = combined.slice(0, 12); // First 12 bytes are the IV
  const ciphertext = combined.slice(12); // The rest is the encrypted data
  console.log();

  // log.info({keyString, key, ciphertext})
  // Perform decryption
  const decrypted = await crypto.subtle.decrypt(
    {
      name: "AES-GCM",
      iv,
      tagLength: 128,
    },
    key,
    ciphertext
  );

  // Convert decrypted data from binary to string
  return new TextDecoder().decode(decrypted);
}

