export function replaceLock(o?: { lock?: string | string[] }) {
  if (Array.isArray(o?.lock)) {
    o.lock = o.lock.join("\n");
  }
  if (o?.lock?.startsWith("!inline ")) {
    try {
      const lockPath = o?.lock?.split(" ")[1];
      o.lock = readInlinePathSync(lockPath);
    } catch (e) {
      log.info(
        colors.yellow(`Failed to read lockfile, doing as if it was empty: ${e}`)
      );
      o.lock = "";
    }
  }
}

export async function parseMetadataFileIfExists(
  scriptPath: string
): Promise<{ isJson: boolean; payload: any; path: string } | undefined> {
  let metadataFilePath = scriptPath + ".script.json";
  try {
    await stat(metadataFilePath);
    const payload = JSON.parse(await readTextFile(metadataFilePath));
    replaceLock(payload);
    return {
      path: metadataFilePath,
      payload,
      isJson: true,
    };
  } catch {
    try {
      metadataFilePath = scriptPath + ".script.yaml";
      await stat(metadataFilePath);
      const payload: any = await yamlParseFile(metadataFilePath);
      replaceLock(payload);

      return {
        path: metadataFilePath,
        payload,
        isJson: false,
      };
    } catch {
      return undefined;
    }
  }
}

export async function parseMetadataFile(
  scriptPath: string,
  generateMetadataIfMissing:
    | (GlobalOptions & {
      path: string;
      workspaceRemote: Workspace;
      schemaOnly?: boolean;
      rawWorkspaceDependencies: Record<string, string>;
      codebases: SyncCodebase[]
    })
    | undefined
): Promise<{ isJson: boolean; payload: any; path: string }> {
  let metadataFilePath = scriptPath + ".script.json";
  try {
    await stat(metadataFilePath);
    return {
      path: metadataFilePath,
      payload: JSON.parse(await readTextFile(metadataFilePath)),
      isJson: true,
    };
  } catch {
    try {
      metadataFilePath = scriptPath + ".script.yaml";
      await stat(metadataFilePath);
      const payload: any = await yamlParseFile(metadataFilePath);
      replaceLock(payload);

      return {
        path: metadataFilePath,
        payload,
        isJson: false,
      };
    } catch {
      // Try folder layout: {scriptPath}__mod/script.yaml or .json
      const moduleFolderMeta = scriptPath + getModuleFolderSuffix();
      try {
        metadataFilePath = moduleFolderMeta + "/script.json";
        await stat(metadataFilePath);
        return {
          path: metadataFilePath,
          payload: JSON.parse(await readTextFile(metadataFilePath)),
          isJson: true,
        };
      } catch {
        try {
          metadataFilePath = moduleFolderMeta + "/script.yaml";
          await stat(metadataFilePath);
          const payload: any = await yamlParseFile(metadataFilePath);
          replaceLock(payload);
          return {
            path: metadataFilePath,
            payload,
            isJson: false,
          };
        } catch {
          // fall through to create metadata
        }
      }
    }
  }
  // no metadata file at all. Create it
  metadataFilePath = scriptPath + ".script.yaml";
  log.info(
    (await blueColor())(
      `Creating script metadata file for ${metadataFilePath}`
    )
  );
  let scriptInitialMetadata = defaultScriptMetadata();
  const lockPath = scriptPath + ".script.lock";
  scriptInitialMetadata.lock = "!inline " + lockPath;
  const scriptInitialMetadataYaml = yamlStringify(
    scriptInitialMetadata as Record<string, any>,
    yamlOptions
  );

  await writeFile(metadataFilePath, scriptInitialMetadataYaml, { flag: "wx", encoding: "utf-8" });
  await writeFile(lockPath, "", { flag: "wx", encoding: "utf-8" });

  if (generateMetadataIfMissing) {
    log.info(
      (await blueColor())(
        `Generating lockfile and schema for ${metadataFilePath}`
      )
    );
    try {
      await generateScriptMetadataInternal(
        generateMetadataIfMissing.path,
        generateMetadataIfMissing.workspaceRemote,
        generateMetadataIfMissing,
        false,
        false,
        generateMetadataIfMissing.rawWorkspaceDependencies,
        generateMetadataIfMissing.codebases,
        false
      );
      scriptInitialMetadata = (await yamlParseFile(
        metadataFilePath
      )) as ScriptMetadata;
      if (!generateMetadataIfMissing.schemaOnly) {
        replaceLock(scriptInitialMetadata);
      }
    } catch (e) {
      log.info(
        colors.yellow(
          `Failed to generate lockfile and schema for ${metadataFilePath}: ${e}`
        )
      );
    }
  }
  return {
    path: metadataFilePath,
    payload: scriptInitialMetadata,
    isJson: false,
  };
}

export type LockVersion = "v2";

export interface Lock {
  version?: LockVersion;
  locks?: { [path: string]: string | { [subpath: string]: string } };
}

const WMILL_LOCKFILE = "wmill-lock.yaml";
const CURRENT_LOCK_VERSION: LockVersion = "v2";
// Versions this CLI knows how to read/write. An unknown value indicates the
// lockfile was written by a newer CLI; we refuse to touch it rather than
// silently fall through to a legacy code path (the bug that 1.692.0 had with
// the proposed v3 marker).
// Real v1 lockfiles never had a version field (it was added with v2). The
// "v1" string is included here only to be lenient about manual edits that
// label a v1 lockfile explicitly — the downstream isFlatKeyed check ensures
// it still goes through the legacy nested-key path.
const KNOWN_LOCK_VERSIONS: readonly string[] = ["v1", "v2"];
const SCRIPT_TOP_HASH = "__script_hash";

/**
 * Normalizes a path to use Linux separators (forward slashes) and strips a
 * leading "./" prefix. Forward slashes ensure wmill-lock.yaml is portable
 * across Windows and Linux; stripping "./" collapses entries from older CLIs
 * that joined paths against the current directory before storing.
 */
export function normalizeLockPath(p: string): string {
  let n = p.replace(/\\/g, "/");
  if (n.startsWith("./")) n = n.slice(2);
  return n;
}

// When set, `clearGlobalLock` and `updateMetadataGlobalLock` mutate this
// in-memory copy instead of doing a full read-modify-write on disk for every
// call. Callers that fan out item processing through a worker pool wrap the
// pool with `beginLockfileBatch()`/`flushLockfileBatch()` so the lockfile is
// only written once at the end — see `generate-metadata` parallelism.
let inMemoryLock: Lock | null = null;

export async function beginLockfileBatch(): Promise<void> {
  if (inMemoryLock) return;
  inMemoryLock = await readLockfile();
}

export async function flushLockfileBatch(): Promise<void> {
  if (!inMemoryLock) return;
  // Write first, then clear: if the disk write throws (e.g. ENOSPC), the
  // buffered updates remain in memory and a retry can re-attempt the flush.
  await writeFile(
    WMILL_LOCKFILE,
    yamlStringify(inMemoryLock as Record<string, any>, yamlOptions),
    "utf-8",
  );
  inMemoryLock = null;
}

export async function readLockfile(): Promise<Lock> {
  if (inMemoryLock) return inMemoryLock;
  let parsed: unknown;
  try {
    parsed = await yamlParseFile(WMILL_LOCKFILE);
  } catch {
    const lock: Lock = { locks: {}, version: CURRENT_LOCK_VERSION };
    await writeFile(WMILL_LOCKFILE, yamlStringify(lock, yamlOptions), "utf-8");
    log.info(colors.green("wmill-lock.yaml created"));
    return lock;
  }
  if (typeof parsed != "object" || parsed == null) {
    throw new MalformedLockfileError(
      "wmill-lock.yaml is malformed (expected an object). " +
      "Refusing to operate to avoid corrupting the lockfile.",
    );
  }
  const conf = parsed as Lock;
  if (conf.version != null && !KNOWN_LOCK_VERSIONS.includes(conf.version)) {
    throw new UnknownLockVersionError(
      `wmill-lock.yaml is at unknown version "${conf.version}". This was ` +
      `written by a newer wmill CLI; please upgrade with \`wmill upgrade\`. ` +
      `Refusing to operate to avoid corrupting the lockfile.`,
    );
  }
  return conf;
}

function v2LockPath(path: string, subpath?: string) {
  const normalizedPath = normalizeLockPath(path);
  if (subpath) {
    return `${normalizedPath}+${normalizeLockPath(subpath)}`;
  } else {
    return normalizedPath;
  }
}
export async function checkifMetadataUptodate(
  path: string,
  hash: string,
  conf: Lock | undefined,
  subpath?: string
) {
  if (!conf) {
    conf = await readLockfile();
  }
  if (!conf.locks) {
    return false;
  }
  const isFlatKeyed = conf?.version === "v2";

  // Older CLIs sometimes wrote entries with a leading "./" prefix; some
  // lockfiles even contain both forms with different stale values. Accept
  // either form so duplicate-key drift doesn't cause false positives.
  if (isFlatKeyed) {
    const key = v2LockPath(path, subpath);
    return conf.locks?.[key] === hash || conf.locks?.["./" + key] === hash;
  }
  for (const p of [path, "./" + path]) {
    const obj = conf.locks?.[p];
    const v = subpath && typeof obj == "object" ? obj?.[subpath] : obj;
    if (v === hash) return true;
  }
  return false;
}

export async function generateScriptHash(
  rawWorkspaceDependencies: Record<string, string>,
  scriptContent: string,
  newMetadataContent: string
) {
  return await generateHash(
    JSON.stringify(rawWorkspaceDependencies) + scriptContent + newMetadataContent
  );
}

async function computeModuleHashes(
  moduleFolderPath: string,
  defaultTs: "bun" | "deno" | undefined,
  rawWorkspaceDependencies: Record<string, string>,
  isFolderLayout: boolean,
  // A dbt project's files are taken verbatim, so hash them the same way the
  // push reads them: a `.sql` model has no inferable language, and dropping it
  // here would leave an edited model looking up to date.
  verbatim: boolean = false,
): Promise<Record<string, string>> {
  const hashes: Record<string, string> = {};
  const skipDirs = verbatim
    ? dbtGeneratedDirs(moduleFolderPath)
    : new Set<string>();

  async function readDir(dirPath: string, relPrefix: string) {
    const entries = readdirSync(dirPath, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dirPath, entry.name);
      const relPath = relPrefix ? relPrefix + "/" + entry.name : entry.name;
      const isTopLevel = relPrefix === "";

      if (entry.isDirectory()) {
        // A configured `target-path` may be nested (`build/target`), so the
        // comparison is on the project-relative path, not the entry name.
        if (skipDirs.size > 0 && isUnderGeneratedDir(relPath, skipDirs)) continue;
        await readDir(fullPath, relPath);
        // See the bundle builder: a verbatim (dbt) bundle carries a `.lock` the
        // project authored, so the hash has to see it or a change to it would
        // never be detected as a change.
      } else if (
        entry.isFile() &&
        (verbatim || !entry.name.endsWith(".lock")) &&
        !(isFolderLayout && isTopLevel && entry.name.startsWith("script.")) &&
        // The descriptor is the script's CONTENT, hashed as such: counting it
        // here too would make one edit look like two changes.
        !(verbatim && isTopLevel && entry.name === DBT_DESCRIPTOR_NAME)
      ) {
        if (!verbatim) {
          try {
            inferContentTypeFromFilePath(entry.name, defaultTs);
          } catch {
            continue;
          }
        } else if (!isBundledModuleFile(fullPath)) {
          // Hash only what the push actually sends. Hashing a file the bundle
          // drops would make the script permanently stale: every check would
          // see a change no push can ever resolve.
          continue;
        }
        const content = readTextFileSync(fullPath);
        const normalizedPath = normalizeLockPath(relPath);
        hashes[normalizedPath] = await generateHash(
          content + JSON.stringify(rawWorkspaceDependencies)
        );
      }
    }
  }

  await readDir(moduleFolderPath, "");
  return hashes;
}

export async function clearGlobalLock(path: string): Promise<void> {
  const conf = await readLockfile();
  if (!conf?.locks) {
    conf.locks = {};
  }
  const isFlatKeyed = conf?.version === "v2";

  if (isFlatKeyed) {
    // Remove the specific flat-keyed lock entry. Match both the canonical
    // form and the legacy "./"-prefixed form so duplicate entries left over
    // from older CLIs get cleaned up alongside the canonical write.
    // Match exactly `key` or `key+<subpath>` (and the same for the legacy
    // "./"-prefixed form). The "+" separator boundary is critical: a plain
    // startsWith("f/foo") would also match "f/foobar+..." entries belonging
    // to a sibling script.
    const key = v2LockPath(path);
    const legacyKey = "./" + key;
    if (conf.locks) {
      Object.keys(conf.locks).forEach((k) => {
        if (!conf.locks) return;
        if (
          k === key || k.startsWith(key + "+") ||
          k === legacyKey || k.startsWith(legacyKey + "+")
        ) {
          delete conf.locks[k];
        }
      });
    }
    if (!inMemoryLock) {
      await writeFile(
        WMILL_LOCKFILE,
        yamlStringify(conf as Record<string, any>, yamlOptions),
        "utf-8"
      );
    }
  }
}

export async function updateMetadataGlobalLock(
  path: string,
  hash: string,
  subpath?: string
): Promise<void> {
  const conf = await readLockfile();
  if (!conf?.locks) {
    conf.locks = {};
  }
  const isFlatKeyed = conf?.version === "v2";

  if (isFlatKeyed) {
    conf.locks[v2LockPath(path, subpath)] = hash;
  } else {
    if (subpath) {
      let prev: any = conf.locks[path];
      if (!prev || typeof prev != "object") {
        prev = {};
        conf.locks[path] = prev;
      }
      prev[subpath] = hash;
    } else {
      conf.locks[path] = hash;
    }
  }
  if (!inMemoryLock) {
    await writeFile(
      WMILL_LOCKFILE,
      yamlStringify(conf as Record<string, any>, yamlOptions),
      "utf-8"
    );
  }
}

/**
 * Port collision detection + fallback for `wmill dev` and `wmill app dev`.
 *
 * Why this exists: Node's default listen() has platform-dependent dual-stack
 * behaviour. If the requested IPv4 binding (0.0.0.0:N) is already taken by
 * another process, Node may silently fall back to IPv6-only ([::1]:N). The OS
 * then routes new `localhost` connections to the older IPv4 listener, so the
 * user opens http://localhost:N and sees the wrong server with no signal that
 * anything is wrong. Bit us in practice: a leftover `wmill dev --proxy-port 4000`
 * served traffic for a freshly-started `wmill app dev --port 4000`.
 *
 * The fix: probe both stacks before binding. Treat the port as taken if either
 * 0.0.0.0 or :: refuses the bind. On collision, walk upward to the next free
 * port and log the shift prominently.
 */

import { createServer } from "node:net";
import { execSync } from "node:child_process";

type Host = "0.0.0.0" | "::";

/**
 * Try to bind a fresh server to (port, host) and immediately close it.
 *
 * Returns false ONLY when the port is genuinely held by another process
 * (EADDRINUSE) or denied by permissions (EACCES). Other errors — most
 * importantly EAFNOSUPPORT / EADDRNOTAVAIL on the IPv6 probe when the host
 * has no IPv6 stack at all — return true: the stack we're probing simply
 * isn't reachable, which is functionally indistinguishable from "free" for
 * the dual-stack collision check.
 */
function isPortFree(port: number, host: Host): Promise<boolean> {
  return new Promise((resolve) => {
    const s = createServer();
    s.once("error", (err: NodeJS.ErrnoException) => {
      const code = err.code ?? "";
      // Anything that means "another process is holding this port" → not free.
      // Anything else (no IPv6 stack on this host, etc.) → treat as free so we
      // don't false-alarm on IPv4-only containers.
      resolve(code !== "EADDRINUSE" && code !== "EACCES");
    });
    s.once("listening", () => s.close(() => resolve(true)));
    s.listen(port, host);
  });
}

/**
 * A port counts as free only if BOTH IPv4 and IPv6 stacks accept the bind.
 * If either is held by another process, the OS may route `localhost` traffic
 * to that other process even when our listener succeeds on the free stack.
 *
 * Probes sequentially, not in parallel: on Linux the default is
 * `net.ipv6.bindv6only=0`, which makes a `bind(::, port)` socket also occupy
 * the IPv4 stack on the same port. Running both probes concurrently then
 * causes one to lose the race with EADDRINUSE on a port that is actually
 * free, producing false negatives. Sequential keeps each probe's bind fully
 * released before the next starts.
 */
async function isPortFreeOnBothStacks(port: number): Promise<boolean> {
  if (!(await isPortFree(port, "0.0.0.0"))) return false;
  if (!(await isPortFree(port, "::"))) return false;
  return true;
}

/**
 * Best-effort lookup of the PID + command currently bound to <port>. Returns
 * undefined if nothing is found, the lookup fails, or the platform tooling
 * isn't installed. Never throws.
 */
function findPortHolder(port: number): { pid: number; command: string } | undefined {
  // macOS + Linux: lsof. -nP avoids DNS / port-name lookups, -sTCP:LISTEN
  // narrows to the listening socket.
  try {
    const out = execSync(`lsof -nP -iTCP:${port} -sTCP:LISTEN -F pc 2>/dev/null`, {
      encoding: "utf-8",
      stdio: ["ignore", "pipe", "ignore"],
    });
    // -F pc emits records like:
    //   p91418
    //   cbun
    let pid: number | undefined;
    let cmd: string | undefined;
    for (const line of out.split("\n")) {
      if (line.startsWith("p")) pid = parseInt(line.slice(1), 10);
      else if (line.startsWith("c")) cmd = line.slice(1);
      if (pid && cmd) return { pid, command: cmd };
    }
  } catch {
    // lsof missing or no holder — fall through.
  }

  // Linux fallback: ss. -ltnp lists listening TCP sockets with PID/command.
  try {
    const out = execSync(`ss -ltnp 2>/dev/null | awk '$4 ~ /:${port}$/ { print $NF }'`, {
      encoding: "utf-8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
    // Format: users:(("bun",pid=91418,fd=23))
    const m = out.match(/\("([^"]+)",pid=(\d+)/);
    if (m) return { pid: parseInt(m[2], 10), command: m[1] };
  } catch {
    /* fall through */
  }

  return undefined;
}

/**
 * Resolve the port we should actually bind to.
 *
 * Walks upward from `requested` until a port is free on both stacks, capped
 * at +20 to avoid silently scanning the whole 4xxx range. On shift, logs a
 * prominent warning naming the holder if we can find it.
 *
 * Returns the chosen port (== requested when it was already free).
 */
export async function resolveBindPort(
  requested: number,
  flagLabel: string,
  log: { info: (msg: string) => void; warn: (msg: string) => void },
): Promise<number> {
  const MAX_SHIFT = 20;
  for (let port = requested; port < requested + MAX_SHIFT; port++) {
    if (await isPortFreeOnBothStacks(port)) {
      if (port !== requested) {
        const holder = findPortHolder(requested);
        const holderHint = holder
          ? ` (held by PID ${holder.pid} \`${holder.command}\`)`
          : "";
        log.warn(
          `Port ${requested} is already in use${holderHint}. Using port ${port} instead.`,
        );
        log.info(
          `If you need port ${requested} stable (e.g. a launch.json entry pinned to it), stop the holder and re-run with ${flagLabel} ${requested}.`,
        );
      }
      return port;
    }
  }
  throw new Error(
    `Could not find a free port in the range ${requested}-${requested + MAX_SHIFT - 1}. Stop a holder or pass ${flagLabel} <other>.`,
  );
}

/**
 * The host string we bind to. Explicit IPv4 — `localhost` resolves to
 * 127.0.0.1 first on every platform we care about, and binding both stacks
 * relies on platform-specific IPV6_V6ONLY behaviour we don't want to debug.
 */
export const BIND_HOST = "0.0.0.0" as const;

/**
 * Relative Imports Utilities for CLI
 *
 * Provides functions to parse relative imports from TypeScript/Python scripts using WASM.
 */

import { ScriptLanguage } from "./script_common.ts";
import { loadParser } from "./metadata.ts";
import * as log from "../core/log.ts";

/**
 * Extract relative imports from script content based on language.
 * Returns resolved absolute Windmill paths (e.g., "f/folder/helper").
 */
export async function extractRelativeImports(
  code: string,
  scriptPath: string,
  language: ScriptLanguage
): Promise<string[]> {
  try {
    switch (language) {
      case "bun":
      case "nativets":
      case "deno": {
        const { parse_ts_relative_imports } = await loadParser("windmill-parser-wasm-ts");
        return parse_ts_relative_imports(code, scriptPath);
      }
      case "python3": {
        const { parse_py_relative_imports } = await loadParser("windmill-parser-wasm-py-imports");
        return parse_py_relative_imports(code, scriptPath);
      }
      default:
        return [];
    }
  } catch (e) {
    log.warn(`Failed to parse relative imports for ${scriptPath}: ${e}. Dependency tracking for relative imports will be disabled.`);
    return [];
  }
}

/**
 * Utility module for handling resource folder naming conventions.
 *
 * This module centralizes the logic for detecting and manipulating paths
 * that contain resource folders (.flow, .app, .raw_app).
 *
 * The folder suffixes can be configured to use either dot-prefixed names
 * (.flow, .app, .raw_app) or dunder-prefixed names (__flow, __app, __raw_app).
 */

import { existsSync } from "node:fs";
import * as log from "../core/log.ts";
import { sep as SEP } from "node:path";
import { yamlParseFile } from "./yaml.ts";
import * as fs from "node:fs";
import * as path from "node:path";
import process from "node:process";

// Resource types that use folder-based storage
export type FolderResourceType = "flow" | "app" | "raw_app";

// Configuration for folder suffixes - can be switched between dot and dunder prefixes
// The default uses dot-prefixed names (.flow, .app, .raw_app)
const DOTTED_SUFFIXES = {
  flow: ".flow",
  app: ".app",
  raw_app: ".raw_app",
} as const;

// Alternative dunder-prefixed names (__flow, __app, __raw_app)
const NON_DOTTED_SUFFIXES = {
  flow: "__flow",
  app: "__app",
  raw_app: "__raw_app",
} as const;

export type FolderSuffixes =
  | typeof DOTTED_SUFFIXES
  | typeof NON_DOTTED_SUFFIXES;

// Global state for nonDottedPaths configuration
let _nonDottedPaths = false;
let _nonDottedPathsLogged = false;

/**
 * Set whether to use non-dotted paths (__flow, __app, __raw_app)
 * instead of dotted paths (.flow, .app, .raw_app).
 * This should be called once at startup based on wmill.yaml configuration.
 */
export function setNonDottedPaths(value: boolean): void {
  if (value && !_nonDottedPathsLogged) {
    log.debug("Using non-dotted paths (__flow, __app, __raw_app)");
    _nonDottedPathsLogged = true;
  }
  _nonDottedPaths = value;
}

/**
 * Get the current nonDottedPaths setting.
 */
export function getNonDottedPaths(): boolean {
  return _nonDottedPaths;
}

/**
 * Search for wmill.yaml by traversing upward from the current directory
 * and initialize the nonDottedPaths setting.
 * Unlike findWmillYaml() in conf.ts, this does not stop at the git root -
 * it continues searching until the filesystem root.
 * This is needed for commands like `app dev` and `app new` which may run
 * from inside folders that are deeply nested within a larger git repository.
 */
export async function loadNonDottedPathsSetting(): Promise<void> {
  let currentDir = process.cwd();

  while (true) {
    const wmillYamlPath = path.join(currentDir, "wmill.yaml");

    if (fs.existsSync(wmillYamlPath)) {
      try {
        const config = (await yamlParseFile(wmillYamlPath)) as {
          nonDottedPaths?: boolean;
        };
        setNonDottedPaths(config?.nonDottedPaths ?? false);
        log.debug(
          `Found wmill.yaml at ${wmillYamlPath}, nonDottedPaths=${
            config?.nonDottedPaths ?? false
          }`
        );
      } catch (e) {
        log.debug(`Failed to parse wmill.yaml at ${wmillYamlPath}: ${e}`);
      }
      return;
    }

    // Check if we've reached the filesystem root
    const parentDir = path.dirname(currentDir);
    if (parentDir === currentDir) {
      // Reached filesystem root without finding wmill.yaml
      log.debug("No wmill.yaml found, using default dotted paths");
      return;
    }

    currentDir = parentDir;
  }
}

/**
 * Get the folder suffixes based on the global configuration.
 */
export function getFolderSuffixes(): FolderSuffixes {
  return _nonDottedPaths ? NON_DOTTED_SUFFIXES : DOTTED_SUFFIXES;
}

// Metadata file names inside each folder type
const METADATA_FILES = {
  flow: { yaml: "flow.yaml", json: "flow.json" },
  app: { yaml: "app.yaml", json: "app.json" },
  raw_app: { yaml: "raw_app.yaml", json: "raw_app.json" },
} as const;

/**
 * Get the folder suffix for a resource type (e.g., ".flow", ".app", ".raw_app" or "__flow", "__app", "__raw_app")
 */
export function getFolderSuffix(type: FolderResourceType): string {
  return getFolderSuffixes()[type];
}

/**
 * Get the folder suffix with path separator (e.g., ".flow/", ".app/", ".raw_app/")
 */
export function getFolderSuffixWithSep(type: FolderResourceType): string {
  return getFolderSuffixes()[type] + SEP;
}

/**
 * Get the metadata file name for a resource type
 */
export function getMetadataFileName(
  type: FolderResourceType,
  format: "yaml" | "json"
): string {
  return METADATA_FILES[type][format];
}

/**
 * Get the full metadata file path suffix (e.g., ".flow/flow.yaml" or "__flow/flow.yaml")
 */
export function getMetadataPathSuffix(
  type: FolderResourceType,
  format: "yaml" | "json"
): string {
  return getFolderSuffixes()[type] + "/" + METADATA_FILES[type][format];
}

// ============================================================================
// Path Detection Functions
// ============================================================================

/**
 * Check if a directory name uses the *wrong* folder suffix format for the
 * current nonDottedPaths setting. Returns the resource type if mismatched,
 * null if the name is fine (or not a resource folder at all).
 *
 * - nonDottedPaths=false (dotted mode): flags __flow, __app, __raw_app
 * - nonDottedPaths=true  (non-dotted):  flags .flow, .app, .raw_app
 */
export function hasWrongFormatSuffix(dirName: string): FolderResourceType | null {
  const wrongSuffixes = _nonDottedPaths ? DOTTED_SUFFIXES : NON_DOTTED_SUFFIXES;
  for (const [type, suffix] of Object.entries(wrongSuffixes)) {
    if (dirName.endsWith(suffix)) {
      return type as FolderResourceType;
    }
  }
  return null;
}

/** Normalize path separators to forward slash for cross-platform matching */
function normalizeSep(p: string): string {
  return p.replaceAll("\\", "/");
}

/**
 * Check if a path is inside a flow folder
 */
export function isFlowPath(p: string): boolean {
  return normalizeSep(p).includes(getFolderSuffixes().flow + "/");
}

/**
 * Check if a path is inside an app folder
 */
export function isAppPath(p: string): boolean {
  return normalizeSep(p).includes(getFolderSuffixes().app + "/");
}

/**
 * Check if a path is inside a raw_app folder
 */
export function isRawAppPath(p: string): boolean {
  return normalizeSep(p).includes(getFolderSuffixes().raw_app + "/");
}

/**
 * Check if a path is inside any folder-based resource (flow, app, or raw_app)
 */
export function isFolderResourcePath(p: string): boolean {
  return isFlowPath(p) || isAppPath(p) || isRawAppPath(p);
}

/**
 * Check if a path is inside a folder-based resource, checking BOTH dotted (.flow, .app, .raw_app)
 * and non-dotted (__flow, __app, __raw_app) formats regardless of the global nonDottedPaths setting.
 * Use this instead of isFolderResourcePath when the config may not yet be loaded or when
 * you need to handle mixed-format workspaces (e.g. generate-metadata scanning all files).
 */
export function isFolderResourcePathAnyFormat(p: string): boolean {
  const n = normalizeSep(p);
  for (const suffixes of [DOTTED_SUFFIXES, NON_DOTTED_SUFFIXES]) {
    if (
      n.includes(suffixes.flow + "/") ||
      n.includes(suffixes.app + "/") ||
      n.includes(suffixes.raw_app + "/")
    ) {
      return true;
    }
  }
  return false;
}

/**
 * Detect the resource type from a path, if any
 */
export function detectFolderResourceType(p: string): FolderResourceType | null {
  if (isFlowPath(p)) return "flow";
  if (isAppPath(p)) return "app";
  if (isRawAppPath(p)) return "raw_app";
  return null;
}

/**
 * Check if a path is inside a raw app backend folder.
 * Matches patterns like: .../myApp.raw_app/backend/... or .../myApp__raw_app/backend/...
 */
export function isRawAppBackendPath(filePath: string): boolean {
  const suffixes = getFolderSuffixes();
  // Normalize path separators for consistent matching
  const normalizedPath = filePath.replaceAll(SEP, "/");
  // Check if path contains pattern: *.[suffix]/backend/
  const escapedSuffix = suffixes.raw_app.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pattern = new RegExp(`${escapedSuffix}/backend/`);
  return pattern.test(normalizedPath);
}

/**
 * Check if a path is inside a normal app folder (inline script).
 * Matches patterns like: .../myApp.app/... or .../myApp__app/...
 * This is used to detect inline scripts that belong to normal apps.
 */
export function isAppInlineScriptPath(filePath: string): boolean {
  const suffixes = getFolderSuffixes();
  // Normalize path separators for consistent matching
  const normalizedPath = filePath.replaceAll(SEP, "/");
  // Check if path contains pattern: *.[suffix]/
  const escapedSuffix = suffixes.app.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pattern = new RegExp(`${escapedSuffix}/`);
  return pattern.test(normalizedPath);
}

/**
 * Check if a path is inside a flow folder (inline script).
 * Matches patterns like: .../myFlow.flow/... or .../myFlow__flow/...
 * This is used to detect inline scripts that belong to flows.
 */
export function isFlowInlineScriptPath(filePath: string): boolean {
  const suffixes = getFolderSuffixes();
  // Normalize path separators for consistent matching
  const normalizedPath = filePath.replaceAll(SEP, "/");
  // Check if path contains pattern: *.[suffix]/
  const escapedSuffix = suffixes.flow.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pattern = new RegExp(`${escapedSuffix}/`);
  return pattern.test(normalizedPath);
}

// ============================================================================
// Path Manipulation Functions
// ============================================================================

/**
 * Extract the resource name from a path (the part before the folder suffix)
 * e.g., "f/my_flow.flow/flow.yaml" -> "f/my_flow"
 */
export function extractResourceName(
  p: string,
  type: FolderResourceType
): string | null {
  const normalized = normalizeSep(p);
  const suffix = getFolderSuffixes()[type] + "/";
  const index = normalized.indexOf(suffix);
  if (index === -1) return null;
  return normalized.substring(0, index);
}

/**
 * Extract the folder path (resource name + folder suffix)
 * e.g., "f/my_flow.flow/flow.yaml" -> "f/my_flow.flow/"
 */
export function extractFolderPath(
  p: string,
  type: FolderResourceType
): string | null {
  const normalized = normalizeSep(p);
  const suffix = getFolderSuffixes()[type] + "/";
  const index = normalized.indexOf(suffix);
  if (index === -1) return null;
  return normalized.substring(0, index) + suffix;
}

/**
 * Build a folder path from a resource name
 * e.g., ("f/my_flow", "flow") -> "f/my_flow.flow"
 */
export function buildFolderPath(
  resourceName: string,
  type: FolderResourceType
): string {
  return resourceName + getFolderSuffixes()[type];
}

/**
 * Build a metadata file path from a resource name
 * e.g., ("f/my_flow", "flow", "yaml") -> "f/my_flow.flow/flow.yaml"
 */
export function buildMetadataPath(
  resourceName: string,
  type: FolderResourceType,
  format: "yaml" | "json"
): string {
  return (
    resourceName +
    getFolderSuffixes()[type] +
    "/" +
    METADATA_FILES[type][format]
  );
}

// ============================================================================
// Folder Validation Functions
// ============================================================================

/**
 * Check if a directory name ends with a specific resource folder suffix
 * e.g., "my_app.raw_app" ends with ".raw_app" or "my_app__raw_app" ends with "__raw_app"
 */
export function hasFolderSuffix(
  dirName: string,
  type: FolderResourceType
): boolean {
  return dirName.endsWith(getFolderSuffixes()[type]);
}

/**
 * Validate that a directory name has the expected folder suffix
 * Returns an error message if invalid, null if valid
 */
export function validateFolderName(
  dirName: string,
  type: FolderResourceType
): string | null {
  const suffixes = getFolderSuffixes();
  if (!hasFolderSuffix(dirName, type)) {
    return `'${dirName}' does not end with '${suffixes[type]}'`;
  }
  return null;
}

/**
 * Extract the resource name from a folder name by removing the suffix
 * e.g., "my_app.raw_app" -> "my_app" or "my_app__raw_app" -> "my_app"
 */
export function extractNameFromFolder(
  folderName: string,
  type: FolderResourceType
): string {
  const suffix = getFolderSuffixes()[type];
  if (folderName.endsWith(suffix)) {
    return folderName.substring(0, folderName.length - suffix.length);
  }
  return folderName;
}

// ============================================================================
// Metadata File Detection Functions
// ============================================================================

/**
 * Check if a path ends with a flow metadata file suffix.
 * Detects BOTH API format (always dotted: .flow.json) and local format (user-configured).
 * This is necessary because the API always returns dotted format, but local files
 * may use non-dotted format if nonDottedPaths is configured.
 */
export function isFlowMetadataFile(p: string): boolean {
  // Always check API format (dotted)
  if (
    p.endsWith(DOTTED_SUFFIXES.flow + ".json") ||
    p.endsWith(DOTTED_SUFFIXES.flow + ".yaml")
  ) {
    return true;
  }
  // Also check non-dotted format for local files
  if (_nonDottedPaths) {
    return (
      p.endsWith(NON_DOTTED_SUFFIXES.flow + ".json") ||
      p.endsWith(NON_DOTTED_SUFFIXES.flow + ".yaml")
    );
  }
  return false;
}

/**
 * Check if a path ends with an app metadata file suffix.
 * Detects BOTH API format (always dotted: .app.json) and local format (user-configured).
 */
export function isAppMetadataFile(p: string): boolean {
  // Always check API format (dotted)
  if (
    p.endsWith(DOTTED_SUFFIXES.app + ".json") ||
    p.endsWith(DOTTED_SUFFIXES.app + ".yaml")
  ) {
    return true;
  }
  // Also check non-dotted format for local files
  if (_nonDottedPaths) {
    return (
      p.endsWith(NON_DOTTED_SUFFIXES.app + ".json") ||
      p.endsWith(NON_DOTTED_SUFFIXES.app + ".yaml")
    );
  }
  return false;
}

/**
 * Check if a path ends with a raw_app metadata file suffix.
 * Detects BOTH API format (always dotted: .raw_app.json) and local format (user-configured).
 */
export function isRawAppMetadataFile(p: string): boolean {
  // Always check API format (dotted)
  if (
    p.endsWith(DOTTED_SUFFIXES.raw_app + ".json") ||
    p.endsWith(DOTTED_SUFFIXES.raw_app + ".yaml")
  ) {
    return true;
  }
  // Also check non-dotted format for local files
  if (_nonDottedPaths) {
    return (
      p.endsWith(NON_DOTTED_SUFFIXES.raw_app + ".json") ||
      p.endsWith(NON_DOTTED_SUFFIXES.raw_app + ".yaml")
    );
  }
  return false;
}

/**
 * Check if a path ends with a specific raw_app metadata file
 * (inside the folder, e.g., ".raw_app/raw_app.yaml" or "__raw_app/raw_app.yaml")
 */
export function isRawAppFolderMetadataFile(p: string): boolean {
  return (
    p.endsWith(getMetadataPathSuffix("raw_app", "yaml")) ||
    p.endsWith(getMetadataPathSuffix("raw_app", "json"))
  );
}

/**
 * Check if a path ends with a specific app metadata file
 * (inside the folder, e.g., ".app/app.yaml" or "__app/app.yaml")
 */
export function isAppFolderMetadataFile(p: string): boolean {
  return (
    p.endsWith(getMetadataPathSuffix("app", "yaml")) ||
    p.endsWith(getMetadataPathSuffix("app", "json"))
  );
}

/**
 * Check if a path ends with a specific flow metadata file
 * (inside the folder, e.g., ".flow/flow.yaml" or "__flow/flow.yaml")
 */
export function isFlowFolderMetadataFile(p: string): boolean {
  return (
    p.endsWith(getMetadataPathSuffix("flow", "yaml")) ||
    p.endsWith(getMetadataPathSuffix("flow", "json"))
  );
}

// ============================================================================
// Script Module Path Functions
// ============================================================================

/**
 * The suffix used for script module folders.
 * Unlike flows/apps, modules always use `__mod` (never dotted `.mod`)
 * to avoid confusion with file extensions.
 */
const MODULE_SUFFIX = "__mod";
/** dbt scripts carry a whole dbt project, not helper code. The folder says so,
 *  and it is what a dbt developer points `--project-dir` at. */
export const DBT_MODULE_SUFFIX = "__dbt";
const MODULE_SUFFIXES = [MODULE_SUFFIX, DBT_MODULE_SUFFIX];

/** A dbt project's descriptor, inside the project it configures and OPTIONAL:
 *  an unmodified dbt project is already a complete Windmill script, and this
 *  file only appears when one needs something Windmill-specific (run arguments,
 *  a named warehouse, an engine pin). Its absence is an empty descriptor, never
 *  a missing script. */
export const DBT_DESCRIPTOR_NAME = "wm_dbt.yaml";

/** Where a dbt script's descriptor lives, given its base path. */
export function dbtDescriptorPath(scriptBasePath: string): string {
  return scriptBasePath + DBT_MODULE_SUFFIX + "/" + DBT_DESCRIPTOR_NAME;
}

/** Whether an error is a dbt descriptor that simply is not there. */
export function isMissingDbtDescriptor(filePath: string, e: unknown): boolean {
  if ((e as { code?: string })?.code !== "ENOENT") return false;
  const norm = filePath.replaceAll("\\", "/");
  if (!isDbtDescriptorPath(norm)) return false;
  // And the PROJECT is there. Absent both, this is not a descriptor-less
  // project but a path that does not exist — a typo, or a project someone
  // deleted — and treating it as an empty descriptor pushes `modules:
  // undefined` over a deployed bundle, dropping it while reporting success.
  return existsSync(
    norm.slice(0, -DBT_DESCRIPTOR_NAME.length) + "dbt_project.yml"
  );
}

/** Whether a path is a dbt descriptor, i.e. a dbt script's content file. */
export function isDbtDescriptorPath(p: string): boolean {
  const norm = normalizeSep(p);
  const base = getScriptBasePathFromModulePath(norm);
  return base !== undefined && norm === dbtDescriptorPath(base);
}

/**
 * Module folder suffix for a script: `__dbt` for a dbt project, `__mod`
 * otherwise.
 */
export function getModuleFolderSuffix(language?: string): string {
  return language === "dbt" ? DBT_MODULE_SUFFIX : MODULE_SUFFIX;
}

/**
 * Check if a path is inside a script module folder.
 * Matches patterns like: .../my_script__mod/... or .../my_project__dbt/...
 */
export function isScriptModulePath(p: string): boolean {
  const n = normalizeSep(p);
  return MODULE_SUFFIXES.some((suffix) => n.includes(suffix + "/"));
}

/** Per-file ceiling for a dbt project's bundle. Real dbt code is small (about
 *  500 bytes median, 1.9 KB at p90 measured across dbt_utils), so this only
 *  ever catches a committed dataset, which belongs in the warehouse rather than
 *  in every version of the script. */
export const MAX_MODULE_BYTES = 5 * 1024 * 1024;

/**
 * Whether a dbt project file is one the bundle carries.
 *
 * A dbt project's authored files are text. A binary one -- an image under
 * `docs/`, a `.DS_Store`, a parquet seed -- would be read as mojibake and, if
 * it carries a NUL, rejected by Postgres with an opaque `unsupported Unicode
 * escape sequence`. Binary is detected the way `git` does it, by a NUL in the
 * first 8000 bytes, rather than by extension, which `docs/` and stray dotfiles
 * do not follow.
 *
 * The push, the staleness hash and the sync diff all ask this same question: a
 * file one drops and another keeps is a change no push can ever resolve.
 */
export function isBundledModuleFile(fullPath: string): boolean {
  return moduleFileExclusion(fullPath) === undefined;
}

/**
 * WHY the bundle does not carry a file, when it does not.
 *
 * The two reasons are not interchangeable. `binary` is dbt's own leftovers and
 * stray archives: nothing to say, so sync hides them. `oversized` is a file the
 * project authored and dbt WOULD read — a large seed CSV — so it has to stay
 * visible in the diff, or the push that reports the actionable size error never
 * runs and the remote project is silently left incomplete.
 */
export function moduleFileExclusion(
  fullPath: string,
): "binary" | "oversized" | undefined {
  // Size from `stat` and only the first 8 KB read: a project may sit next to a
  // multi-gigabyte parquet seed or a stray archive, and reading one whole just
  // to classify it would stall the sync or exhaust the CLI.
  let size: number;
  let fd: number;
  try {
    size = fs.statSync(fullPath).size;
    fd = fs.openSync(fullPath, "r");
  } catch {
    // Unreadable is not the same as excluded. A pull asks this about files that
    // do not exist locally yet, and answering "not carried" there would make
    // sync ignore the whole incoming project and write nothing.
    return undefined;
  }
  let binary: boolean;
  try {
    const head = Buffer.alloc(8000);
    const read = fs.readSync(fd, head, 0, 8000, 0);
    binary = head.subarray(0, read).includes(0);
  } catch {
    return undefined;
  } finally {
    fs.closeSync(fd);
  }
  if (binary) return "binary";
  return size > MAX_MODULE_BYTES ? "oversized" : undefined;
}

/**
 * The refusal an oversized dbt project file earns, raised WITHOUT reading it.
 *
 * dbt would have read the file, so deploying the project without it ships
 * something that compiles here and fails at run time with a missing relation —
 * hence an error rather than a skip. Every path that would otherwise load the
 * body (the sync map, the push) asks first: a multi-gigabyte seed must not be
 * buffered just to be refused.
 */
export function oversizedModuleFileError(relPath: string, size: number): Error {
  return new Error(
    `${relPath} is ${Math.ceil(size / 1024 / 1024)} MB, over the ` +
      `${MAX_MODULE_BYTES / 1024 / 1024} MB per-file limit for a dbt project file. ` +
      `Deploying without it would leave the project incomplete — shrink the file, or ` +
      `keep it out of the project folder.`,
  );
}

/**
 * Refuse an oversized dbt project file before its content is read. `undefined`
 * for everything else, including binary files the bundle merely drops.
 */
export function oversizedDbtFileError(
  fullPath: string,
  relPath: string,
): Error | undefined {
  if (!isDbtModulePath(relPath)) return undefined;
  if (moduleFileExclusion(fullPath) !== "oversized") return undefined;
  let size = 0;
  try {
    size = fs.statSync(fullPath).size;
  } catch {
    return undefined;
  }
  return oversizedModuleFileError(relPath, size);
}

/** Whether a path is inside a dbt project's module folder specifically: those
 *  files are taken verbatim, with no language inference. */
export function isDbtModulePath(p: string): boolean {
  // The OUTERMOST boundary decides, like `getScriptBasePathFromModulePath`.
  // Scanning anywhere in the path would call `foo__mod/vendor/x__dbt/a.ts` a dbt
  // project file, and the push would then look for `foo.script.yaml` instead of
  // the ordinary module entry point and skip the edit.
  const norm = normalizeSep(p);
  const base = getScriptBasePathFromModulePath(norm);
  return base !== undefined && norm.startsWith(base + DBT_MODULE_SUFFIX + "/");
}

/** dbt writes these; a project authors them nowhere. Importing a stale
 *  `target/` would ship a manifest this runtime then reads as the graph, and
 *  `dbt_packages/` is a vendored copy the worker restores from its own cache. */
const DBT_GENERATED_DIRS = ["target", "dbt_packages", "logs", ".git", ".venv", "__pycache__"];

const dbtGeneratedDirsCache = new Map<
  string,
  { stamp: string; dirs: Set<string> }
>();

/** `{{ env_var('NAME') }}` / `{{ env_var("NAME", "default") }}`. */
const DBT_ENV_VAR_CALL =
  /\{\{\s*env_var\(\s*['"]([^'"]+)['"]\s*(?:,\s*['"]([^'"]*)['"]\s*)?\)\s*\}\}/g;

/**
 * Render `dbt_project.yml`'s own `env_var()` calls, which dbt allows there too.
 * A directory setting left as its template names no directory on disk, so the
 * generated tree it points at would be bundled as project source.
 *
 * Against `process.env`, because the CLI runs where the project was built: that
 * is the environment dbt used to produce the tree being read.
 */
export function renderDbtEnvVars(value: string): string {
  return value.replace(
    DBT_ENV_VAR_CALL,
    (whole, name: string, fallback: string | undefined) =>
      process.env[name] ?? fallback ?? whole,
  );
}

/**
 * Files that keep a project's secrets next to it rather than in it: dbt reads
 * none of them (`env_var()` takes the process environment), and the documented
 * way into a bundle is `cp -r my-project/.`, which copies whatever the checkout
 * holds — including the `.env` a `.gitignore` was keeping out of the repo.
 */
export function isLocalSecretFile(name: string): boolean {
  return name === ".env" || name.startsWith(".env.") || name === ".envrc";
}

/**
 * Directories to leave out of a dbt project's module bundle, as project-relative
 * paths — `target-path` and friends may be nested (`build/target`).
 *
 * `target-path`, `packages-install-path` and `clean-targets` are configurable,
 * so they are read from the project rather than assumed. Cached per project
 * folder: this is called once per file of a sync.
 */
export function dbtGeneratedDirs(moduleFolderPath: string): Set<string> {
  const projectFile = path.join(moduleFolderPath, "dbt_project.yml");
  // Cached against the project file's identity, not merely its folder: `wmill
  // dev` is a long-running process, so a `target-path` edited mid-session would
  // otherwise keep excluding the old directory and start bundling the new one
  // as project source. One entry per folder, replaced when the file changes.
  let stamp = "";
  try {
    const st = fs.statSync(projectFile);
    stamp = `${st.mtimeMs}:${st.size}`;
  } catch {
    // No project file yet: the defaults apply, and "absent" is its own stamp.
  }
  const cached = dbtGeneratedDirsCache.get(moduleFolderPath);
  if (cached && cached.stamp === stamp) return cached.dirs;
  const dirs = new Set<string>(DBT_GENERATED_DIRS);
  const add = (raw: string) => {
    const v = normalizeSep(renderDbtEnvVars(raw).trim().replace(/^["']|["']$/g, ""))
      .replace(/^\.\//, "")
      .replace(/\/+$/, "");
    // A configured path that escapes the project is dbt's problem, not ours;
    // ignoring it here just means those files stay in the bundle.
    if (v && !v.startsWith("/") && !v.split("/").includes("..")) dirs.add(v);
  };
  try {
    const projectYml = fs.readFileSync(projectFile, "utf-8");
    for (const m of projectYml.matchAll(
      /^\s*(?:target-path|packages-install-path)\s*:\s*([^\n#]+)/gm,
    )) {
      add(m[1]);
    }
    // `clean-targets` in either of dbt's two spellings: inline `[a, b]`, and the
    // block form, whose entries are on the lines that follow.
    const lines = projectYml.split(/\r?\n/);
    for (let i = 0; i < lines.length; i++) {
      const head = lines[i].match(/^\s*clean-targets\s*:\s*(.*)$/);
      if (!head) continue;
      const inline = head[1].match(/^\[([^\]]*)\]/);
      if (inline) {
        inline[1].split(",").forEach(add);
        continue;
      }
      for (let j = i + 1; j < lines.length; j++) {
        const item = lines[j].match(/^\s+-\s*([^\n#]+)$/);
        if (!item) break;
        add(item[1]);
      }
    }
  } catch {
    // No dbt_project.yml yet (a descriptor pushed before its project): the
    // defaults still apply.
  }
  dbtGeneratedDirsCache.set(moduleFolderPath, { stamp, dirs });
  return dirs;
}

/**
 * Whether a project-relative path sits inside one of `dirs`. Compared segment
 * by segment: `targetx/a` must not match a configured `target`.
 */
export function isUnderGeneratedDir(rel: string, dirs: Set<string>): boolean {
  const n = normalizeSep(rel);
  for (const d of dirs) {
    if (n === d || n.startsWith(d + "/")) return true;
  }
  return false;
}

/**
 * Whether a path under a `__dbt/` folder is one dbt generated rather than one
 * the project authors. Those never belong to the bundle, so sync must not offer
 * them as items of their own either.
 */
export function isDbtGeneratedPath(p: string): boolean {
  const n = normalizeSep(p);
  // Anchored on the outermost boundary, like every other helper here. Matching
  // `__dbt/` anywhere would call `foo__mod/vendor/x__dbt/target/a.ts` generated
  // dbt output, and `ignoreF` would then exclude an ordinary module file so a
  // module-only edit never deploys its parent script.
  if (!isDbtModulePath(n)) return false;
  const base = getScriptBasePathFromModulePath(n)!;
  const projectRoot = base + DBT_MODULE_SUFFIX;
  const rel = n.slice(projectRoot.length + 1);
  if (isUnderGeneratedDir(rel, dbtGeneratedDirs(projectRoot))) {
    return true;
  }
  // Not generated, but not carried either: the bundle drops it, so the diff
  // must not keep offering it as a pending change. An OVERSIZED one is the
  // exception — see `moduleFileExclusion`: hiding it here is what would make an
  // edit to a large seed report no change at all.
  return (
    isLocalSecretFile(n.slice(n.lastIndexOf("/") + 1)) ||
    moduleFileExclusion(p) === "binary"
  );
}

/**
 * Build the module folder path from a script's base path (without extension).
 * e.g., "f/my_script" -> "f/my_script__mod", or "__dbt" for a dbt project.
 */
export function buildModuleFolderPath(scriptBasePath: string, language?: string): string {
  return scriptBasePath + getModuleFolderSuffix(language);
}

/**
 * Check if a file inside a __mod/ folder is the main entry point (script.{ext}).
 * Entry points are files named "script.*" directly under __mod/ (not in subdirs).
 */
export function isModuleEntryPoint(p: string): boolean {
  const norm = normalizeSep(p);
  // Anchored on the OUTERMOST module boundary, like
  // `getScriptBasePathFromModulePath`. Scanning for `__mod/` alone would match a
  // `legacy__mod/` directory nested inside a dbt project — dbt owns those names
  // verbatim — and call its `script.ts` this script's entry point.
  const base = getScriptBasePathFromModulePath(norm);
  if (base === undefined) return false;
  // A dbt project's entry point is its descriptor, which sits INSIDE the
  // project so that an author writes nothing outside the directory dbt itself
  // reads.
  if (norm.startsWith(base + DBT_MODULE_SUFFIX + "/")) {
    return norm === dbtDescriptorPath(base);
  }
  const suffix = MODULE_SUFFIX + "/";
  if (!norm.startsWith(base + suffix)) return false;
  const rest = norm.slice(base.length + suffix.length);
  return rest.startsWith("script.") && !rest.includes("/");
}

/**
 * Extract the script base path from a module folder entry.
 * e.g., "u/admin/my_script__mod/script.ts" -> "u/admin/my_script"
 * e.g., "u/admin/my_script__mod/helper.ts" -> "u/admin/my_script"
 * e.g., "f/x/proj__dbt/models/a.sql" -> "f/x/proj"
 */
export function getScriptBasePathFromModulePath(p: string): string | undefined {
  const norm = normalizeSep(p);
  // The OUTERMOST boundary, not the first suffix that happens to match. A dbt
  // project's directories are the author's verbatim, so `foo__dbt/models/
  // legacy__mod/a.sql` is legal — taking `__mod` first would call
  // `foo__dbt/models/legacy` the script and look for a descriptor that is not
  // there, silently skipping the deploy.
  let best: number | undefined;
  for (const suffix of MODULE_SUFFIXES) {
    const idx = norm.indexOf(suffix + "/");
    if (idx !== -1 && (best === undefined || idx < best)) best = idx;
  }
  return best === undefined ? undefined : norm.slice(0, best);
}

/**
 * Convert a local script file path to its Windmill API remote path.
 * Handles both folder layout (`u/admin/my_script__mod/script.ts` -> `u/admin/my_script`)
 * and flat layout (`u/admin/my_script.ts` -> `u/admin/my_script`).
 *
 * For flat layout, splits at the FIRST `.` which means a script under a
 * folder containing a `.` in its name (e.g. `u/my.folder/script.ts`) gets
 * truncated; that pre-dates this helper and is preserved here for parity.
 */
export function scriptPathToRemotePath(p: string): string {
  return (
    isModuleEntryPoint(p)
      ? getScriptBasePathFromModulePath(p)!
      : p.substring(0, p.indexOf("."))
  ).replaceAll(SEP, "/");
}

// ============================================================================
// Sync-related Path Functions
// ============================================================================

/**
 * Get the path suffix to remove when converting local path to API path
 * for delete operations
 */
export function getDeleteSuffix(
  type: FolderResourceType,
  format: "yaml" | "json"
): string {
  return getFolderSuffixes()[type] + "/" + METADATA_FILES[type][format];
}

/**
 * Transform a JSON path from API format to local directory path for sync.
 * The API always returns dotted format (.flow.json, .app.json, .raw_app.json).
 * This function transforms to the user's configured format (dotted or non-dotted).
 * e.g., with nonDottedPaths=true: "f/my_flow.flow.json" -> "f/my_flow__flow"
 * e.g., with nonDottedPaths=false: "f/my_flow.flow.json" -> "f/my_flow.flow"
 */
export function transformJsonPathToDir(
  p: string,
  type: FolderResourceType
): string {
  // API always returns dotted format
  const apiSuffix = DOTTED_SUFFIXES[type] + ".json";
  if (p.endsWith(apiSuffix)) {
    // Remove the API suffix and add user's configured suffix
    const basePath = p.substring(0, p.length - apiSuffix.length);
    return basePath + getFolderSuffixes()[type];
  }
  // Also handle the case where path already has user's configured format
  const userSuffix = getFolderSuffixes()[type] + ".json";
  if (p.endsWith(userSuffix)) {
    return p.substring(0, p.length - 5); // Remove ".json"
  }
  // Path doesn't match expected suffix pattern, return unchanged
  return p;
}

import { Schema, SchemaProperty } from "../../bootstrap/common.ts";

function quotePropName(name: string): string {
  return /^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(name) ? name : JSON.stringify(name);
}

function isPropertyMap(x: unknown): x is { [name: string]: SchemaProperty } {
  return typeof x === "object" && x !== null && !Array.isArray(x);
}

// Schemas are free-form jsonb: the column is nullable and hub types such as
// `record` or `dbt_profile` carry `{}` / `{"type":"object"}` with no
// `properties`. Anything that is not a property map compiles to `any`, since a
// throw here aborts the whole rt.d.ts generation.
export function compileResourceTypeToTsType(schema: Schema | undefined | null) {
  function rec(x: unknown): string {
    if (!isPropertyMap(x)) {
      return "any";
    }
    const entries = Object.entries(x);
    if (entries.length == 0) {
      return "any";
    }
    let res = "{\n";
    let i = 0;
    for (let [name, prop] of entries) {
      if (prop?.type == "object") {
        res += `  ${quotePropName(name)}: ${rec(prop.properties)}`;
      } else if (prop?.type == "array") {
        res += `  ${quotePropName(name)}: ${prop?.items?.type ?? "any"}[]`;
      } else {
        let typ = prop?.type ?? "any";
        if (typ == "integer") {
          typ = "number";
        }
        res += `  ${quotePropName(name)}: ${typ}`;
      }
      i++;
      if (i < entries.length) {
        res += ",\n";
      }
    }
    res += "\n}";
    return res;
  }

  return rec(schema?.properties);
}

import { isDbtDescriptorPath } from "./resource_folders.ts";
export type ScriptLanguage =
  | "python3"
  | "deno"
  | "bun"
  | "nativets"
  | "go"
  | "bash"
  | "powershell"
  | "postgresql"
  | "mysql"
  | "bigquery"
  | "duckdb"
  | "oracledb"
  | "snowflake"
  | "mssql"
  | "graphql"
  | "php"
  | "rust"
  | "csharp"
  | "nu"
  | "ansible"
  | "ruby"
  | "rlang"
  | "dbt"
  | "java";
// for related places search: ADD_NEW_LANG

// To make language support raw requirements:
// 1. Add value here
// 2. Modify backend to allow raw deps
export type WorkspaceDependenciesLanguage =
  | { language: "bun", filename /** (raw requirements filename) */: "package.json" }
  | { language: "python3", filename: "requirements.in" }
  | { language: "php", filename: "composer.json" }
  | { language: "go", filename: "go.mod" }
  | { language: "powershell", filename: "modules.json" };

export const workspaceDependenciesLanguages: WorkspaceDependenciesLanguage[] = [
  { language: "bun", filename: "package.json" },
  { language: "python3", filename: "requirements.in" },
  { language: "php", filename: "composer.json" },
  { language: "go", filename: "go.mod" },
  { language: "powershell", filename: "modules.json" },
] as const;

export function workspaceDependenciesPathToLanguageAndFilename(path: string): { name: string | undefined, language: ScriptLanguage } | undefined {
  const relativePath = path.replace("dependencies/", "");
  for (const { filename, language } of workspaceDependenciesLanguages) {
    if (relativePath.endsWith(filename)) {
      return {
        name: relativePath === filename ? undefined : relativePath.replace("." + filename, ""),
        language
      };
    }
  }
}

// ---------------------------------------------------------------------------
// Annotation parser — mirrors backend's WorkspaceDependenciesAnnotatedRefs::parse
// (windmill-common/src/workspace_dependencies.rs), so the CLI can tell which
// workspace dependency file a script resolves against without asking a worker.
// ---------------------------------------------------------------------------

export type AnnotationMode = "manual" | "extra";

export interface WorkspaceDepsAnnotation {
  mode: AnnotationMode;
  external: string[];
  inline: string | null;
}

const LANG_ANNOTATION_CONFIG: Partial<
  Record<ScriptLanguage, { comment: string; keyword: string; validityRe?: RegExp }>
> = {
  python3: { comment: "#", keyword: "requirements", validityRe: /^#\s?(\S+)\s*$/ },
  bun: { comment: "//", keyword: "package_json" },
  nativets: { comment: "//", keyword: "package_json" },
  go: { comment: "//", keyword: "go_mod" },
  php: { comment: "//", keyword: "composer_json" },
  powershell: { comment: "#", keyword: "modules_json" },
};

export function extractWorkspaceDepsAnnotation(
  scriptContent: string,
  language: ScriptLanguage,
): WorkspaceDepsAnnotation | null {
  const config = LANG_ANNOTATION_CONFIG[language];
  if (!config) return null;

  const { comment, keyword, validityRe } = config;
  const extraMarkerUnderscore = `extra_${keyword}:`;
  const extraMarkerHyphen = `extra-${keyword}:`;
  const manualMarker = `${keyword}:`;

  const stripComment = (l: string): string | null => {
    if (!l.startsWith(comment)) return null;
    return l.substring(comment.length).trimStart();
  };
  const isExtra = (l: string): boolean => {
    const s = stripComment(l);
    return s !== null && (s.startsWith(extraMarkerUnderscore) || s.startsWith(extraMarkerHyphen));
  };
  const isManual = (l: string): boolean => {
    const s = stripComment(l);
    return s !== null && s.startsWith(manualMarker);
  };

  const lines = scriptContent.split("\n");

  // Find first annotation line (mirrors Rust find_position)
  let pos = -1;
  for (let i = 0; i < lines.length; i++) {
    if (isExtra(lines[i]) || isManual(lines[i])) {
      pos = i;
      break;
    }
  }
  if (pos === -1) return null;

  const annotationLine = lines[pos];
  const mode: AnnotationMode = isExtra(annotationLine) ? "extra" : "manual";

  // Parse external references from the annotation line
  const marker = mode === "extra"
    ? (annotationLine.includes(extraMarkerUnderscore) ? extraMarkerUnderscore : extraMarkerHyphen)
    : manualMarker;
  const unparsed = annotationLine.replaceAll(marker, "").replaceAll(comment, "");
  const external = unparsed
    .split(",")
    .map((s) => s.trim())
    .filter((s) => s.length > 0);

  // Parse inline deps from subsequent lines
  const inlineParts: string[] = [];
  for (let i = pos + 1; i < lines.length; i++) {
    const l = lines[i];
    if (validityRe) {
      const match = validityRe.exec(l);
      if (match && match[1]) {
        inlineParts.push(match[1]);
      } else {
        break;
      }
    } else {
      if (!l.startsWith(comment)) {
        break;
      }
      inlineParts.push(l.substring(comment.length));
    }
  }

  const inlineStr = inlineParts.join("\n");
  const inline = inlineStr.trim().length > 0 ? inlineStr : null;

  return { mode, external, inline };
}

/** The comment marker each language's annotations are written behind. */
export const LANG_COMMENT_LIT: Partial<Record<ScriptLanguage, string>> = {
  python3: "#",
  ansible: "#",
  powershell: "#",
  bun: "//",
  nativets: "//",
  deno: "//",
  go: "//",
  php: "//",
  rust: "//!",
};

/**
 * The annotations each language recognises, by the exact names the worker
 * matches (`#[annotations(..)]` structs in windmill-common/src/worker.rs).
 * Several change what it locks — a pinned interpreter, `npm`, `nobundling` —
 * and the rest are cheap to treat the same way, since the only cost is that
 * such a script keeps a lockfile of its own.
 * for related places search: ADD_NEW_LANG
 */
const LANG_ANNOTATIONS: Partial<Record<ScriptLanguage, string[]>> = {
  python3: [
    "no_cache",
    "no_postinstall",
    "py_select_latest",
    "skip_result_postprocessing",
    "py310",
    "py311",
    "py312",
    "py313",
    "sandbox",
  ],
  bun: ["npm", "nodejs", "native", "nobundling", "sandbox"],
  nativets: ["npm", "nodejs", "native", "nobundling", "sandbox"],
  deno: ["npm", "nodejs", "native", "nobundling", "sandbox"],
  go: ["go1_22_compat"],
};

/**
 * Whether a script's leading comment block carries an annotation the worker
 * acts on, which means its lock may not be its dependency file's.
 *
 * Matched the way the worker matches: the key is the line, or what precedes the
 * first `=`, and it has to BE one of the names above. Unknown keys are ignored
 * there and so here — which is what keeps `# TODO:` or `# type: ignore` from
 * quietly dropping an ordinary documented script out of deduplication.
 *
 * `# py: <specifier>` is the exception the macro does not cover: the python
 * import parser reads it directly (`windmill-parser-py-imports`, alongside the
 * `py310`..`py313` flags) to pick the interpreter, which changes what resolves.
 */
export function hasLockAffectingAnnotation(
  scriptContent: string,
  language: ScriptLanguage,
): boolean {
  const comment = LANG_COMMENT_LIT[language];
  const names = LANG_ANNOTATIONS[language];
  if (!comment || !names) return false;
  for (const line of scriptContent.split("\n")) {
    const trimmed = line.trim();
    if (trimmed === "") continue;
    if (!trimmed.startsWith(comment)) break; // past the header block
    // Matched on the raw line: the parser tests `# py:`/`#py:` before trimming.
    if (language === "python3" && /^#\s?py:/.test(line)) return true;
    const body = trimmed.slice(comment.length).trim();
    const key = body.split("=")[0].trim();
    if (names.includes(key)) return true;
  }
  return false;
}

/** Where the lockfiles shared by several scripts live when `dedupeLockfiles`
 *  is on — see `utils/lock_dedup.ts`. A top-level directory of its own: what a
 *  group shares is a resolved lock, which needs no workspace dependency file
 *  behind it, and inline-script locks would belong here too. */
export const SHARED_LOCK_DIR = "locks";

/** The lockfile shared by the scripts that resolve against a workspace
 *  dependency file: its own name, plus `.lock`. Appending rather than replacing
 *  the extension keeps the correspondence exact and reversible —
 *  `dependencies/team_a.requirements.in` <-> `locks/team_a.requirements.in.lock`. */
export function sharedLockPathFor(depFilePath: string): string {
  const name = depFilePath.replaceAll("\\", "/").split("/").pop()!;
  return `${SHARED_LOCK_DIR}/${name}.lock`;
}

/** The workspace dependency file a shared lockfile belongs to, if it is one. */
export function depFileOfSharedLock(p: string): string | undefined {
  const normalized = p.replaceAll("\\", "/");
  if (!normalized.startsWith(SHARED_LOCK_DIR + "/")) return undefined;
  const name = normalized.slice(SHARED_LOCK_DIR.length + 1);
  if (name.includes("/") || !name.endsWith(".lock")) return undefined;
  const depFile = "dependencies/" + name.slice(0, -".lock".length);
  const info = workspaceDependenciesPathToLanguageAndFilename(depFile);
  // `locks/vendor.lock` names no dependency file, so it is not Windmill's: a
  // repo that already keeps lockfiles here keeps them.
  return info && languageNeedsLock(info.language) ? depFile : undefined;
}

export function isSharedLockPath(p: string): boolean {
  return depFileOfSharedLock(p) !== undefined;
}

/**
 * Returns true if a script in the given language requires a lock file.
 * Matches the condition in updateScriptLock (metadata.ts).
 */
export function languageNeedsLock(language: ScriptLanguage | string): boolean {
  return (
    (workspaceDependenciesLanguages.some((l) => l.language === language) &&
      language !== "powershell") ||
    language === "deno" ||
    language === "rust" ||
    language === "ansible"
  );
}

export function inferContentTypeFromFilePath(
  contentPath: string,
  defaultTs: "bun" | "deno" | undefined
): ScriptLanguage {
  if (contentPath.endsWith(".py")) {
    return "python3";
  } else if (contentPath.endsWith("fetch.ts")) {
    return "nativets";
  } else if (contentPath.endsWith("bun.ts")) {
    return "bun";
  } else if (contentPath.endsWith("deno.ts")) {
    return "deno";
  } else if (contentPath.endsWith(".ts")) {
    return defaultTs ?? "bun";
  } else if (contentPath.endsWith(".go")) {
    return "go";
  } else if (contentPath.endsWith(".my.sql")) {
    return "mysql";
  } else if (contentPath.endsWith(".bq.sql")) {
    return "bigquery";
  } else if (contentPath.endsWith(".odb.sql")) {
    return "oracledb";
  } else if (contentPath.endsWith(".duckdb.sql")) {
    return "duckdb";
  } else if (contentPath.endsWith(".sf.sql")) {
    return "snowflake";
  } else if (contentPath.endsWith(".ms.sql")) {
    return "mssql";
  } else if (contentPath.endsWith(".pg.sql")) {
    return "postgresql";
  } else if (contentPath.endsWith(".gql")) {
    return "graphql";
  } else if (contentPath.endsWith(".sh")) {
    return "bash";
  } else if (contentPath.endsWith(".ps1")) {
    return "powershell";
  } else if (contentPath.endsWith(".php")) {
    return "php";
  } else if (contentPath.endsWith(".rs")) {
    return "rust";
  } else if (contentPath.endsWith(".cs")) {
    return "csharp";
  } else if (contentPath.endsWith(".playbook.yml")) {
    return "ansible";
  } else if (contentPath.endsWith(".nu")) {
    return "nu";
  } else if (contentPath.endsWith(".java")) {
    return "java";
  } else if (contentPath.endsWith(".rb")) {
    return "ruby";
  } else if (isDbtDescriptorPath(contentPath)) {
    return "dbt";
  } else if (contentPath.endsWith(".r")) {
    return "rlang";
	// for related places search: ADD_NEW_LANG
  } else {
    const ext = contentPath.substring(contentPath.lastIndexOf("."));
    let hint = "";
    if (ext === ".sql") {
      hint =
        "\nBare .sql is ambiguous — use a dialect extension: .pg.sql (postgresql), .my.sql (mysql), .bq.sql (bigquery), .sf.sql (snowflake), .ms.sql (mssql), .odb.sql (oracledb), .duckdb.sql (duckdb)";
    }
    throw new Error(
      `Cannot infer script language from extension '${ext}' (file ${contentPath}).` +
        hint +
        "\nSupported extensions: .ts (bun/deno), .py, .go, .sh, .ps1, .php, .rs, .cs, .nu, .java, .rb, .r, .gql, .playbook.yml, .pg.sql, .my.sql, .bq.sql, .sf.sql, .ms.sql, .odb.sql, .duckdb.sql, and a dbt project folder `<name>__dbt/`"
    );
  }
}

import { pack } from "tar-stream";

export interface TarEntry {
  name: string;
  content: Buffer | Uint8Array | string;
}

export function createTarBlob(entries: TarEntry[]): Promise<Blob> {
  return new Promise((resolve, reject) => {
    const p = pack();
    const chunks: Uint8Array[] = [];

    p.on("data", (chunk: Buffer) => chunks.push(new Uint8Array(chunk)));
    p.on("end", () => resolve(new Blob(chunks as BlobPart[])));
    p.on("error", reject);

    for (const entry of entries) {
      p.entry({ name: entry.name }, Buffer.from(entry.content));
    }
    p.finalize();
  });
}

import { Provider } from "@cliffy/command/upgrade";

export type NpmProviderOptions = { main?: string; logger?: any } & (
  | {
      package: string;
    }
  | {
      scope: string;
      name?: string;
    }
);

export class NpmProvider extends Provider {
  name = "npm";
  private readonly repositoryUrl = "https://npmjs.org/";
  private readonly apiUrl = "https://registry.npmjs.org/";
  private readonly packageName?: string;

  constructor({ main, logger, ...options }: NpmProviderOptions) {
    super({ main, logger });

    this.packageName = "package" in options ? options.package : options.name;
  }

  async getVersions(name: string): Promise<any> {
    const response = await fetch(
      new URL(`${this.packageName ?? name}`, this.apiUrl)
    );
    if (!response.ok) {
      throw new Error(
        "couldn't fetch the latest version - try again after sometime"
      );
    }

    const {
      "dist-tags": { latest },
      versions,
    } = (await response.json()) as NpmApiPackageMetadata;

    return {
      latest,
      versions: Object.keys(versions).reverse(),
    };
  }

  getRepositoryUrl(name: string, version?: string): string {
    return new URL(
      `package/${this.packageName ?? name}${version ? `/v/${version}` : ""}`,
      this.repositoryUrl
    ).href;
  }

  getRegistryUrl(name: string, version: string): string {
    return `npm:${this.packageName ?? name}@${version}`;
  }

  async hasRequiredPermissions(): Promise<boolean> {
    return true;
  }

  // Cliffy's default runtime runs `npm install --silent`, so a failed upgrade
  // throws with an empty message. Override to run npm without --silent and put
  // the captured output + recovery hint in the error, so failures are actionable.
  override async upgrade({
    name,
    to,
    main,
    verbose,
  }: {
    name: string;
    to: string;
    main?: string;
    verbose?: boolean;
  }): Promise<void> {
    const specifier = this.getSpecifier(name, to, main).replace(/^npm:/, "");
    const args = ["install", "--global", "--force", specifier];
    this.logger?.log(`$ npm ${args.join(" ")}`);
    const { spawn } = await import("node:child_process");
    const HINT =
      "If this is a permissions error, retry with sudo, or reinstall with: npm uninstall -g windmill-cli && npm install -g windmill-cli";
    // `shell: true` so `npm` resolves on Windows (npm.cmd) — same spawn
    // pattern as commands/app/bundle.ts.
    const proc = spawn("npm", args, {
      stdio: [null, "pipe", "pipe"],
      shell: true,
    });
    const output: string[] = [];
    proc.stdout?.on("data", (d) => {
      output.push(String(d));
      if (verbose) process.stdout.write(d);
    });
    proc.stderr?.on("data", (d) => {
      output.push(String(d));
      if (verbose) process.stderr.write(d);
    });
    // `error` fires when npm can't be spawned at all; without a listener that
    // is an uncaught exception, crashing before any hint prints. `close`
    // resolves null when npm died from a signal — a failure too.
    const exitCode: number | null = await new Promise<number | null>(
      (resolve, reject) => {
        proc.on("error", reject);
        proc.on("close", resolve);
      }
    ).catch((e) => {
      throw new Error(
        `failed to run npm: ${e instanceof Error ? e.message : e}\n\n${HINT}`
      );
    });
    if (exitCode !== 0) {
      const detail = output.join("").trim();
      throw new Error(
        `npm exited with ${
          exitCode === null ? "a signal" : `code ${exitCode}`
        }${detail ? `:\n${detail}` : ""}\n\n${HINT}`
      );
    }
  }
}

type NpmApiPackageMetadata = {
  "dist-tags": {
    latest: string;
  };
  versions: {
    [version: string]: unknown;
  };
};

// Modified from: https://raw.githubusercontent.com/epoberezkin/fast-deep-equal/master/src/index.jst
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-nocheck This file is copied from a JS project, so it's not type-safe.

import { colors } from "@cliffy/ansi/colors";
import * as log from "../core/log.ts";
import { sep as SEP } from "node:path";
import crypto from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
