export function deepEqual<T>(a: T, b: T): boolean {
  if (a === b) return true;

  if (a && b && typeof a === "object" && typeof b === "object") {
    if (a.constructor !== b.constructor) return false;

    let length, i;
    if (Array.isArray(a)) {
      length = a.length;
      if (length != b.length) return false;
      for (i = length; i-- !== 0; ) {
        if (!deepEqual(a[i], b[i])) return false;
      }
      return true;
    }

    if (a instanceof Map && b instanceof Map) {
      if (a.size !== b.size) return false;
      for (i of a.entries()) {
        if (!b.has(i[0])) return false;
      }
      for (i of a.entries()) {
        if (!deepEqual(i[1], b.get(i[0]))) return false;
      }
      return true;
    }

    if (a instanceof Set && b instanceof Set) {
      if (a.size !== b.size) return false;
      for (i of a.entries()) {
        if (!b.has(i[0])) return false;
      }
      return true;
    }

    if (ArrayBuffer.isView(a) && ArrayBuffer.isView(b)) {
      length = a.length;
      if (length != b.length) return false;
      for (i = length; i-- !== 0; ) {
        if (a[i] !== b[i]) return false;
      }
      return true;
    }

    if (a.constructor === RegExp) {
      return a.source === b.source && a.flags === b.flags;
    }
    if (a.valueOf !== Object.prototype.valueOf) {
      return a.valueOf() === b.valueOf();
    }
    if (
      a.toString !== Object.prototype.toString &&
      typeof a.toString == "function"
    ) {
      return a.toString() === b.toString();
    }

    const keys = Object.keys(a);
    length = keys.length;
    if (length !== Object.keys(b).length) return false;

    for (i = length; i-- !== 0; ) {
      if (!Object.prototype.hasOwnProperty.call(b, keys[i])) return false;
    }

    for (i = length; i-- !== 0; ) {
      const key = keys[i];
      if (!deepEqual(a[key], b[key])) return false;
    }

    return true;
  }

  // true if both NaN, false otherwise
  return a !== a && b !== b;
}

export function getHeaders(): Record<string, string> | undefined {
  const headers = process.env["HEADERS"];
  if (headers) {
    const parsedHeaders = Object.fromEntries(
      headers.split(",").map((h) => h.split(":").map((s) => s.trim()))
    );
    log.debug(
      "Headers from env keys: " + JSON.stringify(Object.keys(parsedHeaders))
    );
    return parsedHeaders;
  } else {
    return undefined;
  }
}

export async function digestDir(path: string, conf: string) {
  const hashes: string = [];
  const entries = await readdir(path, { withFileTypes: true });
  entries.sort((a, b) => a.name.localeCompare(b.name));
  for (const e of entries) {
    const npath = path + "/" + e.name;
    if (e.isFile()) {
      hashes.push(await generateHashFromBuffer(await readFile(npath)));
    } else if (e.isDirectory() && !e.isSymbolicLink()) {
      hashes.push(await digestDir(npath, ""));
    }
  }
  return await generateHash(hashes.join("") + conf);
}

export async function generateHash(content: string): Promise<string> {
  const messageBuffer = new TextEncoder().encode(content);
  return await generateHashFromBuffer(messageBuffer);
}

export async function generateHashFromBuffer(
  content: BufferSource
): Promise<string> {
  const hashBuffer = await crypto.subtle.digest("SHA-256", content);
  return Buffer.from(hashBuffer).toString("hex");
}

function decodeBufferAsUtf8(buf: Buffer, path: string | URL): string {
  if (buf.length >= 2) {
    if (buf[0] === 0xff && buf[1] === 0xfe) {
      if (buf.length >= 4 && buf[2] === 0x00 && buf[3] === 0x00) {
        throw new Error(
          `File ${path} is encoded as UTF-32 LE, which is not supported. Please convert it to UTF-8.`
        );
      }
      throw new Error(
        `File ${path} is encoded as UTF-16 LE, which is not supported. Please convert it to UTF-8.`
      );
    }
    if (buf[0] === 0xfe && buf[1] === 0xff) {
      throw new Error(
        `File ${path} is encoded as UTF-16 BE, which is not supported. Please convert it to UTF-8.`
      );
    }
    if (buf.length >= 4 && buf[0] === 0x00 && buf[1] === 0x00 && buf[2] === 0xfe && buf[3] === 0xff) {
      throw new Error(
        `File ${path} is encoded as UTF-32 BE, which is not supported. Please convert it to UTF-8.`
      );
    }
  }
  if (buf.length >= 3 && buf[0] === 0xef && buf[1] === 0xbb && buf[2] === 0xbf) {
    return buf.subarray(3).toString("utf-8");
  }
  return buf.toString("utf-8");
}

export function stripBom(content: string): string {
  if (content.charCodeAt(0) === 0xfeff) {
    return content.slice(1);
  }
  return content;
}

export async function readTextFile(path: string | URL): Promise<string> {
  return decodeBufferAsUtf8(await readFile(path), path);
}

export function readTextFileSync(path: string | URL): string {
  return decodeBufferAsUtf8(readFileSync(path), path);
}

export function readInlinePathSync(path: string): string {
  try {
    return readTextFileSync(path.replaceAll("/", SEP));
  } catch (error) {
    log.warn(`Error reading inline path: ${path}, ${error}`);
    return "";
  }
}

export function sleep(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function isFileResource(path: string): boolean {
  const splitPath = path.split(".");

  // Check for pattern: *.resource.file.* (handles both base and branch-specific)
  return (
    splitPath.length >= 4 &&
    splitPath[splitPath.length - 3] == "resource" &&
    splitPath[splitPath.length - 2] == "file"
  );
}

/**
 * Local resource path -> the resource's path on the server. The suffix is
 * `.resource.<yaml|json>` on a metadata file but `.resource.file.<ext>` on a
 * file resource, so its length depends on which of the two the path is.
 */
export function removeResourceSuffix(path: string): string {
  if (isFileResource(path)) {
    // isFileResource only matches a dotless extension, so the resource path is
    // everything before the trailing `resource`, `file`, `<ext>` segments.
    return path.split(".").slice(0, -3).join(".");
  }
  return path.replace(/\.resource\.(yaml|json)$/, "");
}

/** Matches children inside a .fileset/ directory, not the directory itself. */
export function isFilesetResource(path: string): boolean {
  return path.includes(".fileset/") || path.includes(".fileset\\");
}

export function isRawAppFile(path: string): boolean {
  return isRawAppPath(path);
}

export function isWorkspaceDependencies(path: string): boolean {
  return path.startsWith("dependencies/");
}

export function printSync(input: string | Uint8Array) {
  process.stdout.write(
    typeof input === "string" ? input : Buffer.from(input)
  );
}

// Repository interface for shared selection logic
export interface Repository {
  git_repo_resource_path: string;
}

// Shared repository selection logic
export async function selectRepository<T extends Repository>(
  repositories: T[],
  operation?: string
): Promise<T> {
  if (repositories.length === 0) {
    throw new Error("No git-sync repositories configured in workspace");
  }

  if (repositories.length === 1) {
    const repoPath = repositories[0].git_repo_resource_path.replace(
      /^\$res:/,
      ""
    );
    log.info(colors.cyan(`Auto-selected repository: ${colors.bold(repoPath)}`));
    return repositories[0];
  }

  // Check if we're in a non-interactive environment
  const isInteractive = !!process.stdin.isTTY && !!process.stdout.isTTY;

  if (!isInteractive) {
    const repoPaths = repositories.map((r) =>
      r.git_repo_resource_path.replace(/^\$res:/, "")
    );
    throw new Error(
      `Multiple repositories found: ${repoPaths.join(
        ", "
      )}. Use --repository to specify which one to ${operation || "use"}.`
    );
  }

  // Import Select dynamically to avoid dependency issues
  const { Select } = await import("@cliffy/prompt/select");

  console.log(
    `\nMultiple repositories found. Please select which repository to ${
      operation || "use"
    }:\n`
  );

  const selectedRepo = await Select.prompt({
    message: `Select repository for ${operation || "operation"}:`,
    options: repositories.map((repo, index) => {
      const displayPath = repo.git_repo_resource_path.replace(/^\$res:/, "");
      return {
        name: `${index + 1}. ${displayPath}`,
        value: repo.git_repo_resource_path,
      };
    }),
  });

  return repositories.find((r) => r.git_repo_resource_path === selectedRepo)!;
}

let isWin: boolean | undefined = undefined;
export async function getIsWin(): Promise<boolean> {
  if (isWin === undefined) {
    const os = await import("node:os");
    isWin = os.platform() === "win32";
  }
  return isWin;
}

/**
 * Writes content to a file only if it differs from existing content.
 * Creates parent directories if they don't exist.
 *
 * @param path - The file path to write to
 * @param content - The content to write
 * @returns true if file was written, false if skipped (content unchanged)
 */
export function writeIfChanged(path: string, content: string): boolean {
  try {
    const existing = readTextFileSync(path);
    if (existing === content) {
      return false; // Content unchanged, skip write
    }
  } catch (error: any) {
    // File doesn't exist or can't be read, proceed with write
    if (error?.code !== "ENOENT") {
      // If it's not a "not found" error, we might want to know about it
      // but still proceed with the write attempt
    }
  }

  writeFileSync(path, content, "utf-8");
  return true; // File was written
}

export async function fetchRemoteVersion(
  workspace: Workspace
): Promise<string> {
  const version = await fetchVersion(workspace.remote);
  if (version) {
    updateGlobalVersions(version);
  }
  log.info(colors.gray("CLI version: " + VERSION));
  log.info(colors.gray("Remote version: " + version));
}

export function toCamel(s: string) {
  return s.replace(/([-_][a-z])/gi, ($1) => {
    return $1.toUpperCase().replace("-", "").replace("_", "");
  });
}

export function capitalize(str: string): string {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

export function formatTimestamp(ts: string): string {
  return new Date(ts).toISOString().replace("T", " ").substring(0, 19);
}

/**
 * Validate that required arguments are present when no -d data was provided.
 * Fetches the schema from the API and checks required fields.
 * @param schema - The JSON schema object from the script/flow definition
 * @throws Error if required arguments are missing
 */
export function validateRequiredArgs(
  schema: Record<string, unknown> | undefined | null,
): void {
  const required = (schema as { required?: string[] })?.required ?? [];
  if (required.length > 0) {
    throw new Error(
      `Missing required arguments: ${required.join(", ")}.\nUse -d '{"${required[0]}": ...}' to provide input data.`
    );
  }
}

import { parse as yamlParse } from "yaml";
import type { ParseOptions, DocumentOptions, SchemaOptions, ToJSOptions, ScalarTag } from "yaml";
import { readTextFile } from "./utils.ts";

// Custom YAML tags that resolve `!inline value` and `!inline_fileset value`
// back to their string-prefix form ("!inline value").
// Without these, the yaml parser strips the tag and returns just the scalar,
// breaking the string-prefix-based !inline detection used throughout the CLI.
const inlineTag: ScalarTag = {
  tag: "!inline",
  resolve(value: string) {
    return "!inline " + value;
  },
};

const inlineFilesetTag: ScalarTag = {
  tag: "!inline_fileset",
  resolve(value: string) {
    return "!inline_fileset " + value;
  },
};

const WINDMILL_CUSTOM_TAGS: ScalarTag[] = [inlineTag, inlineFilesetTag];

type YamlParseOptions = ParseOptions & DocumentOptions & SchemaOptions & ToJSOptions;

export async function yamlParseFile(path: string, options: YamlParseOptions = {}) {
  try {
    return yamlParse(await readTextFile(path), {
      ...options,
      customTags: [...WINDMILL_CUSTOM_TAGS, ...((options.customTags as ScalarTag[] | undefined) ?? [])],
    });
  } catch (e) {
    throw new Error(`Error parsing yaml ${path}`, { cause: e });
  }
}

export function yamlParseContent(
  path: string,
  content: string,
  options: YamlParseOptions = {},
) {
  try {
    return yamlParse(content, {
      ...options,
      customTags: [...WINDMILL_CUSTOM_TAGS, ...((options.customTags as ScalarTag[] | undefined) ?? [])],
    });
  } catch (e) {
    throw new Error(`Error parsing yaml ${path}`, { cause: e });
  }
}

/**
 * Integration test for `wmill app dev`'s schema-fetch path.
 *
 * Verifies that path-based runnables (type: script) get a real schema in the
 * generated wmill.d.ts after fetchPathRunnableSchemas() pulls it from the
 * Windmill API. Without this fix the runnable would always render as
 * `args: {}` because the local YAML doesn't carry the schema.
 */

import { expect, test } from "bun:test";
import { withTestBackend } from "./test_backend.ts";
import { addWorkspace } from "../workspace.ts";
import * as fs from "node:fs";
import * as path from "node:path";
import { mkdir, writeFile } from "node:fs/promises";
import { setClient } from "../src/core/client.ts";
import { APP_BACKEND_FOLDER } from "../src/commands/app/app_metadata.ts";
import { loadRunnablesFromBackend } from "../src/commands/app/raw_apps.ts";
import {
  buildWmillTs,
  fetchPathRunnableSchemas,
} from "../src/commands/app/dev.ts";

const TYPED_SCRIPT_CONTENT =
  `export async function main(userId: string, includeProfile: boolean) {\n` +
  `  return { userId, includeProfile };\n` +
  `}\n`;

test("fetchPathRunnableSchemas pulls schema for a path-based script and feeds wmill.d.ts", async () => {
  await withTestBackend(async (backend, tempDir) => {
    // Bind CLI workspace + arm the OpenAPI client
    await addWorkspace(
      {
        remote: backend.baseUrl,
        workspaceId: backend.workspace,
        name: "app_dev_schema_fetch",
        token: backend.token,
      },
      { force: true, configDir: backend.testConfigDir },
    );
    setClient(backend.token, backend.baseUrl);

    // Create the folder + script that the raw app will reference by path
    await backend
      .apiRequest!(`/api/w/${backend.workspace}/folders/create`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: "test" }),
      })
      .then((r) => r.text());

    const scriptPath = "f/test/fetch_user";
    const createResp = await backend.apiRequest!(
      `/api/w/${backend.workspace}/scripts/create`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          path: scriptPath,
          content: TYPED_SCRIPT_CONTENT,
          language: "bun",
          summary: "Fetch user",
          description: "Test script with typed args",
          schema: {
            $schema: "https://json-schema.org/draft/2020-12/schema",
            type: "object",
            properties: {
              userId: { type: "string", description: "user id" },
              includeProfile: { type: "boolean" },
            },
            required: ["userId", "includeProfile"],
          },
        }),
      },
    );
    expect(createResp.status).toBeLessThan(300);

    // Lay out a raw app with a backend folder that references the path script
    const appDir = path.join(tempDir, "f", "test", "schema_fetch_app.raw_app");
    const backendDir = path.join(appDir, APP_BACKEND_FOLDER);
    await mkdir(backendDir, { recursive: true });
    await writeFile(
      path.join(backendDir, "fetchUser.yaml"),
      `type: script\npath: ${scriptPath}\nfields: {}\nname: fetchUser\n`,
      "utf-8",
    );

    // Drive the dev pipeline directly: load -> enrich from API -> render
    const runnables = await loadRunnablesFromBackend(backendDir);
    expect(runnables.fetchUser?.type).toBe("path");
    expect(runnables.fetchUser?.runType).toBe("script");
    expect(runnables.fetchUser?.schema).toBeUndefined();

    const pathSchemas = await fetchPathRunnableSchemas(
      backend.workspace,
      runnables,
    );
    expect(pathSchemas.fetchUser).toBeDefined();
    expect(pathSchemas.fetchUser.properties.userId).toBeDefined();
    expect(pathSchemas.fetchUser.properties.includeProfile).toBeDefined();

    const ts = buildWmillTs(runnables, {}, pathSchemas);

    // Without the fix the line would be `fetchUser: (args: {}) => ...`
    expect(ts).toContain("userId");
    expect(ts).toContain("includeProfile");
    expect(ts).toMatch(/fetchUser:\s*\(args:\s*\{[^}]*userId/);
    expect(ts).not.toMatch(/fetchUser:\s*\(args:\s*\{\s*\}\)/);

    // Sanity: the generated d.ts is syntactically what the dev server writes
    const outPath = path.join(tempDir, "wmill.d.ts.out");
    fs.writeFileSync(outPath, ts);
    expect(fs.statSync(outPath).size).toBeGreaterThan(0);
  });
});

/**
 * Unit tests for `wmill app dev` wmill.d.ts generation.
 *
 * Two regressions covered:
 *
 *  1. Path-based runnables (type: script / flow) used to lose their schema and
 *     always render as `args: {}` in wmill.d.ts. Verified by feeding a
 *     fixture-supplied schema through the load -> override -> generate pipeline.
 *
 *  2. Inline runnables stored in the new backend-folder format (a `*.yaml`
 *     declaring `type: inline` plus a sibling code file) used to bail out of
 *     `inferRunnableSchemaFromFile` because the YAML no longer carries an
 *     `inlineScript` block. Verified by inferring a real schema from a TS file
 *     in that layout and confirming the generated wmill.d.ts uses it.
 *
 * These tests run without a backend - they exercise the local pipeline only.
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import { loadRunnablesFromBackend } from "../src/commands/app/raw_apps.ts";
