import { expect, test } from "bun:test";
import { withTestBackend } from "./test_backend.ts";
import { addWorkspace } from "../workspace.ts";
import * as path from "node:path";
import { writeFile, readdir, stat, rm } from "node:fs/promises";
import { getFolderSuffix, getMetadataFileName } from "../src/utils/resource_folders.ts";

// =============================================================================
// APP INLINE SCRIPT DELETION TESTS
// Regression tests for: deleting inline script files within .app/ folders
// during sync push should re-push the app, not crash with TypeError.
// =============================================================================

async function fileExists(filePath: string): Promise<boolean> {
  try {
    await stat(filePath);
    return true;
  } catch {
    return false;
  }
}

test("App: delete inline script file and push does not crash", async () => {
  await withTestBackend(async (backend, tempDir) => {
    const testWorkspace = {
      remote: backend.baseUrl,
      workspaceId: backend.workspace,
      name: "app_inline_delete_test",
      token: backend.token,
    };
    await addWorkspace(testWorkspace, {
      force: true,
      configDir: backend.testConfigDir,
    });

    await writeFile(
      `${tempDir}/wmill.yaml`,
      `defaultTs: bun\nincludes:\n  - "**"\nexcludes: []`,
      "utf-8"
    );

    // Create an app with an inline script via the API
    const appPath = "f/test/inline_delete_app";
    const inlineContent = `export async function main() {\n  return "hello";\n}`;

    // Create the folder first
    await backend.apiRequest!(
      `/api/w/${backend.workspace}/folders/create`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: "test" }),
      }
    ).then((r) => r.text());

    await backend.createAppWithInlineScript!(appPath, inlineContent, "bun");

    // =========================================================================
    // STEP 1: Pull — get the app folder with inline script files
    // =========================================================================
    const pullResult1 = await backend.runCLICommand(
      ["sync", "pull", "--yes"],
      tempDir,
      "app_inline_delete_test"
    );
    expect(pullResult1.code).toEqual(0);

    // Find the app folder and its inline script files
    const appSuffix = getFolderSuffix("app");
    const appDir = path.join(tempDir, appPath + appSuffix);
    expect(await fileExists(appDir)).toBeTruthy();

    // List files in the app folder to find inline script files
    const appFiles = await readdir(appDir);
    const inlineScriptFiles = appFiles.filter(
      (f) => f.endsWith(".ts") || f.endsWith(".js")
    );
    expect(inlineScriptFiles.length).toBeGreaterThan(0);

    const inlineScriptPath = path.join(appDir, inlineScriptFiles[0]);
    expect(await fileExists(inlineScriptPath)).toBeTruthy();

    const metadataFile = getMetadataFileName("app", "yaml");
    const appYamlPath = path.join(appDir, metadataFile);

    // =========================================================================
    // STEP 2: Remove the inline script from app.yaml and delete the .ts file
    // =========================================================================
    // Replace the inline script with a static text component (no inline scripts)
    const updatedAppYaml = `summary: Test app with inline script
value:
  type: app
  grid:
    - id: text1
      data:
        type: textcomponent
        componentInput:
          type: static
          value: hello world
  hiddenInlineScripts: []
  css: {}
  norefreshbar: false
policy:
  on_behalf_of: null
  on_behalf_of_email: null
  triggerables: {}
  execution_mode: viewer
`;
    await writeFile(appYamlPath, updatedAppYaml, "utf-8");

    // Delete the inline script file
    await rm(inlineScriptPath);
    expect(await fileExists(inlineScriptPath)).toBeFalsy();

    // Also delete any lock files for the inline script
    for (const f of appFiles) {
      if (f.endsWith(".lock")) {
        await rm(path.join(appDir, f));
      }
    }

    // =========================================================================
    // STEP 3: Push — should succeed, NOT crash with TypeError
    // =========================================================================
    const pushResult = await backend.runCLICommand(
      ["sync", "push", "--yes"],
      tempDir,
      "app_inline_delete_test"
    );

    // The critical assertion: push should not crash
    expect(pushResult.code).toEqual(0);

    // =========================================================================
    // STEP 4: Verify by pulling again — inline script should be gone
    // =========================================================================
    await rm(appDir, { recursive: true });

    const pullResult2 = await backend.runCLICommand(
      ["sync", "pull", "--yes"],
      tempDir,
      "app_inline_delete_test"
    );
    expect(pullResult2.code).toEqual(0);

    // App should still exist
    expect(await fileExists(appDir)).toBeTruthy();

    // But no inline script files should be present
    const finalFiles = await readdir(appDir);
    const finalInlineScripts = finalFiles.filter(
      (f) =>
        (f.endsWith(".ts") || f.endsWith(".js")) &&
        f.includes("inline_script")
    );
    expect(finalInlineScripts.length).toEqual(0);
  });
});

/**
 * Unit tests for stable auto-numbered inline-script naming in apps.
 *
 * Bug: when an app has multiple components that share the same runnable
 * `name` (e.g. several "Eval of b" cells), the path-assigner auto-numbers
 * them (`eval_of_b`, `eval_of_b_1`, …) in traversal order. Before the fix,
 * traversal walked the in-memory `Object.entries` order returned by
 * `JSON.parse` — i.e. whatever key order the server happened to send —
 * while the YAML output sorted keys via `yamlOptions.sortMapEntries`. The
 * two orders could disagree, so identically named scripts ended up with
 * numbers that didn't line up with their position in `app.yaml` and could
 * shuffle between pulls when the server returned keys in a different
 * order.
 *
 * Fix: traverse with `yamlSortedEntries`, which sorts plain-object keys
 * with the same comparator as YAML output (and preserves array order).
 * Names are then assigned in the order the scripts will appear on disk,
 * making them deterministic across pulls.
 *
 * No backend required — tests the extractor directly.
 */

import { expect, test, describe } from "bun:test";
import {
  extractInlineScriptsForApps,
  yamlOptions,
} from "../src/commands/sync/sync.ts";
import { newPathAssigner } from "../windmill-utils-internal/src/path-utils/path-assigner.ts";
import { stringify as yamlStringify } from "yaml";

function makeEvalCell(name: string, expr: string) {
  return {
    componentInput: {
      type: "evalv2",
      expr,
      runnable: {
        name,
        inlineScript: {
          content: "return JSON.stringify(freezeTable.selectedRow, null, 2)",
          language: "frontend",
        },
      },
    },
  };
}

function buildAppValue(subgridKeysInOrder: string[]) {
  const subgrids: Record<string, any[]> = {};
  for (const key of subgridKeysInOrder) {
    subgrids[key] = [
      {
        id: `${key}_text`,
        data: makeEvalCell("Eval of b", `JSON.stringify(${key}.selectedRow)`),
      },
    ];
  }
  return { subgrids };
}

describe("extractInlineScriptsForApps — stable auto-numbered naming", () => {
  test("auto-numbered names match YAML output order, not server insertion order", () => {
    // Server returns subgrids with keys in non-alphabetical order — e.g.
    // "r-0" before "pendingContainer-0". This is the order the user reports
    // in their bug repro.
    const value = buildAppValue([
      "b-0",
      "d-0",
      "g-0",
      "n-0",
      "r-0",
      "pendingContainer-0",
    ]);

    const scripts = extractInlineScriptsForApps(
      undefined,
      value,
      newPathAssigner("bun"),
      (_, val) => val["name"],
      false,
    );

    // Names assigned in YAML output order (alphabetical via prioritizeName):
    //   b-0, d-0, g-0, n-0, pendingContainer-0, r-0
    const paths = scripts.map((s) => s.path);
    expect(paths).toEqual([
      "eval_of_b.inline_script.frontend.js",
      "eval_of_b_1.inline_script.frontend.js",
      "eval_of_b_2.inline_script.frontend.js",
      "eval_of_b_3.inline_script.frontend.js",
      "eval_of_b_4.inline_script.frontend.js", // pendingContainer-0
      "eval_of_b_5.inline_script.frontend.js", // r-0
    ]);
  });

  test("naming is identical regardless of server insertion order", () => {
    const insertionOrders = [
      ["b-0", "d-0", "g-0", "n-0", "r-0", "pendingContainer-0"],
      ["pendingContainer-0", "r-0", "b-0", "d-0", "g-0", "n-0"],
      ["r-0", "n-0", "g-0", "d-0", "pendingContainer-0", "b-0"],
    ];

    const refRefs: Record<string, string> = {};
    for (const order of insertionOrders) {
      const value = buildAppValue(order);
      extractInlineScriptsForApps(
        undefined,
        value,
        newPathAssigner("bun"),
        (_, val) => val["name"],
        false,
      );
      // After extraction, every cell's inlineScript.content has been
      // rewritten to "!inline <path>". Capture (subgridKey -> ref) so we
      // can compare across runs.
      const refs: Record<string, string> = {};
      for (const [subgridKey, items] of Object.entries(
        value.subgrids as Record<string, any[]>,
      )) {
        refs[subgridKey] = items[0].data.componentInput.runnable.inlineScript
          .content as string;
      }
      if (Object.keys(refRefs).length === 0) {
        Object.assign(refRefs, refs);
      } else {
        // Same subgrid must always get the same !inline reference,
        // regardless of which order the server returned the keys.
        expect(refs).toEqual(refRefs);
      }
    }
  });

  test("inline reference for each subgrid lines up with its YAML position", () => {
    const value = buildAppValue([
      "b-0",
      "d-0",
      "g-0",
      "n-0",
      "r-0",
      "pendingContainer-0",
    ]);
    extractInlineScriptsForApps(
      undefined,
      value,
      newPathAssigner("bun"),
      (_, val) => val["name"],
      false,
    );

    // After extraction, stringify with the same yamlOptions used in the
    // pull pipeline. The auto-numbered file references must appear in
    // sequential order (0, 1, 2, …) when read top-to-bottom.
    const yaml = yamlStringify(value, yamlOptions);
    const refs = [
      ...yaml.matchAll(/!inline (eval_of_b(?:_\d+)?)\.inline_script\.frontend\.js/g),
    ].map((m) => m[1]);
    expect(refs).toEqual([
      "eval_of_b",
      "eval_of_b_1",
      "eval_of_b_2",
      "eval_of_b_3",
      "eval_of_b_4",
      "eval_of_b_5",
    ]);
  });

  test("array order within a subgrid is preserved (not sorted)", () => {
    // Two cells with the same name in array order [zebra, apple]. Array
    // entries must keep their index order — sorting them would reorder
    // visible UI elements.
    const value = {
      grid: [
        {
          id: "zebra",
          data: makeEvalCell("Eval of b", "zebra.selectedRow"),
        },
        {
          id: "apple",
          data: makeEvalCell("Eval of b", "apple.selectedRow"),
        },
      ],
    };
    const scripts = extractInlineScriptsForApps(
      undefined,
      value,
      newPathAssigner("bun"),
      (_, val) => val["name"],
      false,
    );
    expect(scripts.map((s) => s.path)).toEqual([
      "eval_of_b.inline_script.frontend.js", // zebra (array index 0)
      "eval_of_b_1.inline_script.frontend.js", // apple (array index 1)
    ]);
  });
});

/**
 * The raw-app bundle job carries the frontend's policy derivation, vendored by
 * cli/generate-app-policy.ts into backend/windmill-api/src/apps_raw_policy.gen.js
 * and prepended to the job script.
 *
 * If that copy drifts from the frontend source, deployed apps get policy keys
 * the app editor would not have written, and every runnable is refused at run
 * time with "forbidden by policy" — an app that deploys and then does nothing.
 * So rebuild the bundle here and fail when the committed one no longer matches.
 * Fix by running `bun run gen:app-policy` from cli/.
 *
 * No backend required.
 */

import { expect, test, describe } from "bun:test";
import { readFileSync } from "node:fs";
import { buildAppPolicyBundle, OUT_FILE } from "../generate-app-policy.ts";

describe("raw app policy bundle", () => {
  test("the committed bundle matches the frontend source", async () => {
    // Line endings normalized: a CRLF checkout is the same bundle, and must not
    // read as drift (the committed file's header arrives as CRLF on Windows).
    const lf = (s: string) => s.replace(/\r\n/g, "\n");
    expect(lf(readFileSync(OUT_FILE, "utf-8"))).toBe(
      lf(await buildAppPolicyBundle()),
    );
  });

  test("derives the keys the app editor writes", async () => {
    // Exercise the committed artifact itself, not the frontend module: it is
    // what actually runs on the worker.
    // A module's top-level `var` is not a global, and the job prepends this
    // bundle into its own module, so reach the binding the same way it does.
    const { updateRawAppPolicy } = new Function(
      `${readFileSync(OUT_FILE, "utf-8")}\nreturn __wmillAppPolicy`,
    )();

    const content = "export async function main(a: string) { return a }\n";
    const sha = new Bun.CryptoHasher("sha256").update(content).digest("hex");

    const policy = await updateRawAppPolicy(
      {
        inline: {
          type: "inline",
          inlineScript: { content, language: "bun" },
          fields: {
            pinned: { type: "static", value: "by-the-publisher" },
            secret: { type: "static", value: "shh", sensitive: true },
          },
        },
        by_flow: { type: "path", runType: "flow", path: "u/admin/f", fields: {} },
      },
      undefined,
    );

    expect(Object.keys(policy.triggerables_v2).sort()).toEqual([
      "by_flow:flow/u/admin/f",
      `inline:rawscript/${sha}`,
    ]);
    // `sensitive_inputs` is what makes the server encrypt the arg before it
    // reaches the job, so losing it would silently store the value in plaintext.
    const inline = policy.triggerables_v2[`inline:rawscript/${sha}`];
    expect(inline.static_inputs).toEqual({
      pinned: "by-the-publisher",
      secret: "shh",
    });
    expect(inline.sensitive_inputs).toEqual(["secret"]);
  });
});

