          console.warn(`Could not fetch details for script ${script.path}: ${detailResponse.status}`);
          scriptsWithContent.push(script);
        }
      } catch (error) {
        console.warn(`Error fetching script ${script.path}:`, error);
        scriptsWithContent.push(script);
      }
    }

    return scriptsWithContent;
  }

