  // Private helper methods

  private async waitForHealthy(): Promise<void> {
    console.log('⏳ Waiting for containers to be healthy...');

    const maxAttempts = 30;
    let attempts = 0;

    while (attempts < maxAttempts) {
      const result = await runCommand('docker', ['compose', '-f', this.config.composeFile, 'ps', '--format', 'json'], {
        env: {
          ...(process.env.EE_LICENSE_KEY && { EE_LICENSE_KEY: process.env.EE_LICENSE_KEY })
        }
      });

      if (result.code === 0) {
        const output = result.stdout;
        if (output.trim()) {
          const containers = output.trim().split('\n').map(line => JSON.parse(line));

          const allHealthy = containers.every(container => 
            container.State === 'running' && 
            (container.Health === 'healthy' || container.Health === '' || container.Health === undefined)
          );

          if (allHealthy) {
            return;
          }
        }
      }

      attempts++;
      await new Promise(resolve => setTimeout(resolve, 2000));
    }

    throw new Error('Containers failed to become healthy within timeout');
  }

  private async waitForAPI(): Promise<void> {
    console.log('⏳ Waiting for API to be responsive...');

    const maxAttempts = 30;
    let attempts = 0;

    while (attempts < maxAttempts) {
      try {
        const response = await fetch(`${this.config.baseUrl}/api/version`, {
          signal: AbortSignal.timeout(5000)
        });

        if (response.ok) {
          const version = await response.text();
          console.log(`📡 API ready (version: ${version})`);
          return;
        } else {
          // Consume response body even on non-OK responses to avoid leak
          await response.text();
        }
      } catch (error) {
        // Continue trying
      }

      attempts++;
      await new Promise(resolve => setTimeout(resolve, 2000));
    }

    throw new Error('API failed to respond within timeout');
  }

  /**
   * Quick health check for the backend
   */
  async checkHealth(): Promise<void> {
    try {
      const response = await fetch(`${this.config.baseUrl}/api/version`);
      if (!response.ok) {
        throw new Error(`Health check failed: ${response.status}`);
      }
      await response.text(); // Consume response to avoid leak
    } catch (error) {
      throw new Error(`Backend health check failed: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

}

// Global backend instance for persistent containers
let globalBackend: ContainerizedBackend | null = null;

// Convenience function for tests with persistent backend
export async function withContainerizedBackend<T>(
  testFn: (backend: ContainerizedBackend, tempDir: string) => Promise<T>
): Promise<T> {
  // Reuse global backend if it exists and is healthy
  if (!globalBackend) {
    globalBackend = new ContainerizedBackend();
    await globalBackend.start();
  } else {
    // Quick health check
    try {
      await globalBackend.checkHealth();
    } catch {
      // Backend is unhealthy, restart it
      await globalBackend.stop();
      globalBackend = new ContainerizedBackend();
      await globalBackend.start();
    }
  }

  const tempDir = await mkdtemp(join(tmpdir(), 'windmill_cli_test_'));

  try {
    await globalBackend.reset();
    await globalBackend.seedTestData();

    return await testFn(globalBackend, tempDir);
  } finally {
    await rm(tempDir, { recursive: true });
  }
}

// Cleanup function for test suites
export async function cleanupGlobalBackend(): Promise<void> {
  if (globalBackend) {
    await globalBackend.stop();
    globalBackend = null;
  }
}

/**
 * Unit tests for datatable-migration path parsing and local validation.
 *
 * These exercise pure logic with no backend:
 *  - `parseDatatableMigrationPath` recognizes only the
 *    `migrations/datatable/<dt>/<timestamp>_<name>.(up|down).sql` shape.
 *  - `validateLocalMigrations` rejects the two invalid on-disk states a push
 *    must catch: two up (or two down) files sharing a timestamp, and a
 *    `.down.sql` with no matching `.up.sql`.
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import { parseDatatableMigrationPath } from "../src/types.ts";
import { validateLocalMigrations } from "../src/commands/datatable_migrations.ts";
import { untrackedDatatableMigrationDeletions } from "../src/commands/sync/sync.ts";

describe("parseDatatableMigrationPath", () => {
  test("parses up and down files of the new layout", () => {
    expect(
      parseDatatableMigrationPath(
        "migrations/datatable/mydt/20260101000001_create_users.up.sql",
      ),
    ).toEqual({
      datatable: "mydt",
      timestamp: 20260101000001,
      name: "create_users",
      kind: "up",
    });
    expect(
      parseDatatableMigrationPath(
        "migrations/datatable/my-dt/42_x.down.sql",
      ),
    ).toEqual({ datatable: "my-dt", timestamp: 42, name: "x", kind: "down" });
  });

  test("rejects unrelated, legacy and malformed paths", () => {
    for (
      const p of [
        // legacy top-level layout
        "datatable_migrations/mydt/20260101000001_x.up.sql",
        // wrong sub-namespace / depth
        "migrations/ducklake/mydt/1_x.up.sql",
        "migrations/datatable/1_x.up.sql",
        "migrations/datatable/mydt/sub/1_x.up.sql",
        // not a migration file
        "migrations/datatable/mydt/notes.txt",
        "migrations/datatable/mydt/x.up.sql", // no numeric timestamp prefix
        // unrelated workspace files
        "f/foo/bar.script.yaml",
        "u/admin/script.ts",
      ]
    ) {
      expect(parseDatatableMigrationPath(p)).toBeUndefined();
    }
  });
});

describe("validateLocalMigrations", () => {
  let prevCwd: string;
  let tmp: string;

  beforeEach(() => {
    prevCwd = process.cwd();
    tmp = fs.mkdtempSync(path.join(os.tmpdir(), "dtmig-"));
    process.chdir(tmp);
  });
  afterEach(() => {
    process.chdir(prevCwd);
    fs.rmSync(tmp, { recursive: true, force: true });
  });

  function write(datatable: string, file: string) {
    const dir = path.join(tmp, "migrations", "datatable", datatable);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, file), "-- sql\n");
  }

  test("accepts up+down pairs and up-only migrations", () => {
    write("mydt", "20260101000001_create_users.up.sql");
    write("mydt", "20260101000001_create_users.down.sql");
    write("mydt", "20260101000002_add_email.up.sql"); // down is optional
    expect(validateLocalMigrations()).toEqual([]);
  });

  test("flags two up files sharing a timestamp", () => {
    write("mydt", "20260101000003_foo.up.sql");
    write("mydt", "20260101000003_bar.up.sql");
    const errors = validateLocalMigrations();
    expect(errors.length).toBe(1);
    expect(errors[0]).toContain("20260101000003");
  });

  test("flags two down files sharing a timestamp", () => {
    write("mydt", "20260101000004_a.up.sql");
    write("mydt", "20260101000004_a.down.sql");
    write("mydt", "20260101000004_b.down.sql");
    const errors = validateLocalMigrations();
    // duplicate down + the b.down orphan (no b.up)
    expect(errors.some((e) => e.includes("down") && e.includes("20260101000004"))).toBe(true);
  });

  test("flags a down file with no matching up", () => {
    write("mydt", "20260101000005_orphan.down.sql");
    const errors = validateLocalMigrations();
    expect(errors.length).toBe(1);
    expect(errors[0]).toContain("20260101000005_orphan");
  });

  test("only validates the requested datatables", () => {
    write("bad", "20260101000006_x.up.sql");
    write("bad", "20260101000006_y.up.sql"); // duplicate, but in 'bad'
    write("good", "20260101000007_ok.up.sql");
    expect(validateLocalMigrations(new Set(["good"]))).toEqual([]);
    expect(validateLocalMigrations(new Set(["bad"])).length).toBe(1);
  });

  test("returns no errors when the migrations folder is absent", () => {
    expect(validateLocalMigrations()).toEqual([]);
  });
});

// =============================================================================
// untrackedDatatableMigrationDeletions — the push-side safety net.
//
// Migrations bypass the repo's path filters, so a clone made before they were
// synced sees every server-side migration as remote-only, and
// `pushMigrationFromDisk` reads a missing `.up.sql` as "delete it". What the repo
// has ever committed under migrations/datatable/ is the durable answer to "did we
// track this?" — the working tree is not, because creating a migration locally
// makes the directory appear without anything having been tracked.
// =============================================================================

describe("untrackedDatatableMigrationDeletions", () => {
  const A_UP = "migrations/datatable/mydb/20260101000000_a.up.sql";
  const A_DOWN = "migrations/datatable/mydb/20260101000000_a.down.sql";
  const changes = [
    { name: "deleted", path: A_UP },
    { name: "deleted", path: A_DOWN },
    { name: "deleted", path: "f/foo/bar.script.yaml" },
    { name: "added", path: "migrations/datatable/mydb/20260102000000_b.up.sql" },
  ];

  test("trusts a deletion the repository has committed before", () => {
    expect(
      untrackedDatatableMigrationDeletions(changes, { kind: "known", paths: new Set([A_UP, A_DOWN]) }),
    ).toEqual([]);
  });

  test("flags migrations this repository has never recorded", () => {
    expect(
      untrackedDatatableMigrationDeletions(changes, { kind: "known", paths: new Set() }).map((c) => c.path),
    ).toEqual([A_UP, A_DOWN]);
  });

  test("a locally created migration does not vouch for unrelated ones", () => {
    // `wmill datatable migrate new` makes migrations/datatable/ exist without the
    // checkout having tracked anything, so only the recorded paths count.
    const recorded = {
      kind: "known" as const,
      paths: new Set(["migrations/datatable/mydb/20260102000000_b.up.sql"]),
    };
    expect(
      untrackedDatatableMigrationDeletions(changes, recorded).map((c) => c.path),
    ).toEqual([A_UP, A_DOWN]);
  });

  test("trusts nothing when the history cannot be consulted", () => {
    // A shallow clone or a non-repository can't prove a path was never tracked,
    // so absence is not read as permission to delete.
    expect(
      untrackedDatatableMigrationDeletions(changes, {
        kind: "unknown",
        reason: "this is a shallow clone, so its history is truncated",
        remedy: "Fetch the full history (for actions/checkout, fetch-depth: 0)",
      }).map((c) => c.path),
    ).toEqual([A_UP, A_DOWN]);
  });
});

import { expect, test } from "bun:test";
import {
  buildBindComplete,
  buildCloseComplete,
  buildExecuteResponse,
  buildCommandComplete,
  buildDataRow,
  buildEmptyQueryResponse,
  buildNoData,
  buildParameterDescription,
  buildParseComplete,
  buildPortalSuspended,
  buildQueryResponse,
  buildReadyForQuery,
  buildRowDescription,
  type RawOutputEnvelope,
} from "../src/commands/datatable/pg_wire.ts";

// Postgres wire-protocol byte-level expectations. Every backend message is:
//   1 byte type | int32 length-including-itself | payload

test("buildReadyForQuery: 'Z' + len=5 + 'I'", () => {
  const buf = buildReadyForQuery("I");
  expect(Array.from(buf)).toEqual([
    0x5a, // 'Z'
    0, 0, 0, 5, // length = 4 (length field) + 1 (status)
    0x49, // 'I'
  ]);
});

test("buildCommandComplete: 'C' + tag + null terminator", () => {
  const buf = buildCommandComplete("SELECT 0");
  // 'C' + len(4) + 'SELECT 0'(8) + '\0'(1) → 13 bytes total, length field = 13
  expect(buf[0]).toBe(0x43);
  expect(buf.byteLength).toBe(14);
  expect(buf[buf.byteLength - 1]).toBe(0);
});

test("buildEmptyQueryResponse: 'I' + len=4", () => {
  const buf = buildEmptyQueryResponse();
  expect(Array.from(buf)).toEqual([0x49, 0, 0, 0, 4]);
});

test("buildParseComplete / BindComplete / CloseComplete / NoData / PortalSuspended: empty payload messages", () => {
  expect(Array.from(buildParseComplete())).toEqual([0x31, 0, 0, 0, 4]);
  expect(Array.from(buildBindComplete())).toEqual([0x32, 0, 0, 0, 4]);
  expect(Array.from(buildCloseComplete())).toEqual([0x33, 0, 0, 0, 4]);
  expect(Array.from(buildNoData())).toEqual([0x6e, 0, 0, 0, 4]);
  expect(Array.from(buildPortalSuspended())).toEqual([0x73, 0, 0, 0, 4]);
});

test("buildParameterDescription: count + OIDs", () => {
  const buf = buildParameterDescription([23, 25]);
  expect(buf[0]).toBe(0x74); // 't'
  expect((buf[5] << 8) | buf[6]).toBe(2);
  const firstOid =
    (buf[7] << 24) |
    (buf[8] << 16) |
    (buf[9] << 8) |
    buf[10];
  const secondOid =
    (buf[11] << 24) |
    (buf[12] << 16) |
    (buf[13] << 8) |
    buf[14];
  expect(firstOid).toBe(23);
  expect(secondOid).toBe(25);
});

test("buildRowDescription: encodes one column with given OID", () => {
  const buf = buildRowDescription([{ name: "id", oid: 23, type_name: "int4" }]);
  // 'T'(1) + len(4) + field_count(2) + name(2 + null=3) + tableOid(4) + attnum(2)
  // + typeOid(4) + typeSize(2) + atttypmod(4) + format(2) = 1 + 4 + 2 + 3 + 4 + 2 + 4 + 2 + 4 + 2 = 28
  expect(buf[0]).toBe(0x54); // 'T'
  expect(buf.byteLength).toBe(28);
  // field count INT16 starts at offset 5 (after type byte + length field)
  expect((buf[5] << 8) | buf[6]).toBe(1);
  // typeOid INT32 is at the end of the column header — at offset 28 - 2 - 4 - 2 - 4 = 16
  const typeOidOffset = 28 - 2 /* format */ - 4 /* typmod */ - 2 /* typesize */ - 4;
  const typeOid =
    (buf[typeOidOffset] << 24) |
    (buf[typeOidOffset + 1] << 16) |
    (buf[typeOidOffset + 2] << 8) |
    buf[typeOidOffset + 3];
  expect(typeOid).toBe(23);
});

test("buildDataRow: NULL cell is encoded as int32 -1, length 0 payload", () => {
  const buf = buildDataRow([null]);
  // 'D'(1) + len(4) + col_count(2) + col_length(4 = -1) = 11 bytes
  expect(Array.from(buf)).toEqual([
    0x44, // 'D'
    0, 0, 0, 10, // length field = 4 + 2 + 4
    0, 1, // col_count = 1
    0xff, 0xff, 0xff, 0xff, // -1 (NULL)
  ]);
});

test("buildDataRow: text cell carries UTF-8 bytes prefixed by length", () => {
  const buf = buildDataRow(["hi"]);
  expect(Array.from(buf)).toEqual([
    0x44,
    0, 0, 0, 12, // length = 4 + 2 + 4 + 2
    0, 1, // col count
    0, 0, 0, 2, // string length
    0x68, 0x69, // "hi"
  ]);
});

test("buildDataRow: mixed text + NULL in column order", () => {
  const buf = buildDataRow(["a", null, "bb"]);
  // 'D'(1) + len(4) + col_count(2) + (4 + 1) + 4 + (4 + 2) = 22
  expect(buf.byteLength).toBe(22);
  // col count
  expect((buf[5] << 8) | buf[6]).toBe(3);
  // First cell length=1, byte 'a' at offset 11
  expect(buf[11]).toBe(0x61);
  // Second cell is NULL: bytes 12-15 should be 0xff
  expect(buf[12]).toBe(0xff);
  expect(buf[15]).toBe(0xff);
  // Third cell length=2 at offset 16, bytes 'b','b' at 20-21
  expect(buf[20]).toBe(0x62);
  expect(buf[21]).toBe(0x62);
});

test("buildQueryResponse: empty envelope emits only CommandComplete + ReadyForQuery", () => {
  const envelope: RawOutputEnvelope = { columns: [], rows: [] };
  const buf = buildQueryResponse(envelope);
  // CommandComplete "SELECT 0" = 14 bytes, ReadyForQuery = 6 bytes
  expect(buf.byteLength).toBe(14 + 6);
  expect(buf[0]).toBe(0x43); // 'C'
  expect(buf[14]).toBe(0x5a); // 'Z'
});

test("buildQueryResponse: one column + one row emits T, D, C, Z in that order", () => {
  const envelope: RawOutputEnvelope = {
    columns: [{ name: "n", oid: 23, type_name: "int4" }],
    rows: [["42"]],
  };
  const buf = buildQueryResponse(envelope);
  const tagBytes: number[] = [];
  let off = 0;
  while (off < buf.byteLength) {
    tagBytes.push(buf[off]);
    const len = (buf[off + 1] << 24) | (buf[off + 2] << 16) | (buf[off + 3] << 8) | buf[off + 4];
    off += 1 + len;
  }
  expect(tagBytes).toEqual([0x54 /* T */, 0x44 /* D */, 0x43 /* C */, 0x5a /* Z */]);
});

test("buildExecuteResponse: emits T, D, C without ReadyForQuery", () => {
  const envelope: RawOutputEnvelope = {
    columns: [{ name: "n", oid: 23, type_name: "int4" }],
    rows: [["42"]],
  };
  const response = buildExecuteResponse(envelope);
  const tagBytes: number[] = [];
  let off = 0;
  while (off < response.message.byteLength) {
    tagBytes.push(response.message[off]);
    const len =
      (response.message[off + 1] << 24) |
      (response.message[off + 2] << 16) |
      (response.message[off + 3] << 8) |
      response.message[off + 4];
    off += 1 + len;
  }
  expect(response.suspended).toBe(false);
  expect(response.nextRowOffset).toBe(1);
  expect(tagBytes).toEqual([0x54 /* T */, 0x44 /* D */, 0x43 /* C */]);
});

test("buildExecuteResponse: maxRows suspends portal and omits CommandComplete", () => {
  const envelope: RawOutputEnvelope = {
    columns: [{ name: "n", oid: 23, type_name: "int4" }],
    rows: [["1"], ["2"]],
  };
  const response = buildExecuteResponse(envelope, { maxRows: 1 });
  const tagBytes: number[] = [];
  let off = 0;
  while (off < response.message.byteLength) {
    tagBytes.push(response.message[off]);
    const len =
      (response.message[off + 1] << 24) |
      (response.message[off + 2] << 16) |
      (response.message[off + 3] << 8) |
      response.message[off + 4];
    off += 1 + len;
  }
  expect(response.suspended).toBe(true);
  expect(response.nextRowOffset).toBe(1);
  expect(tagBytes).toEqual([0x54 /* T */, 0x44 /* D */, 0x73 /* s */]);
});

