import { expect, test } from "bun:test";
import { mkdtemp, rm } from "node:fs/promises";
import os from "node:os";
import * as path from "node:path";
import { DoubleLinkedDependencyTree } from "../src/utils/dependency_tree.ts";

// addNode consults wmill-lock.yaml from cwd for workspace deps; run inside a
// temp dir so the test never reads/writes the repo's own lock file.
async function withTempDir(
  fn: () => Promise<void>,
): Promise<void> {
  const tempDir = await mkdtemp(path.join(os.tmpdir(), "wmill_deptree_test_"));
  const originalCwd = process.cwd();
  try {
    process.chdir(tempDir);
    await fn();
  } finally {
    process.chdir(originalCwd);
    await rm(tempDir, { recursive: true });
  }
}

async function buildTree(): Promise<DoubleLinkedDependencyTree> {
  const tree = new DoubleLinkedDependencyTree();
  // main imports lib; other is unrelated
  await tree.addNode(
    "f/test/main",
    `import { x } from "./lib.ts"`,
    "bun",
    "",
    ["f/test/lib"],
    "script",
    "f/test/main",
    "f/test/main.ts",
    true,
  );
  await tree.addNode(
    "f/test/lib",
    "export const x = 1",
    "bun",
    "",
    [],
    "script",
    "f/test/lib",
    "f/test/lib.ts",
    true,
  );
  await tree.addNode(
    "f/other/standalone",
    "export const y = 2",
    "bun",
    "",
    [],
    "script",
    "f/other/standalone",
    "f/other/standalone.ts",
    true,
  );
  return tree;
}

test("getAllTempScriptRefs returns refs for every uploaded node", async () => {
  await withTempDir(async () => {
    const tree = await buildTree();
    // Simulate uploadScripts marking all three as uploaded
    tree.setContentHash("f/test/main", "hash_main");
    tree.setContentHash("f/test/lib", "hash_lib");
    tree.setContentHash("f/other/standalone", "hash_standalone");

    expect(tree.getAllTempScriptRefs()).toEqual({
      "f/test/main": "hash_main",
      "f/test/lib": "hash_lib",
      "f/other/standalone": "hash_standalone",
    });
  });
});

test("getAllTempScriptRefs skips nodes without a content hash", async () => {
  await withTempDir(async () => {
    const tree = await buildTree();
    // Only lib diverged from deployed
    tree.setContentHash("f/test/lib", "hash_lib");

    expect(tree.getAllTempScriptRefs()).toEqual({ "f/test/lib": "hash_lib" });
  });
});

test("getAllTempScriptRefs is a superset of getTempScriptRefs for any node", async () => {
  await withTempDir(async () => {
    const tree = await buildTree();
    tree.setContentHash("f/test/lib", "hash_lib");
    tree.setContentHash("f/other/standalone", "hash_standalone");

    const all = tree.getAllTempScriptRefs();
    for (const node of ["f/test/main", "f/test/lib", "f/other/standalone"]) {
      const perNode = tree.getTempScriptRefs(node);
      for (const [k, v] of Object.entries(perNode)) {
        expect(all[k]).toBe(v);
      }
    }
    // And the per-node view of main only sees its own transitive import
    expect(tree.getTempScriptRefs("f/test/main")).toEqual({
      "f/test/lib": "hash_lib",
    });
  });
});

import { expect, test } from "bun:test";
import { deployItem } from "../windmill-utils-internal/src/deploy.ts";

// `deployItem` spreads the source item into the request body, and a script's/flow's
// on_behalf_of names a username that only exists in the source
// workspace. Sending it to the target pairs one workspace's principal with the other's
// email, which the backend rejects. Deleting the spread is an easy regression, so pin
// that the key never reaches the wire.
function recordingProvider(captured: [string, any][], flowExists: boolean) {
  const source = {
    on_behalf_of_email: "alice@corp",
    on_behalf_of: "u/alice",
  };
  return {
    existsFlowByPath: async () => flowExists,
    existsScriptByPath: async () => true,
    getFlowByPath: async () => ({
      path: "f/x/f",
      summary: "",
      value: { modules: [] },
      ...source,
    }),
    createFlow: async (p: any) => void captured.push(["createFlow", p.requestBody]),
    updateFlow: async (p: any) => void captured.push(["updateFlow", p.requestBody]),
    getScriptByPath: async () => ({
      path: "f/x/s",
      summary: "",
      content: "x",
      language: "bun",
      hash: "abc",
      ...source,
    }),
    createScript: async (p: any) =>
      void captured.push(["createScript", p.requestBody]),
  } as any;
}

test("deployItem: never sends the source workspace's on_behalf_of", async () => {
  const captured: [string, any][] = [];

  // The clear is written out once per branch, so exercise all three: a flow that
  // does not exist in the target (create), one that does (update — the branch
  // `wmill workspace merge` takes for anything already deployed), and a script.
  await deployItem(
    recordingProvider(captured, false),
    "flow" as any,
    "f/x/f",
    "src",
    "dst",
    "alice@corp",
  );
  await deployItem(
    recordingProvider(captured, true),
    "flow" as any,
    "f/x/f",
    "src",
    "dst",
    "alice@corp",
  );
  await deployItem(
    recordingProvider(captured, false),
    "script" as any,
    "f/x/s",
    "src",
    "dst",
    "alice@corp",
  );

  expect(captured.map(([fn]) => fn)).toEqual([
    "createFlow",
    "updateFlow",
    "createScript",
  ]);
  for (const [, body] of captured) {
    // The email is still overridden with the caller's choice...
    expect(body.on_behalf_of_email).toBe("alice@corp");
    expect(body.preserve_on_behalf_of).toBe(true);
    // ...while the principal is dropped, so the backend derives the target's own.
    expect(
      "on_behalf_of" in JSON.parse(JSON.stringify(body)),
    ).toBe(false);
  }
});

/**
 * The recorder `wmill app dev --recording` serves is generated from the
 * frontend's raw-app recorder, not written here, so it can silently ship a stale
 * event model after that recorder changes. The committed bundle records the
 * sources it was built from and their hash; this fails when they no longer
 * agree.
 *
 * Fix a failure with `bun run gen:dev-recorder` from cli/.
 */

import { describe, expect, test } from "bun:test";
import * as fs from "node:fs";
import * as path from "node:path";
import { hashRecorderSources } from "../generate-dev-recorder.ts";
import {
  DEV_RECORDER_BUNDLE,
  DEV_RECORDER_SOURCE_HASH,
  DEV_RECORDER_SOURCES,
} from "../src/commands/app/devRecorderBundle.gen.ts";

const REPO_ROOT = path.join(import.meta.dir, "..", "..");

describe("dev recorder bundle", () => {
  test("exposes the recorder factory as a global", () => {
    expect(DEV_RECORDER_BUNDLE).toContain("__wmillRecorder");
    expect(DEV_RECORDER_BUNDLE).toContain("createRawAppRecording");
    // Runes are stripped at generation; one left in would throw at load time.
    expect(DEV_RECORDER_BUNDLE).not.toContain("$state");
  });

  test("is up to date with the frontend recorder", () => {
    expect(DEV_RECORDER_SOURCES.length).toBeGreaterThan(0);
    const present = DEV_RECORDER_SOURCES.every((f) =>
      fs.existsSync(path.join(REPO_ROOT, f))
    );
    // The published CLI package ships without the frontend sources.
    if (!present) return;
