import { describe, expect, test } from "bun:test";
import {
  branchToForkId,
  validateForkWorkspaceId,
} from "../src/commands/workspace/fork.ts";

describe("branchToForkId — branch name → fork workspace id slug", () => {
  test.each<[string, string]>([
    ["feature-x", "feature-x"],
    ["my_feature", "my_feature"],
    // `/` (common in branch names) must not survive — it would break the
    // wm-fork/<base>/<id> branch-name parsing.
    ["feat/foo", "feat-foo"],
    ["feature/JIRA-123", "feature-JIRA-123"],
    ["a/b/c", "a-b-c"],
    // Other invalid characters collapse to a single dash.
    ["hot fix!", "hot-fix"],
    ["weird@@name", "weird-name"],
    // Leading/trailing separators are trimmed.
    ["/leading", "leading"],
    ["trailing/", "trailing"],
    ["--dashes--", "dashes"],
    // Degenerate input falls back to a usable id.
    ["///", "fork"],
    ["", "fork"],
  ])("%p → %p", (branch, expected) => {
    expect(branchToForkId(branch)).toBe(expected);
  });

  test("result never contains a slash (would break fork branch parsing)", () => {
    for (const branch of ["a/b", "x/y/z", "feat/foo/bar"]) {
      expect(branchToForkId(branch)).not.toContain("/");
    }
  });

  test("caps the slug so wm-fork-<slug> stays within the backend's 50-char limit", () => {
    const long = "feature/TICKET-1234-" + "a".repeat(80);
    const slug = branchToForkId(long);
    expect(slug.length).toBeLessThanOrEqual(42);
    // The full id the backend validates is `wm-fork-<slug>`.
    expect(`wm-fork-${slug}`.length).toBeLessThanOrEqual(50);
    // Truncation must not leave a trailing dash.
    expect(slug.endsWith("-")).toBe(false);
  });
});

describe("validateForkWorkspaceId — mirrors backend validate_fork_workspace_id", () => {
  test("accepts a normal slugged id", () => {
    expect(() => validateForkWorkspaceId("wm-fork-feature-x")).not.toThrow();
  });

  test.each<[string, string]>([
    ["too long (> 50 chars)", "wm-fork-" + "a".repeat(60)],
    ["ends with '.'", "wm-fork-foo."],
    ["ends with '.lock'", "wm-fork-foo.lock"],
    ["contains '..'", "wm-fork-foo..bar"],
    ["contains '//'", "wm-fork-foo//bar"],
    ["contains a space", "wm-fork-foo bar"],
    ["contains a forbidden char", "wm-fork-foo~bar"],
  ])("rejects: %s", (_label, id) => {
    expect(() => validateForkWorkspaceId(id)).toThrow();
  });

  test("a branchToForkId slug always passes validation (with the prefix)", () => {
    for (const branch of [
      "feat/foo",
      "feature/TICKET-1234-" + "a".repeat(80),
      "weird@@name",
      "///",
    ]) {
      const id = `wm-fork-${branchToForkId(branch)}`;
      expect(() => validateForkWorkspaceId(id)).not.toThrow();
    }
  });
});

import { describe, expect, test } from "bun:test";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { execSync } from "node:child_process";
import os from "node:os";
import path from "node:path";
import { stringify as yamlStringify } from "yaml";

import { tryResolveBranchWorkspace } from "../src/core/context.ts";
import { setLastUsedProfile } from "../src/core/branch-profiles.ts";
import { getWorkspaceConfigFilePath } from "../windmill-utils-internal/src/config/config.ts";
import type { GlobalOptions } from "../src/types.ts";
import type { Workspace } from "../src/commands/workspace/workspace.ts";

const BASE_URL = "http://localhost:9999/";
const PARENT_WORKSPACE_ID = "parent";

// Fork-branch workspace resolution: every profile-selection path in
// tryResolveBranchWorkspace must rewrite the returned profile to the fork
// workspace id derived from the wm-fork/<base>/<id> branch — a path that
// returns the parent profile untouched silently targets the parent workspace.
async function withForkBranchSetup(
  profiles: Workspace[],
  fn: (opts: GlobalOptions) => Promise<void>,
): Promise<void> {
  const repoDir = await mkdtemp(path.join(os.tmpdir(), "wmill_fork_repo_"));
  const configDir = await mkdtemp(path.join(os.tmpdir(), "wmill_fork_conf_"));
  const originalCwd = process.cwd();
  try {
    execSync(`git init -q -b wm-fork/main/myfork`, { cwd: repoDir });
    execSync(`git config user.email test@example.com`, { cwd: repoDir });
    execSync(`git config user.name test`, { cwd: repoDir });

    await writeFile(
      path.join(repoDir, "wmill.yaml"),
      yamlStringify({
        workspaces: {
          main: { baseUrl: BASE_URL, workspaceId: PARENT_WORKSPACE_ID },
        },
      }),
    );
    execSync(`git add wmill.yaml && git commit -q -m init`, { cwd: repoDir });

    const remotesPath = await getWorkspaceConfigFilePath(configDir);
    await writeFile(
      remotesPath,
      profiles.map((p) => JSON.stringify(p)).join("\n") + "\n",
    );

    process.chdir(repoDir);
    await fn({ configDir } as GlobalOptions);
  } finally {
    process.chdir(originalCwd);
    await rm(repoDir, { recursive: true, force: true });
    await rm(configDir, { recursive: true, force: true });
  }
}

function profile(name: string): Workspace {
  return {
    name,
    remote: BASE_URL,
    workspaceId: PARENT_WORKSPACE_ID,
    token: `token-${name}`,
  };
}

describe("tryResolveBranchWorkspace on a fork branch", () => {
  test("single matching profile targets the fork workspace", async () => {
    await withForkBranchSetup([profile("prod")], async (opts) => {
      const ws = await tryResolveBranchWorkspace(opts);
      expect(ws?.workspaceId).toEqual("wm-fork-myfork");
      expect(ws?.token).toEqual("token-prod");
    });
  });

  test("last-used profile among multiple still targets the fork workspace", async () => {
    await withForkBranchSetup(
      [profile("prod"), profile("prod-alt")],
      async (opts) => {
        await setLastUsedProfile(
          "main",
          BASE_URL,
          PARENT_WORKSPACE_ID,
          "prod-alt",
          opts.configDir,
        );
        const ws = await tryResolveBranchWorkspace(opts);
        expect(ws?.workspaceId).toEqual("wm-fork-myfork");
        expect(ws?.token).toEqual("token-prod-alt");
      },
    );
  });
});

import { expect, test } from "bun:test";
import { withTestBackend, type TestBackend } from "./test_backend.ts";

// =============================================================================
// FORK & MERGE INTEGRATION TESTS
//
// Tests the full fork/merge cycle using a single test backend instance.
// All sub-tests share the same backend to avoid workspace-limit issues
// (CE limits to 2 non-admins workspaces).
//
// workspace_diff tracking is an EE feature (populated by git sync).
// We manually insert rows into workspace_diff to simulate what git sync
// does, matching the pattern in backend/.../workspace_comparison.rs.
// =============================================================================

const FORK_ID = "wm-fork-merge-test";

async function api(
  backend: TestBackend,
  path: string,
  options: RequestInit = {}
): Promise<Response> {
  return backend.apiRequest!(path, options);
}

async function runSQL(backend: TestBackend, query: string): Promise<void> {
  const dbUrl =
    process.env["DATABASE_URL"] ||
    "postgres://postgres:changeme@localhost:5432";
  const proc = Bun.spawn(
    [
      "psql",
      `${dbUrl}/postgres?sslmode=disable`,
      "-t",
      "-c",
      `SELECT datname FROM pg_database WHERE datname LIKE 'windmill_test_%' ORDER BY datname DESC LIMIT 1`,
    ],
    { stdout: "pipe", stderr: "pipe" }
  );
  const dbName = (await new Response(proc.stdout).text()).trim();
  await proc.exited;
  if (!dbName) throw new Error("Could not find test database");

  const sqlProc = Bun.spawn(
    ["psql", `${dbUrl}/${dbName}?sslmode=disable`, "-c", query],
    { stdout: "pipe", stderr: "pipe" }
  );
  await sqlProc.exited;
}

async function populateWorkspaceDiff(
  backend: TestBackend,
  parentWs: string,
  forkWs: string,
  diffs: Array<{ path: string; kind: string; ahead: number; behind: number }>
): Promise<void> {
  const values = diffs
    .map(
      (d) =>
        `('${parentWs}', '${forkWs}', '${d.path}', '${d.kind}', ${d.ahead}, ${d.behind})`
    )
    .join(",\n");
  await runSQL(
    backend,
    `INSERT INTO workspace_diff (source_workspace_id, fork_workspace_id, path, kind, ahead, behind)
     VALUES ${values}
     ON CONFLICT (source_workspace_id, fork_workspace_id, path, kind)
     DO UPDATE SET ahead = EXCLUDED.ahead, behind = EXCLUDED.behind, has_changes = NULL`
  );
}

async function removeFromSkipTally(backend: TestBackend, workspaceId: string) {
  await runSQL(backend, `DELETE FROM skip_workspace_diff_tally WHERE workspace_id = '${workspaceId}'`);
}

async function deleteFork(backend: TestBackend, forkId: string) {
  try {
    await api(backend, `/api/w/${forkId}/workspaces/delete`, { method: "POST" });
  } catch {}
  // Force-clean via SQL to ensure workspace slot is freed (CE limits to 2)
  const esc = forkId.replace(/'/g, "''");
  await runSQL(backend, `
    SET session_replication_role = replica;
    DO $$ DECLARE r RECORD; BEGIN
      FOR r IN SELECT c.table_name FROM information_schema.columns c
        JOIN information_schema.tables t ON c.table_name = t.table_name AND c.table_schema = t.table_schema
        WHERE c.column_name = 'workspace_id' AND c.table_schema = 'public' AND t.table_type = 'BASE TABLE'
        GROUP BY c.table_name
      LOOP EXECUTE format('DELETE FROM %I WHERE workspace_id = ''${esc}''', r.table_name);
      END LOOP;
    END $$;
    DELETE FROM workspace WHERE id = '${esc}';
    DELETE FROM workspace_diff WHERE fork_workspace_id = '${esc}';
    DELETE FROM skip_workspace_diff_tally WHERE workspace_id = '${esc}';
    SET session_replication_role = DEFAULT;
  `);
}

async function createTestItems(backend: TestBackend, workspace: string) {
  await api(backend, `/api/w/${workspace}/folders/create`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
