      const comp6 = await (await api(backend, `/api/w/${parentWs}/workspaces/compare/${FORK_ID}`)).json();
      const ahead6 = comp6.diffs.filter((d: any) => d.ahead > 0);
      expect(ahead6.length).toBeGreaterThanOrEqual(3);

      // Deploy all
      for (const d of ahead6) {
        if (d.kind === "resource") {
          const r = await (await api(backend, `/api/w/${FORK_ID}/resources/get/${d.path}`)).json();
          await api(backend, `/api/w/${parentWs}/resources/update/${d.path}`, {
            method: "POST", headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ path: d.path, value: r.value, description: r.description ?? "" }),
          });
        } else if (d.kind === "flow") {
          const f = await (await api(backend, `/api/w/${FORK_ID}/flows/get/${d.path}`)).json();
          for (const m of f.value?.modules ?? []) { if (m.value?.hash) m.value.hash = undefined; }
          await api(backend, `/api/w/${parentWs}/flows/update/${d.path}`, {
            method: "POST", headers: { "Content-Type": "application/json" },
            body: JSON.stringify(f),
          });
        } else if (d.kind === "app") {
          const a = await (await api(backend, `/api/w/${FORK_ID}/apps/get/p/${d.path}`)).json();
          await api(backend, `/api/w/${parentWs}/apps/update/${d.path}`, {
            method: "POST", headers: { "Content-Type": "application/json" },
            body: JSON.stringify(a),
          });
        }
      }

      // Verify
      const pRes = await (await api(backend, `/api/w/${parentWs}/resources/get/f/merge_test/res_t6`)).json();
      expect(JSON.stringify(pRes.value)).toContain("fork");
      const pFlow = await (await api(backend, `/api/w/${parentWs}/flows/get/f/merge_test/flow_t6`)).json();
      expect(pFlow.value.modules[0].value.content).toContain("return 2");
      const pApp = await (await api(backend, `/api/w/${parentWs}/apps/get/p/f/merge_test/app_t6`)).json();
      expect(pApp.summary).toBe("Fork App");
      console.log("  ✓ Sub-test 6 passed: all item types merged");

      // ---------------------------------------------------------------
      // Sub-test 7: Secret variables preserved across fork/merge
      // ---------------------------------------------------------------
      console.log("\n--- Sub-test 7: secret variable ---");
      await api(backend, `/api/w/${FORK_ID}/variables/create`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: "f/merge_test/secret_fork", value: "s3cret!", is_secret: true, description: "Secret" }),
      });
      await populateWorkspaceDiff(backend, parentWs, FORK_ID, [
        { path: "f/merge_test/secret_fork", kind: "variable", ahead: 1, behind: 0 },
      ]);
      const comp7 = await (await api(backend, `/api/w/${parentWs}/workspaces/compare/${FORK_ID}`)).json();
      const secDiff = comp7.diffs.find((d: any) => d.path === "f/merge_test/secret_fork");
      expect(secDiff).toBeDefined();

      const secVar = await (await api(backend, `/api/w/${FORK_ID}/variables/get/f/merge_test/secret_fork?decrypt_secret=true`)).json();
      await api(backend, `/api/w/${parentWs}/variables/create`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: secVar.path, value: secVar.value ?? "", is_secret: secVar.is_secret, description: secVar.description ?? "" }),
      });
      const pSec = await (await api(backend, `/api/w/${parentWs}/variables/get/f/merge_test/secret_fork?decrypt_secret=true`)).json();
      expect(pSec.value).toBe("s3cret!");
      expect(pSec.is_secret).toBe(true);
      console.log("  ✓ Sub-test 7 passed: secret variable preserved");

      // ---------------------------------------------------------------
      // Sub-test 8: Special characters in variable values
      // ---------------------------------------------------------------
      console.log("\n--- Sub-test 8: special characters ---");
      await api(backend, `/api/w/${FORK_ID}/variables/create`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: "f/merge_test/special", value: "hello\nworld\t\"quotes\" 'single' \\back 日本語 🎉", is_secret: false, description: "" }),
      });
      await populateWorkspaceDiff(backend, parentWs, FORK_ID, [
        { path: "f/merge_test/special", kind: "variable", ahead: 1, behind: 0 },
      ]);
      const forkSpecial = await (await api(backend, `/api/w/${FORK_ID}/variables/get/f/merge_test/special?decrypt_secret=true`)).json();
      await api(backend, `/api/w/${parentWs}/variables/create`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: forkSpecial.path, value: forkSpecial.value ?? "", is_secret: false, description: "" }),
      });
      const pSpecial = await (await api(backend, `/api/w/${parentWs}/variables/get/f/merge_test/special?decrypt_secret=true`)).json();
      expect(pSpecial.value).toBe(forkSpecial.value);
      console.log("  ✓ Sub-test 8 passed: special characters preserved");

      // ---------------------------------------------------------------
      // Sub-test 9: Partial deploy — only deployed items cleaned by resetDiffTally
      // ---------------------------------------------------------------
      console.log("\n--- Sub-test 9: partial deploy + resetDiffTally ---");
      await api(backend, `/api/w/${FORK_ID}/variables/create`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: "f/merge_test/partial_a", value: "a", is_secret: false, description: "A" }),
      });
      await api(backend, `/api/w/${FORK_ID}/variables/create`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: "f/merge_test/partial_b", value: "b", is_secret: false, description: "B" }),
      });
      await populateWorkspaceDiff(backend, parentWs, FORK_ID, [
        { path: "f/merge_test/partial_a", kind: "variable", ahead: 1, behind: 0 },
        { path: "f/merge_test/partial_b", kind: "variable", ahead: 1, behind: 0 },
      ]);

      // Deploy only partial_a
      const va = await (await api(backend, `/api/w/${FORK_ID}/variables/get/f/merge_test/partial_a?decrypt_secret=true`)).json();
      await api(backend, `/api/w/${parentWs}/variables/create`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: va.path, value: va.value ?? "", is_secret: false, description: "" }),
      });

      await api(backend, `/api/w/${parentWs}/workspaces/reset_diff_tally/${FORK_ID}`, { method: "POST" });
      await new Promise(r => setTimeout(r, 500));
      const comp9 = await (await api(backend, `/api/w/${parentWs}/workspaces/compare/${FORK_ID}`)).json();
      const bAfter = comp9.diffs.find((d: any) => d.path === "f/merge_test/partial_b");
      // partial_b was NOT deployed, so it must still appear in diffs
      expect(bAfter).toBeDefined();
      expect(bAfter?.ahead).toBeGreaterThan(0);
      console.log("  ✓ Sub-test 9 passed: partial deploy + resetDiffTally");

      // ---------------------------------------------------------------
      // Cleanup
      // ---------------------------------------------------------------
      await deleteFork(backend, FORK_ID);
      console.log("\n✅ All sub-tests passed!");
    });
  },
  300_000
);

/**
 * Tests for WASM schema parsing across all supported languages.
 *
 * Calls `inferSchema` directly — no backend needed, fully local.
 * Verifies that each language's WASM parser loads correctly and produces
 * the expected JSON schema output.
 */

import { expect, test, describe } from "bun:test";
import { inferSchema } from "../src/utils/metadata.ts";
import type { ScriptLanguage } from "../src/utils/script_common.ts";

interface LanguageTestCase {
  language: ScriptLanguage;
  content: string;
  /** Property name to verify in schema.properties */
  expectedParam: string;
  /** Expected JSON schema type, or undefined to skip type check */
  expectedType?: string;
  /** If set, verify this resource format exists on the named param */
  expectedResourceParam?: { name: string; format: string };
}

const languageTestCases: LanguageTestCase[] = [
  {
    language: "python3",
    content: `def main(x: str):\n    return x\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "bun",
    content: `export async function main(x: string) {\n  return x;\n}\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "deno",
    content: `export async function main(x: string) {\n  return x;\n}\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "nativets",
    content: `export async function main(x: string) {\n  return x;\n}\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "go",
    content: `package inner\n\nfunc main(x string) (interface{}, error) {\n\treturn x, nil\n}\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "bash",
    // Bash parser infers params from variable assignments like x="$1"
    content: `x="$1"\necho "$x"\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "powershell",
    content: `param([string]$x)\nWrite-Output $x\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "postgresql",
    content: `-- $1 name = default :: text\nSELECT $1::TEXT\n`,
    expectedParam: "name",
    expectedType: "string",
    expectedResourceParam: { name: "database", format: "resource-postgresql" },
  },
  {
    language: "mysql",
    // MySQL parser only auto-detects the database resource param
    content: `SELECT 1\n`,
    expectedParam: "database",
    expectedType: "object",
    expectedResourceParam: { name: "database", format: "resource-mysql" },
  },
  {
    language: "bigquery",
    content: `SELECT 1\n`,
    expectedParam: "database",
    expectedType: "object",
    expectedResourceParam: { name: "database", format: "resource-bigquery" },
  },
  {
    language: "snowflake",
    content: `SELECT 1\n`,
    expectedParam: "database",
    expectedType: "object",
    expectedResourceParam: { name: "database", format: "resource-snowflake" },
  },
  {
    language: "mssql",
    content: `SELECT 1\n`,
    expectedParam: "database",
    expectedType: "object",
    expectedResourceParam: {
      name: "database",
      format: "resource-ms_sql_server",
    },
  },
  {
    language: "oracledb",
    content: `SELECT 1 FROM dual\n`,
    expectedParam: "database",
    expectedType: "object",
    expectedResourceParam: { name: "database", format: "resource-oracledb" },
  },
  {
    language: "duckdb",
    // DuckDB parser doesn't auto-add a database resource
    content: `SELECT 1\n`,
    expectedParam: undefined as any,
    expectedType: undefined,
  },
  {
    language: "graphql",
    content: `query($name: String) {\n  user(name: $name) { id }\n}\n`,
    expectedParam: "name",
    expectedType: "string",
    expectedResourceParam: { name: "api", format: "resource-graphql" },
  },
  {
    language: "php",
    content: `<?php\nfunction main(string $x) {\n  return $x;\n}\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "rust",
    content: `fn main(x: String) -> Result<String, String> {\n    Ok(x)\n}\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "csharp",
    content: `class Script {\n    public static string Main(string x) {\n        return x;\n    }\n}\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "nu",
    content: `def main [x: string] {\n  print $x\n}\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "ansible",
    content: `---\ninventory:\n  - resource_type: ansible_inventory\n---\n- name: Test\n  hosts: 127.0.0.1\n  connection: local\n  tasks:\n  - name: Echo\n    debug:\n      msg: "hello"\n`,
    // Ansible parser produces "inventory.ini" as param name
    expectedParam: "inventory.ini",
    expectedType: undefined,
  },
  {
    language: "java",
    content: `public class Main {\n    public static String main(String x) {\n        return x;\n    }\n}\n`,
    expectedParam: "x",
    expectedType: "string",
  },
  {
    language: "ruby",
    content: `def main(x)\n  puts x\nend\n`,
    expectedParam: "x",
    expectedType: undefined, // Ruby is dynamically typed
  },
];

describe("generate-metadata schema parsing", () => {
  for (const tc of languageTestCases) {
    test(`${tc.language}: WASM parser loads and infers schema`, async () => {
      const result = await inferSchema(
        tc.language,
        tc.content,
        {},
        `test.${tc.language}`
      );

      expect(result).toBeDefined();
      expect(result.schema).toBeDefined();
      expect(result.schema.properties).toBeDefined();

      if (tc.expectedParam) {
        expect(result.schema.properties[tc.expectedParam]).toBeDefined();

        if (tc.expectedType !== undefined) {
          expect(result.schema.properties[tc.expectedParam].type).toEqual(
            tc.expectedType
          );
        }
      }

      if (tc.expectedResourceParam) {
        const rp = result.schema.properties[tc.expectedResourceParam.name];
        expect(rp).toBeDefined();
        expect(rp.type).toEqual("object");
        expect(rp.format).toEqual(tc.expectedResourceParam.format);
      }
    });
  }
});

const allLanguages: ScriptLanguage[] = [
  "python3", "bun", "deno", "nativets", "go", "bash", "powershell",
  "postgresql", "mysql", "bigquery", "snowflake", "mssql", "oracledb",
  "duckdb", "graphql", "php", "rust", "csharp", "nu", "ansible", "java", "ruby",
];

describe("generate-metadata invalid input handling", () => {
  for (const lang of allLanguages) {
    test(`${lang}: does not crash on invalid input`, async () => {
      const result = await inferSchema(
        lang,
        "THIS IS INVALID GARBAGE @#$%^&*()",
        {},
        `test.${lang}`
      );

      expect(result).toBeDefined();
      expect(result.schema).toBeDefined();
      expect(result.schema.properties).toBeDefined();
      // Should return a valid (possibly empty) schema, not throw
      expect(typeof result.schema.properties).toBe("object");
    });
  }
});

