describe("writeAiGuidanceFiles — referencesAgentsCli (via reconciliation)", () => {
  test.each([
    ["bare line", "@AGENTS.wmill.md"],
    ["between blank lines", "before\n\n@AGENTS.wmill.md\n\nafter"],
    ["leading whitespace then include", "  @AGENTS.wmill.md\n"],
    ["CRLF line endings", "line one\r\n@AGENTS.wmill.md\r\nline three"],
    // Mid-sentence include: this is how our own CLAUDE.md default looks
    // ("Instructions are in @AGENTS.md"). A strict line-equality check made
    // `wmill refresh prompts` re-prompt every run on files wmill wrote.
    ["mid-sentence include", "Instructions are in @AGENTS.wmill.md\n"],
    // `>` blockquote prefix doesn't disable Claude's `@`-import expansion,
    // so we treat it as a reference too.
    ["blockquoted include", "> @AGENTS.wmill.md"],
  ])("treats %s as a reference (no append)", async (_label, content) => {
    await withTempDir(async (tempDir) => {
      await writeFile(join(tempDir, "AGENTS.md"), content, "utf8");
      const result = await writeAiGuidanceFiles({ targetDir: tempDir });
      expect(result.agentsMigration).toBe("already-linked");
      expect(await readFile(join(tempDir, "AGENTS.md"), "utf8")).toBe(content);
    });
  });

  test.each([
    ["@AGENTS.wmill.md.backup", "@AGENTS.wmill.md.backup"],
    ["@AGENTS.wmill.mdx", "@AGENTS.wmill.mdx"],
    ["@AGENTS-cli-md (lookalike)", "@AGENTS-cli-md"],
    ["@AGENTS.wmill.md without surrounding whitespace", "foo@AGENTS.wmill.md"],
    ["commented-out include", "<!-- @AGENTS.wmill.md -->"],
  ])("does not treat %s as a reference (append happens)", async (_label, content) => {
    await withTempDir(async (tempDir) => {
      await writeFile(join(tempDir, "AGENTS.md"), content, "utf8");
      const result = await writeAiGuidanceFiles({
        targetDir: tempDir,
        resolveAgentsMdMigration: async () => "append",
      });
      expect(result.agentsMigration).toBe("append");
    });
  });
});

describe("prompts freshness — hash marker", () => {
  test("AGENTS.wmill.md written by writeAiGuidanceFiles carries a hash marker", async () => {
    await withTempDir(async (tempDir) => {
      await writeAiGuidanceFiles({ targetDir: tempDir });
      const agentsCli = await readFile(join(tempDir, "AGENTS.wmill.md"), "utf8");
      const hash = extractPromptsHash(agentsCli);
      expect(hash).not.toBeNull();
      expect(hash).toMatch(/^[0-9a-f]{12}$/);
    });
  });

  test("the stored hash matches currentPromptsHash for the same nonDottedPaths", async () => {
    await withTempDir(async (tempDir) => {
      // writeAiGuidanceFiles defaults nonDottedPaths to `false` (matching
      // core/conf.ts's missing-key default).
      await writeAiGuidanceFiles({ targetDir: tempDir });
      const agentsCli = await readFile(join(tempDir, "AGENTS.wmill.md"), "utf8");
      expect(extractPromptsHash(agentsCli)).toBe(currentPromptsHash(false));
    });
  });

  test("nonDottedPaths setting changes the hash", () => {
    expect(currentPromptsHash(true)).not.toBe(currentPromptsHash(false));
  });

  test("injectPromptsHashMarker places the marker after the H1 title", () => {
    const input = "# Title\n\nbody line\n";
    const out = injectPromptsHashMarker(input, "abc123def456");
    const lines = out.split("\n");
    expect(lines[0]).toBe("# Title");
    expect(lines[1]).toBe("<!-- wmill-prompts-hash: abc123def456 -->");
    expect(lines[2]).toBe("");
    expect(lines[3]).toBe("body line");
  });

  test("injectPromptsHashMarker prepends when there's no H1", () => {
    const input = "no heading\nrest\n";
    const out = injectPromptsHashMarker(input, "abc123def456");
    expect(out).toStartWith("<!-- wmill-prompts-hash: abc123def456 -->");
  });

  test("extractPromptsHash returns null when no marker is present", () => {
    expect(extractPromptsHash("# Title\n\nno marker here\n")).toBeNull();
    expect(extractPromptsHash("<!-- wmill-prompts-hash: tooshort -->")).toBeNull();
  });
});

describe("prompts freshness — shouldRunFreshnessCheck", () => {
  // Each input matches process.argv shape: [node, script, ...args].
  test.each<[string, string[], boolean]>([
    ["empty argv", ["node", "wmill"], false],
    ["wmill --help", ["node", "wmill", "--help"], false],
    ["wmill -h on a subcommand", ["node", "wmill", "init", "-h"], false],
    ["wmill --version", ["node", "wmill", "--version"], false],
    ["wmill init", ["node", "wmill", "init"], false],
    ["wmill init prompts", ["node", "wmill", "init", "prompts"], false],
    ["wmill refresh prompts", ["node", "wmill", "refresh", "prompts"], false],
    ["wmill completions zsh", ["node", "wmill", "completions", "zsh"], false],
    ["wmill upgrade", ["node", "wmill", "upgrade"], false],
    ["wmill sync push", ["node", "wmill", "sync", "push"], true],
    ["wmill flow run", ["node", "wmill", "flow", "run"], true],
    ["wmill --verbose sync push", ["node", "wmill", "--verbose", "sync", "push"], true],
    // Value-taking global options must skip their value when locating the
    // first subcommand. Otherwise `wmill --workspace prod refresh prompts`
    // would misread `"prod"` as the subcommand and trip the warning during
    // the very command that's meant to fix it.
    ["wmill --workspace prod refresh prompts",
      ["node", "wmill", "--workspace", "prod", "refresh", "prompts"], false],
    ["wmill --token tok sync push",
      ["node", "wmill", "--token", "tok", "sync", "push"], true],
    ["wmill --base-url u --workspace w init",
      ["node", "wmill", "--base-url", "u", "--workspace", "w", "init"], false],
    ["wmill --config-dir /etc/wmill init prompts",
      ["node", "wmill", "--config-dir", "/etc/wmill", "init", "prompts"], false],
  ])("%s → %s", (_label, argv, expected) => {
    expect(shouldRunFreshnessCheck(argv)).toBe(expected);
  });
});

describe("prompts freshness — additional invariants", () => {
  test("currentPromptsHash is deterministic across invocations in the same process", () => {
    const h1 = currentPromptsHash(true);
    const h2 = currentPromptsHash(true);
    const h3 = currentPromptsHash(false);
    const h4 = currentPromptsHash(false);
    expect(h1).toBe(h2);
    expect(h3).toBe(h4);
  });

  test("warnIfPromptsStale writes to stderr (never stdout)", async () => {
    await withTempDir(async (tempDir) => {
      // Write a tampered AGENTS.wmill.md so the freshness check trips.
      await writeFile(
        join(tempDir, "AGENTS.wmill.md"),
        "# Windmill CLI Agent Instructions\n<!-- wmill-prompts-hash: 000000000000 -->\nbody\n",
        "utf8"
      );

      const stdoutWrites: string[] = [];
      const stderrWrites: string[] = [];
      const originalStdout = process.stdout.write.bind(process.stdout);
      const originalStderr = process.stderr.write.bind(process.stderr);
      // @ts-expect-error — overriding write for the test
      process.stdout.write = (chunk: any) => {
        stdoutWrites.push(String(chunk));
        return true;
      };
      // @ts-expect-error — overriding write for the test
      process.stderr.write = (chunk: any) => {
        stderrWrites.push(String(chunk));
        return true;
      };

      try {
        await warnIfPromptsStale({
          cwd: tempDir,
          nonDottedPaths: false,
          argv: ["node", "wmill", "sync", "push"],
        });
      } finally {
        process.stdout.write = originalStdout;
        process.stderr.write = originalStderr;
      }

      const stderrJoined = stderrWrites.join("");
      const stdoutJoined = stdoutWrites.join("");
      expect(stderrJoined).toContain("out of date");
      expect(stdoutJoined).not.toContain("out of date");
    });
  });

  // Back-compat: a legacy AGENTS.cli.md is still hash-checked, and we do NOT
  // warn merely because of the old filename — only when it's actually stale.
  test("warnIfPromptsStale stays silent for an up-to-date legacy AGENTS.cli.md", async () => {
    await withTempDir(async (tempDir) => {
      const content = injectPromptsHashMarker(
        "# Windmill CLI Agent Instructions\nbody\n",
        currentPromptsHash(false)
      );
      await writeFile(join(tempDir, "AGENTS.cli.md"), content, "utf8");

      const stderrWrites: string[] = [];
      const originalStderr = process.stderr.write.bind(process.stderr);
      // @ts-expect-error — overriding write for the test
      process.stderr.write = (chunk: any) => {
        stderrWrites.push(String(chunk));
        return true;
      };
      try {
        await warnIfPromptsStale({
          cwd: tempDir,
          nonDottedPaths: false,
          argv: ["node", "wmill", "sync", "push"],
        });
      } finally {
        process.stderr.write = originalStderr;
      }
      expect(stderrWrites.join("")).toBe("");
    });
  });

  test("warnIfPromptsStale warns (naming the legacy file) for a stale AGENTS.cli.md", async () => {
    await withTempDir(async (tempDir) => {
      await writeFile(
        join(tempDir, "AGENTS.cli.md"),
        "# Windmill CLI Agent Instructions\n<!-- wmill-prompts-hash: 000000000000 -->\nbody\n",
        "utf8"
      );

      const stderrWrites: string[] = [];
      const originalStderr = process.stderr.write.bind(process.stderr);
      // @ts-expect-error — overriding write for the test
      process.stderr.write = (chunk: any) => {
        stderrWrites.push(String(chunk));
        return true;
      };
      try {
        await warnIfPromptsStale({
          cwd: tempDir,
          nonDottedPaths: false,
          argv: ["node", "wmill", "sync", "push"],
        });
      } finally {
        process.stderr.write = originalStderr;
      }
      const out = stderrWrites.join("");
      expect(out).toContain("out of date");
      expect(out).toContain("AGENTS.cli.md");
    });
  });
});

/**
 * Integration test: HEADERS env var is forwarded on every CLI fetch call.
 *
 * Spins up an auth-gateway proxy in front of the test backend that:
 *   - 403s + Cloudflare-style HTML if the request is missing CF-Access-Client-Id /
 *     CF-Access-Client-Secret (mirrors the real-world Cloudflare Access challenge),
 *   - otherwise reverse-proxies to the backend.
 *
 * Then runs `wmill sync push` with --base-url pointed at the proxy. If any fetch
 * in the CLI bypasses HEADERS, the proxy returns the challenge page and the push
 * fails (or the request is logged as un-authenticated). Negative case verifies
 * the gateway actually rejects un-headered requests, so a passing positive case
 * is meaningful.
 *
 * Regression coverage for #6421 and the script.ts pushScript /
 * jobs/run/preview_bundle / app dev SSE fetch calls that used to skip getHeaders().
 */

import { expect, test } from "bun:test";
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { Server } from "bun";
import { withTestBackend } from "./test_backend.ts";

const HEADER_NAMES = ["CF-Access-Client-Id", "CF-Access-Client-Secret"] as const;
const HEADER_VALUES = {
  "CF-Access-Client-Id": "test-cf-id",
  "CF-Access-Client-Secret": "test-cf-secret",
} as const;

const HEADERS_ENV = HEADER_NAMES
  .map((h) => `${h}: ${HEADER_VALUES[h]}`)
  .join(", ");

interface ProxyState {
  authenticatedRequests: { method: string; path: string }[];
  rejectedRequests: { method: string; path: string }[];
}

interface RunningProxy {
  server: Server;
  state: ProxyState;
  url: string;
}

function startGatewayProxy(backendUrl: string): RunningProxy {
  const state: ProxyState = {
    authenticatedRequests: [],
    rejectedRequests: [],
  };

  const server = Bun.serve({
    port: 0,
    hostname: "127.0.0.1",
    async fetch(req) {
      const reqUrl = new URL(req.url);
      const pathAndQuery = reqUrl.pathname + reqUrl.search;

      const id = req.headers.get("cf-access-client-id");
      const secret = req.headers.get("cf-access-client-secret");
      const passes =
        id === HEADER_VALUES["CF-Access-Client-Id"] &&
        secret === HEADER_VALUES["CF-Access-Client-Secret"];

      if (!passes) {
        state.rejectedRequests.push({ method: req.method, path: pathAndQuery });
        return new Response(
          '<!DOCTYPE html><title>Sign in ・ Cloudflare Access</title>' +
            '<body>Authenticate to reach this site.</body>',
          {
            status: 403,
            headers: {
              "content-type": "text/html; charset=utf-8",
              "cf-ray": "0000000000000000-TEST",
              "cf-mitigated": "challenge",
            },
          },
        );
      }

      state.authenticatedRequests.push({ method: req.method, path: pathAndQuery });

      const target = new URL(pathAndQuery, backendUrl);
      const forwardHeaders = new Headers(req.headers);
      forwardHeaders.delete("cf-access-client-id");
      forwardHeaders.delete("cf-access-client-secret");
      forwardHeaders.set("host", new URL(backendUrl).host);

      const body =
        req.method === "GET" || req.method === "HEAD"
          ? undefined
          : await req.arrayBuffer();

      return await fetch(target, {
        method: req.method,
        headers: forwardHeaders,
        body,
        redirect: "manual",
      });
    },
  });

  return {
    server,
    state,
    url: `http://127.0.0.1:${server.port}`,
  };
}

async function runCliThroughProxy(
  backend: { workspace: string; testConfigDir: string; token?: string },
  proxyUrl: string,
  cliArgs: string[],
  cwd: string,
  env: Record<string, string>,
): Promise<{ stdout: string; stderr: string; code: number }> {
  // Use fileURLToPath + node:path so the CLI entrypoint is a real OS path on
  // Windows. `new URL(..).pathname` yields `/C:/...` which Bun.spawn fails to
  // resolve, so the negative case "rejected" on launch instead of reaching
  // the proxy and the assertion on rejectedRequests > 0 flaked.
  const cliDir = join(dirname(fileURLToPath(import.meta.url)), "..");
  const useNode = process.env["TEST_CLI_RUNTIME"] === "node";
  const runtime = useNode ? "node" : "bun";
  const entrypoint = useNode
    ? join(cliDir, "npm", "esm", "main.js")
    : join(cliDir, "src", "main.ts");
  const runtimeArgs = useNode ? [entrypoint] : ["run", entrypoint];

  const fullArgs = [
    "--base-url", proxyUrl,
    "--workspace", backend.workspace,
    "--token", backend.token ?? "",
    "--config-dir", backend.testConfigDir,
    ...cliArgs,
  ];

  const proc = Bun.spawn([runtime, ...runtimeArgs, ...fullArgs], {
    cwd,
    env: { ...(process.env as Record<string, string>), ...env },
    stdout: "pipe",
    stderr: "pipe",
  });

  const [stdout, stderr] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
  ]);
  const code = await proc.exited;
  return { stdout, stderr, code };
}

test(
  "HEADERS env var is forwarded on every CLI fetch (sync push of new script)",
  async () => {
    await withTestBackend(async (backend, tempDir) => {
      const proxy = startGatewayProxy(backend.baseUrl);
      try {
        await writeFile(
          `${tempDir}/wmill.yaml`,
          `defaultTs: bun\nincludes:\n  - "**"\nexcludes: []\n`,
          "utf-8",
        );

        const uniqueId = Date.now();
        const scriptName = `headers_${uniqueId}`;
        const scriptDir = `${tempDir}/f/test`;
        await mkdir(scriptDir, { recursive: true });
        await writeFile(
          `${scriptDir}/${scriptName}.ts`,
          `export async function main() {\n  return "headers test ${uniqueId}";\n}\n`,
          "utf-8",
        );
        await writeFile(
          `${scriptDir}/${scriptName}.script.yaml`,
          [
            `summary: "headers regression"`,
            `description: "Push covers /scripts/create + /jobs/run/dependencies_async"`,
            `lock: ""`,
            `schema:`,
            `  $schema: "https://json-schema.org/draft/2020-12/schema"`,
            `  type: object`,
            `  properties: {}`,
            `  required: []`,
            `is_template: false`,
            `kind: script`,
            `language: bun`,
            ``,
          ].join("\n"),
          "utf-8",
        );

        const includesGlob = `f/test/${scriptName}**`;

        // Negative case: no HEADERS env -> the proxy should return the
        // gateway challenge and the CLI should bail out non-zero. Proves the
        // proxy is actually gating, so the positive case isn't a false pass.
        const noHeaders = await runCliThroughProxy(
          backend,
          proxy.url,
          ["sync", "push", "--yes", "--includes", includesGlob],
          tempDir,
          {},
        );
        expect(noHeaders.code).not.toEqual(0);
        expect(proxy.state.rejectedRequests.length).toBeGreaterThan(0);
        expect(proxy.state.authenticatedRequests.length).toEqual(0);

        // Reset proxy state between cases.
        proxy.state.authenticatedRequests.length = 0;
        proxy.state.rejectedRequests.length = 0;

        // Positive case: HEADERS env set -> the proxy must see those headers
        // on every request the CLI makes for sync push to succeed.
        const withHeaders = await runCliThroughProxy(
          backend,
          proxy.url,
          ["sync", "push", "--yes", "--includes", includesGlob],
          tempDir,
          { HEADERS: HEADERS_ENV },
        );
        expect(withHeaders.code).toEqual(0);
        expect(proxy.state.rejectedRequests).toEqual([]);

        const paths = proxy.state.authenticatedRequests.map((r) => r.path);

        // Print the full path list when an assertion below fails so the
        // failure is debuggable without re-running with extra logging.
        const debug = () => paths.join("\n  ");

        // Tarball download (sync diff): src/commands/sync/pull.ts
        expect(
          paths.some((p) =>
            p.startsWith(`/api/w/${backend.workspace}/workspaces/tarball`),
          ),
          `expected tarball request, got:\n  ${debug()}`,
        ).toBe(true);

        // Script create: src/commands/script/script.ts pushScript().
        // This is the regression: PR #8936 switched from wmill.createScript()
        // (SDK, inherits OpenAPI.HEADERS) to a raw fetch that didn't forward
        // HEADERS. Without the fix, the proxy would 403 this request and the
        // CLI exit would be non-zero — so this assertion is the load-bearing
        // one for #8936 / #6421-style regressions.
        expect(
          paths.some((p) =>
            p.includes(`/api/w/${backend.workspace}/scripts/create`),
          ),
          `expected /scripts/create request, got:\n  ${debug()}`,
        ).toBe(true);

        // Lock generation: src/utils/metadata.ts. Was the original #6421 fix
        // (PR #6422) — a soft check; the backend may skip queueing a lock job
        // for trivial bun scripts under some feature configurations, so we
        // only verify it *if* the CLI tried to generate one.
        // (No assertion — covered by the tarball+create checks above plus
        // the negative case proving the proxy actually gates requests.)
      } finally {
        proxy.server.stop(true);
      }
    });
  },
  240_000,
);

import { expect, test } from "bun:test";
import {
  AuthGatewayChallengeError,
  detectAuthGatewayChallenge,
} from "../src/utils/http_guards.ts";

const URL = "https://windmill.example.com/api/w/dev/scripts/create";

function htmlResponse(body: string, headers: Record<string, string> = {}) {
  return new Response(body, {
    status: 200,
    headers: { "content-type": "text/html; charset=utf-8", ...headers },
  });
}

test("throws on Cloudflare Access SSO HTML", async () => {
  const body =
    '<!DOCTYPE html><title>Sign in ・ Cloudflare Access</title><body>...</body>';
  const res = htmlResponse(body, {
    "cf-ray": "8a1234abcdef-ATL",
    "cf-mitigated": "challenge",
  });

  await expect(detectAuthGatewayChallenge(res, URL)).rejects.toBeInstanceOf(
    AuthGatewayChallengeError,
  );
});

test("error includes cf-ray, cf-mitigated, status, body snippet", async () => {
  const body = '<!DOCTYPE html><title>Sign in ・ Cloudflare Access</title>';
  const res = htmlResponse(body, {
    "cf-ray": "ray-123",
    "cf-mitigated": "challenge",
  });

  try {
    await detectAuthGatewayChallenge(res, URL);
    throw new Error("expected to throw");
  } catch (e) {
    expect(e).toBeInstanceOf(AuthGatewayChallengeError);
    const err = e as AuthGatewayChallengeError;
    expect(err.url).toBe(URL);
    expect(err.cfRay).toBe("ray-123");
    expect(err.cfMitigated).toBe("challenge");
    expect(err.status).toBe(200);
    expect(err.message).toContain("ray-123");
    expect(err.message).toContain("cf-mitigated=challenge");
    expect(err.message).toContain("Sign in");
  }
});

test("throws on generic HTML body even without cf headers", async () => {
  const body = "<!doctype html><html><body>Login required</body></html>";
  const res = htmlResponse(body);

  await expect(detectAuthGatewayChallenge(res, URL)).rejects.toBeInstanceOf(
    AuthGatewayChallengeError,
  );
});

test("throws on cf-mitigated=challenge even with non-HTML content type", async () => {
  // CF Access can challenge non-HTML responses too; the header alone is enough.
  const res = new Response('<title>Sign in ・ Cloudflare Access</title>', {
    status: 200,
    headers: {
      "content-type": "application/octet-stream",
      "cf-mitigated": "challenge",
    },
  });

  await expect(detectAuthGatewayChallenge(res, URL)).rejects.toBeInstanceOf(
    AuthGatewayChallengeError,
  );
});

test("normalizes content-type case (Text/HTML)", async () => {
  const body = "<!doctype html><html></html>";
  const res = new Response(body, {
    status: 200,
    headers: { "content-type": "Text/HTML; charset=UTF-8" },
  });

  await expect(detectAuthGatewayChallenge(res, URL)).rejects.toBeInstanceOf(
    AuthGatewayChallengeError,
  );
});

test("does NOT throw on JSON happy-path response", async () => {
  const res = new Response(JSON.stringify({ id: "abc" }), {
    status: 200,
    headers: { "content-type": "application/json" },
  });

  await expect(detectAuthGatewayChallenge(res, URL)).resolves.toBeUndefined();
});

test("does NOT throw on cf-mitigated values other than 'challenge' (e.g. 'block') with non-HTML body", async () => {
  // If CF marks something with cf-mitigated: block on a non-HTML response, the
  // cheap path should skip the challenge predicate entirely.
  const res = new Response('{"error":"blocked"}', {
    status: 403,
    headers: {
      "content-type": "application/json",
      "cf-mitigated": "block",
    },
  });

  await expect(detectAuthGatewayChallenge(res, URL)).resolves.toBeUndefined();
});

test("does NOT throw on text/plain body that isn't an auth challenge", async () => {
  const res = new Response("just some plaintext", {
    status: 200,
    headers: { "content-type": "text/plain" },
  });

  await expect(detectAuthGatewayChallenge(res, URL)).resolves.toBeUndefined();
});

test("does NOT throw when body is empty", async () => {
  // Body absent (e.g. 204) — treat as non-challenge regardless of headers.
  const res = new Response(null, {
    status: 204,
    headers: { "content-type": "text/html" },
  });

  await expect(detectAuthGatewayChallenge(res, URL)).resolves.toBeUndefined();
});

test("falls back to response.url when caller url is omitted", async () => {
  const body = "<!doctype html><title>Sign in ・ Cloudflare Access</title>";
  const res = htmlResponse(body);

  try {
    await detectAuthGatewayChallenge(res);
    throw new Error("expected to throw");
  } catch (e) {
    const err = e as AuthGatewayChallengeError;
    // Response constructor doesn't set .url, so we expect the unknown sentinel.
    expect(err.url).toBe("(unknown)");
  }
});

import { expect, test } from "bun:test";
import { writeFile } from "node:fs/promises";
import { withTestBackend } from "./test_backend.ts";
import { addWorkspace } from "../workspace.ts";
import { parseJsonFromCLIOutput } from "./test_config_helpers.ts";

// =============================================================================
// INCLUDE FLAGS BYPASS FILTERING TESTS
// Tests that CLI include flags properly bypass path-based filtering
// =============================================================================

// Helper function to set up workspace profile
async function setupWorkspaceProfile(backend: any): Promise<void> {
  const testWorkspace = {
    remote: backend.baseUrl,
    workspaceId: backend.workspace,
    name: "localhost_test",
    token: backend.token
  };

  await addWorkspace(testWorkspace, { force: true, configDir: backend.testConfigDir });
}

// The ContainerizedBackend already creates test data we can use:
// - admin user (admin@windmill.dev)
// - test_group (created by seedTestData())
// - workspace encryption key
// - test apps, resources, variables via seedTestData()
// No additional setup needed!

test("CLI include flags bypass restrictive path filtering", async () => {
  await withTestBackend(async (backend, tempDir) => {
    await setupWorkspaceProfile(backend);

    // Create wmill.yaml with very restrictive includes that would exclude special files
    await writeFile(`${tempDir}/wmill.yaml`, `defaultTs: bun
includes:
  - "f/**"
excludes: []
skipVariables: true
skipResources: true
includeUsers: false
includeGroups: false
includeSettings: false
includeKey: false`, "utf-8");

    // Test: CLI flags should override config and bypass path filtering
    const result = await backend.runCLICommand([
      'sync', 'pull',
      '--include-users',
      '--include-groups',
      '--include-settings',
      '--include-key',
      '--dry-run',
      '--json-output'
    ], tempDir);

    expect(result.code).toEqual(0);

    const output = parseJsonFromCLIOutput(result.stdout);
    const changePaths = output.changes.map((c: any) => c.path);

    // Assert that special files are included despite restrictive path filtering
    // Normalize paths for cross-platform comparison (Windows uses backslashes)
    const normalizedPaths = changePaths.map((p: string) => p.replace(/\\/g, '/'));
    const hasUser = normalizedPaths.some((path: string) => path.includes('admin@windmill.dev.user.yaml'));
    const hasGroup = normalizedPaths.some((path: string) => path.includes('groups/test_group.group.yaml'));
    const hasSettings = changePaths.some((path: string) => path === 'settings.yaml');
    const hasEncryptionKey = changePaths.some((path: string) => path === 'encryption_key.yaml');

    expect(hasUser).toBe(true);
    expect(hasGroup).toBe(true);
    expect(hasSettings).toBe(true);
    expect(hasEncryptionKey).toBe(true);
  });
});

