    await writeFile(`${tempDir}/stray.ts`, `export function main() {}`, "utf-8");
    const strayResult = await backend.runCLICommand(
      ["script", "preview", "stray.ts", "--silent"],
      tempDir
    );
    expect(strayResult.code).toEqual(1);
  });
});

