/** Only a `.css` 404 may be forgiven — see `getRawAppBundlePart`. */

import { expect, test, describe } from "bun:test";
import { getRawAppBundlePart } from "../windmill-utils-internal/src/deploy.ts";

function providerThatFailsWith(err: unknown) {
  return {
    getRawAppData: () => Promise.reject(err),
  } as any;
}

function httpError(status: number) {
  return Object.assign(new Error(`HTTP ${status}`), { status });
}

describe("getRawAppBundlePart", () => {
  test("requests each half under its own extension", async () => {
    const asked: Array<{ secretWithExtension: string; workspace: string }> = [];
    const provider = {
      getRawAppData: (p: { secretWithExtension: string; workspace: string }) => {
        asked.push(p);
        return Promise.resolve(`body-of-${p.secretWithExtension}`);
      },
    } as any;

    expect(await getRawAppBundlePart(provider, "sec", "js", "ws")).toBe(
      "body-of-sec.js"
    );
    expect(await getRawAppBundlePart(provider, "sec", "css", "ws")).toBe(
      "body-of-sec.css"
    );
    // Swapping the two extensions would deploy the stylesheet as the bundle.
    expect(asked).toEqual([
      { secretWithExtension: "sec.js", workspace: "ws" },
      { secretWithExtension: "sec.css", workspace: "ws" },
    ]);
  });

  test("treats a missing .css as empty rather than fatal", async () => {
    const provider = providerThatFailsWith(httpError(404));
    expect(await getRawAppBundlePart(provider, "sec", "css", "ws")).toBe("");
  });

  test("still fails loudly on a missing .js", async () => {
    const provider = providerThatFailsWith(httpError(404));
    await expect(
      getRawAppBundlePart(provider, "sec", "js", "ws")
    ).rejects.toThrow();
  });

  test("does not swallow non-404 failures on .css", async () => {
    for (const status of [401, 403, 500]) {
      const provider = providerThatFailsWith(httpError(status));
      await expect(
        getRawAppBundlePart(provider, "sec", "css", "ws")
      ).rejects.toThrow();
    }
  });

  test("does not swallow a .css failure that carries no status", async () => {
    const provider = providerThatFailsWith(new Error("network down"));
    await expect(
      getRawAppBundlePart(provider, "sec", "css", "ws")
    ).rejects.toThrow("network down");
  });
});

/**
 * `wmill app dev --recording` writes multi-MB session recordings into
 * `<app>.raw_app/recordings/`. They are local artifacts: the sync differ must
 * not offer them as app source (the push itself drops them in
 * `collectAppFiles`, so a differ that still sees them reports a change that
 * pushing can never settle).
 */

import { expect, test } from "bun:test";
import { sep as SEP } from "node:path";
import { elementsToMap } from "../src/commands/sync/sync.ts";

type MockFile = { path: string; content: string };

// FSFSElement joins with the platform separator, and the exclusion has to hold
// on Windows too.
const p = (...parts: string[]) => parts.join(SEP);

function mockElement(files: MockFile[]) {
  return {
    isDirectory: true,
    path: "",
    async getContentText() {
      return "";
    },
    async *getChildren() {
      for (const file of files) {
        yield {
          isDirectory: false,
          path: file.path,
          async getContentText() {
            return file.content;
          },
          async *getChildren() {},
        };
      }
    },
  };
}

test("elementsToMap skips recordings/ at the root of a raw app folder only", async () => {
  const app = p("f", "demo", "myapp.raw_app");
  const files: MockFile[] = [
    { path: p(app, "index.tsx"), content: "export {}" },
    {
      path: p(app, "recordings", "recording-2026-01-01-00-00-00.json"),
      content: '{"version":1}',
    },
    // The dev server never writes here, so this is the app's own source.
    { path: p(app, "src", "recordings", "fixture.json"), content: "{}" },
  ];

  const result = await elementsToMap(
    mockElement(files) as any,
    () => false,
    false,
    {},
  );

  expect(Object.keys(result).sort()).toEqual(
    [p(app, "index.tsx"), p(app, "src", "recordings", "fixture.json")].sort(),
  );
});

/**
 * A raw app brings its own Svelte *runtime* via package.json, so it has to be
 * compiled with its own *compiler* too — the two share internals that change
 * between versions. Svelte 5.52.0 moved delegated event handlers off
 * `element.__click` onto a Symbol-keyed map, so compiling with a version on the
 * other side of that line produces an app that builds, renders, and has every
 * `onclick` silently dead.
 *
 * `import("svelte/compiler")` resolves against the CLI, whose svelte floats
 * independently of the app's. These cover the app-local resolution that avoids
 * that drift.
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import { loadSvelteCompiler } from "../src/commands/app/bundle.ts";

let tempDir: string;

/** A stand-in svelte install, identifiable by a version the real one never has. */
function installStubSvelte(dir: string, version: string) {
  const pkgDir = path.join(dir, "node_modules", "svelte");
  fs.mkdirSync(pkgDir, { recursive: true });
  fs.writeFileSync(
    path.join(pkgDir, "package.json"),
    JSON.stringify({
      name: "svelte",
      version,
      type: "module",
      exports: { "./compiler": "./compiler.js" },
    }),
    "utf-8",
  );
  fs.writeFileSync(
    path.join(pkgDir, "compiler.js"),
    `export const VERSION = ${JSON.stringify(version)};\n` +
      `export function compile() { return { js: { code: "", map: null }, warnings: [] }; }\n` +
      `export function compileModule() { return { js: { code: "", map: null }, warnings: [] }; }\n`,
    "utf-8",
  );
}

/**
 * A stand-in shaped like the real svelte: `./compiler` maps `require` at a UMD
 * bundle and `default` at the ESM sources, and only the ESM half survives an
 * `import()` with its named exports intact.
 */
function installDualStubSvelte(dir: string) {
  const pkgDir = path.join(dir, "node_modules", "svelte");
  fs.mkdirSync(pkgDir, { recursive: true });
  fs.writeFileSync(
    path.join(pkgDir, "package.json"),
    JSON.stringify({
      name: "svelte",
      version: "0.0.0-dual",
      type: "module",
      exports: {
        "./package.json": "./package.json",
        "./compiler": {
          types: "./types/index.d.ts",
          require: "./compiler/index.cjs",
          default: "./src/compiler/index.js",
        },
      },
    }),
    "utf-8",
  );
  fs.mkdirSync(path.join(pkgDir, "src", "compiler"), { recursive: true });
  fs.writeFileSync(
    path.join(pkgDir, "src", "compiler", "index.js"),
    `export const VERSION = "0.0.0-esm";\n` +
      `export function compile() { return { js: { code: "", map: null }, warnings: [] }; }\n`,
    "utf-8",
  );
  fs.mkdirSync(path.join(pkgDir, "compiler"), { recursive: true });
  fs.writeFileSync(
    path.join(pkgDir, "compiler", "index.cjs"),
    // The UMD wrapper the published bundle uses: no static `exports.x = ...` for
    // a lexer to find, so an `import()` of this file sees only `default`.
    `!function(e,t){"object"==typeof exports&&"undefined"!=typeof module?t(exports):e(t)}` +
      `(0,function(e){e.VERSION="0.0.0-cjs";` +
      `e.compile=function(){return{js:{code:"",map:null},warnings:[]}}});\n`,
    "utf-8",
  );
}

