      // Call 2: wrong hash same path + right hash wrong path → both should be mismatched
      const call2 = await diffRawScriptsWithDeployed({
        workspace: backend.workspace,
        requestBody: {
          scripts: {
            "f/test/deployed_script": wrongHash,
