  });

  test("overwrites existing module folder on re-write", async () => {
    const moduleFolderPath = path.join(tempDir, "my_script__mod");

    // First write
    await writeModulesToDisk(moduleFolderPath, {
      "old.ts": { content: "old content\n", language: "bun" as const },
    }, "bun");
    expect(fs.existsSync(path.join(moduleFolderPath, "old.ts"))).toBe(true);

    // Second write with different module
    await writeModulesToDisk(moduleFolderPath, {
      "new.ts": { content: "new content\n", language: "bun" as const },
    }, "bun");
    expect(fs.existsSync(path.join(moduleFolderPath, "new.ts"))).toBe(true);
    // old.ts should still exist (writeModulesToDisk doesn't clean up)
    // This is intentional — cleanup happens at the sync level
  });
});

// =============================================================================
// findContentFile
// =============================================================================

describe("findContentFile", () => {
  let tempDir: string;

  beforeEach(() => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "wm-find-content-"));
  });

  afterEach(() => {
    fs.rmSync(tempDir, { recursive: true, force: true });
  });

  test("resolves the entry point of a module folder", async () => {
    const modDir = path.join(tempDir, "my_script__mod");
    fs.mkdirSync(modDir, { recursive: true });
    fs.writeFileSync(path.join(modDir, "script.ts"), "export async function main() {}\n");
    fs.writeFileSync(path.join(modDir, "script.yaml"), "summary: ''\n");

    expect(await findContentFile(path.join(modDir, "script.yaml"))).toBe(
      path.join(modDir, "script.ts")
    );
  });

  // `isModuleEntryPoint` treats `\` as a separator on every platform, so
  // findContentFile must too or it rejects every Windows module path. Runnable
  // on POSIX because there the backslash is merely part of the file name.
  test("resolves a module entry point written with a backslash separator", async () => {
    const meta = path.join(tempDir, "my_script__mod") + "\\script.yaml";
    const content = path.join(tempDir, "my_script__mod") + "\\script.ts";
    fs.mkdirSync(path.dirname(meta), { recursive: true });
    fs.writeFileSync(content, "export async function main() {}\n");
    fs.writeFileSync(meta, "summary: ''\n");

    expect(await findContentFile(meta)).toBe(content);
  });

  // sync push catches UnresolvableScriptContentFileError to record the change as
  // failed and carry on; any other error aborts the whole push, so every branch
  // that simply cannot pair a metadata file with one script file must use it.
  test("signals every unpairable case with UnresolvableScriptContentFileError", async () => {
    const dir = path.join(tempDir, "f", "test");
    fs.mkdirSync(dir, { recursive: true });

    // no script file at all
    const orphan = path.join(dir, "orphan.script.yaml");
    fs.writeFileSync(orphan, "summary: ''\n");
    await expect(findContentFile(orphan)).rejects.toBeInstanceOf(
      UnresolvableScriptContentFileError
    );

    // two script files, so the metadata cannot name one
    const ambiguous = path.join(dir, "both.script.yaml");
    fs.writeFileSync(ambiguous, "summary: ''\n");
    fs.writeFileSync(path.join(dir, "both.ts"), "export async function main() {}\n");
    fs.writeFileSync(path.join(dir, "both.py"), "def main():\n    pass\n");
    await expect(findContentFile(ambiguous)).rejects.toBeInstanceOf(
      UnresolvableScriptContentFileError
    );
  });

  // A script.yaml nested deeper in the module tree is a module file, not the
  // script's metadata — resolving it to itself would make the caller deploy it
  // as if it were a script.
  test("rejects a script.yaml nested below the module entry point", async () => {
    const nested = path.join(tempDir, "my_script__mod", "config");
    fs.mkdirSync(nested, { recursive: true });
    const nestedMeta = path.join(nested, "script.yaml");
    fs.writeFileSync(nestedMeta, "nested: data\n");

    await expect(findContentFile(nestedMeta)).rejects.toThrow(
      "is not a script metadata file"
    );
  });
});

import { describe, expect, test } from "bun:test";
import { mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { stringify as yamlStringify } from "yaml";

import { computePushMetadataHash } from "../src/commands/script/script.ts";
import { generateScriptHash, checkifMetadataUptodate } from "../src/utils/metadata.ts";

async function withTempDir(fn: (tempDir: string) => Promise<void>): Promise<void> {
  const tempDir = await mkdtemp(path.join(os.tmpdir(), "wmill_push_meta_"));
  const originalCwd = process.cwd();
  try {
    process.chdir(tempDir);
    await fn(tempDir);
  } finally {
    process.chdir(originalCwd);
    await rm(tempDir, { recursive: true, force: true });
  }
}

describe("script push metadata hash", () => {
  test("matches generate-metadata lock hash for a script with inline metadata", async () => {
    await withTempDir(async (tempDir) => {
      const scriptPath = path.join(tempDir, "f/test/example.ts");
      const metadataPath = path.join(tempDir, "f/test/example.script.yaml");
      await mkdir(path.dirname(scriptPath), { recursive: true });

      await writeFile(
        scriptPath,
        'export async function main() { return "metadata"; }\n'
      );

      const metadataContent = yamlStringify({
        summary: "test",
        description: "",
        lock: "",
        kind: "script",
        schema: {
          $schema: "https://json-schema.org/draft/2020-12/schema",
          type: "object",
          properties: {},
          required: [],
        },
      });
      await writeFile(metadataPath, metadataContent);

      const scriptContent = await readFile(scriptPath, "utf-8");
      const expectedHash = await generateScriptHash({}, scriptContent, metadataContent);
      const pushHash = await computePushMetadataHash("f/test/example.ts", scriptContent);

      expect(pushHash).toEqual(expectedHash);
      expect(
        await checkifMetadataUptodate("f/test/example", pushHash, {
          version: "v2",
          locks: { "f/test/example": pushHash },
        })
      ).toBeTrue();
    });
  });
});

/**
 * `wmill script push` short-circuits when the local script already matches the
 * remote. The comparison has to hold in both directions: an untouched script
 * deploys nothing, and every field the push body carries (labels and the language
 * inferred from defaultTs included) still counts as a change.
 */

import { expect, test } from "bun:test";
import { writeFile, readFile, mkdir } from "node:fs/promises";
import { withTestBackend } from "./test_backend.ts";
import { waitForDeploymentJobs } from "./new_commands_helpers.ts";

test("Integration: script push skips an unchanged script and deploys a changed one", async () => {
  await withTestBackend(async (backend, tempDir) => {
    const uniqueId = Date.now();
    const scriptPath = `f/test/uptodate_${uniqueId}`;
    const getScript = async () =>
      await (
        await backend.apiRequest!(
          `/api/w/${backend.workspace}/scripts/get/p/${scriptPath}`,
        )
      ).json();
    const push = async () =>
      await backend.runCLICommand(["script", "push", `${scriptPath}.ts`], tempDir);
    const wmillYaml = (defaultTs: string) =>
      `defaultTs: ${defaultTs}\nincludes:\n  - "${scriptPath}**"\nexcludes: []\n`;

    await mkdir(`${tempDir}/f/test`, { recursive: true });
    await backend.apiRequest!(`/api/w/${backend.workspace}/folders/create`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: "test" }),
    });
    const createResp = await backend.apiRequest!(
      `/api/w/${backend.workspace}/scripts/create`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          path: scriptPath,
          content: `export async function main() {\n  return "Hello world";\n}`,
          summary: "Test up to date",
          description: "",
          language: "bun",
          kind: "script",
          schema: {
            $schema: "https://json-schema.org/draft/2020-12/schema",
            type: "object",
            properties: {},
            required: [],
          },
          labels: ["l1"],
        }),
      },
    );
    expect(createResp.ok).toEqual(true);

    await writeFile(`${tempDir}/wmill.yaml`, wmillYaml("bun"), "utf-8");
    // The lock a deploy's dependency job writes is part of the comparison, so every
    // pull has to happen after that job has landed or the skip races it.
    await waitForDeploymentJobs(backend);
    expect((await backend.runCLICommand(["sync", "pull", "--yes"], tempDir)).code).toEqual(0);

    const hashBefore = (await getScript()).hash;
    expect((await push()).stdout).toContain("is up to date");
    expect((await getScript()).hash).toEqual(hashBefore);

    const metadataPath = `${tempDir}/${scriptPath}.script.yaml`;
    await writeFile(
      metadataPath,
      (await readFile(metadataPath, "utf-8")).replace("- l1", "- l2"),
      "utf-8",
    );
    expect((await push()).stdout).not.toContain("is up to date");
    expect((await getScript()).labels).toEqual(["l2"]);

    // 2, not 0 or 1: those two are the values a truthiness comparison would also
    // call equal, so they cannot pin that priority is compared by value.
    await waitForDeploymentJobs(backend);
    expect((await backend.runCLICommand(["sync", "pull", "--yes"], tempDir)).code).toEqual(0);
    await writeFile(metadataPath, (await readFile(metadataPath, "utf-8")) + "priority: 2\n", "utf-8");
    expect((await push()).stdout).not.toContain("is up to date");
    expect((await getScript()).priority).toEqual(2);
    await waitForDeploymentJobs(backend);
    expect((await backend.runCLICommand(["sync", "pull", "--yes"], tempDir)).code).toEqual(0);
    expect((await push()).stdout).toContain("is up to date");

    await writeFile(`${tempDir}/wmill.yaml`, wmillYaml("deno"), "utf-8");
    expect((await push()).stdout).not.toContain("is up to date");
    expect((await getScript()).language).toEqual("deno");
  });
});

