      name: "ws",
      slack_team_id: "T12345",
      slack_name: "my-team",
      slack_command_script: "u/admin/slack_handler",
    };
    const result = migrateToGroupedFormat(settings);
    expect(result.slack_team_id).toBe("T12345");
    expect(result.slack_name).toBe("my-team");
    expect(result.slack_command_script).toBe("u/admin/slack_handler");
  });

  // error_handler / success_handler: null must round-trip through migration so
  // that `wmill sync push` can forward it to the backend as a "clear remote"
  // signal. Before this fix, null fell through the truthy-object + string
  // branches and ended up as undefined, making an explicit `error_handler: null`
  // in settings.yaml a no-op under the universal "omit = clear" rule.
  test("preserves explicit null error_handler", () => {
    const result = migrateToGroupedFormat({ name: "ws", error_handler: null });
    expect(result.error_handler).toBeNull();
    expect("error_handler" in result).toBe(true);
  });

  test("preserves explicit null success_handler", () => {
    const result = migrateToGroupedFormat({ name: "ws", success_handler: null });
    expect(result.success_handler).toBeNull();
    expect("success_handler" in result).toBe(true);
  });

  test("preserves both null handlers alongside a populated handler", () => {
    const result = migrateToGroupedFormat({
      name: "ws",
      error_handler: { path: "u/admin/err", muted_on_cancel: false },
      success_handler: null,
    });
    expect(result.error_handler).toEqual({
      path: "u/admin/err",
      muted_on_cancel: false,
    });
    expect(result.success_handler).toBeNull();
  });

  // slack_oauth_client_id / slack_oauth_client_secret are the workspace-level
  // OAuth override. Pull always emits them (null when DB is NULL), and push
  // forwards whatever is in YAML — both present upserts, anything else deletes.
  test("copies slack_oauth_client_id / _secret through (populated)", () => {
    const result = migrateToGroupedFormat({
      name: "ws",
      slack_oauth_client_id: "1234567890.1234567890",
      slack_oauth_client_secret: "abcdef0123456789",
    });
    expect(result.slack_oauth_client_id).toBe("1234567890.1234567890");
    expect(result.slack_oauth_client_secret).toBe("abcdef0123456789");
  });

  test("copies slack_oauth_client_id / _secret through (null)", () => {
    const result = migrateToGroupedFormat({
      name: "ws",
      slack_oauth_client_id: null,
      slack_oauth_client_secret: null,
    });
    // migrateToGroupedFormat only copies fields that are `!== undefined`;
    // null is a valid value and must flow through so the push comparison sees
    // "local is null, remote is null → equal" instead of treating absence as
    // "not in YAML".
    expect(result.slack_oauth_client_id).toBeNull();
    expect(result.slack_oauth_client_secret).toBeNull();
  });
});

/**
 * Global test setup — preloaded before all test files.
 *
 * When UNIT_ONLY=1, skips all backend setup (cargo build, database, etc.)
 * so that unit tests can run instantly without any external dependencies.
 *
 * Otherwise:
 * 1. Builds the backend binary so `cargo run` starts instantly.
 * 2. Starts a shared backend instance so integration tests don't
 *    bear the startup cost inside their per-test timeout window.
 */

if (process.env["UNIT_ONLY"]) {
  // Nothing to do — unit tests don't need backend setup
} else {

const { resolve } = await import("node:path");
const { fileURLToPath } = await import("node:url");
const { statSync } = await import("node:fs");

const __dirname = resolve(fileURLToPath(import.meta.url), "..");

function findBackendDir(): string {
  const candidates = [
    resolve(__dirname, "..", "..", "backend"),
    resolve(__dirname, "..", "..", "..", "backend"),
    resolve(".", "backend"),
    resolve("..", "backend"),
  ];

  for (const candidate of candidates) {
    try {
      const cargoPath = resolve(candidate, "Cargo.toml");
      const stat = statSync(cargoPath);
      if (stat.isFile()) {
        return candidate;
      }
    } catch {
      // Continue searching
    }
  }

  throw new Error("Could not find backend directory.");
}

// Build the backend binary so `cargo run` is fast for all tests
const backendDir = findBackendDir();

const isCI = process.env["CI_MINIMAL_FEATURES"] === "true";
const hasLicenseKey = !!process.env["EE_LICENSE_KEY"];
const features = isCI
  ? ["zip"]
  : hasLicenseKey
    ? ["zip", "private", "enterprise", "license"]
    : ["zip"];

const cargoArgs = ["build", "--features", features.join(",")];
console.log(`Pre-building backend: cargo ${cargoArgs.join(" ")}`);

const proc = Bun.spawn(["cargo", ...cargoArgs], {
  cwd: backendDir,
  stdout: "inherit",
  stderr: "inherit",
  env: {
    ...process.env as Record<string, string>,
    SQLX_OFFLINE: "true",
  },
});

const exitCode = await proc.exited;
if (exitCode !== 0) {
  throw new Error(`cargo build failed with exit code ${exitCode}`);
}
console.log("Backend build complete.");

// Start the shared backend instance so it's ready before any test runs.
// This avoids the first integration test timing out while the backend
// creates its database, starts the process, and waits for the health check.
if (process.env["DATABASE_URL"]) {
  // Clean up any stale databases/processes from previous crashed test runs
  const { cleanupStaleTestResources } = await import("./cargo_backend.ts");
  await cleanupStaleTestResources();

  const { getTestBackend, cleanupTestBackend } = await import("./test_backend.ts");
  console.log("Pre-starting test backend...");
  await getTestBackend();
  console.log("Test backend is ready for all tests.");

  // Register afterAll to do full async cleanup (kill processes + drop DB)
  // when all tests complete. The synchronous "exit" handler alone can't
  // drop databases or scan /proc for orphaned child processes.
  const { afterAll } = await import("bun:test");
  afterAll(async () => {
    await cleanupTestBackend();
  });
}

// When TEST_CLI_RUNTIME=node, also build the npm package so tests
// can invoke `node npm/esm/main.js` instead of `bun run src/main.ts`
if (process.env["TEST_CLI_RUNTIME"] === "node") {
  const cliDir = resolve(__dirname, "..");
  console.log("Building npm package for Node runtime testing...");
  const npmBuild = Bun.spawn(["bun", "run", "build-npm.ts"], {
    cwd: cliDir,
    stdout: "inherit",
    stderr: "inherit",
    env: process.env as Record<string, string>,
  });
  const npmExit = await npmBuild.exited;
  if (npmExit !== 0) {
    throw new Error(`npm build failed with exit code ${npmExit}`);
  }
  console.log("npm package built — tests will use Node runtime.");
}

}

/**
 * diffSharedUi must mirror pushSharedUi's apply semantics so the git-sync
 * dry-run preview and the real apply never diverge: it emits ui/<rel> entries
 * exactly when the local ui/ folder differs from the remote store, and nothing
 * (including no local folder) when the apply would be a no-op.
 */

import { expect, test, describe, beforeEach, afterEach, mock } from "bun:test";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

let remoteFiles: Record<string, string> = {};

mock.module("../gen/services.gen.ts", () => ({
  getSharedUi: async (_args: { workspace: string }) => ({ files: remoteFiles }),
}));

const { diffSharedUi } = await import("../src/commands/shared_ui.ts");

describe("diffSharedUi", () => {
  const ws = "test-workspace";
  let tmpDir: string;
  let prevCwd: string;

  beforeEach(() => {
    remoteFiles = {};
    prevCwd = process.cwd();
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "wm-shared-ui-"));
    process.chdir(tmpDir);
  });

  afterEach(() => {
    process.chdir(prevCwd);
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  function writeUi(rel: string, content: string) {
    const full = path.join(tmpDir, "ui", rel);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, content, "utf-8");
  }

  test("emits an added ui/<rel> entry when local has a file the remote lacks", async () => {
    writeUi("theme.json", "{}");
    const changes = await diffSharedUi(ws);
    expect(changes).toEqual([{ type: "added", path: "ui/theme.json" }]);
  });

  test("emits an edited ui/<rel> entry when local content differs", async () => {
    remoteFiles = { "theme.json": "{}" };
    writeUi("theme.json", '{"a":1}');
    const changes = await diffSharedUi(ws);
    expect(changes).toEqual([
      { type: "edited", path: "ui/theme.json", before: "{}", after: '{"a":1}' },
    ]);
  });

  test("emits a deleted ui/<rel> entry when remote has a file local lacks", async () => {
    remoteFiles = { "theme.json": "{}", "extra.json": "1" };
    writeUi("theme.json", "{}");
    const changes = await diffSharedUi(ws);
    expect(changes).toEqual([{ type: "deleted", path: "ui/extra.json" }]);
  });

  test("emits nothing when local matches the remote store", async () => {
    remoteFiles = { "theme.json": "{}" };
    writeUi("theme.json", "{}");
    const changes = await diffSharedUi(ws);
    expect(changes).toEqual([]);
  });

  test("diffs files named after Object.prototype members (e.g. toString)", async () => {
    // Own-property check, not `in`: a local-only ui/toString is an add, and a
    // remote-only ui/toString is a delete, despite Object.prototype.toString.
    writeUi("toString", "x");
    let changes = await diffSharedUi(ws);
    expect(changes).toEqual([{ type: "added", path: "ui/toString" }]);

    fs.rmSync(path.join(tmpDir, "ui", "toString"));
    fs.mkdirSync(path.join(tmpDir, "ui"), { recursive: true });
    remoteFiles = { toString: "x" };
    changes = await diffSharedUi(ws);
    expect(changes).toEqual([{ type: "deleted", path: "ui/toString" }]);
  });

  test("emits nothing when there is no local ui/ folder (apply is a no-op)", async () => {
    remoteFiles = { "theme.json": "{}" };
    const changes = await diffSharedUi(ws);
    expect(changes).toEqual([]);
  });
});

/**
 * Slack settings sync tests.
 *
 * Covers the "omit = clear" normalization applied to error_handler,
 * success_handler, slack_oauth_client_id, and slack_oauth_client_secret:
 *
 *   - pull always emits these 4 fields (null when remote is NULL) so that
 *     settings.yaml is a complete snapshot of remote state.
 *   - push treats the YAML as canonical: absence and explicit null both clear;
 *     a populated value upserts.
 *   - Round-trip (pull → push with no edits) is idempotent.
