test("Integration: Mixed scripts and flows with nonDottedPaths are idempotent", async () => {
    await withTestBackend(async (backend, tempDir) => {
      // Create wmill.yaml with nonDottedPaths enabled
      await writeFile(
        `${tempDir}/wmill.yaml`,
        `defaultTs: bun
