import { expect, test } from "bun:test";

import { computeWsSpecificFlagOnlyPushes } from "../src/commands/sync/sync.ts";
import type { SpecificItemsConfig } from "../src/core/specific_items.ts";

// =============================================================================
// computeWsSpecificFlagOnlyPushes
// Verifies which (kind, path) pairs are emitted as ws_specific_flag changes
// during sync push when local config flags an item ws_specific but the server
// does not yet.
// =============================================================================

test("emits a flag-only push for a resource missing from the server list", () => {
  const localMap: Record<string, string> = {
    "u/admin/db.resource.yaml": "value: foo",
  };
  const local: SpecificItemsConfig = { resources: ["u/admin/db.resource.yaml"] };
  const server: Array<{ item_kind: string; path: string }> = [];

  const out = computeWsSpecificFlagOnlyPushes(localMap, local, server);
  expect(out).toEqual([
    {
      kind: "resource",
      serverPath: "u/admin/db",
      filePath: "u/admin/db.resource.yaml",
    },
  ]);
});

test("emits a flag-only push for a variable missing from the server list", () => {
  const localMap: Record<string, string> = {
    "u/admin/v.variable.yaml": "value: bar",
  };
  const local: SpecificItemsConfig = { variables: ["u/admin/v.variable.yaml"] };

  const out = computeWsSpecificFlagOnlyPushes(localMap, local, []);
  expect(out).toEqual([
    {
      kind: "variable",
      serverPath: "u/admin/v",
      filePath: "u/admin/v.variable.yaml",
    },
  ]);
});

test("does not emit a flag-only push when the server already has the row", () => {
  const localMap: Record<string, string> = {
    "u/admin/db.resource.yaml": "value: foo",
  };
  const local: SpecificItemsConfig = { resources: ["u/admin/db.resource.yaml"] };
  const server = [{ item_kind: "resource", path: "u/admin/db" }];

  expect(computeWsSpecificFlagOnlyPushes(localMap, local, server)).toEqual([]);
});

test("does not emit anything for schedules in specificItems", () => {
  // The backend's list_ws_specific_versions endpoint only handles
  // resource + variable today; schedules have their ws_specific concept
  // expressed through workspace-specific files but the server has no
  // ws_specific row for them, so flag-only pushes don't apply.
  const localMap: Record<string, string> = {
    "u/admin/cron.schedule.yaml": "schedule: '* * * * *'",
  };
  const local: SpecificItemsConfig = { schedules: ["u/admin/cron.schedule.yaml"] };

  expect(computeWsSpecificFlagOnlyPushes(localMap, local, [])).toEqual([]);
});

test("does not emit anything for triggers in specificItems", () => {
  // Same reason as schedules — the backend doesn't track ws_specific for
  // any *_trigger kind.
  const localMap: Record<string, string> = {
    "u/admin/hook.http_trigger.yaml": "method: GET",
  };
  const local: SpecificItemsConfig = { triggers: ["u/admin/hook.http_trigger.yaml"] };

  expect(computeWsSpecificFlagOnlyPushes(localMap, local, [])).toEqual([]);
});

test("returns empty when serverItems is null (server doesn't expose the endpoint)", () => {
  const localMap: Record<string, string> = {
    "u/admin/db.resource.yaml": "value: foo",
  };
  const local: SpecificItemsConfig = { resources: ["u/admin/db.resource.yaml"] };

  expect(computeWsSpecificFlagOnlyPushes(localMap, local, null)).toEqual([]);
});

test("handles .json resource files (extension is preserved on filePath)", () => {
  const localMap: Record<string, string> = {
    "u/admin/db.resource.json": "{\"value\":\"foo\"}",
  };
  const local: SpecificItemsConfig = {
    // Patterns are conventionally .yaml; isSpecificItem normalizes .json -> .yaml
    resources: ["u/admin/db.resource.yaml"],
  };

  const out = computeWsSpecificFlagOnlyPushes(localMap, local, []);
  expect(out).toEqual([
    {
      kind: "resource",
      serverPath: "u/admin/db",
      filePath: "u/admin/db.resource.json",
    },
  ]);
});

test("ignores files not in specificItems", () => {
  const localMap: Record<string, string> = {
    "u/admin/db.resource.yaml": "value: foo",
    "u/admin/other.resource.yaml": "value: bar",
  };
  const local: SpecificItemsConfig = { resources: ["u/admin/db.resource.yaml"] };

  const out = computeWsSpecificFlagOnlyPushes(localMap, local, []);
  expect(out.map((p) => p.filePath)).toEqual(["u/admin/db.resource.yaml"]);
});

/**
 * YAML Format Snapshot Tests
 *
 * Asserts that representative `flow.yaml` files in
 * `test/fixtures/yaml-snapshots/` round-trip through the CLI's parse +
 * stringify pipeline without byte changes.
 *
 * What this catches:
 * - yaml library upgrades that alter indent / quote / map-flow style
 *   (e.g. the Deno `@std/yaml` → npm `yaml` migration in #8041 silently
 *   changed bytes for the same logical content).
 * - Edits to `yamlOptions` (sortMapEntries via `prioritizeName`,
 *   `singleQuote`, `aliasDuplicateObjects`) that re-order fields or
 *   re-quote scalars.
 * - Custom-tag handler regressions for `!inline` / `!inline_fileset` —
 *   the parser resolves them to `"!inline X"` strings, the serializer
 *   then has to single-quote them because of the leading `!`.
 *
 * What this does NOT catch:
 * - Logic regressions in the backend-Flow-JSON → on-disk-folder
 *   conversion (extracting inline scripts, splitting into files). That
 *   would need synthetic backend fixtures and is intentionally out of
 *   scope.
 *
 * **If a fixture's expected output changes**: re-run
 * `bun run test/fixtures/yaml-snapshots/regenerate.ts` and review the
 * diff. If intentional, commit. If not, investigate the upstream change.
 */

import { expect, test, describe } from "bun:test";
import { readdirSync, readFileSync } from "node:fs";
import * as path from "node:path";
import { stringify as yamlStringify } from "yaml";
import { yamlParseContent } from "../src/utils/yaml.ts";
import { yamlOptions } from "../src/commands/sync/sync.ts";

const FIXTURE_DIR = path.join(import.meta.dir, "fixtures", "yaml-snapshots");

describe("yaml format snapshot — flow.yaml fixtures", () => {
  const fixtures = readdirSync(FIXTURE_DIR).filter((f) => f.endsWith(".yaml"));

  // Sanity guard so a typo in the fixture dir path doesn't silently
  // produce zero tests and a green CI.
  test("fixture directory is non-empty", () => {
    expect(fixtures.length).toBeGreaterThan(0);
  });

  for (const filename of fixtures) {
    test(`${filename}: round-trip is byte-stable`, () => {
      const filePath = path.join(FIXTURE_DIR, filename);
      // Normalize CRLF→LF: on Windows, git checkout may rewrite line endings
      // even though .gitattributes pins these fixtures to LF. yamlStringify
      // always emits LF, so we compare in LF form.
      const original = readFileSync(filePath, "utf-8").replace(/\r\n/g, "\n");
      const parsed = yamlParseContent(filename, original);
      const reSerialized = yamlStringify(parsed, yamlOptions);
      expect(reSerialized).toEqual(original);
    });
  }
});

/**
 * Unit tests for custom !inline and !inline_fileset YAML tag handling.
 * These tests require no backend — they test YAML parsing logic.
 */

import { expect, test, describe } from "bun:test";
import { yamlParseContent } from "../src/utils/yaml.ts";
import { stringify as yamlStringify } from "yaml";

describe("YAML !inline tag resolution", () => {
  test("unquoted !inline resolves to string with prefix", () => {
    const result = yamlParseContent("test.yaml", "content: !inline get_users.ts");
    expect(result.content).toBe("!inline get_users.ts");
  });

  test("quoted !inline is preserved as-is", () => {
    const result = yamlParseContent("test.yaml", 'content: "!inline get_users.ts"');
    expect(result.content).toBe("!inline get_users.ts");
  });

  test("unquoted and quoted produce identical results", () => {
    const unquoted = yamlParseContent("test.yaml", "content: !inline script.ts");
    const quoted = yamlParseContent("test.yaml", 'content: "!inline script.ts"');
    expect(unquoted.content).toBe(quoted.content);
  });

  test("unquoted !inline_fileset resolves to string with prefix", () => {
    const result = yamlParseContent("test.yaml", "value: !inline_fileset my_resource.fileset");
    expect(result.value).toBe("!inline_fileset my_resource.fileset");
  });

  test("works within nested flow.yaml structure", () => {
    const yaml = `
value:
  modules:
    - id: a
      value:
        type: rawscript
        content: !inline get_users.ts
        language: bun
    - id: b
      value:
        type: rawscript
        content: !inline send_mail.ts
        language: bun`;
    const result = yamlParseContent("flow.yaml", yaml);
    expect(result.value.modules[0].value.content).toBe("!inline get_users.ts");
    expect(result.value.modules[1].value.content).toBe("!inline send_mail.ts");
  });

  test("round-trip: parse unquoted → stringify → parse preserves value", () => {
    const yaml = "content: !inline my_script.ts";
    const parsed = yamlParseContent("test.yaml", yaml);
    const serialized = yamlStringify(parsed);
    const reparsed = yamlParseContent("test.yaml", serialized);
    expect(reparsed.content).toBe("!inline my_script.ts");
  });
});

