/**
 * Get the value of an item for diff comparison.
 * Returns a normalized representation suitable for JSON comparison.
 */
export async function getItemValue(
  provider: DeployProvider,
  kind: DeployKind,
  path: string,
  workspace: string
): Promise<unknown> {
  try {
    if (kind === "flow") {
      const flow = await provider.getFlowByPath({ workspace, path });
      getAllModules(flow.value?.modules ?? [], flow.value?.failure_module).forEach(
        (x: any) => {
          if (x.value?.type === "script" && x.value.hash != undefined) {
            x.value.hash = undefined;
          }
        }
      );
      return {
        summary: flow.summary,
        description: flow.description,
        value: flow.value,
      };
    } else if (kind === "script") {
      const script = await provider.getScriptByPath({ workspace, path });
      return {
        content: script.content,
        lock: script.lock,
        schema: script.schema,
        summary: script.summary,
        language: script.language,
      };
    } else if (kind === "app" || kind === "raw_app") {
      return await provider.getAppByPath({ workspace, path });
    } else if (kind === "variable") {
      const variable = await provider.getVariable({
        workspace,
        path,
        decryptSecret: true,
      });
      return variable.value;
    } else if (kind === "resource") {
      const resource = await provider.getResource({ workspace, path });
      return resource.value;
    } else if (kind === "resource_type") {
      const rt = await provider.getResourceType({ workspace, path });
      return rt.schema;
    } else if (kind === "folder") {
      const folder = await provider.getFolder({
        workspace,
        name: folderName(path),
      });
      return {
        name: folder.name,
        owners: folder.owners,
        extra_perms: folder.extra_perms,
        summary: folder.summary,
      };
    } else if (kind === "schedule") {
      // Mirror the runtime-fields-ignore set used server-side so the diff drawer
      // matches the merge UI's "did config change?" semantics.
      const schedule = await provider.getSchedule({ workspace, path });
      return stripTriggerOrScheduleRuntimeFields(schedule);
    } else if (isTriggerKind(kind)) {
      const trigger = await provider.getTriggerValue(kind, { workspace, path });
      return stripTriggerOrScheduleRuntimeFields(trigger);
    } else if (kind === "datatable_migration") {
      // Surface the migration SQL so the diff drawer shows the up/down bodies a
      // reviewer needs to inspect before deploying.
      const { datatable, timestamp } = parseDatatableMigrationDeployPath(path);
      const migrations = (await provider.listDatatableMigrations({
        workspace,
      })) as {
        datatable: string;
        timestamp: number;
        name: string;
        code_up: string;
        code_down?: string;
      }[];
      const migration = migrations.find(
        (m) => m.datatable === datatable && m.timestamp === timestamp
      );
      if (migration) {
        return {
          name: migration.name,
          code_up: migration.code_up,
          code_down: migration.code_down ?? null,
        };
      }
    }
  } catch {
    // Item may not exist
  }
  return {};
}

/**
 * Strip runtime fields from a trigger or schedule row so the diff drawer
 * shows only config differences. Mirrors the backend's
 * `TRIGGER_COMPARE_IGNORE` constant.
 */
function stripTriggerOrScheduleRuntimeFields(row: unknown): unknown {
  if (!row || typeof row !== "object") return row;
  const ignore = new Set([
    "workspace_id",
    "edited_by",
    "edited_at",
    "email",
    "error",
    "enabled",
    "mode",
    "server_id",
    "last_server_ping",
    "extra_perms",
    "permissioned_as",
    // Server-managed (kept in sync with backend `TRIGGER_COMPARE_IGNORE`).
    "subscription_id",
    "push_auth_config",
  ]);
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(row as Record<string, unknown>)) {
    if (!ignore.has(k)) out[k] = v;
  }
  return out;
}

/**
 * Fetch the on_behalf_of value for a deployable item.
 * Returns an email for flows/scripts/apps, or undefined if not applicable.
 */
export async function getOnBehalfOf(
  provider: DeployProvider,
  kind: DeployKind,
  path: string,
  workspace: string
): Promise<string | undefined> {
  try {
    if (kind === "flow") {
      const flow = await provider.getFlowByPath({ workspace, path });
      return flow.on_behalf_of_email;
    } else if (kind === "script") {
      const script = await provider.getScriptByPath({ workspace, path });
      return script.on_behalf_of_email;
    } else if (kind === "app" || kind === "raw_app") {
      const app = await provider.getAppByPath({ workspace, path });
      return app.policy?.on_behalf_of_email;
    } else if (kind === "schedule") {
      const schedule = await provider.getSchedule({ workspace, path });
      return schedule.permissioned_as;
    } else if (isTriggerKind(kind)) {
      return await provider.getTriggerPermissionedAs(kind, { workspace, path });
    }
  } catch {
    // Item may not exist
  }
  return undefined;
}

/**
 * @fileoverview Main entry point for windmill-utils-internal package
 * 
 * This module provides utilities for handling Windmill flows, scripts, and schemas:
 * - Inline script extraction and replacement
 * - Path utilities for different programming languages  
 * - Schema parsing and conversion utilities
 * - Cross-platform path constants
 */

export * from "./inline-scripts";
export * from "./path-utils";
export * from "./parse";
export * from "./deploy";
export { SEP, DELIMITER } from "./constants";

import { LANGUAGE_EXTENSIONS, newPathAssigner, PathAssigner } from "../path-utils/path-assigner";
import { FlowModule, RawScript, ScriptLang } from "../gen/types.gen";

/**
 * Represents an inline script extracted from a flow module
 */
export interface InlineScript {
  /** File path where the script content should be written */
  path: string;
  /** The actual script content */
  content: string;
  /** The script language */
  language: ScriptLang;
  is_lock: boolean;
}

function extractRawscriptInline(
  id: string,
  summary: string | undefined,
  rawscript: RawScript,
  mapping: Record<string, string>,
  separator: string,
  assigner: PathAssigner,
  failOnInlineDirective: boolean
): InlineScript[] {
  const [basePath, ext] = assigner.assignPath(summary ?? id, rawscript.language);
  const mappedPath = mapping[id];
  const path = mappedPath ?? basePath + ext;
  const language = rawscript.language;
  const content = rawscript.content;
  // Opt-in defensive guard: when extracting from backend-shaped data (i.e.
  // sync pull), a rawscript whose content is itself an `!inline ...` directive
  // means the backend was poisoned by a prior push that sent the unresolved
  // directive as the script body (GIT-871 / #9140). Refuse to write it back
  // to disk. Off by default because callers that operate on YAML-parsed local
  // flows (flow_metadata, dev) legitimately see `!inline foo.ts` as content.
  if (failOnInlineDirective && typeof content === "string" && content.startsWith("!inline ")) {
    throw new Error(
      `Refusing to extract corrupted inline script for module '${id}': ` +
      `rawscript.content is the literal string \`${content.split("\n")[0]}\` ` +
      `instead of script source. The backend's flow_version.value is corrupt — ` +
      `re-push from a known-good local copy to repair it.`
    );
  }
  const r = [{ path: path, content: content, language, is_lock: false}];
  rawscript.content = "!inline " + path.replaceAll(separator, "/");
  const lock = rawscript.lock;
  if (lock && lock != "") {
    // Derive lock path base from the mapped content path when available,
    // so lock files are named consistently with their content files.
    const lockBasePath = mappedPath
      ? lockBasePathForContent(mappedPath, language)
      : basePath;
    const lockPath = lockBasePath + "lock";
    rawscript.lock = "!inline " + lockPath.replaceAll(separator, "/");
    r.push({ path: lockPath, content: lock, language, is_lock: true});
  }
  return r;
}

/**
 * Derive the lock path base (including trailing dot) from an inline script's
 * content path. The full language extension must be stripped — for compound
 * extensions like "deno.ts", stripping only the last dot segment would yield
 * "x.inline_script.deno.lock" while the assigner-based branch (no mapping,
 * e.g. fresh sync pull) yields "x.inline_script.lock", flip-flopping the lock
 * filename between operations. See legacyLockPathForContent for the old name.
 */
function lockBasePathForContent(contentPath: string, language: ScriptLang): string {
  const langExt = LANGUAGE_EXTENSIONS[language];
  if (langExt && contentPath.endsWith("." + langExt)) {
    return contentPath.substring(0, contentPath.length - langExt.length);
  }
  // Collapsed "ts" (language == defaultTs) or a custom extension: a single
  // dot segment is the whole extension.
  const dotIdx = contentPath.lastIndexOf(".");
  return dotIdx > 0 ? contentPath.substring(0, dotIdx + 1) : contentPath + ".";
}

/**
 * Lock path that CLI versions between #8561 and this fix produced for a given
 * content path (last dot segment stripped, e.g. "x.inline_script.deno.lock").
 * Returns undefined when it matches the canonical name. Callers use this to
 * clean up the stale legacy file after writing the canonical one.
 */
export function legacyLockPathForContent(contentPath: string, language: ScriptLang): string | undefined {
  const dotIdx = contentPath.lastIndexOf(".");
  const legacy = (dotIdx > 0 ? contentPath.substring(0, dotIdx + 1) : contentPath + ".") + "lock";
  const canonical = lockBasePathForContent(contentPath, language) + "lock";
  return legacy === canonical ? undefined : legacy;
}

/**
 * Options for extractInlineScripts function
 */
export interface ExtractInlineScriptsOptions {
  /** When true, skip the .inline_script. suffix in file names */
  skipInlineScriptSuffix?: boolean;
  /**
   * When true, throw if a `rawscript.content` is itself an `!inline ...`
   * directive. Set this only at the sync-pull call site, where the input
   * comes from the backend's `flow_version.value` and `!inline ...` content
   * means the row is corrupt (GIT-871 / #9140). Leave off for callers that
   * pass YAML-parsed local flows — the directive is the legitimate on-disk
   * shape there.
   */
  failOnInlineDirective?: boolean;
}

/**
 * Extracts inline scripts from flow modules, converting them to separate files
 * and replacing the original content with file references.
 *
 * @param modules - Array of flow modules to process
 * @param mapping - Optional mapping of module IDs to custom file paths
 * @param separator - Path separator to use
 * @param defaultTs - Default TypeScript runtime to use ("bun" or "deno")
 * @param pathAssigner - Optional path assigner to reuse (for nested calls)
 * @param options - Optional configuration options
 * @returns Array of inline scripts with their paths and content
 */
export function extractInlineScripts(
  modules: FlowModule[],
  mapping: Record<string, string> = {},
  separator: string = "/",
  defaultTs?: "bun" | "deno",
  pathAssigner?: PathAssigner,
  options?: ExtractInlineScriptsOptions
): InlineScript[] {
  // Create pathAssigner only if not provided (top-level call), but reuse it for nested calls
  const assigner = pathAssigner ?? newPathAssigner(defaultTs ?? "bun", { skipInlineScriptSuffix: options?.skipInlineScriptSuffix });
  const failOnInlineDirective = options?.failOnInlineDirective ?? false;

  return modules.flatMap((m) => {
    if (m.value.type == "rawscript") {
      return extractRawscriptInline(
        m.id,
        m.summary,
        m.value,
        mapping,
        separator,
        assigner,
        failOnInlineDirective
      );
    } else if (m.value.type == "forloopflow") {
      return extractInlineScripts(
        m.value.modules,
        mapping,
        separator,
        defaultTs,
        assigner,
        options
      );
    } else if (m.value.type == "branchall") {
      return m.value.branches.flatMap((b) =>
        extractInlineScripts(b.modules, mapping, separator, defaultTs, assigner, options)
      );
    } else if (m.value.type == "whileloopflow") {
      return extractInlineScripts(
        m.value.modules,
        mapping,
        separator,
        defaultTs,
        assigner,
        options
      );
    } else if (m.value.type == "branchone") {
      return [
        ...m.value.branches.flatMap((b) =>
          extractInlineScripts(
            b.modules,
            mapping,
            separator,
            defaultTs,
            assigner,
            options
          )
        ),
        ...extractInlineScripts(
          m.value.default,
          mapping,
          separator,
          defaultTs,
          assigner,
          options
        ),
      ];
    } else if (m.value.type == "aiagent") {
      return (m.value.tools ?? []).flatMap((tool) => {
        const toolValue = tool.value;
        // Only process flowmodule tools with rawscript type
        if (!toolValue || toolValue.tool_type !== 'flowmodule' || toolValue.type !== 'rawscript') {
          return [];
        }

        return extractRawscriptInline(
          tool.id,
          tool.summary,
          toolValue,
          mapping,
          separator,
          assigner,
          failOnInlineDirective
        );
      });
    } else {
      return [];
    }
  });
}

/**
 * Extracts the current mapping of module IDs to file paths from flow modules
 * by analyzing existing inline script references.
 *
 * @param modules - Array of flow modules to analyze (can be undefined)
 * @param mapping - Existing mapping to extend (defaults to empty object)
 * @returns Record mapping module IDs to their corresponding file paths
 */
export function extractCurrentMapping(
  modules: FlowModule[] | undefined,
  mapping: Record<string, string> = {},
  failureModule?: FlowModule,
  preprocessorModule?: FlowModule,
): Record<string, string> {
  if (failureModule) {
    extractCurrentMapping([failureModule], mapping);
  }
  if (preprocessorModule) {
    extractCurrentMapping([preprocessorModule], mapping);
  }

  if (!modules || !Array.isArray(modules)) {
    return mapping;
  }

  modules.forEach((m) => {
    if (!m?.value?.type) {
      return;
    }

    if (m.value.type === "rawscript") {
      if (m.value.content && m.value.content.startsWith("!inline ")) {
        mapping[m.id] = m.value.content.trim().split(" ")[1];
      }
    } else if (
      m.value.type === "forloopflow" ||
      m.value.type === "whileloopflow"
    ) {
      extractCurrentMapping(m.value.modules, mapping);
    } else if (m.value.type === "branchall") {
      m.value.branches.forEach((b) =>
        extractCurrentMapping(b.modules, mapping)
      );
    } else if (m.value.type === "branchone") {
      m.value.branches.forEach((b) =>
        extractCurrentMapping(b.modules, mapping)
      );
      extractCurrentMapping(m.value.default, mapping);
    } else if (m.value.type === "aiagent") {
      (m.value.tools ?? []).forEach((tool) => {
        const toolValue = tool.value;
        if (!toolValue || toolValue.tool_type !== 'flowmodule' || toolValue.type !== 'rawscript' || !toolValue.content || !toolValue.content.startsWith("!inline ")) {
          return;
        }
        mapping[tool.id] = toolValue.content.trim().split(" ")[1];
      });
    }
  });

  return mapping;
}

import { AiAgent, FlowModule, FlowValue, RawScript } from "../gen/types.gen";

export type LocalScriptInfo = {
  content: string;
  language: RawScript["language"];
  lock?: string;
  tag?: string;
};

async function replaceRawscriptInline(
  id: string,
  rawscript: RawScript,
  fileReader: (path: string) => Promise<string>,
  logger: { info: (message: string) => void; error: (message: string) => void },
  separator: string,
  removeLocks?: string[],
  missingFiles?: string[]
): Promise<void> {
  if (!rawscript.content || !rawscript.content.startsWith("!inline")) {
    return;
  }

  const path = rawscript.content.split(" ")[1];
  const pathSuffix = path.split(".").slice(1).join(".");
  const newPath = id + "." + pathSuffix;

  try {
    rawscript.content = await fileReader(path);
  } catch {
    logger.error(`Script file ${path} not found`);
    try {
      rawscript.content = await fileReader(newPath);
    } catch {
      logger.error(`Script file ${newPath} not found`);
      if (missingFiles) missingFiles.push(path);
    }
  }

  const lock = rawscript.lock;
  if (removeLocks && removeLocks.includes(path)) {
    rawscript.lock = undefined;
  } else if (
    lock &&
    typeof lock === "string" &&
    lock.trimStart().startsWith("!inline ")
  ) {
    const lockPath = lock.split(" ")[1];
    try {
      rawscript.lock = await fileReader(lockPath.replaceAll("/", separator));
    } catch {
      logger.error(`Lock file ${lockPath} not found, treating as empty`);
      rawscript.lock = "";
    }
  }
}

/**
 * Replaces inline script references with actual file content from the filesystem.
 * This function recursively processes all flow modules and their nested structures.
 * 
 * @param modules - Array of flow modules to process
 * @param fileReader - Function to read file content (typically fs.readFile or similar)
 * @param logger - Optional logger object with info and error methods
 * @param localPath - Base path for resolving relative file paths
 * @param removeLocks - Optional array of paths for which to remove lock files
 * @returns Promise that resolves when all inline scripts have been replaced
 */
export async function replaceInlineScripts(
    modules: FlowModule[],
    fileReader: (path: string) => Promise<string>,
    logger: {
      info: (message: string) => void,
      error: (message: string) => void,
    } = {
      info: () => {},
      error: () => {},
    },
    localPath: string,
    separator: string = "/",
    removeLocks?: string[],
    missingFiles?: string[],
  ): Promise<string[]> {
    const missing = missingFiles ?? [];
    await Promise.all(modules.map(async (module) => {
      if (!module.value) {
        throw new Error(`Module value is undefined for module ${module.id}`);
      }

      if (module.value.type === "rawscript") {
        await replaceRawscriptInline(
          module.id,
          module.value,
          fileReader,
          logger,
          separator,
          removeLocks,
          missing
        );
      } else if (module.value.type === "forloopflow" || module.value.type === "whileloopflow") {
        await replaceInlineScripts(module.value.modules, fileReader, logger, localPath, separator, removeLocks, missing);
      } else if (module.value.type === "branchall") {
        await Promise.all(module.value.branches.map(async (branch) => {
          await replaceInlineScripts(branch.modules, fileReader, logger, localPath, separator, removeLocks, missing);
        }));
      } else if (module.value.type === "branchone") {
        await Promise.all(module.value.branches.map(async (branch) => {
          await replaceInlineScripts(branch.modules, fileReader, logger, localPath, separator, removeLocks, missing);
        }));
        await replaceInlineScripts(module.value.default, fileReader, logger, localPath, separator, removeLocks, missing);
      } else if (module.value.type === "aiagent") {
        await Promise.all((module.value.tools ?? []).map(async (tool) => {
          const toolValue = tool.value;
          if (
            !toolValue ||
            toolValue.tool_type !== "flowmodule" ||
            toolValue.type !== "rawscript"
          ) {
            return;
          }
          await replaceRawscriptInline(
            tool.id,
            toolValue,
            fileReader,
            logger,
            separator,
            removeLocks,
            missing
          );
        }));
      }
    }));
    return missing;
  }

/**
 * Replaces PathScript ("script" type) modules with RawScript ("rawscript" type) using local file content.
 * This is used during flow preview so that local script changes are tested instead of remote versions.
 *
 * @param modules - Array of flow modules to process
 * @param scriptReader - Function that takes a script path and returns local content/language/lock, or undefined if not found locally
 * @param logger - Logger for info/error messages
 */
export async function replacePathScriptsWithLocal(
  modules: FlowModule[],
  scriptReader: (scriptPath: string) => Promise<LocalScriptInfo | undefined>,
  logger: {
    info: (message: string) => void;
    error: (message: string) => void;
  } = {
    info: () => {},
    error: () => {},
  }
): Promise<void> {
  await Promise.all(modules.map(async (module) => {
    if (!module.value) {
      return;
    }

    if (module.value.type === "script") {
      const scriptPath = module.value.path;
      const localScript = await scriptReader(scriptPath);
      if (localScript) {
        const pathScript = module.value;
        module.value = {
          type: "rawscript",
          content: localScript.content,
          language: localScript.language,
          lock: localScript.lock,
          path: scriptPath,
          input_transforms: pathScript.input_transforms,
          tag: pathScript.tag_override ?? localScript.tag,
        } satisfies RawScript;
      }
    } else if (module.value.type === "forloopflow" || module.value.type === "whileloopflow") {
      await replacePathScriptsWithLocal(module.value.modules, scriptReader, logger);
    } else if (module.value.type === "branchall") {
      await Promise.all(module.value.branches.map(async (branch) => {
        await replacePathScriptsWithLocal(branch.modules, scriptReader, logger);
      }));
    } else if (module.value.type === "branchone") {
      await Promise.all(module.value.branches.map(async (branch) => {
        await replacePathScriptsWithLocal(branch.modules, scriptReader, logger);
      }));
      await replacePathScriptsWithLocal(module.value.default, scriptReader, logger);
    } else if (module.value.type === "aiagent") {
      await Promise.all((module.value.tools ?? []).map(async (tool) => {
        const toolValue = tool.value;
        if (!toolValue || toolValue.tool_type !== "flowmodule" || toolValue.type !== "script") {
          return;
        }
        const localScript = await scriptReader(toolValue.path);
        if (localScript) {
          (tool as AiAgent["tools"][number]).value = {
            tool_type: "flowmodule",
            type: "rawscript",
            content: localScript.content,
            language: localScript.language,
            lock: localScript.lock,
            path: toolValue.path,
            input_transforms: toolValue.input_transforms,
            tag: toolValue.tag_override ?? localScript.tag,
          };
        }
      }));
    }
  }));
}

function collectPathScriptPathsFromModules(
  modules: FlowModule[],
  paths: Set<string>
): void {
  for (const module of modules) {
    if (!module.value) {
      continue;
    }

    if (module.value.type === "script") {
      paths.add(module.value.path);
    } else if (
      module.value.type === "forloopflow" ||
      module.value.type === "whileloopflow"
    ) {
      collectPathScriptPathsFromModules(module.value.modules, paths);
    } else if (module.value.type === "branchall") {
      for (const branch of module.value.branches) {
        collectPathScriptPathsFromModules(branch.modules, paths);
      }
    } else if (module.value.type === "branchone") {
      for (const branch of module.value.branches) {
        collectPathScriptPathsFromModules(branch.modules, paths);
      }
      collectPathScriptPathsFromModules(module.value.default, paths);
    } else if (module.value.type === "aiagent") {
      for (const tool of module.value.tools ?? []) {
        const toolValue = tool.value;
        if (
          toolValue &&
          toolValue.tool_type === "flowmodule" &&
          toolValue.type === "script"
        ) {
          paths.add(toolValue.path);
        }
      }
    }
  }
}

/**
 * Replaces all PathScript modules in a flow value (modules, failure_module, preprocessor_module)
 * with RawScript using local file content.
 */
export async function replaceAllPathScriptsWithLocal(
  flowValue: FlowValue,
  scriptReader: (scriptPath: string) => Promise<LocalScriptInfo | undefined>,
  logger: {
    info: (message: string) => void;
    error: (message: string) => void;
  } = {
    info: () => {},
    error: () => {},
  }
): Promise<void> {
  await replacePathScriptsWithLocal(flowValue.modules, scriptReader, logger);
  if (flowValue.failure_module) {
    await replacePathScriptsWithLocal([flowValue.failure_module], scriptReader, logger);
  }
  if (flowValue.preprocessor_module) {
    await replacePathScriptsWithLocal([flowValue.preprocessor_module], scriptReader, logger);
  }
}

export function collectPathScriptPaths(flowValue: FlowValue): string[] {
  const paths = new Set<string>();
  collectPathScriptPathsFromModules(flowValue.modules, paths);
  if (flowValue.failure_module) {
    collectPathScriptPathsFromModules([flowValue.failure_module], paths);
  }
  if (flowValue.preprocessor_module) {
    collectPathScriptPathsFromModules([flowValue.preprocessor_module], paths);
  }
  return [...paths];
}

/**
 * Type alias for enum values - can be an array of strings or undefined
 */
export type EnumType =
  | string[]
  | { label: string; value: string }[]
  | undefined;

/**
 * Represents a property in a JSON schema with various validation and display options
 */
export interface SchemaProperty {
  type: string | undefined;
  description?: string;
  pattern?: string;
  default?: any;
  enum?: EnumType;
  contentEncoding?: "base64" | "binary";
  format?: string;
  items?: {
    type?: "string" | "number" | "bytes" | "object" | "resource";
    contentEncoding?: "base64";
    enum?: EnumType;
    resourceType?: string;
    properties?: { [name: string]: SchemaProperty };
  };
  min?: number;
  max?: number;
  currency?: string;
  currencyLocale?: string;
  multiselect?: boolean;
  customErrorMessage?: string;
  properties?: { [name: string]: SchemaProperty };
  required?: string[];
  showExpr?: string;
  password?: boolean;
  order?: string[];
  nullable?: boolean;
  dateFormat?: string;
  title?: string;
  placeholder?: string;
  oneOf?: SchemaProperty[];
  originalType?: string;
}

const ITEMS_PRESERVED_FIELDS = [
  "properties",
  "required",
  "additionalProperties",
  "enum",
  "resourceType",
  "contentEncoding",
  "description",
] as (keyof SchemaProperty["items"])[];

/**
 * Converts argument signature types to JSON schema properties.
 * This function handles various Windmill-specific types and converts them
 * to standard JSON schema format while preserving existing property metadata.
 *
 * @param t - The argument signature type definition (can be string or complex object types)
 * @param oldS - Existing schema property to update with new type information
 */

export function argSigToJsonSchemaType(
  t:
    | string
    | { resource: string | null }
    | {
        list:
          | (string | { name?: string; props?: { key: string; typ: any }[] })
          | { str: any }
          | { object: { name?: string; props?: { key: string; typ: any }[] } }
          | null;
      }
    | { dynselect: string }
    | { dynmultiselect: string }
    | { str: string[] | null }
    | { object: { name?: string; props?: { key: string; typ: any }[] } }
    | {
        oneof: {
          label: string;
          properties: { key: string; typ: any }[];
        }[];
      },
  oldS: SchemaProperty
): void {
  const newS: SchemaProperty = { type: "" };
  if (t === "int") {
    newS.type = "integer";
  } else if (t === "float") {
    newS.type = "number";
  } else if (t === "bool") {
    newS.type = "boolean";
  } else if (t === "email") {
    newS.type = "string";
    newS.format = "email";
  } else if (t === "sql") {
    newS.type = "string";
    newS.format = "sql";
  } else if (t === "yaml") {
    newS.type = "string";
    newS.format = "yaml";
  } else if (t === "bytes") {
    newS.type = "string";
    newS.contentEncoding = "base64";
    newS.originalType = "bytes";
  } else if (t === "datetime") {
    newS.type = "string";
    newS.format = "date-time";
  } else if (t === "date") {
    newS.type = "string";
    newS.format = "date";
  } else if (typeof t !== "string" && "oneof" in t) {
    newS.type = "object";
    if (t.oneof) {
      newS.oneOf = t.oneof.map((obj) => {
        const oldObjS =
          oldS.oneOf?.find((o) => o?.title === obj.label) ?? undefined;
        const properties: Record<string, any> = {};
        for (const prop of obj.properties) {
          if (oldObjS?.properties && prop.key in oldObjS?.properties) {
            properties[prop.key] = oldObjS?.properties[prop.key];
          } else {
            properties[prop.key] = { description: "", type: "" };
          }
          argSigToJsonSchemaType(prop.typ, properties[prop.key]);
        }
        return {
          type: "object",
          title: obj.label,
          properties,
          order: oldObjS?.order ?? undefined,
        };
      });
    }
  } else if (typeof t !== "string" && `object` in t) {
    newS.type = "object";
    if (t.object.name) {
      newS.format = `resource-${t.object.name}`;
    }
    if (t.object.props) {
      const properties: Record<string, any> = {};
      for (const prop of t.object.props) {
        if (oldS.properties && prop.key in oldS.properties) {
          properties[prop.key] = oldS.properties[prop.key];
        } else {
          properties[prop.key] = { description: "", type: "" };
        }
        argSigToJsonSchemaType(prop.typ, properties[prop.key]);
      }
      newS.properties = properties;
    }
  } else if (typeof t !== "string" && `str` in t) {
    newS.type = "string";
    if (t.str) {
      newS.originalType = "enum";
      newS.enum = t.str;
    } else if (oldS.originalType == "string" && oldS.enum) {
      newS.originalType = "string";
      newS.enum = oldS.enum;
    } else {
      newS.originalType = "string";
      newS.enum = undefined;
    }
  } else if (typeof t !== "string" && `resource` in t) {
    newS.type = "object";
    newS.format = `resource-${t.resource}`;
  } else if (typeof t !== "string" && `dynselect` in t) {
    newS.type = "object";
    newS.format = `dynselect-${t.dynselect}`;
  } else if (typeof t !== "string" && `dynmultiselect` in t) {
    newS.type = "object";
    newS.format = `dynmultiselect-${t.dynmultiselect}`;
  } else if (typeof t !== "string" && `list` in t) {
    newS.type = "array";
    if (t.list === "int" || t.list === "float") {
      newS.items = { type: "number" };
      newS.originalType = "number[]";
    } else if (t.list === "bytes") {
      newS.items = { type: "string", contentEncoding: "base64" };
      newS.originalType = "bytes[]";
    } else if (
      t.list &&
      typeof t.list == "object" &&
      "str" in t.list &&
      t.list.str
    ) {
      newS.items = { type: "string", enum: t.list.str };
      newS.originalType = "enum[]";
    } else if (
      t.list == "string" ||
      (t.list && typeof t.list == "object" && "str" in t.list)
    ) {
      newS.items = { type: "string", enum: oldS.items?.enum };
      newS.originalType = "string[]";
    } else if (
      t.list &&
      typeof t.list == "object" &&
      "resource" in t.list &&
      t.list.resource
    ) {
      newS.items = {
        type: "resource",
        resourceType: t.list.resource as string,
      };
      newS.originalType = "resource[]";
    } else if (
      t.list &&
      typeof t.list == "object" &&
      "object" in t.list &&
      t.list.object
    ) {
      if (t.list.object.name) {
        newS.format = `resource-${t.list.object.name}`;
      }
      if (t.list.object.props && t.list.object.props.length > 0) {
        const properties: Record<string, any> = {};
        for (const prop of t.list.object.props) {
          properties[prop.key] = { description: "", type: "" };
          argSigToJsonSchemaType(prop.typ, properties[prop.key]);
        }
        newS.items = { type: "object", properties: properties };
      } else {
        // Preserve ALL user-defined fields when parser cannot infer structure
        newS.items = { type: oldS.items?.type || "object" };

        if (oldS.items && typeof oldS.items === "object") {
          ITEMS_PRESERVED_FIELDS.forEach((field) => {
            if (oldS.items && oldS.items[field] !== undefined) {
              (newS.items as any)[field] = oldS.items[field];
            }
          });
        }
      }
      newS.originalType = "record[]";
    } else {
      // Preserve ALL user-defined fields for untyped lists (same as record[] branch)
      newS.items = { type: oldS.items?.type || "object" };

      if (oldS.items && typeof oldS.items === "object") {
        ITEMS_PRESERVED_FIELDS.forEach((field) => {
          if (oldS.items && oldS.items[field] !== undefined) {
            (newS.items as any)[field] = oldS.items[field];
          }
        });
      }
      newS.originalType = "object[]";
    }
  } else {
    // Preserve existing type when inference fails, default to "object" for undefined/null
    newS.type = oldS.type ?? "object";
  }

  const preservedFields = [
    "description",
    "pattern",
    "min",
    "max",
    "currency",
    "currencyLocale",
    "multiselect",
    "customErrorMessage",
    "required",
    "showExpr",
    "password",
    "order",
    "dateFormat",
    "title",
    "placeholder",
  ];

  preservedFields.forEach((field) => {
    // @ts-ignore
    if (oldS[field] !== undefined) {
      // @ts-ignore
      newS[field] = oldS[field];
    }
  });

  if (oldS.type != newS.type) {
    for (const prop of Object.getOwnPropertyNames(newS)) {
      if (prop != "description") {
        // @ts-ignore
        delete oldS[prop];
      }
    }
  } else if (
    (oldS.format == "date" || oldS.format === "date-time") &&
    newS.format == "string"
  ) {
    newS.format = oldS.format;
  } else if (newS.format == "date-time" && oldS.format == "date") {
    newS.format = "date";
  } else if (newS.format == "date" || newS.format == "date-time") {
    newS.format = oldS.format;
  } else if (oldS.items?.type != newS.items?.type) {
    delete oldS.items;
  } else if (oldS.type == "string" && oldS.format != undefined) {
    newS.format = oldS.format;
  }

  if (
    (oldS.type != newS.type || newS.type != "string") &&
    newS.format == undefined
  ) {
    oldS.format = undefined;
  }

  Object.assign(oldS, newS);
}

import { RawScript } from "../gen/types.gen";

const INLINE_SCRIPT_PREFIX = "inline_script";

/**
 * Union type of all supported programming languages in Windmill
 */
export type SupportedLanguage = RawScript["language"] | "frontend" | "bunnative" | "oracledb" | "rust" | "csharp" | "nu" | "ansible" | "java" | "duckdb";

/**
 * Mapping of supported languages to their file extensions
 */
export const LANGUAGE_EXTENSIONS: Record<SupportedLanguage, string> = {
  python3: "py",
  bun: "bun.ts",
  deno: "deno.ts", 
  go: "go",
  bash: "sh",
  powershell: "ps1",
  postgresql: "pg.sql",
  mysql: "my.sql",
  bigquery: "bq.sql",
  oracledb: "odb.sql",
  snowflake: "sf.sql",
  mssql: "ms.sql",
  graphql: "gql",
  nativets: "native.ts",
  frontend: "frontend.js",
  php: "php",
  rust: "rs",
  csharp: "cs",
  nu: "nu",
  ansible: "playbook.yml",
  java: "java",
  duckdb: "duckdb.sql",
  bunnative: "ts",
  ruby: "rb",
  rlang: "r",
  dbt: "dbt.yaml",
  // for related places search: ADD_NEW_LANG
};

/**
 * Gets the appropriate file extension for a given programming language.
 * Handles special cases for TypeScript variants based on the default runtime.
 *
 * @param language - The programming language to get extension for
 * @param defaultTs - Default TypeScript runtime ("bun" or "deno")
 * @returns File extension string (without the dot)
 */
export function getLanguageExtension(
  language: SupportedLanguage,
  defaultTs: "bun" | "deno" = "bun"
): string {
  if (language === defaultTs || language === "bunnative") {
    return "ts";
  }
  return LANGUAGE_EXTENSIONS[language] || "no_ext";
}

/**
 * Reverse mapping from file extensions to languages.
 * Used when deriving language from file extension.
 */
export const EXTENSION_TO_LANGUAGE: Record<string, SupportedLanguage> = {
  "py": "python3",
  "bun.ts": "bun",
  "deno.ts": "deno",
  "go": "go",
  "sh": "bash",
  "ps1": "powershell",
  "pg.sql": "postgresql",
  "my.sql": "mysql",
  "bq.sql": "bigquery",
  "odb.sql": "oracledb",
  "sf.sql": "snowflake",
  "ms.sql": "mssql",
  "gql": "graphql",
  "native.ts": "nativets",
  "frontend.js": "frontend",
  "php": "php",
  "rs": "rust",
  "cs": "csharp",
  "nu": "nu",
  "playbook.yml": "ansible",
  "java": "java",
  "duckdb.sql": "duckdb",
  "dbt.yaml": "dbt",
  "rb": "ruby",
  // Plain .ts defaults to bun (will be overridden by defaultTs setting)
  "ts": "bun",
};

/**
 * Gets the language from a file extension.
 *
 * @param ext - File extension (e.g., "py", "ts", "bun.ts")
 * @param defaultTs - Default TypeScript runtime for plain .ts files
 * @returns The language, or undefined if not recognized
 */
export function getLanguageFromExtension(
  ext: string,
  defaultTs: "bun" | "deno" = "bun"
): SupportedLanguage | undefined {
  // Check for compound extensions first (e.g., "bun.ts", "pg.sql")
  const lang = EXTENSION_TO_LANGUAGE[ext];
  if (lang) {
    // For plain .ts, return the default TypeScript runtime
    if (ext === "ts") {
      return defaultTs;
    }
    return lang;
  }
  return undefined;
}

/**
 * Sanitizes a summary string for use as a filesystem-safe name.
 * Removes or replaces characters that are invalid on common filesystems.
 */
const WINDOWS_RESERVED = /^(con|prn|aux|nul|com[0-9]|lpt[0-9])$/;

export function sanitizeForFilesystem(
  summary: string,
  options?: { preserveCase?: boolean },
): string {
  let name = summary
    .replaceAll(" ", "_")
    // Remove characters invalid on Windows/Unix/Mac: / \ : * ? " < > |
    // Also remove control characters (0x00-0x1F) and DEL (0x7F)
    // deno-lint-ignore no-control-regex
    .replace(/[/\\:*?"<>|\x00-\x1f\x7f]/g, "")
    // Collapse consecutive underscores
    .replace(/_+/g, "_")
    // Trim leading/trailing dots and underscores (hidden files, Windows edge cases)
    .replace(/^[._]+|[._]+$/g, "");
  if (!options?.preserveCase) {
    name = name.toLowerCase();
  }
  // Prefix Windows reserved device names (CON, PRN, AUX, NUL, COM0-9, LPT0-9)
  return WINDOWS_RESERVED.test(name.toLowerCase()) ? `_${name}` : name;
}

export interface PathAssigner {
  assignPath(summary: string | undefined, language: SupportedLanguage): [string, string];
}

export interface PathAssignerOptions {
  defaultTs: "bun" | "deno";
  /** When true, skip the .inline_script. suffix in file names */
  skipInlineScriptSuffix?: boolean;
}

/**
 * Creates a new path assigner for inline scripts.
 *
 * @param defaultTs - Default TypeScript runtime ("bun" or "deno")
 * @param options - Optional configuration (can pass options object instead of defaultTs)
 * @returns Path assigner function
 */
export function newPathAssigner(defaultTs: "bun" | "deno" | PathAssignerOptions, options?: { skipInlineScriptSuffix?: boolean }): PathAssigner {
  // Handle both old signature (defaultTs string) and new signature (options object)
  const resolvedOptions: PathAssignerOptions = typeof defaultTs === "object"
    ? defaultTs
    : { defaultTs, skipInlineScriptSuffix: options?.skipInlineScriptSuffix };

  const { defaultTs: tsRuntime, skipInlineScriptSuffix } = resolvedOptions;

  let counter = 0;
  // Dedupe case-insensitively so case-only duplicates don't collide on
  // case-insensitive filesystems (Windows, default macOS).
  const seen_names = new Set<string>();
  function assignPath(
    summary: string | undefined,
    language: SupportedLanguage
  ): [string, string] {
    let name;

    name = summary ? sanitizeForFilesystem(summary) : "";

    let original_name = name;

    if (name == "") {
      original_name = INLINE_SCRIPT_PREFIX;
      name = `${INLINE_SCRIPT_PREFIX}_0`;
    }

    while (seen_names.has(name.toLowerCase())) {
      counter++;
      name = `${original_name}_${counter}`;
    }
    seen_names.add(name.toLowerCase());

    const ext = getLanguageExtension(language, tsRuntime);

    // When skipInlineScriptSuffix is true, don't add .inline_script. to the path
    const suffix = skipInlineScriptSuffix ? "." : ".inline_script.";
    return [`${name}${suffix}`, ext];
  }
  return { assignPath };
}

/**
 * Creates a new path assigner for raw app runnables.
 * Unlike newPathAssigner, this does NOT add ".inline_script." prefix since
 * everything in raw_app/backend/ is already known to be for inline scripts.
 *
 * @param defaultTs - Default TypeScript runtime ("bun" or "deno")
 * @returns Path assigner function
 */
export function newRawAppPathAssigner(defaultTs: "bun" | "deno"): PathAssigner {
  let counter = 0;
  // Dedupe case-insensitively so case-only duplicates don't collide on
  // case-insensitive filesystems (Windows, default macOS).
  const seen_names = new Set<string>();
  function assignPath(
    summary: string | undefined,
    language: SupportedLanguage
  ): [string, string] {
    let name;

    name = summary ? sanitizeForFilesystem(summary, { preserveCase: true }) : "";

    let original_name = name;

    if (name == "") {
      original_name = "runnable";
      name = `runnable_0`;
    }

    while (seen_names.has(name.toLowerCase())) {
      counter++;
      name = `${original_name}_${counter}`;
    }
    seen_names.add(name.toLowerCase());

    const ext = getLanguageExtension(language, defaultTs);

    return [`${name}.`, ext];
  }
  return { assignPath };
}

